(() => {
    const THREE_URL = 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.min.js';
    const root = document.documentElement;
    const en = () => (root.lang || '').startsWith('en');
    const calm = () => window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    const touch = () => window.matchMedia && window.matchMedia('(hover: none)').matches;

    const ICON = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2.8 7 9.6h2.6L5.6 15h5.1v5.6h2.6V15h5.1l-4-5.4H17Z" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"/></svg>';

    // Playlist YouTube du mode révision (l'ID après « list= » dans le lien)
    const PLAYLIST_ID = 'PLdrao3armmLc';

    const ICON_STUDY = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 14v-2a8 8 0 0 1 16 0v2" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/><rect x="3" y="13" width="4.5" height="7" rx="1.6" fill="none" stroke="currentColor" stroke-width="1.8"/><rect x="16.5" y="13" width="4.5" height="7" rx="1.6" fill="none" stroke="currentColor" stroke-width="1.8"/></svg>';
    const ICON_AI = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3.5c.5 3.9 2.6 6 6.5 6.5-3.9.5-6 2.6-6.5 6.5-.5-3.9-2.6-6-6.5-6.5 3.9-.5 6-2.6 6.5-6.5Z" fill="currentColor"/><path d="M18.5 15.5c.2 1.6 1 2.4 2.5 2.5-1.5.2-2.3 1-2.5 2.5-.2-1.5-1-2.3-2.5-2.5 1.5-.1 2.3-.9 2.5-2.5Z" fill="currentColor"/></svg>';
    const ICON_SHUFFLE = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3.5 7h3.2c2 0 3.3 1 4.4 2.6l2 3c1.1 1.6 2.4 2.4 4.4 2.4h3" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round"/><path d="M3.5 17h3.2c1.6 0 2.7-.6 3.7-1.7M14.2 8.6c.9-1 2-1.6 3.6-1.6h2.7" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round"/><path d="m18.2 4.6 2.6 2.4-2.6 2.4M18.2 12.6l2.6 2.4-2.6 2.4" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"/></svg>';
    const ICON_PAUSE = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 5v14M16 5v14" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"/></svg>';
    const ICON_PLAY = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 5.5v13l10.5-6.5Z" fill="currentColor"/></svg>';
    const ICON_NEXT = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 5.5v13l9-6.5Z" fill="currentColor"/><path d="M18 5.5v13" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"/></svg>';

    const CHEV_L = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m14.5 5.5-6.5 6.5 6.5 6.5" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';
    const CHEV_R = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9.5 5.5 6.5 6.5-6.5 6.5" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';

    const words = () => (en() ? {
        open: 'Show the dioramas',
        dialog: 'Dioramas',
        close: 'Close',
        prev: 'Previous diorama',
        next: 'Next diorama',
        loading: 'Building the diorama…',
        error: 'The 3D scene could not load. Check your connection and try again.',
        nogl: 'Your browser cannot display 3D here.',
        ai: 'AI notice',
        aiTitle: 'Generated by AI',
        aiMore: 'This diorama was generated by an AI. I wanted a beautiful place to study, so I added it to my portfolio so others can enjoy it too.',
        study: 'Study mode',
        studyHelp: 'Random music from my playlist',
        studyStop: 'Stop study mode',
        studyLoading: 'Loading the music…',
        studyPause: 'Pause',
        studyPlay: 'Play',
        studyNext: 'Next track',
        studyError: 'The music could not load.',
        studyMissing: 'Playlist not configured yet.',
        shuffle: 'Shuffle',
        shuffleHelp: 'Change diorama with every new song',
        forestTitle: 'The living forest.',
        forestHelp: touch() ? 'Drag to turn · pinch to zoom · tap the animals or the pond' : 'Drag to turn · scroll to zoom · click the animals or the pond',
        boatTitle: 'Lost at sea.',
        boatHelp: touch() ? 'Drag to turn · pinch to zoom · tap the boat, the water or the sky' : 'Drag to turn · scroll to zoom · click the boat, the water or the sky',
        lighthouseTitle: 'The lighthouse in the storm.',
        desertTitle: 'The oasis in the sandstorm.',
        desertHelp: touch() ? 'Drag to turn · pinch to zoom · tap the crocodiles or the water' : 'Drag to turn · scroll to zoom · click the crocodiles or the water',
        lighthouseHelp: touch() ? 'Drag to turn · pinch to zoom · tap the lighthouse, the monsters or the water' : 'Drag to turn · scroll to zoom · click the lighthouse, the monsters or the water',
        snowTitle: 'The chalet in the blizzard.',
        classroomTitle: 'Revision time.',
        classroomHelp: touch() ? 'Drag to turn · pinch to zoom · tap a student, the teacher or the board' : 'Drag to turn · scroll to zoom · click a student, the teacher or the board',
        snowHelp: touch() ? 'Drag to turn · pinch to zoom · tap the chalet or the fir trees' : 'Drag to turn · scroll to zoom · click the chalet or the fir trees',
    } : {
        open: 'Afficher les dioramas',
        dialog: 'Dioramas',
        close: 'Fermer',
        prev: 'Diorama précédent',
        next: 'Diorama suivant',
        loading: 'Le diorama se construit…',
        error: 'La scène 3D n\'a pas pu se charger. Vérifie ta connexion et réessaie.',
        nogl: 'Ton navigateur ne peut pas afficher la 3D ici.',
        ai: 'Mention IA',
        aiTitle: 'Généré par une IA',
        aiMore: 'Ce diorama a été généré par une IA. Je voulais un bel environnement pour réviser, alors je l\'ai intégré à mon portfolio pour que d\'autres puissent en profiter aussi.',
        study: 'Mode révision',
        studyHelp: 'Musique aléatoire de ma playlist',
        studyStop: 'Quitter le mode révision',
        studyLoading: 'Chargement de la musique…',
        studyPause: 'Pause',
        studyPlay: 'Lecture',
        studyNext: 'Morceau suivant',
        studyError: 'La musique n\'a pas pu se charger.',
        studyMissing: 'Playlist pas encore configurée.',
        shuffle: 'Aléatoire',
        shuffleHelp: 'Change de diorama à chaque nouvelle musique',
        forestTitle: 'La forêt vivante.',
        forestHelp: touch() ? 'Glisse pour tourner · pince pour zoomer · touche les animaux ou l\'étang' : 'Glisse pour tourner · molette pour zoomer · clique sur les animaux ou l\'étang',
        boatTitle: 'Perdu au large.',
        boatHelp: touch() ? 'Glisse pour tourner · pince pour zoomer · touche le bateau, l\'eau ou le ciel' : 'Glisse pour tourner · molette pour zoomer · clique sur le bateau, l\'eau ou le ciel',
        lighthouseTitle: 'Le phare dans la tempête.',
        desertTitle: 'L\'oasis dans la tempête.',
        desertHelp: touch() ? 'Glisse pour tourner · pince pour zoomer · touche les crocodiles ou l\'eau' : 'Glisse pour tourner · molette pour zoomer · clique sur les crocodiles ou l\'eau',
        lighthouseHelp: touch() ? 'Glisse pour tourner · pince pour zoomer · touche le phare, les monstres ou l\'eau' : 'Glisse pour tourner · molette pour zoomer · clique sur le phare, les monstres ou l\'eau',
        snowTitle: 'Le chalet dans la tempête.',
        classroomTitle: 'L\'heure des révisions.',
        classroomHelp: touch() ? 'Glisse pour tourner · pince pour zoomer · touche un élève, la prof ou le tableau' : 'Glisse pour tourner · molette pour zoomer · clique sur un élève, la prof ou le tableau',
        snowHelp: touch() ? 'Glisse pour tourner · pince pour zoomer · touche le chalet ou les sapins' : 'Glisse pour tourner · molette pour zoomer · clique sur le chalet ou les sapins',
    });

    // Vitesse de la rotation automatique au repos : lente, la même pour tous les dioramas
    const IDLE_SPIN = 0.03;

    // Les dioramas, dans l'ordre des flèches
    const SCENES = [
        { id: 'forest', build: (THREE, stage) => buildForest(THREE, stage) },
        { id: 'boat', build: (THREE, stage) => buildBoat(THREE, stage) },
        { id: 'lighthouse', build: (THREE, stage) => buildLighthouse(THREE, stage) },
        { id: 'desert', build: (THREE, stage) => buildDesert(THREE, stage) },
        { id: 'snow', build: (THREE, stage) => buildSnow(THREE, stage) },
        { id: 'classroom', build: (THREE, stage) => buildClassroom(THREE, stage) },
    ];

    let egg;
    let overlay = null;
    let scene3d = null;
    let current = 0;

    document.addEventListener('DOMContentLoaded', () => {
        egg = document.createElement('button');
        egg.type = 'button';
        egg.className = 'diorama-egg';
        egg.innerHTML = ICON;
        label();
        egg.addEventListener('click', open);
        document.body.appendChild(egg);
        document.querySelectorAll('.lang-switcher a').forEach(a => a.addEventListener('click', () => setTimeout(label, 0)));
    });

    function label() {
        egg.setAttribute('aria-label', words().open);
        egg.title = words().open;
    }

    async function open() {
        if (overlay) return;
        const t = words();
        const o = document.createElement('div');
        o.className = 'diorama-overlay';
        o.innerHTML = `
            <div class="diorama-window" role="dialog" aria-modal="true" aria-label="${t.dialog}">
                <div class="diorama-stage">
                    <div class="diorama-sky diorama-sky--day"></div>
                    <div class="diorama-sky diorama-sky--boat"></div>
                    <div class="diorama-sky diorama-sky--storm"></div>
                    <div class="diorama-sky diorama-sky--desert"></div>
                    <div class="diorama-sky diorama-sky--snow"></div>
                    <div class="diorama-sky diorama-sky--classroom"></div>
                    <p class="diorama-loading">${t.loading}</p>
                </div>
                <div class="diorama-side">
                    <div class="diorama-study">
                        <button type="button" class="diorama-study-toggle" aria-pressed="false">
                            <span class="diorama-study-icon">${ICON_STUDY}</span>
                            <span class="diorama-study-text"><b>${t.study}</b><small>${t.studyHelp}</small></span>
                        </button>
                        <div class="diorama-player">
                            <span class="diorama-eq" aria-hidden="true"><i></i><i></i><i></i></span>
                            <span class="diorama-track" aria-live="polite"><b></b><small></small></span>
                            <button type="button" class="diorama-mini diorama-pp" aria-label="${t.studyPause}">${ICON_PAUSE}</button>
                            <button type="button" class="diorama-mini diorama-skip" aria-label="${t.studyNext}">${ICON_NEXT}</button>
                        </div>
                        <div class="diorama-yt" aria-hidden="true"></div>
                    </div>
                </div>
                <button type="button" class="diorama-btn diorama-close" aria-label="${t.close}">×</button>
                <button type="button" class="diorama-btn diorama-nav diorama-prev" aria-label="${t.prev}">${CHEV_L}</button>
                <button type="button" class="diorama-btn diorama-nav diorama-next" aria-label="${t.next}">${CHEV_R}</button>
                <p class="diorama-caption"><em></em><span></span></p>
                <div class="diorama-dock">
                    <button type="button" class="diorama-chip diorama-shuffle" aria-pressed="false" title="${t.shuffleHelp}">
                        <span class="diorama-chip-icon">${ICON_SHUFFLE}</span><span class="diorama-chip-text">${t.shuffle}</span>
                    </button>
                    <div class="diorama-ai">
                        <button type="button" class="diorama-ai-toggle" aria-expanded="false" aria-controls="diorama-ai-more">
                            <span class="diorama-ai-icon">${ICON_AI}</span><span>${t.ai}</span>
                        </button>
                        <div class="diorama-ai-more" id="diorama-ai-more">
                            <strong>${t.aiTitle}</strong>
                            <p>${t.aiMore}</p>
                        </div>
                    </div>
                </div>
            </div>`;
        overlay = o;
        document.body.appendChild(o);
        root.classList.add('diorama-open');
        requestAnimationFrame(() => o.classList.add('is-open'));

        const stage = o.querySelector('.diorama-stage');
        const loading = o.querySelector('.diorama-loading');
        const [prevBtn, nextBtn, closeBtn] = [o.querySelector('.diorama-prev'), o.querySelector('.diorama-next'), o.querySelector('.diorama-close')];
        const studyBtn = o.querySelector('.diorama-study-toggle');
        const ppBtn = o.querySelector('.diorama-pp');
        const skipBtn = o.querySelector('.diorama-skip');
        const aiBtn = o.querySelector('.diorama-ai-toggle');
        const shuffleBtn = o.querySelector('.diorama-shuffle');
        const buttons = [studyBtn, ppBtn, skipBtn, prevBtn, nextBtn, shuffleBtn, aiBtn, closeBtn];
        // Aléatoire : à chaque nouvelle musique, on change de diorama
        let shuffle = false;
        const study = studyMode(o, t, {
            onTrack: () => {
                if (!shuffle || SCENES.length < 2) return;
                let i = Math.floor(Math.random() * (SCENES.length - 1));
                if (i >= current) i++;
                show(i);
            },
        });
        let THREE = null;
        let token = 0;

        const caption = () => {
            const id = SCENES[current].id;
            o.querySelector('.diorama-caption em').innerHTML = `<b class="diorama-count">${current + 1}/${SCENES.length}</b>${t[id + 'Title']}`;
            o.querySelector('.diorama-caption span').textContent = t[id + 'Help'];
        };
        // Passe d'un diorama à l'autre : l'ancien s'efface, le nouveau se construit
        const show = async (i) => {
            current = (i + SCENES.length) % SCENES.length;
            const mine = ++token;
            o.dataset.scene = SCENES[current].id;
            // Interface claire sur les scènes sombres, sombre sur les scènes en plein jour
            o.classList.toggle('is-night', SCENES[current].id !== 'desert');
            caption();
            if (scene3d) {
                o.classList.remove('is-ready');
                const old = scene3d;
                scene3d = null;
                await new Promise(r => setTimeout(r, 260));
                old.dispose();
            }
            if (overlay !== o || mine !== token || !THREE) return;
            try {
                scene3d = SCENES[current].build(THREE, stage);
                o.classList.add('is-ready');
            } catch (e) {
                console.error('Diorama :', e);
                loading.textContent = t.nogl;
            }
        };
        const onKey = (e) => {
            if (e.key === 'Escape') close();
            if (e.key === 'ArrowLeft') show(current - 1);
            if (e.key === 'ArrowRight') show(current + 1);
            if (e.key === 'Tab') {
                e.preventDefault();
                const live = buttons.filter(b => b.offsetParent !== null);
                const k = live.indexOf(document.activeElement);
                live[(k + (e.shiftKey ? live.length - 1 : 1)) % live.length].focus();
            }
        };
        const close = () => {
            if (overlay !== o) return;
            overlay = null;
            token++;
            document.removeEventListener('keydown', onKey);
            root.classList.remove('diorama-open');
            o.classList.remove('is-open');
            study.stop();
            if (scene3d) {
                scene3d.dispose();
                scene3d = null;
            }
            setTimeout(() => o.remove(), 300);
            egg.focus();
        };
        o.addEventListener('click', (e) => { if (e.target === o) close(); });
        closeBtn.addEventListener('click', close);
        prevBtn.addEventListener('click', () => show(current - 1));
        nextBtn.addEventListener('click', () => show(current + 1));
        studyBtn.addEventListener('click', () => study.toggle());
        aiBtn.addEventListener('click', () => {
            const openAi = !o.classList.contains('is-ai-open');
            o.classList.toggle('is-ai-open', openAi);
            aiBtn.setAttribute('aria-expanded', String(openAi));
        });
        shuffleBtn.addEventListener('click', () => {
            shuffle = !shuffle;
            shuffleBtn.setAttribute('aria-pressed', String(shuffle));
            shuffleBtn.classList.toggle('is-on', shuffle);
            // Sans musique, l'aléatoire ne servirait à rien : on la lance
            if (shuffle && !study.isOn()) study.toggle();
        });
        ppBtn.addEventListener('click', () => study.playPause());
        skipBtn.addEventListener('click', () => study.next());
        document.addEventListener('keydown', onKey);
        closeBtn.focus({ preventScroll: true });
        show(current);

        try {
            THREE = await import(THREE_URL);
        } catch (e) {
            if (overlay === o) loading.textContent = t.error;
            return;
        }
        if (overlay === o) show(current);
    }

    // ---------------------------------------------------------------------
    // Mode révision : lance la playlist YouTube en aléatoire, lecteur caché,
    // avec un petit bandeau (titre, pause, morceau suivant).
    // ---------------------------------------------------------------------
    let ytApi = null;
    function loadYouTube() {
        if (window.YT && window.YT.Player) return Promise.resolve(window.YT);
        if (ytApi) return ytApi;
        ytApi = new Promise((resolve, reject) => {
            const prev = window.onYouTubeIframeAPIReady;
            window.onYouTubeIframeAPIReady = () => {
                if (typeof prev === 'function') prev();
                resolve(window.YT);
            };
            const s = document.createElement('script');
            s.src = 'https://www.youtube.com/iframe_api';
            s.onerror = () => { ytApi = null; reject(new Error('YouTube API')); };
            document.head.appendChild(s);
        });
        return ytApi;
    }

    function studyMode(o, t, hooks = {}) {
        const btn = o.querySelector('.diorama-study-toggle');
        const small = btn.querySelector('small');
        const trackEl = o.querySelector('.diorama-track');
        const trackTitle = trackEl.querySelector('b');
        const trackAuthor = trackEl.querySelector('small');
        // Affiche un message, ou le titre + l'artiste du morceau
        const track = {
            set textContent(msg) { trackTitle.textContent = msg; trackAuthor.textContent = ''; },
        };
        const pp = o.querySelector('.diorama-pp');
        const host = o.querySelector('.diorama-yt');
        let player = null;
        let on = false;
        let playing = false;
        let lastId = null;

        const setPlaying = (v) => {
            playing = v;
            o.classList.toggle('is-playing', v);
            pp.innerHTML = v ? ICON_PAUSE : ICON_PLAY;
            pp.setAttribute('aria-label', v ? t.studyPause : t.studyPlay);
        };
        const title = () => {
            const d = player && player.getVideoData && player.getVideoData();
            if (!d || !d.title) return;
            trackTitle.textContent = d.title;
            trackAuthor.textContent = (d.author || '').replace(/ - Topic$/, '');
            trackEl.title = d.author ? `${d.title} — ${trackAuthor.textContent}` : d.title;
        };
        // Choisit un morceau au hasard dans la playlist (sauf celui en cours)
        const random = () => {
            const list = player && player.getPlaylist && player.getPlaylist();
            if (!list || !list.length) return false;
            const cur = player.getPlaylistIndex();
            let i = Math.floor(Math.random() * list.length);
            if (list.length > 1 && i === cur) i = (i + 1) % list.length;
            player.playVideoAt(i);
            return true;
        };

        const start = async () => {
            on = true;
            o.classList.add('is-study');
            btn.setAttribute('aria-pressed', 'true');
            btn.setAttribute('aria-label', t.studyStop);
            if (!PLAYLIST_ID) {
                track.textContent = t.studyMissing;
                return;
            }
            track.textContent = t.studyLoading;
            if (player) {
                player.playVideo();
                return;
            }
            let YT;
            try {
                YT = await loadYouTube();
            } catch (e) {
                if (on) track.textContent = t.studyError;
                return;
            }
            if (!on || overlay !== o) return;
            const el = document.createElement('div');
            host.appendChild(el);
            player = new YT.Player(el, {
                width: 200,
                height: 200,
                playerVars: { listType: 'playlist', list: PLAYLIST_ID, playsinline: 1, controls: 0, disablekb: 1 },
                events: {
                    onReady: (e) => {
                        o.classList.add('has-player');
                        e.target.setShuffle(true);
                        e.target.setLoop(true);
                        e.target.setVolume(60);
                        // La playlist met parfois un instant à arriver
                        let tries = 0;
                        const go = () => {
                            if (!on) return;
                            if (random() || tries++ > 20) {
                                if (tries > 20) e.target.playVideo();
                                return;
                            }
                            setTimeout(go, 150);
                        };
                        go();
                    },
                    onStateChange: (e) => {
                        if (e.data === YT.PlayerState.PLAYING) {
                            setPlaying(true);
                            title();
                            // Nouveau morceau : on prévient (pour l'aléatoire des dioramas)
                            const d = player.getVideoData && player.getVideoData();
                            const id = d && d.video_id;
                            if (id && lastId && id !== lastId && hooks.onTrack) hooks.onTrack();
                            if (id) lastId = id;
                        }
                        if (e.data === YT.PlayerState.PAUSED) setPlaying(false);
                        if (e.data === YT.PlayerState.ENDED) random();
                    },
                    onError: () => { if (!random()) track.textContent = t.studyError; },
                },
            });
        };

        const stop = () => {
            on = false;
            o.classList.remove('is-study');
            setPlaying(false);
            btn.setAttribute('aria-pressed', 'false');
            btn.removeAttribute('aria-label');
            if (player && player.pauseVideo) player.pauseVideo();
        };

        small.textContent = t.studyHelp;
        return {
            toggle: () => (on ? stop() : start()),
            isOn: () => on,
            playPause: () => {
                if (!player) return;
                if (playing) player.pauseVideo(); else player.playVideo();
            },
            next: () => { if (player) random(); },
            stop: () => {
                stop();
                if (player && player.destroy) player.destroy();
                player = null;
            },
        };
    }

    // ---------------------------------------------------------------------
    // Premier diorama : une forêt géante et vivante, un matin de soleil. Une laie
    // se promène autour de la clairière avec ses marcassins, s'arrête pour
    // fouiller la terre ; des papillons volent entre les fleurs, les poissons
    // tournent dans l'étang et les feuilles tombent doucement.
    // ---------------------------------------------------------------------
    function buildForest(THREE, stage) {
        const phone = Math.min(window.innerWidth, window.innerHeight) < 600 || touch();
        const S = 10;
        const HALF = S / 2;
        const WATER = -0.28;
        const BASE = -3.3;
        const N = phone ? 44 : 64;
        const rand = mulberry32(21);
        const rr = (a, b) => a + (b - a) * rand();
        const color = (hex) => new THREE.Color(hex);
        const V = (x, y, z) => new THREE.Vector3(x, y, z);

        // --- Plan de la scène ---
        const PONDS = [[-4.0, 4.0, 2.0], [-2.4, 4.6, 1.05]];
        const FACE = -0.5;
        const FX = Math.sin(FACE);
        const FZ = Math.cos(FACE);
        const GIANTS = [
            { x: 0.9, z: -1.0, r: 1.0, h: 5.2 },
            { x: -2.9, z: -2.9, r: 0.9, h: 4.7 },
            { x: 3.5, z: -3.3, r: 0.9, h: 4.8 },
            { x: -3.9, z: 0.5, r: 0.8, h: 4.3 },
            { x: 3.9, z: 1.3, r: 0.8, h: 4.4 },
        ];
        const MAIN = GIANTS[0];
        // La clairière où se promènent les sangliers, devant le grand arbre
        const CLEAR = { x: MAIN.x + FX * 2.6, z: MAIN.z + FZ * 2.6 };
        const PATH = [[5.2, 2.6], [3.6, 2.2], [2.2, 1.5], [1.0, 1.0]];
        const pondD = (x, z) => {
            let d = Infinity;
            for (const [cx, cz, r] of PONDS) d = Math.min(d, Math.hypot(x - cx, z - cz) - r);
            return d;
        };
        const pathD = (x, z) => {
            let d = Infinity;
            for (let i = 0; i < PATH.length - 1; i++) {
                const [ax, az] = PATH[i];
                const [bx, bz] = PATH[i + 1];
                const vx = bx - ax;
                const vz = bz - az;
                const k = clamp(((x - ax) * vx + (z - az) * vz) / (vx * vx + vz * vz), 0, 1);
                d = Math.min(d, Math.hypot(x - ax - vx * k, z - az - vz * k));
            }
            return d;
        };
        // Le chemin des cerfs : une boucle dans le pré, devant, jusqu'au bord de l'étang
        const deerTrail = new THREE.CatmullRomCurve3([
            [-1.0, 4.2], [0.2, 4.5], [1.6, 4.35], [3.0, 4.45], [4.3, 4.0],
            [4.4, 3.15], [3.3, 3.05], [2.0, 3.35], [0.6, 3.7], [-0.5, 3.75],
        ].map(([x, z]) => new THREE.Vector3(x, 0, z)), true, 'centripetal');
        const deerPts = deerTrail.getSpacedPoints(140);
        const deerD = (x, z) => {
            let d = Infinity;
            for (const p of deerPts) d = Math.min(d, Math.hypot(x - p.x, z - p.z));
            return d;
        };
        const bumps = (x, z) => Math.sin(x * 1.3 + Math.sin(z * 0.7) * 2) * 0.5 + Math.sin(z * 1.1 - x * 0.4) * 0.35 + Math.sin((x + z) * 2.7) * 0.15;
        const mound = (x, z) => {
            let m = 0;
            for (const g of GIANTS) m += 0.28 * Math.exp(-Math.pow(Math.hypot(x - g.x, z - g.z) / (1.7 * g.r), 2));
            return m;
        };
        const height = (x, z) => {
            const d = pondD(x, z);
            if (d > 0) {
                const k = Math.min(1, d / 1.1);
                return -0.35 + Math.pow(k, 0.8) * 0.35 + bumps(x, z) * 0.08 * k + mound(x, z) * k - Math.max(0, 0.16 - pathD(x, z)) * 0.25;
            }
            const k = Math.min(1, -d / 1.4);
            const s = k * k * (3 - 2 * k);
            return -0.35 - 1.45 * s + bumps(x * 1.7, z * 1.7) * 0.07 * s;
        };

        // --- Rendu ---
        const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, powerPreference: 'high-performance' });
        renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, phone ? 1.75 : 2));
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        renderer.setClearColor(0x000000, 0);
        renderer.domElement.className = 'diorama-canvas';
        stage.appendChild(renderer.domElement);

        const scene = new THREE.Scene();
        scene.fog = new THREE.Fog(0x31463f, 20, 50);
        const camera = new THREE.PerspectiveCamera(30, 1, 0.1, 300);
        const uniforms = {
            uTime: { value: 0 },
            uWater: { value: WATER },
        };

        // --- Lumière d'un jour de pluie : ciel gris-vert, lumière douce ---
        const HEMI = 1.0;
        const hemi = new THREE.HemisphereLight(0xc2d6d6, 0x43503a, HEMI);
        scene.add(hemi);
        const sun = new THREE.DirectionalLight(0xdde9ee, 1.3);
        sun.position.set(-6, 13, 4);
        sun.castShadow = true;
        sun.shadow.mapSize.set(phone ? 1024 : 2048, phone ? 1024 : 2048);
        Object.assign(sun.shadow.camera, { left: -9, right: 9, top: 9, bottom: -9, near: 1, far: 45 });
        sun.shadow.bias = -0.0006;
        sun.shadow.normalBias = 0.03;
        scene.add(sun);
        const bounce = new THREE.DirectionalLight(0x9fc2b8, 0.3);
        bounce.position.set(7, 4, -5);
        scene.add(bounce);

        const flat = (hex, extra) => new THREE.MeshStandardMaterial(Object.assign({ color: hex, flatShading: true, roughness: 0.85 }, extra || {}));
        const WHITE = 0xffffff;

        // --- Sol ---
        const grid = new THREE.PlaneGeometry(S, S, N, N);
        grid.rotateX(-Math.PI / 2);
        const gp = grid.attributes.position;
        for (let i = 0; i < gp.count; i++) gp.setY(i, height(gp.getX(i), gp.getZ(i)));
        const terrainGeo = grid.toNonIndexed();
        grid.dispose();
        const tp = terrainGeo.attributes.position;
        const tc = new Float32Array(tp.count * 3);
        const MOSS = [0x6a9c48, 0x5e8f42, 0x76a84f, 0x568640].map(color);
        const CLEARC = [0x86b45a, 0x92bd62, 0x7dab55].map(color);
        const SOIL = [0x6d5a3c, 0x7a6544].map(color);
        const PATHC = [0xb08f63, 0xa58457].map(color);
        const SAND = color(0xcdbf8a);
        const BED = color(0xb7a676);
        const DEEP = color(0x6f8466);
        const tmp = new THREE.Color();
        for (let f = 0; f < tp.count; f += 3) {
            const x = (tp.getX(f) + tp.getX(f + 1) + tp.getX(f + 2)) / 3;
            const y = (tp.getY(f) + tp.getY(f + 1) + tp.getY(f + 2)) / 3;
            const z = (tp.getZ(f) + tp.getZ(f + 1) + tp.getZ(f + 2)) / 3;
            const h = hash(x, z);
            if (y > WATER + 0.1) {
                const nearGiant = GIANTS.some(g => Math.hypot(x - g.x, z - g.z) < 1.5 * g.r);
                if (pathD(x, z) < 0.17) tmp.copy(PATHC[h < 0.5 ? 0 : 1]);
                else if (Math.hypot(x - CLEAR.x, z - CLEAR.z) < 1.5) tmp.copy(CLEARC[Math.floor(h * CLEARC.length)]);
                else if (nearGiant && h < 0.45) tmp.copy(SOIL[h < 0.22 ? 0 : 1]);
                else tmp.copy(MOSS[Math.floor(h * MOSS.length)]);
            } else if (y > WATER - 0.08) {
                tmp.copy(SAND);
            } else {
                tmp.copy(BED).lerp(DEEP, clamp((WATER - y) / 1.2, 0, 1));
            }
            for (let k = 0; k < 3; k++) tmp.toArray(tc, (f + k) * 3);
        }
        terrainGeo.setAttribute('color', new THREE.BufferAttribute(tc, 3));
        terrainGeo.computeVertexNormals();
        const terrainMat = new THREE.MeshStandardMaterial({ vertexColors: true, flatShading: true, roughness: 0.95 });
        decorate(terrainMat);
        const terrain = new THREE.Mesh(terrainGeo, terrainMat);
        terrain.receiveShadow = true;
        scene.add(terrain);

        // --- Côtés du bloc : couches de terre, et l'eau vue en coupe ---
        const strata = strataTexture();
        const sideMat = new THREE.MeshStandardMaterial({ map: strata, roughness: 1 });
        const lipMat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 1 });
        const glassMat = new THREE.MeshBasicMaterial({ vertexColors: true, color: 0x6f92b4, transparent: true, opacity: 0.5, depthWrite: false, side: THREE.DoubleSide, fog: false });
        const EDGES = [
            { x0: -HALF, z0: HALF, dx: 1, dz: 0 },
            { x0: HALF, z0: HALF, dx: 0, dz: -1 },
            { x0: HALF, z0: -HALF, dx: -1, dz: 0 },
            { x0: -HALF, z0: -HALF, dx: 0, dz: 1 },
        ];
        const rimPts = [];
        const TOPSOIL = color(0x4f3b2a);
        const GLASS_TOP = color(0x9fe9ec);
        const GLASS_BOTTOM = color(0x2a98a6);
        EDGES.forEach((e, ei) => {
            const body = [];
            const bodyUv = [];
            const lip = [];
            const lipCol = [];
            const glass = [];
            const glassCol = [];
            for (let i = 0; i <= N; i++) {
                const x = e.x0 + e.dx * S * i / N;
                const z = e.z0 + e.dz * S * i / N;
                const top = height(x, z);
                const wet = top < WATER + 0.1;
                lip.push(x, top, z, x, top - 0.12, z);
                // Haut du bord : l'herbe ; bas du bord : la couleur de la terre, pour un passage en douceur
                const lc = wet ? SAND : (pathD(x, z) < 0.17 ? PATHC[1] : color(0x5a8a40));
                lc.toArray(lipCol, lipCol.length);
                (wet ? SAND : TOPSOIL).toArray(lipCol, lipCol.length);
                body.push(x, top - 0.12, z, x, BASE, z);
                const u = (ei * S + S * i / N) / 6;
                bodyUv.push(u, (top - 0.12 - BASE) / (0.3 - BASE), u, 0);
                const bottom = Math.min(top, WATER);
                glass.push(x, WATER, z, x, bottom, z);
                GLASS_TOP.toArray(glassCol, glassCol.length);
                tmp.copy(GLASS_TOP).lerp(GLASS_BOTTOM, clamp((WATER - bottom) / 1.3, 0, 1)).toArray(glassCol, glassCol.length);
                if (top < WATER - 0.005) rimPts.push([ei, i, x, z]);
            }
            const normal = [-e.dz, 0, e.dx];
            scene.add(strip(body, bodyUv, null, normal, sideMat, true));
            scene.add(strip(lip, null, lipCol, normal, lipMat, true));
            const g = strip(glass, null, glassCol, normal, glassMat, false);
            g.renderOrder = 3;
            scene.add(g);
        });
        const bottomGeo = new THREE.PlaneGeometry(S, S);
        bottomGeo.rotateX(Math.PI / 2);
        const bottom = new THREE.Mesh(bottomGeo, new THREE.MeshStandardMaterial({ color: 0x5d4330 }));
        bottom.position.y = BASE;
        scene.add(bottom);

        const rim = [];
        for (let k = 1; k < rimPts.length; k++) {
            const a = rimPts[k - 1];
            const b = rimPts[k];
            if (a[0] === b[0] && b[1] === a[1] + 1) rim.push(a[2], WATER + 0.004, a[3], b[2], WATER + 0.004, b[3]);
        }
        const corner = height(-HALF, HALF);
        if (corner < WATER) rim.push(-HALF, WATER, HALF, -HALF, corner, HALF);
        const rimGeo = new THREE.BufferGeometry();
        rimGeo.setAttribute('position', new THREE.Float32BufferAttribute(rim, 3));
        const rimLines = new THREE.LineSegments(rimGeo, new THREE.LineBasicMaterial({ color: 0xbfd8ff, transparent: true, opacity: 0.45, fog: false }));
        rimLines.renderOrder = 4;
        scene.add(rimLines);

        const contact = new THREE.Mesh(new THREE.PlaneGeometry(S * 1.9, S * 1.9), new THREE.MeshBasicMaterial({ map: radialTexture('rgba(0,0,0,0.45)', 'rgba(0,0,0,0)'), transparent: true, depthWrite: false, fog: false }));
        contact.rotation.x = -Math.PI / 2;
        contact.position.set(0.8, BASE - 0.02, -0.4);
        scene.add(contact);

        // --- Eau ---
        const WSEG = phone ? 36 : 48;
        const waterGeo = new THREE.PlaneGeometry(S, S, WSEG, WSEG);
        waterGeo.rotateX(-Math.PI / 2);
        const wp = waterGeo.attributes.position;
        const waves = [];
        for (let i = 0; i < wp.count; i++) {
            const x = wp.getX(i);
            const z = wp.getZ(i);
            if (Math.abs(x) < HALF - 1e-3 && Math.abs(z) < HALF - 1e-3 && height(x, z) < WATER + 0.12) waves.push(i);
        }
        const waterMat = new THREE.MeshStandardMaterial({ color: 0x1b6676, transparent: true, opacity: 0.86, roughness: 0.14, metalness: 0.05, flatShading: true, depthWrite: false });
        const water = new THREE.Mesh(waterGeo, waterMat);
        water.position.y = WATER;
        water.receiveShadow = true;
        water.renderOrder = 2;
        scene.add(water);

        // --- Arbres géants ---
        const BARK = [0x5b4030, 0x6a4a35, 0x4e3628].map(color);
        const MOSSY = [0x5a6f3a, 0x627a40, 0x526636].map(color);
        const trunkMat = new THREE.MeshStandardMaterial({ vertexColors: true, flatShading: true, roughness: 0.95 });
        const rootMats = [flat(0x5a4130), flat(0x4f7f3c), flat(0x63482f)];
        const crownMat = flat(WHITE, { roughness: 0.8 });
        const crowns = [];
        const trunks = [];
        const faceAngle = Math.atan2(FZ, FX);
        GIANTS.forEach((g, gi) => {
            const y0 = height(g.x, g.z) - 0.1;
            const prof = [[1.3, 0], [0.98, 0.03], [0.74, 0.08], [0.6, 0.16], [0.53, 0.3], [0.49, 0.5], [0.44, 0.7], [0.39, 0.86], [0.33, 1.0]];
            const lathe = new THREE.LatheGeometry(prof.map(([m, f]) => new THREE.Vector2(m * g.r, f * g.h)), 12);
            const lp = lathe.attributes.position;
            for (let i = 0; i < lp.count; i++) {
                const x = lp.getX(i);
                const y = lp.getY(i);
                const z = lp.getZ(i);
                const a = Math.atan2(z, x);
                const k = 1 + 0.09 * Math.sin(a * 3 + y * 0.9 + gi) + 0.05 * Math.sin(a * 7 - y * 1.7);
                lp.setXYZ(i, x * k, y, z * k);
            }
            const trunkGeo = lathe.toNonIndexed();
            lathe.dispose();
            const tpos = trunkGeo.attributes.position;
            const tcol = new Float32Array(tpos.count * 3);
            for (let f = 0; f < tpos.count; f += 3) {
                const cx = (tpos.getX(f) + tpos.getX(f + 1) + tpos.getX(f + 2)) / 3;
                const cy = (tpos.getY(f) + tpos.getY(f + 1) + tpos.getY(f + 2)) / 3;
                const cz = (tpos.getZ(f) + tpos.getZ(f + 1) + tpos.getZ(f + 2)) / 3;
                const ang = Math.atan2(cz, cx);
                const sector = Math.floor((ang + Math.PI) / (Math.PI * 2) * 12);
                const band = prof.findIndex(([, fr]) => fr * g.h > cy);
                const h = hash(sector + gi * 3.1, band * 1.7);
                const mossy = h < 0.62 - band * 0.14 + Math.max(0, Math.cos(ang - 2.4)) * 0.25;
                tmp.copy(mossy ? MOSSY[Math.floor(hash(band, sector) * 3)] : BARK[Math.floor(hash(sector, band + gi) * 3)]);
                for (let k = 0; k < 3; k++) tmp.toArray(tcol, (f + k) * 3);
            }
            trunkGeo.setAttribute('color', new THREE.BufferAttribute(tcol, 3));
            trunkGeo.computeVertexNormals();
            const trunk = new THREE.Mesh(trunkGeo, trunkMat);
            trunk.position.set(g.x, y0, g.z);
            trunk.castShadow = true;
            trunk.receiveShadow = true;
            scene.add(trunk);
            trunks.push(trunk);

            const nRoots = 6;
            for (let k = 0; k < nRoots; k++) {
                const a = (k / nRoots) * Math.PI * 2 + rr(-0.3, 0.3);
                if (gi === 0 && Math.abs(Math.atan2(Math.sin(a - faceAngle), Math.cos(a - faceAngle))) < 0.75) continue;
                const ca = Math.cos(a);
                const sa = Math.sin(a);
                const pt = (dist, lift) => {
                    const x = clamp(g.x + ca * dist * g.r, -HALF + 0.05, HALF - 0.05);
                    const z = clamp(g.z + sa * dist * g.r, -HALF + 0.05, HALF - 0.05);
                    return V(x, height(x, z) + lift, z);
                };
                const curve = new THREE.CatmullRomCurve3([pt(0.55, 0.75), pt(1.1, 0.42), pt(1.75, 0.16), pt(2.35, -0.12)]);
                const rootMesh = new THREE.Mesh(taperedTube(curve, 0.2 * g.r, 0.05 * g.r), rootMats[k % 3]);
                rootMesh.castShadow = true;
                rootMesh.receiveShadow = true;
                scene.add(rootMesh);
                if (gi === 0) trunks.push(rootMesh);
            }

            const top = V(g.x, y0 + g.h * 0.96, g.z);
            for (let k = 0; k < 5; k++) {
                const a = (k / 5) * Math.PI * 2 + rr(-0.4, 0.4);
                const dist = k === 0 ? 0 : rr(0.9, 1.5) * g.r * 1.2;
                const c = V(g.x + Math.cos(a) * dist, top.y + rr(0.1, 0.8), g.z + Math.sin(a) * dist);
                const radius = rr(0.85, 1.2) * g.r * (k === 0 ? 1.2 : 1);
                crowns.push({ x: c.x, y: c.y, z: c.z, s: radius, yaw: rr(0, 6.28), phase: rr(0, 6.28), col: [0x3d7a3c, 0x4a8a44, 0x356c37, 0x52924a][Math.floor(rand() * 4)] });
                if (k) {
                    const br = limb(V(g.x, top.y - 0.6, g.z), c, 0.16 * g.r, 0.07 * g.r, rootMats[0]);
                    br.castShadow = true;
                    scene.add(br);
                }
            }
        });
        const crownMesh = new THREE.InstancedMesh(new THREE.IcosahedronGeometry(1, 0), crownMat, crowns.length);
        crownMesh.castShadow = true;
        crowns.forEach((c, i) => crownMesh.setColorAt(i, color(c.col)));
        scene.add(crownMesh);

        // --- Forêt dense autour ---
        const nearGiantTrunk = (x, z, pad) => GIANTS.some(g => Math.hypot(x - g.x, z - g.z) < g.r * 1.25 + pad);
        const inClearing = (x, z, pad = 0) => Math.hypot(x - CLEAR.x, z - CLEAR.z) < 1.95 + pad;
        const spots = [];
        const want = phone ? 46 : 72;
        for (let tries = 0; tries < 6000 && spots.length < want; tries++) {
            const x = rr(-HALF + 0.35, HALF - 0.35);
            const z = rr(-HALF + 0.35, HALF - 0.35);
            if (pondD(x, z) < 0.5 || pathD(x, z) < 0.38 || inClearing(x, z) || nearGiantTrunk(x, z, 0.3) || deerD(x, z) < 0.55) continue;
            const s = rr(0.75, 1.45);
            if (spots.some(p => Math.hypot(p.x - x, p.z - z) < 0.42 * (p.s + s))) continue;
            const k = rand();
            spots.push({ x, z, s, y: height(x, z) - 0.03, kind: k < 0.5 ? 'pine' : k < 0.8 ? 'round' : 'birch', phase: rr(0, 6.28), yaw: rr(0, 6.28) });
        }
        const pines = spots.filter(p => p.kind === 'pine');
        const rounds = spots.filter(p => p.kind === 'round');
        const birches = spots.filter(p => p.kind === 'birch');
        const parts = [{ mesh: crownMesh, list: crowns, sway: 0.4 }];
        const part = (geo, mat, list, tint) => {
            const m = new THREE.InstancedMesh(geo, mat, Math.max(1, list.length));
            m.count = list.length;
            m.castShadow = true;
            m.receiveShadow = true;
            list.forEach((p, i) => { if (tint) m.setColorAt(i, tint(p, i)); });
            scene.add(m);
            parts.push({ mesh: m, list, sway: 1 });
            return m;
        };
        const woodMat = flat(WHITE);
        const leafMat = flat(WHITE, { roughness: 0.8 });
        const PINE = [0x24563f, 0x2d6448, 0x214d39, 0x356c4c].map(color);
        const LEAF = [0x4f8c43, 0x5a9a4a, 0x437c3c, 0x6aa650].map(color);
        const pineColor = (p) => p.c || (p.c = PINE[Math.floor(hash(p.x, p.z) * PINE.length)]);
        const roundColor = (p) => p.c || (p.c = LEAF[Math.floor(hash(p.x, p.z) * LEAF.length)]);
        const at = (geo, y, x = 0, z = 0) => geo.translate(x, y, z);
        part(at(new THREE.CylinderGeometry(0.05, 0.075, 0.36, 5), 0.18), woodMat, pines, () => color(0x5e3f2a));
        part(at(new THREE.ConeGeometry(0.43, 0.62, 7), 0.6), leafMat, pines, (p) => pineColor(p).clone());
        part(at(new THREE.ConeGeometry(0.34, 0.54, 7), 0.9), leafMat, pines, (p) => pineColor(p).clone().offsetHSL(0, 0, 0.03));
        part(at(new THREE.ConeGeometry(0.23, 0.44, 7), 1.18), leafMat, pines, (p) => pineColor(p).clone().offsetHSL(0, 0, 0.06));
        part(at(new THREE.CylinderGeometry(0.05, 0.08, 0.6, 5), 0.3), woodMat, rounds, () => color(0x6a4630));
        part(at(new THREE.IcosahedronGeometry(0.42, 0), 0.88), leafMat, rounds, (p) => roundColor(p).clone());
        part(at(new THREE.IcosahedronGeometry(0.28, 0), 1.12, 0.17, 0.06), leafMat, rounds, (p) => roundColor(p).clone().offsetHSL(0, 0.02, 0.05));
        // Bouleaux : tronc blanc fin, feuillage clair en petites boules
        const BIRCH = [0x8fbf55, 0xa3c95e, 0x7fb04c].map(color);
        const birchColor = (p) => p.c || (p.c = BIRCH[Math.floor(hash(p.x, p.z) * BIRCH.length)]);
        part(at(new THREE.CylinderGeometry(0.035, 0.05, 1.1, 6), 0.55), woodMat, birches, () => color(0xe9e4d8));
        part(at(new THREE.CylinderGeometry(0.052, 0.052, 0.04, 6), 0.32), woodMat, birches, () => color(0x2f2b28));
        part(at(new THREE.CylinderGeometry(0.044, 0.044, 0.03, 6), 0.71), woodMat, birches, () => color(0x2f2b28));
        part(at(new THREE.IcosahedronGeometry(0.27, 0), 1.12, 0.05, 0), leafMat, birches, (p) => birchColor(p).clone());
        part(at(new THREE.IcosahedronGeometry(0.2, 0), 1.36, -0.08, 0.06), leafMat, birches, (p) => birchColor(p).clone().offsetHSL(0, 0, 0.05));
        part(at(new THREE.IcosahedronGeometry(0.18, 0), 0.96, -0.14, -0.1), leafMat, birches, (p) => birchColor(p).clone().offsetHSL(0, 0, -0.03));

        // Buissons (certains avec des baies) qui comblent le sous-bois
        const bushes = [];
        for (let tries = 0; tries < 5000 && bushes.length < (phone ? 40 : 70); tries++) {
            const x = rr(-HALF + 0.2, HALF - 0.2);
            const z = rr(-HALF + 0.2, HALF - 0.2);
            if (pondD(x, z) < 0.3 || pathD(x, z) < 0.3 || inClearing(x, z, -0.25) || nearGiantTrunk(x, z, 0.05) || deerD(x, z) < 0.4) continue;
            if (spots.some(p => Math.hypot(p.x - x, p.z - z) < 0.22 * p.s) || bushes.some(b => Math.hypot(b.x - x, b.z - z) < 0.3)) continue;
            bushes.push({ x, z, y: height(x, z) - 0.02, s: rr(0.7, 1.25), yaw: rr(0, 6.28), phase: rr(0, 6.28), berry: rand() < 0.3 });
        }
        const BUSH = [0x4a8a3c, 0x568f40, 0x3f7a36, 0x63a24a].map(color);
        const bushColor = (p) => p.c || (p.c = BUSH[Math.floor(hash(p.x * 1.7, p.z) * BUSH.length)]);
        part(at(new THREE.IcosahedronGeometry(0.2, 0).scale(1.15, 0.8, 1.05), 0.12), leafMat, bushes, (p) => bushColor(p).clone());
        part(at(new THREE.IcosahedronGeometry(0.14, 0), 0.2, 0.13, 0.05), leafMat, bushes, (p) => bushColor(p).clone().offsetHSL(0, 0, 0.05));
        part(at(new THREE.IcosahedronGeometry(0.12, 0), 0.1, -0.15, -0.06), leafMat, bushes, (p) => bushColor(p).clone().offsetHSL(0, 0, -0.03));
        const berryBushes = bushes.filter(b => b.berry);
        const berryGeo = mergeLeaf([[0.12, 0.2, 0.14], [-0.14, 0.17, 0.1], [0.04, 0.27, -0.12], [0.2, 0.12, -0.05], [-0.06, 0.24, 0.16], [-0.18, 0.1, -0.1]]
            .map(([x, y, z]) => new THREE.IcosahedronGeometry(0.025, 0).translate(x, y, z)));
        part(berryGeo, flat(WHITE, { roughness: 0.4 }), berryBushes, (p) => color(hash(p.z, p.x) < 0.6 ? 0xc8323a : 0x3b3a7a));

        const ferns = [];
        for (let tries = 0; tries < 5000 && ferns.length < (phone ? 120 : 220); tries++) {
            const x = rr(-HALF + 0.15, HALF - 0.15);
            const z = rr(-HALF + 0.15, HALF - 0.15);
            if (pondD(x, z) < 0.25 || pathD(x, z) < 0.25 || inClearing(x, z, -0.35) || nearGiantTrunk(x, z, 0) || deerD(x, z) < 0.2) continue;
            ferns.push({ x, z, y: height(x, z), s: rr(0.7, 1.35), yaw: rr(0, 6.28), phase: rr(0, 6.28) });
        }
        const fernMesh = new THREE.InstancedMesh(fernGeometry(), flat(WHITE, { side: THREE.DoubleSide }), ferns.length);
        ferns.forEach((p, i) => fernMesh.setColorAt(i, color([0x5d9a45, 0x4f8a3f, 0x6aab4e, 0x447a37][Math.floor(hash(p.x, p.z) * 4)])));
        fernMesh.receiveShadow = true;
        scene.add(fernMesh);

        const rocks = [];
        const addRock = (x, z, s) => rocks.push({ x, z, y: height(x, z) - 0.05 * s, s, yaw: rr(0, 6.28), tilt: rr(-0.3, 0.3) });
        for (let k = 0, tries = 0; k < 8 && tries < 600; tries++) {
            const x = rr(-4.8, 0.5);
            const z = rr(-0.5, 4.8);
            const d = pondD(x, z);
            if (d > -0.05 && d < 0.35) {
                addRock(x, z, rr(0.7, 1.4));
                k++;
            }
        }
        for (let k = 0, tries = 0; k < 6 && tries < 600; tries++) {
            const x = rr(-4.9, -1);
            const z = rr(1.5, 4.9);
            if (pondD(x, z) < -0.35) {
                addRock(x, z, rr(0.6, 1.2));
                k++;
            }
        }
        for (let k = 0, tries = 0; k < 10 && tries < 800; tries++) {
            const x = rr(-4.6, 4.6);
            const z = rr(-4.6, 4.6);
            if (pondD(x, z) > 0.8 && pathD(x, z) > 0.3 && !inClearing(x, z, 0) && !nearGiantTrunk(x, z, 0.1)) {
                addRock(x, z, rr(0.7, 1.6));
                k++;
            }
        }
        instanced(new THREE.DodecahedronGeometry(0.17, 0).scale(1.2, 0.7, 1), flat(WHITE, { roughness: 0.9 }), rocks, (p) => color([0x7f8a72, 0x6f7f62, 0x8a8d80, 0x5f7a52][Math.floor(hash(p.x, p.z) * 4)]), true);
        const log = new THREE.Mesh(new THREE.CylinderGeometry(0.26, 0.3, 2.1, 9), flat(0x5a4130));
        log.rotation.set(0, 0.6, Math.PI / 2 - 0.08);
        log.position.set(-1.4, height(-1.4, -1.0) + 0.22, -1.0);
        log.castShadow = true;
        log.receiveShadow = true;
        scene.add(log);
        const logMoss = new THREE.Mesh(new THREE.CylinderGeometry(0.27, 0.31, 1.5, 9, 1, true, -0.9, 1.8), flat(0x5d8f45, { side: THREE.DoubleSide }));
        logMoss.rotation.copy(log.rotation);
        logMoss.position.copy(log.position).add(V(0.04, 0.02, 0));
        scene.add(logMoss);

        const shrooms = [];
        GIANTS.forEach((g, gi) => {
            for (let k = 0; k < (phone ? 3 : 5); k++) {
                const a = rr(0, 6.28);
                const d = g.r * rr(1.25, 1.7);
                const x = clamp(g.x + Math.cos(a) * d, -4.9, 4.9);
                const z = clamp(g.z + Math.sin(a) * d, -4.9, 4.9);
                if (inClearing(x, z, -0.2)) continue;
                shrooms.push({ x, z, y: height(x, z), s: rr(0.8, 1.5), yaw: 0 });
            }
        });
        // Petits champignons au pied des arbres
        instanced(new THREE.CylinderGeometry(0.015, 0.02, 0.08, 5).translate(0, 0.04, 0), flat(0xefe8da), shrooms, null, false);
        instanced(new THREE.SphereGeometry(0.05, 7, 3, 0, Math.PI * 2, 0, Math.PI / 2).translate(0, 0.08, 0), flat(WHITE), shrooms, (p) => color(hash(p.x, p.z) < 0.5 ? 0xc0442f : 0xb98a52), false);

        // Touffes d'herbe partout sur la terre ferme
        const tufts = [];
        for (let tries = 0; tries < 6000 && tufts.length < (phone ? 180 : 340); tries++) {
            const x = rr(-HALF + 0.08, HALF - 0.08);
            const z = rr(-HALF + 0.08, HALF - 0.08);
            if (pondD(x, z) < 0.12 || pathD(x, z) < 0.12 || nearGiantTrunk(x, z, -0.1)) continue;
            tufts.push({ x, z, y: height(x, z) - 0.01, s: rr(0.6, 1.3), yaw: rr(0, 6.28), phase: rr(0, 6.28) });
        }
        const tuftMesh = new THREE.InstancedMesh(tuftGeometry(), flat(WHITE, { side: THREE.DoubleSide }), Math.max(1, tufts.length));
        const GRASS = [0x6fa64c, 0x7fb556, 0x5e9443, 0x8cbd5a].map(color);
        tufts.forEach((p, i) => tuftMesh.setColorAt(i, GRASS[Math.floor(hash(p.x * 2.3, p.z * 1.1) * GRASS.length)]));
        tuftMesh.receiveShadow = true;
        scene.add(tuftMesh);

        // Quelques souches moussues
        const stumps = [];
        for (let tries = 0; tries < 600 && stumps.length < 4; tries++) {
            const x = rr(-4.5, 4.5);
            const z = rr(-4.5, 4.5);
            if (pondD(x, z) < 0.5 || pathD(x, z) < 0.35 || inClearing(x, z, 0.1) || nearGiantTrunk(x, z, 0.2) || deerD(x, z) < 0.45) continue;
            if (spots.some(p => Math.hypot(p.x - x, p.z - z) < 0.35) || stumps.some(p => Math.hypot(p.x - x, p.z - z) < 1.5)) continue;
            stumps.push({ x, z, y: height(x, z) - 0.02, s: rr(0.8, 1.2), yaw: rr(0, 6.28) });
        }
        instanced(new THREE.CylinderGeometry(0.13, 0.17, 0.22, 8).translate(0, 0.11, 0), flat(0x6a4a33), stumps, null, true);
        instanced(new THREE.CylinderGeometry(0.11, 0.11, 0.012, 8).translate(0, 0.226, 0), flat(0xc9a676), stumps, null, false);
        instanced(new THREE.SphereGeometry(0.1, 6, 3, 0, Math.PI * 2, 0, Math.PI / 2).scale(1.2, 0.5, 1).translate(0.06, 0.2, 0.02), flat(0x5d8f45), stumps, null, false);

        // --- Étang : plantes, roseaux, nénuphars, poissons ---
        const weeds = [];
        for (let tries = 0; tries < 900 && weeds.length < (phone ? 10 : 16); tries++) {
            const x = rr(-4.95, -1);
            const z = rr(1.5, 4.95);
            if (pondD(x, z) < -0.35) weeds.push({ x, z, y: height(x, z), s: rr(0.6, 1.3), phase: rr(0, 6.28) });
        }
        const weedMesh = new THREE.InstancedMesh(new THREE.ConeGeometry(0.035, 0.5, 4).translate(0, 0.25, 0), flat(WHITE), Math.max(1, weeds.length));
        weeds.forEach((p, i) => weedMesh.setColorAt(i, color(hash(p.x, p.z) < 0.5 ? 0x3f8f5a : 0x5aa865)));
        scene.add(weedMesh);

        const reeds = [];
        const shore = [];
        for (let tries = 0; tries < 4000 && shore.length < 5; tries++) {
            const x = rr(-4.85, -0.5);
            const z = rr(1.0, 4.85);
            if (Math.abs(pondD(x, z) - 0.12) < 0.06 && !shore.some(([sx, sz]) => Math.hypot(sx - x, sz - z) < 1.0)) shore.push([x, z]);
        }
        shore.forEach(([sx, sz]) => {
            const n = 5 + Math.floor(rand() * 5);
            for (let k = 0; k < n; k++) {
                const x = clamp(sx + rr(-0.25, 0.25), -4.95, 4.95);
                const z = clamp(sz + rr(-0.25, 0.25), -4.95, 4.95);
                reeds.push({ x, z, y: height(x, z) - 0.02, s: rr(0.8, 1.25), h: rr(0.35, 0.75), yaw: rr(0, 6.28), phase: rr(0, 6.28), cat: rand() < 0.45 });
            }
        });
        const reedMesh = new THREE.InstancedMesh(new THREE.CylinderGeometry(0.011, 0.016, 1, 4).translate(0, 0.5, 0), flat(0x6f9a46), Math.max(1, reeds.length));
        reedMesh.castShadow = true;
        scene.add(reedMesh);
        const cats = reeds.filter(r => r.cat);
        const catMesh = new THREE.InstancedMesh(new THREE.CapsuleGeometry(0.026, 0.09, 2, 5), flat(0x6b4426), Math.max(1, cats.length));
        scene.add(catMesh);

        const pads = [];
        for (let tries = 0; tries < 900 && pads.length < 6; tries++) {
            const x = rr(-4.7, -1);
            const z = rr(1.5, 4.7);
            if (pondD(x, z) < -0.3 && !pads.some(p => Math.hypot(p.x - x, p.z - z) < 0.45)) pads.push({ x, z, s: rr(0.75, 1.25), yaw: rr(0, 6.28), phase: rr(0, 6.28) });
        }
        const padGeo = new THREE.CircleGeometry(0.17, 12, 0.35, Math.PI * 2 - 0.7);
        padGeo.rotateX(-Math.PI / 2);
        const padMesh = new THREE.InstancedMesh(padGeo, flat(0x5d9f45, { side: THREE.DoubleSide }), Math.max(1, pads.length));
        scene.add(padMesh);

        const fishes = [];
        const fishBody = new THREE.IcosahedronGeometry(0.075, 0).scale(0.75, 0.9, 1.7);
        const fishTail = new THREE.ConeGeometry(0.05, 0.09, 4).rotateX(-Math.PI / 2).translate(0, 0, -0.16);
        const FISH = [0xf28a3a, 0xf3c34c, 0xe9643d, 0xfff1dc];
        [[-3.8, 3.8, 0.75, 0.7], [-3.6, 3.6, 0.9, 0.8], [-2.6, 4.3, 0.55, 0.4], [-4.1, 3.1, 0.45, 0.6]].slice(0, phone ? 3 : 4).forEach(([cx, cz, rx, rz], i) => {
            const f = new THREE.Group();
            const mat = flat(FISH[i % FISH.length]);
            const tail = new THREE.Mesh(fishTail, mat);
            f.add(new THREE.Mesh(fishBody, mat), tail);
            f.scale.setScalar(rr(1.2, 1.6));
            scene.add(f);
            let bed = -Infinity;
            for (let k = 0; k < 32; k++) {
                const a = (k / 32) * Math.PI * 2;
                bed = Math.max(bed, height(cx + rx * Math.cos(a), cz + rz * Math.sin(a)));
            }
            fishes.push({ g: f, tail, cx, cz, rx, rz, y: Math.min(WATER - 0.18, Math.max(rr(-0.85, -0.55), bed + 0.16)), a: rr(0, 6.28), speed: rr(0.35, 0.6) * (i % 2 ? 1 : -1), boost: 0, phase: rr(0, 6.28) });
        });

        // --- Des fleurs dans la clairière et le long du chemin ---
        const flowers = [];
        for (let tries = 0; tries < 3000 && flowers.length < (phone ? 45 : 80); tries++) {
            const x = rr(-HALF + 0.2, HALF - 0.2);
            const z = rr(-HALF + 0.2, HALF - 0.2);
            const near = Math.hypot(x - CLEAR.x, z - CLEAR.z) < 2.3 || pathD(x, z) < 0.6;
            if (!near || pondD(x, z) < 0.2 || pathD(x, z) < 0.18 || nearGiantTrunk(x, z, 0)) continue;
            flowers.push({ x, z, y: height(x, z), s: rr(0.8, 1.3), yaw: rr(0, 6.28), phase: rr(0, 6.28) });
        }
        const FLOWER = [0xfff6e0, 0xf6d24a, 0xc79be8, 0xf2a3c0, 0xffffff].map(color);
        const stemMesh = new THREE.InstancedMesh(new THREE.CylinderGeometry(0.006, 0.008, 0.14, 4).translate(0, 0.07, 0), flat(0x5c8f3e), Math.max(1, flowers.length));
        const bloomMesh = new THREE.InstancedMesh(new THREE.IcosahedronGeometry(0.032, 0).scale(1, 0.55, 1).translate(0, 0.145, 0), flat(WHITE, { roughness: 0.6 }), Math.max(1, flowers.length));
        flowers.forEach((p, i) => bloomMesh.setColorAt(i, FLOWER[Math.floor(hash(p.x * 3.1, p.z) * FLOWER.length)]));
        bloomMesh.castShadow = true;
        scene.add(stemMesh, bloomMesh);

        // --- La laie et ses marcassins ---
        // Ils font le tour de la clairière : elle avance tranquillement, s'arrête pour
        // fouiller la terre avec son groin, et les petits la suivent en file en trottinant.
        const loopPts = [];
        for (let k = 0; k < 9; k++) {
            const a = (k / 9) * Math.PI * 2;
            const r = 1.2 + 0.22 * Math.sin(a * 2 + 1);
            loopPts.push(V(CLEAR.x + Math.cos(a) * r * 1.15, 0, CLEAR.z + Math.sin(a) * r));
        }
        const trail = new THREE.CatmullRomCurve3(loopPts, true, 'centripetal');
        const trailLen = trail.getLength();
        const BRISTLE = [0x3b3029, 0x46392f, 0x342a24].map(color);
        const PIGLET = [color(0xa36e40), color(0xe8d2a2), color(0x8a5a33)];
        const snoutMat = flat(0x7c645b);
        const hoofMat = flat(0x2a221d);
        const tuskMat = flat(0xf0e8d6);
        const eyeMat = new THREE.MeshBasicMaterial({ color: 0x120c0a });
        function makeBoar(baby) {
            const g = new THREE.Group();
            const body = new THREE.Group();
            g.add(body);
            // Le corps : plus haut aux épaules qu'à la croupe ; les petits ont des rayures claires
            const bodyGeo = new THREE.IcosahedronGeometry(0.2, 1).scale(0.85, 0.8, 1.45);
            const bpos = bodyGeo.attributes.position;
            for (let i = 0; i < bpos.count; i++) {
                const y = bpos.getY(i);
                if (y > 0) bpos.setY(i, y * (1 + 0.22 * clamp(bpos.getZ(i) / 0.29, -1, 1)));
            }
            const bcol = new Float32Array(bpos.count * 3);
            for (let f = 0; f < bpos.count; f += 3) {
                const cx = (bpos.getX(f) + bpos.getX(f + 1) + bpos.getX(f + 2)) / 3;
                const cy = (bpos.getY(f) + bpos.getY(f + 1) + bpos.getY(f + 2)) / 3;
                const cz = (bpos.getZ(f) + bpos.getZ(f + 1) + bpos.getZ(f + 2)) / 3;
                if (baby) {
                    const band = Math.floor((Math.atan2(cy, cx) + Math.PI) / (Math.PI / 6));
                    tmp.copy(cy < -0.06 ? PIGLET[0] : band % 2 ? PIGLET[1] : PIGLET[cy > 0.12 ? 2 : 0]);
                } else {
                    tmp.copy(BRISTLE[Math.floor(hash(cx * 9 + cz, cy * 7) * 3)]);
                    if (cy < -0.08) tmp.offsetHSL(0, 0, 0.04);
                }
                for (let k = 0; k < 3; k++) tmp.toArray(bcol, (f + k) * 3);
            }
            bodyGeo.setAttribute('color', new THREE.BufferAttribute(bcol, 3));
            bodyGeo.computeVertexNormals();
            body.add(new THREE.Mesh(bodyGeo, new THREE.MeshStandardMaterial({ vertexColors: true, flatShading: true, roughness: 0.95 })));
            const furMat = flat(baby ? 0x8a5a33 : 0x2f2621);
            if (!baby) {
                // Crinière de soies sur le dos
                for (let k = 0; k < 6; k++) {
                    const z = 0.2 - k * 0.075;
                    const spike = new THREE.Mesh(new THREE.ConeGeometry(0.025, 0.07, 4), furMat);
                    spike.position.set(0, 0.17 + 0.035 * clamp(z / 0.29, -1, 1) + 0.01, z);
                    spike.rotation.x = -0.5;
                    body.add(spike);
                }
            }
            // La tête : un groin conique qui pointe vers l'avant
            const head = new THREE.Group();
            head.position.set(0, 0.05, 0.25);
            body.add(head);
            const hs = baby ? 1.25 : 1;
            const skull = new THREE.Mesh(new THREE.CylinderGeometry(0.045, 0.11, 0.26, 7).rotateX(Math.PI / 2).translate(0, -0.02, 0.1), baby ? flat(0x9c683c) : furMat);
            skull.scale.setScalar(hs);
            head.add(skull);
            const plate = new THREE.Mesh(new THREE.CylinderGeometry(0.045, 0.045, 0.02, 8).rotateX(Math.PI / 2), snoutMat);
            plate.position.set(0, -0.02 * hs, 0.235 * hs);
            head.add(plate);
            [-1, 1].forEach((sd) => {
                const eye = new THREE.Mesh(new THREE.SphereGeometry(0.014 * hs, 5, 4), eyeMat);
                eye.position.set(sd * 0.055 * hs, 0.035 * hs, 0.06 * hs);
                head.add(eye);
                const ear = new THREE.Mesh(new THREE.ConeGeometry(0.03 * hs, 0.08 * hs, 4), furMat);
                ear.position.set(sd * 0.06 * hs, 0.085 * hs, 0.0);
                ear.rotation.set(-0.3, 0, -sd * 0.4);
                head.add(ear);
                if (!baby) {
                    const tusk = new THREE.Mesh(new THREE.ConeGeometry(0.008, 0.045, 4), tuskMat);
                    tusk.position.set(sd * 0.04, -0.01, 0.2);
                    tusk.rotation.set(-0.5, 0, sd * 0.3);
                    head.add(tusk);
                }
            });
            // Les pattes, accrochées aux hanches pour pouvoir marcher
            const legs = [[-1, 1], [1, 1], [-1, -1], [1, -1]].map(([sx, sz]) => {
                const hip = new THREE.Group();
                hip.position.set(sx * 0.09, -0.06, sz * 0.17);
                const leg = new THREE.Mesh(new THREE.CylinderGeometry(0.022, 0.026, 0.2, 5).translate(0, -0.1, 0), baby ? flat(0x8a5a33) : furMat);
                const hoof = new THREE.Mesh(new THREE.BoxGeometry(0.04, 0.025, 0.05).translate(0, -0.205, 0.008), hoofMat);
                hip.add(leg, hoof);
                body.add(hip);
                return { hip, phase: (sx * sz > 0 ? 0 : Math.PI) };
            });
            const tail = limb(V(0, 0.06, -0.28), V(0, -0.05, -0.33), 0.008, 0.005, furMat);
            body.add(tail);
            g.traverse((m) => { if (m.isMesh) { m.castShadow = true; m.receiveShadow = true; } });
            g.scale.setScalar(baby ? 0.5 : 1.25);
            scene.add(g);
            return { g, body, head, legs, tail, baby, pos: V(0, 0, 0), heading: 0, gait: 0, hop: 0, hopY: 0 };
        }
        const mom = makeBoar(false);
        const boars = [mom];
        for (let i = 0; i < (phone ? 3 : 4); i++) {
            const b = makeBoar(true);
            b.lag = 0.5 + i * 0.32;
            b.side = (i % 2 ? 1 : -1) * rr(0.04, 0.1);
            b.ph = rr(0, 6.28);
            boars.push(b);
        }
        const family = { s: rr(0, trailLen), state: 'walk', until: rr(4, 7), scare: 0, dig: 0 };
        boars.forEach((b, i) => {
            trail.getPointAt(((family.s - (b.lag || 0)) / trailLen % 1 + 1) % 1, b.pos);
        });

        // --- Une famille de cerfs : le cerf devant, la biche, puis le faon ---
        // Ils font le tour du pré, s'arrêtent pour brouter ou boire au bord de l'étang ;
        // le cerf relève souvent la tête pour surveiller. Un clic : ils se figent puis détalent.
        const deerLen = deerTrail.getLength();
        const v0 = new THREE.Vector3();
        const antlerMat = flat(0xe3d3b3);
        const deerLight = flat(0xeadcc0);
        const deerDark = flat(0x2a211c);
        function makeDeer(kind) {
            const g = new THREE.Group();
            const body = new THREE.Group();
            g.add(body);
            const coat = flat(kind === 'fawn' ? 0xb57a42 : kind === 'stag' ? 0x8d5631 : 0xa56c3c);
            const torso = new THREE.Mesh(new THREE.IcosahedronGeometry(0.16, 1).scale(0.72, 0.78, 1.6), coat);
            torso.position.y = 0.08;
            const belly = new THREE.Mesh(new THREE.IcosahedronGeometry(0.12, 1).scale(0.82, 0.55, 1.6), deerLight);
            belly.position.y = 0.025;
            const rump = new THREE.Mesh(new THREE.IcosahedronGeometry(0.06, 0).scale(1, 1, 0.5), deerLight);
            rump.position.set(0, 0.1, -0.235);
            body.add(torso, belly, rump);
            const tail = new THREE.Group();
            tail.position.set(0, 0.16, -0.25);
            tail.add(new THREE.Mesh(new THREE.ConeGeometry(0.022, 0.07, 5).translate(0, -0.035, 0), coat));
            body.add(tail);
            // Le cou pivote à l'épaule : c'est lui qui baisse la tête pour brouter
            const neck = new THREE.Group();
            neck.position.set(0, 0.13, 0.19);
            body.add(neck);
            neck.add(limb(V(0, 0, 0), V(0, 0.2, 0.08), 0.058, 0.04, coat));
            const head = new THREE.Group();
            head.position.set(0, 0.2, 0.08);
            neck.add(head);
            head.add(new THREE.Mesh(new THREE.IcosahedronGeometry(0.06, 0).scale(0.85, 0.9, 1.1), coat));
            head.add(new THREE.Mesh(new THREE.CylinderGeometry(0.026, 0.045, 0.11, 6).rotateX(Math.PI / 2).translate(0, -0.022, 0.08), coat));
            const nose = new THREE.Mesh(new THREE.SphereGeometry(0.018, 6, 4), deerDark);
            nose.position.set(0, -0.022, 0.138);
            head.add(nose);
            const ears = [-1, 1].map((sd) => {
                const eye = new THREE.Mesh(new THREE.SphereGeometry(0.011, 5, 4), eyeMat);
                eye.position.set(sd * 0.042, 0.012, 0.03);
                head.add(eye);
                const ear = new THREE.Group();
                ear.position.set(sd * 0.045, 0.045, -0.02);
                ear.rotation.z = -sd * 1.0;
                ear.add(new THREE.Mesh(new THREE.ConeGeometry(0.026, 0.085, 4).scale(1, 1, 0.5).translate(0, 0.04, 0), coat));
                head.add(ear);
                if (kind === 'stag') {
                    // Les bois : une perche et ses andouillers
                    head.add(limb(V(sd * 0.025, 0.05, -0.01), V(sd * 0.09, 0.2, -0.045), 0.012, 0.009, antlerMat));
                    head.add(limb(V(sd * 0.032, 0.07, -0.014), V(sd * 0.038, 0.1, 0.05), 0.007, 0.004, antlerMat));
                    head.add(limb(V(sd * 0.058, 0.13, -0.028), V(sd * 0.075, 0.18, 0.04), 0.008, 0.005, antlerMat));
                    head.add(limb(V(sd * 0.09, 0.2, -0.045), V(sd * 0.15, 0.27, -0.02), 0.008, 0.004, antlerMat));
                    head.add(limb(V(sd * 0.09, 0.2, -0.045), V(sd * 0.075, 0.3, -0.08), 0.007, 0.004, antlerMat));
                }
                return { ear, sd };
            });
            if (kind === 'fawn') {
                // Les taches claires du faon
                [[-0.05, 0.13], [0.05, 0.1], [-0.04, 0.0], [0.045, -0.03], [-0.05, -0.12], [0.05, -0.15], [0, 0.04]].forEach(([x, z]) => {
                    const dot = new THREE.Mesh(new THREE.SphereGeometry(0.014, 5, 3), deerLight);
                    dot.position.set(x, 0.19 - Math.abs(x) * 0.6, z);
                    body.add(dot);
                });
            }
            const legs = [[-1, 1], [1, 1], [-1, -1], [1, -1]].map(([sx, sz]) => {
                const hip = new THREE.Group();
                hip.position.set(sx * 0.065, 0.0, sz * 0.17);
                hip.add(new THREE.Mesh(new THREE.CylinderGeometry(0.014, 0.024, 0.36, 5).translate(0, -0.18, 0), coat));
                hip.add(new THREE.Mesh(new THREE.BoxGeometry(0.028, 0.03, 0.036).translate(0, -0.36, 0.006), deerDark));
                body.add(hip);
                return { hip, phase: sx * sz > 0 ? 0 : Math.PI };
            });
            g.traverse((m) => { if (m.isMesh) { m.castShadow = true; m.receiveShadow = true; } });
            const sz = kind === 'stag' ? 1.18 : kind === 'doe' ? 1.0 : 0.62;
            g.scale.setScalar(sz);
            scene.add(g);
            return { g, body, neck, head, ears, legs, tail, kind, s: sz, pos: V(0, 0, 0), heading: 0, gait: 0, move: 0, graze: 0, ph: rr(0, 6.28) };
        }
        const deer = [makeDeer('stag'), makeDeer('doe'), makeDeer('fawn')];
        deer[0].lag = 0;
        deer[0].side = 0;
        deer[1].lag = 0.75;
        deer[1].side = 0.05;
        deer[2].lag = 1.25;
        deer[2].side = -0.12;
        const herd = { s: rr(0, deerLen), state: 'walk', until: rr(4, 7), scare: 0 };
        deer.forEach((d) => {
            deerTrail.getPointAt((((herd.s - d.lag) / deerLen) % 1 + 1) % 1, d.pos);
            deerTrail.getTangentAt((((herd.s - d.lag) / deerLen) % 1 + 1) % 1, v0);
            d.heading = Math.atan2(v0.x, v0.z);
        });

        // --- Des lapins qui sautillent au bord des clairières ---
        const rabbits = [];
        [[-1.9, 2.6], [2.6, 2.75], [1.1, 3.05]].slice(0, phone ? 2 : 3).forEach(([hx, hz], i) => {
            const g = new THREE.Group();
            g.rotation.order = 'YXZ';
            const fur = flat(i % 2 ? 0xa58866 : 0x8c7055);
            const bod = new THREE.Mesh(new THREE.SphereGeometry(0.06, 7, 5).scale(0.85, 0.85, 1.15), fur);
            bod.position.y = 0.06;
            const head = new THREE.Group();
            head.position.set(0, 0.105, 0.065);
            head.add(new THREE.Mesh(new THREE.SphereGeometry(0.04, 7, 5).scale(0.9, 0.95, 1.1), fur));
            const ears = [-1, 1].map((sd) => {
                const ear = new THREE.Group();
                ear.position.set(sd * 0.016, 0.03, -0.01);
                ear.rotation.set(-0.25, 0, -sd * 0.12);
                ear.add(new THREE.Mesh(new THREE.BoxGeometry(0.018, 0.08, 0.008).translate(0, 0.04, 0), fur));
                head.add(ear);
                const eye = new THREE.Mesh(new THREE.SphereGeometry(0.008, 5, 3), eyeMat);
                eye.position.set(sd * 0.03, 0.01, 0.022);
                head.add(eye);
                return ear;
            });
            const puff = new THREE.Mesh(new THREE.SphereGeometry(0.02, 5, 4), deerLight);
            puff.position.set(0, 0.075, -0.07);
            g.add(bod, head, puff);
            g.traverse((m) => { if (m.isMesh) { m.castShadow = true; m.receiveShadow = true; } });
            g.scale.setScalar(1.15);
            scene.add(g);
            const at0 = V(hx, 0, hz);
            rabbits.push({ g, head, ears, home: at0.clone(), from: at0.clone(), to: at0.clone(), k: 1, dur: 0.28, hops: 0, rest: rr(0.5, 3), heading: rr(0, 6.28), bolt: 0, ph: rr(0, 6.28) });
        });
        function rabbitTarget(r, far) {
            for (let k = 0; k < 30; k++) {
                const a = rr(0, 6.28);
                const d = far ? rr(0.6, 1.0) : rr(0.15, 0.6);
                const x = clamp(r.home.x + Math.cos(a) * d, -4.8, 4.8);
                const z = clamp(r.home.z + Math.sin(a) * d, -4.8, 4.8);
                if (pondD(x, z) > 0.2 && !nearGiantTrunk(x, z, 0.05)) return V(x, 0, z);
            }
            return r.home.clone();
        }

        // --- Des oiseaux qui tournent au-dessus de la canopée ---
        const birds = [];
        for (let i = 0; i < (phone ? 3 : 5); i++) {
            const g = new THREE.Group();
            const mat = flat(i === 1 ? 0x41516b : 0x3a3533);
            g.add(new THREE.Mesh(new THREE.ConeGeometry(0.028, 0.13, 5).rotateX(Math.PI / 2), mat));
            if (i === 2) {
                const chest = new THREE.Mesh(new THREE.SphereGeometry(0.024, 5, 4), flat(0xd0663a));
                chest.position.set(0, -0.008, 0.03);
                g.add(chest);
            }
            const wings = [-1, 1].map((sd) => {
                const piv = new THREE.Group();
                piv.add(new THREE.Mesh(new THREE.PlaneGeometry(0.15, 0.055).rotateX(-Math.PI / 2).translate(sd * 0.075, 0, -0.005), flat(i === 1 ? 0x4c5f7e : 0x4a4441, { side: THREE.DoubleSide })));
                g.add(piv);
                return { piv, sd };
            });
            g.rotation.order = 'YXZ';
            scene.add(g);
            birds.push({ g, wings, cx: rr(-1.2, 1.2), cz: rr(-1.5, 0.8), r: rr(2.6, 3.8), h: rr(4.3, 5.4), w: rr(0.28, 0.42) * (i % 2 ? 1 : -1), a: rr(0, 6.28), ph: rr(0, 6.28) });
        }

        // --- Des papillons qui volent entre les fleurs ---
        const butterflies = [];
        const BUTTER = [0xfff2a6, 0xffffff, 0xf2953a, 0x8fb6ff, 0xf3a9cb];
        // Sous la pluie, les papillons restent à l'abri
        for (let i = 0; i < 0; i++) {
            const g = new THREE.Group();
            const mat = new THREE.MeshStandardMaterial({ color: BUTTER[i % BUTTER.length], side: THREE.DoubleSide, roughness: 0.6, emissive: BUTTER[i % BUTTER.length], emissiveIntensity: 0.15 });
            const wings = [-1, 1].map((sd) => {
                const piv = new THREE.Group();
                const w = new THREE.Mesh(new THREE.CircleGeometry(0.045, 6).scale(1, 1.25, 1).rotateX(-Math.PI / 2).translate(sd * 0.042, 0, 0), mat);
                piv.add(w);
                g.add(piv);
                return { piv, sd };
            });
            g.add(new THREE.Mesh(new THREE.CylinderGeometry(0.006, 0.006, 0.06, 4).rotateX(Math.PI / 2), flat(0x2c2622)));
            const home = flowers.length ? flowers[Math.floor(rand() * flowers.length)] : { x: CLEAR.x, z: CLEAR.z };
            scene.add(g);
            butterflies.push({ g, wings, hx: home.x, hz: home.z, ph: rr(0, 6.28), sp: rr(0.25, 0.45), r: rr(0.5, 1.2) });
        }

        // --- Rayons de soleil à travers la canopée ---
        const sunDir = sun.position.clone().normalize();
        const rays = [];
        const rayGeo = new THREE.PlaneGeometry(1, 1);
        [[CLEAR.x + 0.3, CLEAR.z - 0.3, 1.0], [CLEAR.x - 1.2, CLEAR.z + 0.5, 0.65], [2.4, -0.4, 0.75], [-1.6, -0.6, 0.6], [2.4, 2.8, 0.65]].slice(0, 0).forEach(([x, z, w], i) => {
            const len = 7.5;
            const foot = V(x, height(x, z), z);
            const mat = new THREE.ShaderMaterial({
                uniforms: { uTime: uniforms.uTime, uSeed: { value: i * 1.7 } },
                vertexShader: 'varying vec2 vUv;\nvoid main() { vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }',
                fragmentShader: `uniform float uTime;
uniform float uSeed;
varying vec2 vUv;
void main() {
    float across = smoothstep(0.0, 0.5, vUv.x) * smoothstep(1.0, 0.5, vUv.x);
    float along = smoothstep(0.0, 0.3, vUv.y) * smoothstep(1.0, 0.45, vUv.y);
    float flick = 0.75 + 0.25 * sin(uTime * 0.6 + uSeed + vUv.y * 2.5);
    gl_FragColor = vec4(vec3(1.0, 0.93, 0.7), pow(across, 1.6) * along * flick * 0.13);
}`,
                transparent: true,
                depthWrite: false,
                blending: THREE.AdditiveBlending,
                side: THREE.DoubleSide,
            });
            const m = new THREE.Mesh(rayGeo, mat);
            m.renderOrder = 8;
            scene.add(m);
            rays.push({ m, c: foot.clone().addScaledVector(sunDir, len / 2), w, len });
        });

        const mistTex = radialTexture('rgba(255,255,255,0.9)', 'rgba(255,255,255,0)');
        const mists = [];
        for (let i = 0; i < (phone ? 7 : 12); i++) {
            const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: mistTex, color: 0xa9bdb6, transparent: true, opacity: 0.2, depthWrite: false, fog: false }));
            const x = rr(-4, 4);
            const z = rr(-4, 4);
            sp.scale.set(rr(2.5, 4), rr(0.9, 1.4), 1);
            sp.position.set(x, Math.max(WATER, height(x, z)) + rr(0.25, 0.9), z);
            scene.add(sp);
            mists.push({ sp, x, z, ph: rr(0, 6.28) });
        }

        // --- Particules ---
        const pointScale = { value: 1 };
        const pollen = particles(phone ? 40 : 70, true);
        const dirt = particles(40, false);
        const bubbles = particles(phone ? 12 : 18, false);
        pollen.items.forEach((p) => Object.assign(p, { ox: rr(-4.6, 4.6), oz: rr(-4.6, 4.6), oy: rr(0.3, 3.2), ph: rr(0, 6.28), sp: rr(0.15, 0.35) }));
        dirt.items.forEach((p) => { p.life = 1; });
        bubbles.items.forEach((p) => resetBubble(p, true));
        // Petites mottes de terre que les groins envoient en l'air
        function dirtAt(at, n = 4, power = 1) {
            let k = 0;
            dirt.items.forEach((p) => {
                if (k >= n || p.life < 1) return;
                k++;
                p.life = 0;
                p.from = at.clone();
                p.vel = V(rr(-0.35, 0.35), rr(0.35, 0.8), rr(-0.35, 0.35)).multiplyScalar(power);
                p.c = [[0.36, 0.26, 0.17], [0.45, 0.33, 0.21], [0.3, 0.22, 0.15]][k % 3];
            });
        }
        function resetBubble(p, anywhere) {
            for (let k = 0; k < 40; k++) {
                const x = rr(-4.9, -1);
                const z = rr(1.5, 4.9);
                if (pondD(x, z) < -0.3) {
                    p.x = x;
                    p.z = z;
                    p.y0 = height(x, z) + 0.05;
                    break;
                }
            }
            p.y = anywhere ? rr(p.y0 || -1, WATER) : p.y0;
            p.sp = rr(0.18, 0.4);
            p.ph = rr(0, 6.28);
            p.size = rr(0.04, 0.075);
        }

        const leaves = [];
        const leafMesh = new THREE.InstancedMesh(new THREE.PlaneGeometry(0.09, 0.06), flat(WHITE, { side: THREE.DoubleSide }), phone ? 8 : 14);
        for (let i = 0; i < leafMesh.count; i++) {
            const l = { i };
            resetLeaf(l, true);
            leaves.push(l);
            leafMesh.setColorAt(i, color([0x7fb04f, 0xc9a548, 0x5f9a45, 0xd98a3a][i % 4]));
        }
        scene.add(leafMesh);
        function resetLeaf(l, anywhere) {
            const c = crowns[Math.floor(rand() * crowns.length)];
            l.x = clamp(c.x + rr(-0.8, 0.8), -4.9, 4.9);
            l.z = clamp(c.z + rr(-0.8, 0.8), -4.9, 4.9);
            l.top = c.y - 0.5;
            l.ground = height(l.x, l.z);
            l.y = anywhere ? rr(l.ground, l.top) : l.top;
            l.sp = rr(0.25, 0.45);
            l.ph = rr(0, 6.28);
            l.rest = 0;
        }

        const rings = [];
        const ringGeo = new THREE.RingGeometry(0.9, 1, 40);
        ringGeo.rotateX(-Math.PI / 2);
        for (let i = 0; i < 32; i++) {
            const m = new THREE.Mesh(ringGeo, new THREE.MeshBasicMaterial({ color: 0xbfd8ff, transparent: true, opacity: 0, depthWrite: false, fog: false }));
            m.visible = false;
            m.renderOrder = 5;
            scene.add(m);
            rings.push({ m, t: 1, max: 0.5, dur: 1 });
        }
        // --- Pluie : des traits fins poussés par le vent, des éclaboussures au sol, des ronds sur l'étang ---
        const RAIN = phone ? 260 : 520;
        const RAIN_TOP = 8.5;
        const RAIN_SPEED = 5.5;
        const DRIFT_X = 0.12;
        const DRIFT_Z = 0.05;
        const DROP = 0.3;
        const rainPos = new Float32Array(RAIN * 6);
        const rainGeo = new THREE.BufferGeometry();
        rainGeo.setAttribute('position', new THREE.BufferAttribute(rainPos, 3));
        const rain = new THREE.LineSegments(rainGeo, new THREE.LineBasicMaterial({ color: 0xdfe8ea, transparent: true, opacity: 0.26, depthWrite: false }));
        rain.frustumCulled = false;
        rain.renderOrder = 7;
        scene.add(rain);
        const drops = Array.from({ length: RAIN }, () => ({}));
        // Chaque goutte vise un point du bloc ; le vent la fait arriver en biais
        function resetDrop(d, anywhere) {
            d.x = rr(-HALF + 0.02, HALF - 0.02);
            d.z = rr(-HALF + 0.02, HALF - 0.02);
            d.ground = height(d.x, d.z);
            d.floor = Math.max(d.ground, WATER);
            d.y = anywhere ? rr(d.floor, RAIN_TOP) : rr(RAIN_TOP - 0.5, RAIN_TOP + 1.5);
            d.sp = rr(0.85, 1.15);
        }
        drops.forEach((d) => resetDrop(d, true));
        const splash = particles(phone ? 50 : 90, false);
        splash.items.forEach((p) => { p.life = 1; });
        function splashAt(x, y, z) {
            let n = 0;
            for (const p of splash.items) {
                if (p.life < 1) continue;
                p.life = 0;
                p.from = V(x, y + 0.01, z);
                p.vel = V(rr(-0.25, 0.25), rr(0.25, 0.5), rr(-0.25, 0.25));
                if (++n >= 2) break;
            }
        }
        // Un éclair lointain de temps en temps
        const storm = { next: rr(8, 14), flash: 0 };

        function ripple(x, z, max = 0.45, dur = 1.4, delay = 0) {
            const r = rings.find(k => k.t >= 1) || rings[0];
            Object.assign(r, { t: -delay / dur, max, dur });
            r.m.position.set(x, WATER + 0.035, z);
        }

        // --- Caméra ---
        const target = V(0.25, 1.0, 0.1);
        // Vue de départ : dans le décor, à hauteur de la clairière
        const HOME_EL = 0.42;
        const HOME_ZOOM = () => (camera.aspect < 0.8 ? 0.7 : 0.54);
        let az = -0.5;
        let el = HOME_EL;
        let zoom = 0.54;
        let fit = 26;
        let lastInput = -10;
        let touched = false;
        const pointers = new Map();
        let pinch = 0;
        let downAt = null;
        const canvas = renderer.domElement;
        const onDown = (e) => {
            canvas.setPointerCapture(e.pointerId);
            pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
            if (pointers.size === 1) downAt = { x: e.clientX, y: e.clientY, t: performance.now() };
            if (pointers.size === 2) pinch = spread();
            lastInput = clock;
            touched = true;
        };
        const onMove = (e) => {
            const p = pointers.get(e.pointerId);
            if (!p) return;
            const dx = e.clientX - p.x;
            const dy = e.clientY - p.y;
            p.x = e.clientX;
            p.y = e.clientY;
            if (pointers.size === 1) {
                az -= dx * 0.0065;
                el = clamp(el + dy * 0.0045, 0.06, 1.15);
            } else if (pointers.size === 2) {
                const s = spread();
                if (pinch) zoom = clamp(zoom * pinch / s, 0.35, 1.6);
                pinch = s;
            }
            lastInput = clock;
        };
        const onUp = (e) => {
            pointers.delete(e.pointerId);
            pinch = 0;
            if (downAt && pointers.size === 0) {
                const moved = Math.hypot(e.clientX - downAt.x, e.clientY - downAt.y);
                if (moved < 7 && performance.now() - downAt.t < 400) tap(e);
            }
            downAt = null;
        };
        const onWheel = (e) => {
            e.preventDefault();
            zoom = clamp(zoom * Math.exp(e.deltaY * 0.0012), 0.35, 1.6);
            lastInput = clock;
        };
        const spread = () => {
            const [a, b] = [...pointers.values()];
            return Math.hypot(a.x - b.x, a.y - b.y) || 1;
        };
        canvas.addEventListener('pointerdown', onDown);
        canvas.addEventListener('pointermove', onMove);
        canvas.addEventListener('pointerup', onUp);
        canvas.addEventListener('pointercancel', onUp);
        canvas.addEventListener('wheel', onWheel, { passive: false });

        const ray = new THREE.Raycaster();
        const ndc = new THREE.Vector2();
        const boarTargets = [];
        boars.forEach((bo) => bo.g.traverse((m) => { if (m.isMesh) boarTargets.push(m); }));
        const deerTargets = [];
        deer.forEach((d) => d.g.traverse((m) => { if (m.isMesh) deerTargets.push(m); }));
        const rabbitTargets = [];
        rabbits.forEach((r) => r.g.traverse((m) => { if (m.isMesh) { m.userData.rabbit = r; rabbitTargets.push(m); } }));
        function tap(e) {
            const r = canvas.getBoundingClientRect();
            ndc.set(((e.clientX - r.left) / r.width) * 2 - 1, -((e.clientY - r.top) / r.height) * 2 + 1);
            ray.setFromCamera(ndc, camera);
            // Les marcassins sursautent et filent se coller à leur mère
            if (ray.intersectObjects(boarTargets, false).length) {
                family.scare = 2.2;
                boars.forEach((bo) => { if (bo.baby) bo.hop = 1; });
                dirtAt(mom.g.position.clone().add(V(0, 0.05, 0)), 8, 1.2);
                return;
            }
            // Les cerfs se figent, la tête haute, puis s'enfuient en bondissant
            if (ray.intersectObjects(deerTargets, false).length) {
                if (herd.scare <= 0) herd.scare = 3.4;
                return;
            }
            // Un lapin touché détale, et ceux d'à côté aussi
            const hitRabbit = ray.intersectObjects(rabbitTargets, false)[0];
            if (hitRabbit) {
                const r0 = hitRabbit.object.userData.rabbit;
                rabbits.forEach((r) => {
                    if (r === r0 || Math.hypot(r.g.position.x - r0.g.position.x, r.g.position.z - r0.g.position.z) < 1.6) {
                        r.bolt = 2.5;
                        r.rest = 0;
                        r.hops = 0;
                    }
                });
                return;
            }
            const w = ray.intersectObject(water)[0];
            if (!w || height(w.point.x, w.point.z) > WATER - 0.03) return;
            const { x, z } = w.point;
            ripple(x, z, 0.55, 1.5);
            ripple(x, z, 0.38, 1.3, 0.22);
            ripple(x, z, 0.22, 1.1, 0.42);
            fishes.forEach((f) => {
                if (Math.hypot(f.g.position.x - x, f.g.position.z - z) < 1.6) f.boost = 3.2;
            });
        }

        function resize() {
            const w = stage.clientWidth || 1;
            const h = stage.clientHeight || 1;
            renderer.setSize(w, h, false);
            camera.aspect = w / h;
            const tanV = Math.tan(THREE.MathUtils.degToRad(camera.fov / 2));
            fit = Math.max(16.4 / tanV / 2, (camera.aspect < 0.8 ? 14 : 15.6) / (tanV * camera.aspect) / 2);
            if (!touched) zoom = HOME_ZOOM();
            camera.updateProjectionMatrix();
            pointScale.value = camera.projectionMatrix.elements[5] * renderer.domElement.height / 2;
        }
        const ro = new ResizeObserver(resize);
        ro.observe(stage);
        resize();

        // --- Boucle ---
        const m4 = new THREE.Matrix4();
        const q = new THREE.Quaternion();
        const qYaw = new THREE.Quaternion();
        const v3 = new THREE.Vector3();
        const v4 = new THREE.Vector3();
        const sc = new THREE.Vector3();
        const up = new THREE.Vector3(0, 1, 0);
        const windAxis = new THREE.Vector3(1, 0, 0.3).normalize();
        const euler = new THREE.Euler();
        const basis = new THREE.Matrix4();
        const still = calm();
        let clock = 0;
        let last = performance.now();
        let raf = 0;
        let alive = true;

        function frame(now) {
            if (!alive) return;
            const real = Math.min(0.25, (now - last) / 1000);
            const dt = Math.min(0.05, real);
            last = now;
            clock += dt;
            const t = clock;
            uniforms.uTime.value = t;


            // Au repos : tour complet et lent, en revenant doucement à la hauteur de départ
            if (!still && !pointers.size) {
                const idle = clamp((clock - lastInput - 3) / 2, 0, 1);
                const ease = idle * idle * (3 - 2 * idle);
                az += IDLE_SPIN * dt * ease;
                el += (HOME_EL - el) * Math.min(1, dt * 0.8) * ease;
            }
            const dist = fit * zoom;
            camera.position.set(target.x + dist * Math.cos(el) * Math.sin(az), target.y + dist * Math.sin(el), target.z + dist * Math.cos(el) * Math.cos(az));
            camera.lookAt(target);
            scene.fog.near = dist - 2;
            scene.fog.far = dist + 22;

            for (const i of waves) {
                const x = wp.getX(i);
                const z = wp.getZ(i);
                wp.setY(i, 0.022 * Math.sin(x * 2.2 + t * 1.3) * Math.cos(z * 1.8 - t * 1.05) + 0.011 * Math.sin((x + z) * 4.3 + t * 2.1));
            }
            wp.needsUpdate = true;
            waterGeo.computeVertexNormals();

            parts.forEach(({ mesh, list, sway }) => {
                list.forEach((p, i) => {
                    q.setFromAxisAngle(windAxis, (Math.sin(t * 1.25 + p.phase) * 0.03 + Math.sin(t * 2.9 + p.phase * 2) * 0.008) * sway);
                    qYaw.setFromAxisAngle(up, p.yaw);
                    q.multiply(qYaw);
                    m4.compose(v3.set(p.x, p.y, p.z), q, sc.setScalar(p.s));
                    mesh.setMatrixAt(i, m4);
                });
                mesh.instanceMatrix.needsUpdate = true;
            });
            ferns.forEach((p, i) => {
                q.setFromAxisAngle(windAxis, Math.sin(t * 1.4 + p.phase) * 0.07);
                qYaw.setFromAxisAngle(up, p.yaw);
                q.multiply(qYaw);
                m4.compose(v3.set(p.x, p.y, p.z), q, sc.setScalar(p.s));
                fernMesh.setMatrixAt(i, m4);
            });
            fernMesh.instanceMatrix.needsUpdate = true;
            tufts.forEach((p, i) => {
                q.setFromAxisAngle(windAxis, Math.sin(t * 1.8 + p.phase) * 0.12);
                qYaw.setFromAxisAngle(up, p.yaw);
                q.multiply(qYaw);
                m4.compose(v3.set(p.x, p.y, p.z), q, sc.setScalar(p.s));
                tuftMesh.setMatrixAt(i, m4);
            });
            tuftMesh.instanceMatrix.needsUpdate = true;
            reeds.forEach((p, i) => {
                q.setFromAxisAngle(windAxis, Math.sin(t * 1.6 + p.phase) * 0.09);
                qYaw.setFromAxisAngle(up, p.yaw);
                q.multiply(qYaw);
                m4.compose(v3.set(p.x, p.y, p.z), q, sc.set(p.s, p.h, p.s));
                reedMesh.setMatrixAt(i, m4);
            });
            reedMesh.instanceMatrix.needsUpdate = true;
            cats.forEach((p, i) => {
                const a = Math.sin(t * 1.6 + p.phase) * 0.09;
                v4.set(0, p.h - 0.04, 0).applyAxisAngle(windAxis, a).add(v3.set(p.x, p.y, p.z));
                q.setFromAxisAngle(windAxis, a);
                m4.compose(v4, q, sc.setScalar(1));
                catMesh.setMatrixAt(i, m4);
            });
            catMesh.instanceMatrix.needsUpdate = true;
            weeds.forEach((p, i) => {
                q.setFromAxisAngle(windAxis, Math.sin(t * 0.9 + p.phase) * 0.18);
                m4.compose(v3.set(p.x, p.y, p.z), q, sc.set(1, p.s, 1));
                weedMesh.setMatrixAt(i, m4);
            });
            weedMesh.instanceMatrix.needsUpdate = true;
            pads.forEach((p, i) => {
                qYaw.setFromAxisAngle(up, p.yaw + Math.sin(t * 0.3 + p.phase) * 0.15);
                m4.compose(v3.set(p.x, WATER + 0.03 + Math.sin(t * 1.3 + p.phase) * 0.008, p.z), qYaw, sc.setScalar(p.s));
                padMesh.setMatrixAt(i, m4);
            });
            padMesh.instanceMatrix.needsUpdate = true;

            fishes.forEach((f) => {
                f.boost = Math.max(0, f.boost - dt * 1.6);
                f.a += f.speed * (1 + f.boost) * dt;
                const x = f.cx + f.rx * Math.cos(f.a);
                const z = f.cz + f.rz * Math.sin(f.a);
                f.g.position.set(x, f.y + Math.sin(t * 1.3 + f.phase) * 0.04, z);
                f.g.rotation.y = Math.atan2(-f.rx * Math.sin(f.a) * Math.sign(f.speed), f.rz * Math.cos(f.a) * Math.sign(f.speed));
                f.tail.rotation.y = Math.sin(t * (9 + f.boost * 8) + f.phase) * 0.45;
            });
            rings.forEach((r) => {
                if (r.t >= 1) {
                    r.m.visible = false;
                    return;
                }
                r.t += dt / r.dur;
                if (r.t < 0) return;
                const k = Math.min(1, r.t);
                r.m.visible = true;
                r.m.scale.setScalar(0.04 + r.max * easeOut(k));
                r.m.material.opacity = (1 - k) * 0.5;
            });

            // Fleurs qui bougent dans le vent
            flowers.forEach((p, i) => {
                q.setFromAxisAngle(windAxis, Math.sin(t * 1.5 + p.phase) * 0.12);
                m4.compose(v3.set(p.x, p.y, p.z), q, sc.setScalar(p.s));
                stemMesh.setMatrixAt(i, m4);
                bloomMesh.setMatrixAt(i, m4);
            });
            stemMesh.instanceMatrix.needsUpdate = true;
            bloomMesh.instanceMatrix.needsUpdate = true;

            // La laie avance, s'arrête, fouille ; les marcassins suivent ou jouent autour d'elle
            family.scare = Math.max(0, family.scare - dt);
            if (t > family.until) {
                family.state = family.state === 'walk' ? 'root' : 'walk';
                family.until = t + (family.state === 'walk' ? rr(5, 8) : rr(3, 5));
            }
            const walking = family.state === 'walk' || family.scare > 0;
            if (walking) family.s += dt * (family.scare > 0 ? 0.5 : 0.22);
            const u = ((family.s / trailLen) % 1 + 1) % 1;
            trail.getPointAt(u, v4);
            mom.pos.lerp(v4, Math.min(1, dt * 6));
            trail.getTangentAt(u, v3);
            const momHeading = Math.atan2(v3.x, v3.z);
            mom.heading += Math.atan2(Math.sin(momHeading - mom.heading), Math.cos(momHeading - mom.heading)) * Math.min(1, dt * 4);
            mom.gait += dt * (walking ? 7 : 0);
            family.dig = walking ? Math.max(0, family.dig - dt * 2) : Math.min(1, family.dig + dt * 1.5);
            // Fouiller : la tête plonge et remonte, et des mottes de terre volent
            mom.head.rotation.x = family.dig * (0.55 + Math.sin(t * 7) * 0.15) - (family.scare > 0 ? 0.25 : 0);
            if (family.dig > 0.8 && Math.sin(t * 7) > 0.95 && rand() < 0.5) {
                v3.set(Math.sin(mom.heading) * 0.42, 0.04, Math.cos(mom.heading) * 0.42).add(mom.g.position);
                v3.y = height(v3.x, v3.z) + 0.03;
                dirtAt(v3, 3, 0.7);
            }
            boars.forEach((b, i) => {
                if (b.baby) {
                    // Où le petit veut aller : derrière sa mère en file, ou tout autour quand elle fouille
                    if (walking) {
                        trail.getPointAt((((family.s - b.lag) / trailLen) % 1 + 1) % 1, v4);
                        trail.getTangentAt((((family.s - b.lag) / trailLen) % 1 + 1) % 1, v3);
                        v4.x += v3.z * b.side;
                        v4.z -= v3.x * b.side;
                    } else {
                        const a = b.ph + t * 0.35 * (i % 2 ? 1 : -1);
                        const rad = 0.45 + 0.12 * Math.sin(t * 0.8 + b.ph);
                        v4.set(mom.pos.x + Math.cos(a) * rad, 0, mom.pos.z + Math.sin(a) * rad);
                    }
                    v3.subVectors(v4, b.pos);
                    v3.y = 0;
                    const d = v3.length();
                    const maxSp = family.scare > 0 ? 1.1 : 0.55;
                    const step = Math.min(d, maxSp * dt);
                    if (d > 1e-4) {
                        b.pos.addScaledVector(v3, step / d);
                        if (d > 0.02) {
                            const want = Math.atan2(v3.x, v3.z);
                            b.heading += Math.atan2(Math.sin(want - b.heading), Math.cos(want - b.heading)) * Math.min(1, dt * 6);
                        }
                    }
                    b.gait += (step / Math.max(dt, 1e-4)) * dt * 30;
                    // Petit saut quand on les surprend
                    b.hop = Math.max(0, b.hop - dt * 2.2);
                    b.hopY = Math.sin((1 - b.hop) * Math.PI) * 0.12 * (b.hop > 0 ? 1 : 0);
                    b.head.rotation.x = walking ? Math.sin(t * 3 + b.ph) * 0.08 : 0.25 + Math.sin(t * 5 + b.ph) * 0.2;
                }
                const ground = height(b.pos.x, b.pos.z);
                const s = b.baby ? 0.5 : 1.25;
                const bob = Math.abs(Math.sin(b.gait)) * 0.012 * s;
                b.g.position.set(b.pos.x, ground + 0.262 * s + bob + (b.hopY || 0), b.pos.z);
                b.g.rotation.y = b.heading;
                const swing = Math.min(1, b.baby ? 1 : (walking ? 1 : 0)) * 0.45;
                b.legs.forEach((l) => { l.hip.rotation.x = Math.sin(b.gait + l.phase) * swing; });
                b.tail.rotation.z = Math.sin(t * (b.baby ? 9 : 4) + i) * 0.4;
            });

            // Les cerfs : marche, broutage, alerte puis fuite
            herd.scare = Math.max(0, herd.scare - dt);
            const alert = herd.scare > 2.6;
            const fleeing = herd.scare > 0 && !alert;
            if (t > herd.until && herd.scare <= 0) {
                herd.state = herd.state === 'walk' ? 'graze' : 'walk';
                herd.until = t + (herd.state === 'walk' ? rr(5, 9) : rr(4, 7));
            }
            const herdSpeed = alert ? 0 : fleeing ? 0.95 * Math.min(1, herd.scare) + 0.2 : herd.state === 'walk' ? 0.2 : 0;
            herd.s += dt * herdSpeed;
            deer.forEach((d, i) => {
                const u = (((herd.s - d.lag) / deerLen) % 1 + 1) % 1;
                deerTrail.getPointAt(u, v4);
                deerTrail.getTangentAt(u, v3);
                v4.x += v3.z * d.side;
                v4.z -= v3.x * d.side;
                d.pos.lerp(v4, Math.min(1, dt * 5));
                const want = Math.atan2(v3.x, v3.z);
                d.heading += Math.atan2(Math.sin(want - d.heading), Math.cos(want - d.heading)) * Math.min(1, dt * 3);
                d.move += ((herdSpeed > 0 ? 1 : 0) - d.move) * Math.min(1, dt * 4);
                d.gait += dt * herdSpeed * (fleeing ? 30 : 34) / d.s;
                // Brouter : le cou plonge vers l'herbe ; le cerf relève souvent la tête pour surveiller
                const watch = d.kind === 'stag' && Math.sin(t * 0.55 + d.ph) > 0.35;
                const wantGraze = herd.state === 'graze' && herd.scare <= 0 && !watch ? 1 : 0;
                d.graze += (wantGraze - d.graze) * Math.min(1, dt * 2.2);
                const chew = d.graze > 0.8 ? Math.sin(t * 6 + d.ph) * 0.06 : 0;
                d.neck.rotation.x = d.graze * 1.45 - (herd.scare > 0 ? 0.3 : 0) + Math.sin(t * 1.2 + d.ph) * 0.03 * (1 - d.graze);
                d.head.rotation.x = d.graze * 0.35 + chew;
                d.head.rotation.y = watch && herd.state === 'graze' ? Math.sin(t * 0.8 + d.ph) * 0.5 : 0;
                d.ears.forEach(({ ear, sd }) => {
                    const flick = Math.pow(Math.max(0, Math.sin(t * 1.1 + d.ph * 3 + sd)), 24) * 0.7;
                    ear.rotation.z = -sd * (herd.scare > 0 ? 0.55 : 1.0) + sd * flick;
                });
                const run = fleeing ? 1 : 0;
                const swing = d.move * (0.45 + run * 0.4);
                d.legs.forEach((l) => { l.hip.rotation.x = Math.sin(d.gait + l.phase + (run && l.hip.position.z < 0 ? 0.6 : 0)) * swing; });
                d.tail.rotation.x = herd.scare > 0 ? -1.3 : Math.sin(t * 2 + d.ph) * 0.15;
                const ground = height(d.pos.x, d.pos.z);
                const bound = run * Math.abs(Math.sin(d.gait)) * 0.09 * d.s + Math.abs(Math.sin(d.gait)) * 0.008 * d.s * d.move;
                d.g.position.set(d.pos.x, ground + 0.375 * d.s + bound, d.pos.z);
                d.g.rotation.y = d.heading;
                d.body.rotation.x = run * Math.sin(d.gait) * 0.08;
            });

            // Les lapins : petits bonds, pause, reniflent, repartent
            rabbits.forEach((r) => {
                r.bolt = Math.max(0, r.bolt - dt);
                if (r.k < 1) {
                    r.k = Math.min(1, r.k + dt / r.dur);
                } else if (r.hops > 0) {
                    r.hops--;
                    r.from.copy(r.g.position);
                    r.from.y = 0;
                    v3.subVectors(r.goal, r.from);
                    v3.y = 0;
                    const step = Math.min(v3.length(), r.bolt > 0 ? 0.3 : 0.16);
                    if (step < 0.02) r.hops = 0;
                    else {
                        r.heading = Math.atan2(v3.x, v3.z);
                        r.to.copy(r.from).addScaledVector(v3.normalize(), step);
                        r.k = 0;
                        r.dur = r.bolt > 0 ? 0.2 : 0.28;
                    }
                } else if (r.bolt > 0) {
                    r.goal = rabbitTarget(r, true);
                    r.hops = 6;
                } else {
                    r.rest -= dt;
                    if (r.rest <= 0) {
                        r.goal = rabbitTarget(r, false);
                        r.hops = 2 + Math.floor(rr(0, 4));
                        r.rest = rr(1.5, 4.5);
                    }
                }
                const k = r.k;
                const x = r.from.x + (r.to.x - r.from.x) * k;
                const z = r.from.z + (r.to.z - r.from.z) * k;
                const air = k < 1 ? Math.sin(k * Math.PI) : 0;
                r.g.position.set(x, height(x, z) + air * (r.bolt > 0 ? 0.1 : 0.065), z);
                r.g.rotation.y = r.heading;
                r.g.rotation.x = k < 1 ? -Math.cos(k * Math.PI) * 0.3 : 0;
                // Au repos : le museau renifle et les oreilles bougent
                r.head.rotation.x = k >= 1 ? Math.sin(t * 9 + r.ph) * 0.05 + 0.08 : -0.1;
                r.ears.forEach((ear, j) => { ear.rotation.x = -0.25 - (k < 1 ? 0.35 : Math.pow(Math.max(0, Math.sin(t * 1.4 + r.ph + j)), 20) * 0.4); });
            });

            // Les oiseaux : grands cercles, battements par moments, planés le reste du temps
            birds.forEach((b) => {
                b.a += b.w * dt;
                const x = b.cx + Math.cos(b.a) * b.r;
                const z = b.cz + Math.sin(b.a) * b.r;
                b.g.position.set(x, b.h + Math.sin(t * 0.7 + b.ph) * 0.25, z);
                b.g.rotation.y = Math.atan2(-Math.sin(b.a) * Math.sign(b.w), Math.cos(b.a) * Math.sign(b.w));
                b.g.rotation.z = -Math.sign(b.w) * 0.35;
                const flapping = Math.sin(t * 0.9 + b.ph) > -0.2;
                const flap = flapping ? Math.sin(t * 15 + b.ph) * 0.75 : 0.12;
                b.wings.forEach(({ piv, sd }) => { piv.rotation.z = sd * flap; });
            });

            // Papillons
            butterflies.forEach((bf) => {
                const k = t * bf.sp + bf.ph;
                const x = bf.hx + Math.sin(k) * bf.r;
                const z = bf.hz + Math.sin(k * 1.7 + 1) * bf.r * 0.7;
                const y = height(x, z) + 0.35 + Math.sin(k * 2.3) * 0.15 + Math.abs(Math.sin(k * 5.1)) * 0.05;
                const dx = Math.cos(k) * bf.r;
                const dz = Math.cos(k * 1.7 + 1) * 1.7 * bf.r * 0.7;
                bf.g.position.set(x, y, z);
                bf.g.rotation.y = Math.atan2(dx, dz);
                const flap = Math.sin(t * 22 + bf.ph) * 0.9;
                bf.wings.forEach(({ piv, sd }) => { piv.rotation.z = sd * (0.25 + flap); });
            });

            rays.forEach((r) => {
                v3.copy(camera.position).sub(r.c);
                v4.crossVectors(sunDir, v3).normalize();
                sc.crossVectors(v4, sunDir).normalize();
                basis.makeBasis(v4, sunDir, sc);
                r.m.quaternion.setFromRotationMatrix(basis);
                r.m.position.copy(r.c);
                r.m.scale.set(r.w, r.len, 1);
            });
            mists.forEach((m) => {
                m.sp.position.x = m.x + Math.sin(t * 0.08 + m.ph) * 0.6;
                m.sp.material.opacity = 0.17 + 0.07 * Math.sin(t * 0.3 + m.ph);
            });

            // Pollen qui flotte dans la lumière
            pollen.items.forEach((p, i) => {
                const x = p.ox + Math.sin(t * p.sp + p.ph) * 0.5;
                const z = p.oz + Math.cos(t * p.sp * 0.8 + p.ph) * 0.5;
                pollen.set(i, x, height(x, z) + p.oy + Math.sin(t * p.sp * 1.3 + p.ph * 2) * 0.25, z, 0.035, [0.78, 0.88, 0.9], 0.15 + 0.12 * Math.sin(t * 1.7 + p.ph));
            });
            pollen.update();
            dirt.items.forEach((p, i) => {
                if (p.life >= 1) {
                    dirt.set(i, 0, -50, 0, 0, [0, 0, 0], 0);
                    return;
                }
                p.life += real / 0.7;
                const k = Math.min(1, p.life);
                v3.copy(p.from).addScaledVector(p.vel, k * 0.6);
                v3.y -= k * k * 0.45;
                dirt.set(i, v3.x, v3.y, v3.z, 0.045, p.c, 1 - k * k);
            });
            dirt.update();
            bubbles.items.forEach((p, i) => {
                p.y += p.sp * dt;
                if (p.y > WATER - 0.02) {
                    if (rand() < 0.3) ripple(p.x, p.z, 0.12, 0.8);
                    resetBubble(p, false);
                }
                bubbles.set(i, p.x + Math.sin(t * 3 + p.ph) * 0.02, p.y, p.z + Math.cos(t * 2.6 + p.ph) * 0.02, p.size, [0.8, 0.9, 1], 0.6);
            });
            bubbles.update();

            // La pluie tombe ; au sol elle éclabousse, sur l'étang elle fait des ronds
            for (let i = 0; i < RAIN; i++) {
                const d = drops[i];
                d.y -= RAIN_SPEED * d.sp * dt;
                if (d.y <= d.floor) {
                    if (d.ground < WATER - 0.02) {
                        if (rand() < 0.12) ripple(d.x, d.z, rr(0.08, 0.16), 0.7);
                    } else if (rand() < 0.3) {
                        splashAt(d.x, d.floor, d.z);
                    }
                    resetDrop(d, false);
                }
                const up = d.y - d.floor;
                const x = d.x + up * DRIFT_X;
                const z = d.z + up * DRIFT_Z;
                rainPos[i * 6] = x + DROP * DRIFT_X;
                rainPos[i * 6 + 1] = d.y + DROP;
                rainPos[i * 6 + 2] = z + DROP * DRIFT_Z;
                rainPos[i * 6 + 3] = x;
                rainPos[i * 6 + 4] = d.y;
                rainPos[i * 6 + 5] = z;
            }
            rainGeo.attributes.position.needsUpdate = true;
            splash.items.forEach((p, i) => {
                if (p.life >= 1) {
                    splash.set(i, 0, -50, 0, 0, [0, 0, 0], 0);
                    return;
                }
                p.life += real / 0.35;
                const k = Math.min(1, p.life);
                v3.copy(p.from).addScaledVector(p.vel, k * 0.35);
                v3.y -= k * k * 0.12;
                splash.set(i, v3.x, v3.y, v3.z, 0.03, [0.85, 0.92, 0.95], (1 - k) * 0.7);
            });
            splash.update();

            // Éclair lointain : deux lueurs rapides qui éclairent la scène et le fond
            if (!still && t > storm.next) {
                storm.flash = 1;
                storm.next = t + rr(32, 55);
            }
            storm.flash = Math.max(0, storm.flash - dt * 0.7);
            const fl = storm.flash;
            const glow = Math.sin(fl * Math.PI) * 0.35;
            hemi.intensity = HEMI + glow * 0.9;
            stage.style.setProperty('--flash', glow.toFixed(3));

            leaves.forEach((l) => {
                if (l.rest > 0) {
                    l.rest -= dt;
                    if (l.rest <= 0) resetLeaf(l, false);
                } else {
                    l.y -= l.sp * dt;
                    l.x += Math.sin(t * 1.7 + l.ph) * 0.004;
                    l.z += Math.cos(t * 1.3 + l.ph) * 0.003;
                    const floor = Math.max(l.ground, WATER) + 0.02;
                    if (l.y <= floor) {
                        l.y = floor;
                        l.rest = rr(1.5, 3.5);
                    }
                }
                const spin = l.rest > 0 ? 0 : t * 2.2 + l.ph;
                q.setFromEuler(euler.set(l.rest > 0 ? -Math.PI / 2 : Math.sin(spin) * 1.2, spin, Math.cos(spin * 0.7) * 0.8));
                m4.compose(v3.set(l.x, l.y, l.z), q, sc.setScalar(l.rest > 0 ? Math.min(1, l.rest) : 1));
                leafMesh.setMatrixAt(l.i, m4);
            });
            leafMesh.instanceMatrix.needsUpdate = true;

            renderer.render(scene, camera);
            raf = requestAnimationFrame(frame);
        }
        raf = requestAnimationFrame(frame);

        return {
            dispose() {
                alive = false;
                stage.style.removeProperty('--flash');
                cancelAnimationFrame(raf);
                ro.disconnect();
                canvas.removeEventListener('wheel', onWheel);
                scene.traverse((o) => {
                    if (o.geometry) o.geometry.dispose();
                    if (o.material) {
                        [].concat(o.material).forEach((m) => {
                            Object.values(m).forEach((v) => { if (v && v.isTexture) v.dispose(); });
                            m.dispose();
                        });
                    }
                });
                renderer.dispose();
                canvas.remove();
            },
        };

        // ---------------- Outils de la scène ----------------
        function instanced(geo, mat, list, tint, shadow) {
            const m = new THREE.InstancedMesh(geo, mat, Math.max(1, list.length));
            m.count = list.length;
            const rot = new THREE.Quaternion();
            const yAxis = new THREE.Vector3(0, 1, 0);
            const xAxis = new THREE.Vector3(1, 0, 0);
            list.forEach((p, i) => {
                rot.setFromAxisAngle(yAxis, p.yaw || 0);
                if (p.tilt) rot.multiply(new THREE.Quaternion().setFromAxisAngle(xAxis, p.tilt));
                m.setMatrixAt(i, new THREE.Matrix4().compose(new THREE.Vector3(p.x, p.y, p.z), rot, new THREE.Vector3(p.s, p.s, p.s)));
                if (tint) m.setColorAt(i, tint(p, i));
            });
            m.castShadow = !!shadow;
            m.receiveShadow = true;
            scene.add(m);
            return m;
        }

        function limb(a, b, r1, r2, mat) {
            const dir = new THREE.Vector3().subVectors(b, a);
            const len = dir.length();
            const m = new THREE.Mesh(new THREE.CylinderGeometry(r2, r1, len, 7), mat);
            m.position.copy(a).addScaledVector(dir, 0.5);
            m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
            return m;
        }

        function taperedTube(curve, r0, r1) {
            const segs = 12;
            const rad = 6;
            const g = new THREE.TubeGeometry(curve, segs, 1, rad, false);
            const pos = g.attributes.position;
            const p = new THREE.Vector3();
            const c = new THREE.Vector3();
            for (let i = 0; i <= segs; i++) {
                curve.getPointAt(i / segs, c);
                const r = lerp(r0, r1, i / segs);
                for (let j = 0; j <= rad; j++) {
                    const k = i * (rad + 1) + j;
                    p.fromBufferAttribute(pos, k).sub(c).multiplyScalar(r).add(c);
                    pos.setXYZ(k, p.x, p.y, p.z);
                }
            }
            g.computeVertexNormals();
            return g;
        }

        // Réunit plusieurs petites géométries en une seule (positions + normales)
        function mergeLeaf(geos) {
            const pos = [];
            const nor = [];
            geos.forEach((g) => {
                const n = g.index ? g.toNonIndexed() : g;
                n.computeVertexNormals();
                pos.push(...n.attributes.position.array);
                nor.push(...n.attributes.normal.array);
                if (n !== g) n.dispose();
                g.dispose();
            });
            const out = new THREE.BufferGeometry();
            out.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
            out.setAttribute('normal', new THREE.Float32BufferAttribute(nor, 3));
            return out;
        }

        // Une touffe : cinq brins fins qui partent en étoile
        function tuftGeometry() {
            const pos = [];
            for (let k = 0; k < 5; k++) {
                const a = k * 1.257 + 0.3;
                const lean = 0.035 + (k % 2) * 0.02;
                const h = 0.13 + (k % 3) * 0.035;
                const cx = Math.cos(a);
                const cz = Math.sin(a);
                const w = 0.018;
                pos.push(-cz * w, 0, cx * w, cz * w, 0, -cx * w, cx * lean, h, cz * lean);
            }
            const g = new THREE.BufferGeometry();
            g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
            g.computeVertexNormals();
            return g;
        }

        function fernGeometry() {
            const pts = [];
            for (let k = 0; k < 7; k++) {
                const a = (k / 7) * Math.PI * 2;
                const ca = Math.cos(a);
                const sa = Math.sin(a);
                const P = (side, upY, out) => [ca * out - sa * side, upY, sa * out + ca * side];
                const base = P(0, 0, 0.02);
                const l = P(-0.05, 0.16, 0.16);
                const r = P(0.05, 0.16, 0.16);
                const tip = P(0, 0.1, 0.36);
                pts.push(...base, ...l, ...tip, ...base, ...tip, ...r);
            }
            const g = new THREE.BufferGeometry();
            g.setAttribute('position', new THREE.Float32BufferAttribute(pts, 3));
            g.computeVertexNormals();
            return g;
        }

        function strip(pts, uv, cols, normal, mat, shadow) {
            const g = new THREE.BufferGeometry();
            g.setAttribute('position', new THREE.Float32BufferAttribute(pts, 3));
            const count = pts.length / 3;
            const nrm = [];
            for (let i = 0; i < count; i++) nrm.push(...normal);
            g.setAttribute('normal', new THREE.Float32BufferAttribute(nrm, 3));
            if (uv) g.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
            if (cols) g.setAttribute('color', new THREE.Float32BufferAttribute(cols, 3));
            const idx = [];
            for (let i = 0; i < count / 2 - 1; i++) {
                const a = i * 2;
                idx.push(a + 1, a + 3, a + 2, a + 1, a + 2, a);
            }
            g.setIndex(idx);
            const m = new THREE.Mesh(g, mat);
            m.receiveShadow = shadow;
            return m;
        }

        // Ajoute à un matériau la teinte « sous l'eau » de l'étang, avec ses reflets de lumière
        function decorate(mat) {
            mat.onBeforeCompile = (sh) => {
                Object.assign(sh.uniforms, { uTime: uniforms.uTime, uWater: uniforms.uWater });
                sh.vertexShader = 'varying vec3 vWPos;\n' + sh.vertexShader.replace('#include <begin_vertex>', '#include <begin_vertex>\nvWPos = (modelMatrix * vec4(transformed, 1.0)).xyz;');
                sh.fragmentShader = `uniform float uTime;
uniform float uWater;
varying vec3 vWPos;
float caustic(vec2 p, float t) {
    vec2 q = p;
    float c = 0.0;
    for (int n = 0; n < 3; n++) {
        float fn = float(n);
        q += 0.55 * vec2(sin(q.y * 1.35 + t + fn * 1.7), cos(q.x * 1.15 - t * 0.85 + fn * 2.3));
        c += abs(sin(q.x * 1.9) + sin(q.y * 1.9));
    }
    return pow(clamp(1.0 - c / 3.0, 0.0, 1.0), 3.0);
}
` + sh.fragmentShader.replace('#include <emissivemap_fragment>', `#include <emissivemap_fragment>
float wd = uWater - vWPos.y;
if (wd > 0.0) {
    float fade = smoothstep(0.0, 0.12, wd);
    diffuseColor.rgb = mix(diffuseColor.rgb, vec3(0.1, 0.36, 0.4), clamp(wd * 0.45, 0.0, 0.6) * fade);
    float cs = caustic(vWPos.xz * 1.8, uTime * 0.8);
    totalEmissiveRadiance += vec3(0.75, 0.95, 1.0) * cs * fade * (1.0 - smoothstep(0.4, 1.8, wd) * 0.5) * 0.14;
}`);
            };
        }

        function particles(count, additive) {
            const pos = new Float32Array(count * 3);
            const col = new Float32Array(count * 3);
            const size = new Float32Array(count);
            const alpha = new Float32Array(count);
            const g = new THREE.BufferGeometry();
            g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
            g.setAttribute('aColor', new THREE.BufferAttribute(col, 3));
            g.setAttribute('aSize', new THREE.BufferAttribute(size, 1));
            g.setAttribute('aAlpha', new THREE.BufferAttribute(alpha, 1));
            const m = new THREE.ShaderMaterial({
                uniforms: { uScale: pointScale },
                vertexShader: `attribute vec3 aColor;
attribute float aSize;
attribute float aAlpha;
uniform float uScale;
varying vec3 vColor;
varying float vAlpha;
void main() {
    vec4 mv = modelViewMatrix * vec4(position, 1.0);
    gl_Position = projectionMatrix * mv;
    gl_PointSize = aSize * uScale / -mv.z;
    vColor = aColor;
    vAlpha = aAlpha;
}`,
                fragmentShader: `varying vec3 vColor;
varying float vAlpha;
void main() {
    float r = length(gl_PointCoord - 0.5);
    float a = smoothstep(0.5, 0.05, r) * vAlpha;
    if (a < 0.01) discard;
    gl_FragColor = vec4(vColor, a);
}`,
                transparent: true,
                depthWrite: false,
                blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending,
            });
            const pts = new THREE.Points(g, m);
            pts.frustumCulled = false;
            pts.renderOrder = 9;
            scene.add(pts);
            const items = Array.from({ length: count }, () => ({}));
            return {
                items,
                set(i, x, y, z, s, c, a) {
                    pos[i * 3] = x;
                    pos[i * 3 + 1] = y;
                    pos[i * 3 + 2] = z;
                    col[i * 3] = c[0];
                    col[i * 3 + 1] = c[1];
                    col[i * 3 + 2] = c[2];
                    size[i] = s;
                    alpha[i] = a;
                },
                update() {
                    g.attributes.position.needsUpdate = true;
                    g.attributes.aColor.needsUpdate = true;
                    g.attributes.aSize.needsUpdate = true;
                    g.attributes.aAlpha.needsUpdate = true;
                },
            };
        }

        // Les couches de terre sur les côtés du bloc : elles se fondent les unes dans les autres
        function strataTexture() {
            const W = 1024;
            const H = 512;
            const cv = document.createElement('canvas');
            cv.width = W;
            cv.height = H;
            const g = cv.getContext('2d');
            const yPx = (y) => (1 - (y - BASE) / (0.3 - BASE)) * H;
            const STOPS = [[0.3, [79, 59, 42]], [-0.45, [92, 67, 46]], [-1.15, [118, 86, 58]], [-1.85, [158, 124, 86]], [-2.55, [198, 172, 132]], [BASE, [222, 206, 176]]];
            // Bande par bande, un dégradé vertical dont les paliers ondulent doucement
            for (let x = 0; x < W; x += 4) {
                const u = (x / W) * Math.PI * 2;
                const grad = g.createLinearGradient(0, 0, 0, H);
                STOPS.forEach(([y, c], k) => {
                    const off = k && k < STOPS.length - 1 ? Math.sin(u * 2 + k) * 9 + Math.sin(u * 5 + k * 2) * 4 : 0;
                    grad.addColorStop(clamp((yPx(y) + off) / H, 0, 1), `rgb(${c[0]},${c[1]},${c[2]})`);
                });
                g.fillStyle = grad;
                g.fillRect(x, 0, 4, H);
            }
            const rnd = mulberry32(5);
            const dot = (x, y, rx, ry, c) => {
                g.fillStyle = c;
                [x - W, x, x + W].forEach((xx) => {
                    g.beginPath();
                    g.ellipse(xx, y, rx, ry, 0, 0, Math.PI * 2);
                    g.fill();
                });
            };
            // Grain de la terre, et quelques cailloux de plus en plus clairs en descendant
            for (let i = 0; i < 1600; i++) {
                const x = rnd() * W;
                const y = rnd() * H;
                const deep = y / H;
                dot(x, y, 1 + rnd() * 1.2, 0.8 + rnd(), `rgba(${deep > 0.6 ? '255,248,232' : '30,20,12'},${0.05 + rnd() * 0.08})`);
            }
            for (let i = 0; i < 260; i++) {
                const x = rnd() * W;
                const y = yPx(-0.7) + rnd() * (H - yPx(-0.7));
                const r = 1.5 + rnd() * 3.5;
                const deep = (y - yPx(-0.7)) / (H - yPx(-0.7));
                dot(x, y, r * 1.3, r, `rgba(${Math.round(lerp(120, 245, deep))},${Math.round(lerp(98, 236, deep))},${Math.round(lerp(72, 214, deep))},${0.18 + rnd() * 0.22})`);
            }
            // Fines racines qui descendent de l'herbe et s'estompent
            for (let i = 0; i < 70; i++) {
                let x = rnd() * W;
                let y = yPx(0.3);
                for (let s = 0; s < 9; s++) {
                    const nx = x + (rnd() - 0.5) * 16;
                    const ny = y + 4 + rnd() * 8;
                    g.strokeStyle = `rgba(35,24,14,${0.5 * (1 - s / 9)})`;
                    g.lineWidth = 1.6 * (1 - s / 12);
                    g.beginPath();
                    g.moveTo(x, y);
                    g.lineTo(nx, ny);
                    g.stroke();
                    x = nx;
                    y = ny;
                }
            }
            const tex = new THREE.CanvasTexture(cv);
            tex.wrapS = THREE.RepeatWrapping;
            tex.colorSpace = THREE.SRGBColorSpace;
            tex.anisotropy = 4;
            return tex;
        }

        function radialTexture(inner, outer) {
            const cv = document.createElement('canvas');
            cv.width = cv.height = 256;
            const g = cv.getContext('2d');
            const grad = g.createRadialGradient(128, 128, 10, 128, 128, 128);
            grad.addColorStop(0, inner);
            grad.addColorStop(1, outer);
            g.fillStyle = grad;
            g.fillRect(0, 0, 256, 256);
            const tex = new THREE.CanvasTexture(cv);
            tex.colorSpace = THREE.SRGBColorSpace;
            return tex;
        }
    }

    // ---------------------------------------------------------------------
    // Deuxième diorama : un bloc d'océan en pleine nuit d'orage. Un petit bateau
    // de pêche se fait bercer par la houle sous la pluie et les éclairs.
    // À travers les vitres et la surface on voit les poissons, une raie et des
    // méduses, et le bloc a l'air de descendre à l'infini : tout devient de plus
    // en plus sombre et flou avec la profondeur. Un masque « stencil » ne dessine
    // ce puits sans fin qu'à l'intérieur du bloc : de l'extérieur, ça reste un
    // simple rectangle.
    // ---------------------------------------------------------------------
    function buildBoat(THREE, stage) {
        const phone = Math.min(window.innerWidth, window.innerHeight) < 600 || touch();
        const S = 10;
        const HALF = S / 2;
        const BASE = -3.3;
        const ABYSS = -70;
        const rand = mulberry32(5);
        const rr = (a, b) => a + (b - a) * rand();
        const color = (hex) => new THREE.Color(hex);
        const V = (x, y, z) => new THREE.Vector3(x, y, z);
        const flat = (hex, extra) => new THREE.MeshStandardMaterial(Object.assign({ color: hex, flatShading: true, roughness: 0.8 }, extra || {}));
        const tmp = new THREE.Color();
        const smooth = (u) => u * u * (3 - 2 * u);
        const still = calm();

        const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, stencil: true, powerPreference: 'high-performance' });
        renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, phone ? 1.75 : 2));
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        renderer.setClearColor(0x000000, 0);
        renderer.domElement.className = 'diorama-canvas';
        stage.appendChild(renderer.domElement);
        const scene = new THREE.Scene();
        const camera = new THREE.PerspectiveCamera(30, 1, 0.05, 400);
        const uTime = { value: 0 };
        const uFlash = { value: 0 };

        // --- Nuit d'orage : une lune voilée, et la lumière des éclairs ---
        const hemi = new THREE.HemisphereLight(0x5a7698, 0x10202c, 1.05);
        scene.add(hemi);
        const moon = new THREE.DirectionalLight(0x8eaad0, 0.8);
        moon.position.set(6, 9, -5);
        moon.castShadow = true;
        moon.shadow.mapSize.set(phone ? 1024 : 2048, phone ? 1024 : 2048);
        Object.assign(moon.shadow.camera, { left: -8, right: 8, top: 8, bottom: -8, near: 1, far: 40 });
        moon.shadow.bias = -0.0006;
        moon.shadow.normalBias = 0.02;
        scene.add(moon);
        const flashLight = new THREE.DirectionalLight(0xd2deff, 0);
        flashLight.position.set(-3, 10, -7);
        scene.add(flashLight);

        // --- La houle : de longues vagues fluides qui se croisent, avec un peu de clapot.
        // Elles s'aplatissent juste au bord pour que le bloc reste bien droit de l'extérieur.
        const WAVES = [
            [0.94, 0.34, 1.366, 1.15, 0.16],
            [0.25, 0.97, 1.963, 1.45, 0.1],
            [-0.6, 0.8, 2.99, 1.85, 0.06],
            [0.83, -0.56, 4.83, 2.4, 0.03],
            [-0.3, -0.95, 7.85, 3.0, 0.015],
        ];
        const EDGE = 0.6;
        const wave = (x, z, t) => {
            let h = 0;
            for (const [dx, dz, k, w, a] of WAVES) h += a * (Math.exp(Math.sin((dx * x + dz * z) * k - w * t) - 1) - 0.43);
            return h * smooth(clamp((HALF - Math.max(Math.abs(x), Math.abs(z))) / EDGE, 0, 1));
        };
        const edgeGLSL = `smoothstep(0.0, 1.0, clamp((${HALF.toFixed(2)} - max(abs(p.x), abs(p.y))) / ${EDGE.toFixed(2)}, 0.0, 1.0))`;
        const WAVE_GLSL = `uniform float uTime;
varying vec2 vXZ;
float waveH(vec2 p) {
    float h = 0.0;
${WAVES.map(([dx, dz, k, w, a]) => `    h += ${a.toFixed(4)} * (exp(sin(dot(p, vec2(${dx.toFixed(3)}, ${dz.toFixed(3)})) * ${k.toFixed(3)} - ${w.toFixed(3)} * uTime) - 1.0) - 0.43);`).join('\n')}
    return h * ${edgeGLSL};
}
vec3 waveN(vec2 p) {
    vec2 g = vec2(0.0);
    float th;
${WAVES.map(([dx, dz, k, w, a]) => `    th = dot(p, vec2(${dx.toFixed(3)}, ${dz.toFixed(3)})) * ${k.toFixed(3)} - ${w.toFixed(3)} * uTime;
    g += ${(a * k).toFixed(4)} * exp(sin(th) - 1.0) * cos(th) * vec2(${dx.toFixed(3)}, ${dz.toFixed(3)});`).join('\n')}
    g *= ${edgeGLSL};
    return normalize(vec3(-g.x, 1.0, -g.y));
}
`;

        // --- La profondeur : plus on descend, plus l'eau avale les couleurs (et plus c'est flou) ---
        const FOG_GLSL = `uniform float uFlash;
vec3 waterFog(vec3 col, float y) {
    float d = max(0.0, -y);
    float f = 1.0 - exp(-d * 0.15);
    vec3 fogc = mix(vec3(0.07, 0.25, 0.3), vec3(0.008, 0.03, 0.06), clamp(d / 24.0, 0.0, 1.0)) * (1.0 + uFlash * 0.7);
    return mix(col, fogc, f);
}
`;
        const underwater = (mat) => {
            mat.onBeforeCompile = (sh) => {
                sh.uniforms.uFlash = uFlash;
                sh.vertexShader = 'varying vec3 vWater;\n' + sh.vertexShader.replace('#include <project_vertex>', `#include <project_vertex>
vec4 wW = vec4(transformed, 1.0);
#ifdef USE_INSTANCING
wW = instanceMatrix * wW;
#endif
vWater = (modelMatrix * wW).xyz;`);
                sh.fragmentShader = 'varying vec3 vWater;\n' + FOG_GLSL + sh.fragmentShader.replace('#include <dithering_fragment>', 'gl_FragColor.rgb = waterFog(gl_FragColor.rgb, vWater.y);\n#include <dithering_fragment>');
            };
            mat.customProgramCacheKey = () => 'underwater';
            return mat;
        };
        // Ce qui n'existe que « vu à travers le bloc » : le puits sans fond
        const gate = (mat, func) => {
            mat.stencilWrite = true;
            mat.stencilRef = 1;
            mat.stencilFunc = func === undefined ? THREE.EqualStencilFunc : func;
            mat.stencilFail = THREE.KeepStencilOp;
            mat.stencilZFail = THREE.KeepStencilOp;
            mat.stencilZPass = THREE.KeepStencilOp;
            return mat;
        };

        // --- Les parois du puits : un dégradé avec des reflets de lumière qui s'éteignent en descendant ---
        const wellMat = (side, func) => {
            const m = new THREE.ShaderMaterial({
                uniforms: { uTime, uFlash },
                vertexShader: `varying vec3 vW;
varying vec3 vN;
void main() {
    vec4 w = modelMatrix * vec4(position, 1.0);
    vW = w.xyz;
    vN = normalize(mat3(modelMatrix) * normal);
    gl_Position = projectionMatrix * viewMatrix * w;
}`,
                fragmentShader: `uniform float uTime;
varying vec3 vW;
varying vec3 vN;
${FOG_GLSL}
float caustic(vec2 p, float t) {
    vec2 q = p;
    float c = 0.0;
    for (int n = 0; n < 3; n++) {
        float fn = float(n);
        q += 0.55 * vec2(sin(q.y * 1.35 + t + fn * 1.7), cos(q.x * 1.15 - t * 0.85 + fn * 2.3));
        c += abs(sin(q.x * 1.9) + sin(q.y * 1.9));
    }
    return pow(clamp(1.0 - c / 3.0, 0.0, 1.0), 3.0);
}
void main() {
    float d = max(0.0, -vW.y);
    vec2 uv = abs(vN.y) > 0.5 ? vW.xz : vec2(abs(vN.x) > 0.5 ? vW.z : vW.x, vW.y);
    float shade = 0.82 + 0.18 * dot(normalize(vN), normalize(vec3(-0.5, 0.0, 0.8)));
    vec3 col = vec3(0.1, 0.29, 0.34) * shade;
    col += vec3(0.45, 0.75, 0.8) * caustic(uv * 1.2, uTime * 0.6) * 0.32 * exp(-d * 0.45);
    col *= 1.0 - 0.1 * smoothstep(0.9, 1.0, fract(vW.y * 0.5));
    gl_FragColor = vec4(waterFog(col, vW.y), 1.0);
}`,
                side,
            });
            if (func !== undefined) gate(m, func);
            return m;
        };
        const wall = (h, yc, mat, order) => {
            [[0, HALF, 0], [HALF, 0, Math.PI / 2], [0, -HALF, Math.PI], [-HALF, 0, -Math.PI / 2]].forEach(([x, z, ry]) => {
                const m = new THREE.Mesh(new THREE.PlaneGeometry(S, h).rotateY(ry), mat);
                m.position.set(x, yc, z);
                m.renderOrder = order;
                scene.add(m);
            });
        };
        // Haut du puits (dans le bloc) : visible de partout
        wall(-BASE, BASE / 2, wellMat(THREE.BackSide), 0);
        // Le reste du puits, sous le bloc : seulement à travers le bloc (vitres ou surface)
        wall(BASE - ABYSS, (BASE + ABYSS) / 2, wellMat(THREE.BackSide, THREE.EqualStencilFunc), 2);
        const floorGeo = () => new THREE.PlaneGeometry(S, S).rotateX(-Math.PI / 2);
        const abyssCap = new THREE.Mesh(floorGeo(), wellMat(THREE.FrontSide, THREE.EqualStencilFunc));
        abyssCap.position.y = ABYSS;
        abyssCap.renderOrder = 2;
        scene.add(abyssCap);
        // Le masque : marque les pixels où l'on regarde à l'intérieur du bloc (par le dessus ou par les côtés).
        // Le puits sans fond n'est dessiné que là : de l'extérieur, le bloc reste un simple rectangle.
        const mask = new THREE.Mesh(new THREE.BoxGeometry(S, -BASE, S).translate(0, BASE / 2, 0), gate(new THREE.MeshBasicMaterial({ colorWrite: false, depthWrite: false }), THREE.AlwaysStencilFunc));
        mask.material.stencilZPass = THREE.ReplaceStencilOp;
        mask.renderOrder = 1;
        scene.add(mask);

        // --- Les vitres : on voit à travers, légèrement teintées ---
        const glassMat = new THREE.MeshBasicMaterial({ vertexColors: true, transparent: true, depthWrite: false, fog: false });
        [[0, HALF, 0], [HALF, 0, Math.PI / 2], [0, -HALF, Math.PI], [-HALF, 0, -Math.PI / 2]].forEach(([x, z, ry]) => {
            const g = new THREE.PlaneGeometry(S, -BASE, 1, 1).rotateY(ry);
            const col = [];
            for (let i = 0; i < 4; i++) col.push(...(i < 2 ? [0.55, 0.85, 0.9, 0.12] : [0.05, 0.16, 0.24, 0.26]));
            g.setAttribute('color', new THREE.Float32BufferAttribute(col, 4));
            const m = new THREE.Mesh(g, glassMat);
            m.position.set(x, BASE / 2, z);
            m.renderOrder = 6;
            scene.add(m);
        });
        const corners = [[-HALF, HALF], [HALF, HALF], [HALF, -HALF], [-HALF, -HALF]];
        const topLine = new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints(corners.map(([x, z]) => V(x, 0.003, z))), new THREE.LineBasicMaterial({ color: 0xbfe2ea, transparent: true, opacity: 0.5 }));
        // Les arêtes du bas et des coins : seulement celles du contour, jamais celles qu'on verrait
        // à travers la vitre (sinon on devinerait un fond). On les choisit à chaque image selon la caméra.
        const edgeMat = new THREE.LineBasicMaterial({ color: 0xa9d2dc, transparent: true, opacity: 0.3 });
        const line = (p1, p2) => {
            const l = new THREE.Line(new THREE.BufferGeometry().setFromPoints([p1, p2]), edgeMat);
            l.renderOrder = 8;
            scene.add(l);
            return l;
        };
        const vEdges = corners.map(([x, z]) => line(V(x, 0, z), V(x, BASE, z)));
        const bEdges = corners.map(([x, z], i) => line(V(x, BASE, z), V(corners[(i + 1) % 4][0], BASE, corners[(i + 1) % 4][1])));
        topLine.renderOrder = 8;
        // Les arêtes du puits continuent vers le bas et s'effacent peu à peu
        const wellPts = [];
        const wellCol = [];
        const fade = (y) => 0.38 * Math.exp(y * 0.085);
        corners.forEach(([x, z]) => {
            for (let y = 0; y > -40; y -= 1) {
                wellPts.push(x, y, z, x, y - 1, z);
                wellCol.push(0.66, 0.86, 0.9, fade(y), 0.66, 0.86, 0.9, fade(y - 1));
            }
        });
        for (let y = -5.8; y > -40; y -= 2.5) {
            corners.forEach(([x, z], i) => {
                const [x2, z2] = corners[(i + 1) % 4];
                wellPts.push(x, y, z, x2, y, z2);
                wellCol.push(0.66, 0.86, 0.9, fade(y) * 0.45, 0.66, 0.86, 0.9, fade(y) * 0.45);
            });
        }
        const wellGeo = new THREE.BufferGeometry();
        wellGeo.setAttribute('position', new THREE.Float32BufferAttribute(wellPts, 3));
        wellGeo.setAttribute('color', new THREE.Float32BufferAttribute(wellCol, 4));
        const wellLines = new THREE.LineSegments(wellGeo, gate(new THREE.LineBasicMaterial({ vertexColors: true, transparent: true, depthWrite: false })));
        wellLines.renderOrder = 3;
        scene.add(wellLines);
        scene.add(topLine);
        const contact = new THREE.Mesh(new THREE.PlaneGeometry(S * 1.9, S * 1.9), new THREE.MeshBasicMaterial({ map: radialTexture('rgba(0,0,0,0.45)', 'rgba(0,0,0,0)'), transparent: true, depthWrite: false }));
        contact.rotation.x = -Math.PI / 2;
        contact.position.set(1, BASE - 0.02, -0.8);
        scene.add(contact);

        // --- La surface : transparente quand on regarde dedans, brillante en rasant ---
        const M = phone ? 100 : 140;
        const waterGeo = new THREE.PlaneGeometry(S, S, M, M);
        waterGeo.rotateX(-Math.PI / 2);
        const waterMat = new THREE.MeshStandardMaterial({ color: 0x2a7f8c, roughness: 0.12, metalness: 0.15, transparent: true, depthWrite: false });
        waterMat.onBeforeCompile = (sh) => {
            sh.uniforms.uTime = uTime;
            sh.uniforms.uFlash = uFlash;
            sh.vertexShader = WAVE_GLSL + sh.vertexShader
                .replace('#include <beginnormal_vertex>', 'vec3 objectNormal = waveN(position.xz);')
                .replace('#include <begin_vertex>', '#include <begin_vertex>\nvXZ = transformed.xz;\ntransformed.y += waveH(transformed.xz);');
            sh.fragmentShader = WAVE_GLSL + 'uniform float uFlash;\n' + sh.fragmentShader
                .replace('#include <normal_fragment_begin>', '#include <normal_fragment_begin>\nnormal = normalize((viewMatrix * vec4(waveN(vXZ), 0.0)).xyz);')
                .replace('#include <emissivemap_fragment>', `#include <emissivemap_fragment>
float hh = waveH(vXZ);
float foam = smoothstep(0.08, 0.17, hh);
diffuseColor.rgb = mix(diffuseColor.rgb, vec3(0.78, 0.87, 0.9), foam * 0.75);
float fres = pow(1.0 - abs(dot(normal, normalize(vViewPosition))), 3.0);
diffuseColor.a = clamp(0.3 + fres * 0.6 + foam * 0.5, 0.0, 0.95);
totalEmissiveRadiance += vec3(0.14, 0.22, 0.28) * fres * 0.6 + vec3(0.5, 0.6, 0.75) * uFlash * fres * 0.4;`);
        };
        const water = new THREE.Mesh(waterGeo, waterMat);
        water.receiveShadow = true;
        water.renderOrder = 7;
        scene.add(water);

        // --- Le bateau ---
        const boat = new THREE.Group();
        scene.add(boat);
        const B0 = V(0.2, 0, 0.3);
        const YAW = 0.35;
        const BS = 0.7;
        boat.scale.setScalar(BS);
        const hull = (() => {
            const g = new THREE.BoxGeometry(2.0, 0.5, 0.8, 10, 5, 2).toNonIndexed();
            const p = g.attributes.position;
            const col = new Float32Array(p.count * 3);
            const a = new THREE.Vector3();
            const b = new THREE.Vector3();
            const c = new THREE.Vector3();
            for (let f = 0; f < p.count; f += 3) {
                a.fromBufferAttribute(p, f);
                b.fromBufferAttribute(p, f + 1);
                c.fromBufferAttribute(p, f + 2);
                const ny = b.clone().sub(a).cross(c.clone().sub(a)).normalize().y;
                const yc = (a.y + b.y + c.y) / 3;
                let hex = 0x5b2a2c;
                if (ny > 0.9) hex = 0xb48655;
                else if (yc > 0.15) hex = 0xeadcc0;
                else if (yc > -0.05) hex = 0x5b2a2c;
                else if (yc > -0.15) hex = 0x4c2325;
                else hex = 0x8e3a2c;
                tmp.set(hex);
                for (let k = 0; k < 3; k++) tmp.toArray(col, (f + k) * 3);
            }
            for (let i = 0; i < p.count; i++) {
                const x = p.getX(i);
                let y = p.getY(i);
                let z = p.getZ(i);
                const u = (x + 1) / 2;
                const k = (y + 0.25) / 0.5;
                let w = u > 0.55 ? 1 - Math.pow((u - 0.55) / 0.45, 1.7) : 1;
                if (u < 0.06) w *= 0.94;
                w *= 0.5 + 0.5 * Math.pow(k, 0.6);
                z *= Math.max(0.02, w);
                y += 0.14 * Math.pow(u, 3) * k + 0.1 * u * u * (1 - k);
                p.setXYZ(i, x, y, z);
            }
            g.setAttribute('color', new THREE.BufferAttribute(col, 3));
            g.computeVertexNormals();
            const m = new THREE.Mesh(g, new THREE.MeshStandardMaterial({ vertexColors: true, flatShading: true, roughness: 0.75 }));
            m.position.y = 0.06;
            return m;
        })();
        boat.add(hull);
        const deckAt = (x) => 0.31 + 0.14 * Math.pow((x + 1) / 2, 3);
        const wood = flat(0xa87a4a);
        const woodDark = flat(0x6b4a2e);
        const cream = flat(0xefe5cf);
        const roofMat = flat(0x3a3138);
        const glassDark = flat(0x3a2a14, { roughness: 0.3, emissive: 0xffa54a, emissiveIntensity: 0.85 });
        // Timonerie
        const cabX = 0.12;
        const cabY = deckAt(cabX);
        const cabin = new THREE.Mesh(new THREE.BoxGeometry(0.58, 0.44, 0.56), cream);
        cabin.position.set(cabX, cabY + 0.22, 0);
        boat.add(cabin);
        const roof = new THREE.Mesh(new THREE.BoxGeometry(0.68, 0.05, 0.66), roofMat);
        roof.position.set(cabX, cabY + 0.465, 0);
        boat.add(roof);
        [[0.291, 0.3, 0, 0.005, 0.11, 0.42], [cabX, 0.3, 0.281, 0.4, 0.11, 0.005], [cabX, 0.3, -0.281, 0.4, 0.11, 0.005]].forEach(([x, y, z, w, h, d]) => {
            const win = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), glassDark);
            win.position.set(x, cabY + y, z);
            boat.add(win);
        });
        const door = new THREE.Mesh(new THREE.BoxGeometry(0.005, 0.32, 0.16), woodDark);
        door.position.set(cabX - 0.291, cabY + 0.17, 0.1);
        boat.add(door);
        const lampMat = new THREE.MeshStandardMaterial({ color: 0xfff1c9, emissive: 0xffb45c, emissiveIntensity: 1.2 });
        const lamp = new THREE.Mesh(new THREE.CylinderGeometry(0.04, 0.05, 0.07, 10), lampMat);
        lamp.position.set(cabX + 0.2, cabY + 0.525, 0.22);
        boat.add(lamp);
        const radarPost = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.012, 0.14, 5), woodDark);
        radarPost.position.set(cabX - 0.1, cabY + 0.56, 0);
        boat.add(radarPost);
        const radar = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.02, 0.03), roofMat);
        radar.position.set(cabX - 0.1, cabY + 0.64, 0);
        boat.add(radar);
        // Mât, vergue, haubans et petit drapeau
        const mastX = 0.6;
        const mastBase = deckAt(mastX);
        const mast = new THREE.Mesh(new THREE.CylinderGeometry(0.022, 0.03, 1.3, 6), woodDark);
        mast.position.set(mastX, mastBase + 0.65, 0);
        boat.add(mast);
        const spar = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.012, 0.5, 5), woodDark);
        spar.rotation.x = Math.PI / 2;
        spar.position.set(mastX, mastBase + 1.0, 0);
        boat.add(spar);
        const ropes = new THREE.BufferGeometry().setFromPoints([
            V(mastX, mastBase + 1.28, 0), V(0.98, deckAt(0.98) + 0.02, 0),
            V(mastX, mastBase + 1.28, 0), V(-0.95, deckAt(-0.95) + 0.25, 0),
            V(mastX, mastBase + 1.0, 0.25), V(mastX - 0.1, mastBase + 0.02, 0.36),
            V(mastX, mastBase + 1.0, -0.25), V(mastX - 0.1, mastBase + 0.02, -0.36),
        ]);
        boat.add(new THREE.LineSegments(ropes, new THREE.LineBasicMaterial({ color: 0x3b2f28 })));
        const flagGeo = new THREE.PlaneGeometry(0.24, 0.15, 6, 1);
        const fpos = flagGeo.attributes.position;
        const fcol = new Float32Array(fpos.count * 3);
        for (let i = 0; i < fpos.count; i++) tmp.set(fpos.getX(i) < -0.04 ? 0x2e8f8a : fpos.getX(i) < 0.04 ? 0xf3e7cf : 0xe0743a).toArray(fcol, i * 3);
        flagGeo.setAttribute('color', new THREE.BufferAttribute(fcol, 3));
        flagGeo.translate(0.12, 0, 0);
        const flagBase = Float32Array.from(fpos.array);
        const flag = new THREE.Mesh(flagGeo, new THREE.MeshStandardMaterial({ vertexColors: true, side: THREE.DoubleSide, roughness: 0.9 }));
        flag.position.set(mastX, mastBase + 1.2, 0);
        flag.rotation.y = Math.PI;
        boat.add(flag);
        // Bric-à-brac du pont : caisses, tonneaux, bouée, cordage, filet, seau
        [[0.78, 0.13, 0.16, 0.18], [0.82, -0.14, 0.14, 0.15], [0.66, 0.2, 0.12, 0.12]].forEach(([x, z, sx, sy]) => {
            const box = new THREE.Mesh(new THREE.BoxGeometry(sx, sy, sx), wood);
            box.position.set(x, deckAt(x) + sy / 2, z);
            box.rotation.y = rr(-0.4, 0.4);
            boat.add(box);
        });
        [[-0.25, -0.24], [-0.1, -0.26]].forEach(([x, z]) => {
            const barrel = new THREE.Mesh(new THREE.CylinderGeometry(0.075, 0.075, 0.2, 8), flat(0x7b5232));
            barrel.position.set(x, deckAt(x) + 0.1, z);
            boat.add(barrel);
        });
        const ring = new THREE.Mesh(new THREE.TorusGeometry(0.085, 0.022, 6, 14), flat(0xe8622f));
        ring.position.set(cabX, cabY + 0.24, 0.29);
        boat.add(ring);
        const coil = new THREE.Mesh(new THREE.TorusGeometry(0.07, 0.018, 5, 12).rotateX(Math.PI / 2), flat(0xc9b48a));
        coil.position.set(0.45, deckAt(0.45) + 0.02, -0.2);
        boat.add(coil);
        const net = new THREE.Mesh(new THREE.IcosahedronGeometry(0.14, 1).scale(1.4, 0.55, 1), flat(0x3f5f4a));
        net.position.set(-0.85, deckAt(-0.85) + 0.06, -0.2);
        boat.add(net);
        const boom = limb(V(-0.75, deckAt(-0.75), -0.3), V(-1.05, deckAt(-0.75) + 0.75, -0.05), 0.022, 0.016, woodDark);
        boat.add(boom);
        boat.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([V(-1.05, deckAt(-0.75) + 0.75, -0.05), V(-0.88, deckAt(-0.85) + 0.12, -0.18)]), new THREE.LineBasicMaterial({ color: 0x3b2f28 })));
        const bucket = new THREE.Mesh(new THREE.CylinderGeometry(0.065, 0.05, 0.11, 10, 1, true), flat(0x8fa3ad, { side: THREE.DoubleSide, metalness: 0.3 }));
        const BUCKET = V(-0.32, deckAt(-0.32) + 0.055, 0.14);
        bucket.position.copy(BUCKET);
        boat.add(bucket);
        // Petit garde-corps à l'arrière
        for (let k = 0; k < 4; k++) {
            const x = -0.92 + k * 0.28;
            [-1, 1].forEach((side) => {
                const z = side * 0.39;
                boat.add(limb(V(x, deckAt(x), z), V(x, deckAt(x) + 0.15, z), 0.008, 0.008, woodDark));
                if (k < 3) boat.add(limb(V(x, deckAt(x) + 0.15, z), V(x + 0.28, deckAt(x + 0.28) + 0.15, z), 0.007, 0.007, woodDark));
            });
        }

        // Une caisse sur le pont arrière, et une lanterne sur un petit poteau
        const crate = new THREE.Mesh(new THREE.BoxGeometry(0.24, 0.17, 0.22), wood);
        crate.position.set(-0.62, deckAt(-0.62) + 0.085, 0.1);
        boat.add(crate);
        const lanternPivot = new THREE.Group();
        lanternPivot.position.set(-0.5, deckAt(-0.44) + 0.44, 0.35);
        boat.add(lanternPivot);
        const iron = flat(0x26231f, { metalness: 0.4 });
        boat.add(limb(V(-0.44, deckAt(-0.44), 0.36), V(-0.44, deckAt(-0.44) + 0.46, 0.36), 0.009, 0.008, woodDark));
        boat.add(limb(V(-0.44, deckAt(-0.44) + 0.45, 0.36), V(-0.51, deckAt(-0.44) + 0.45, 0.35), 0.006, 0.006, iron));
        lanternPivot.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([V(0, 0, 0), V(0, -0.05, 0)]), new THREE.LineBasicMaterial({ color: 0x2a2420 })));
        const lanternMat = new THREE.MeshStandardMaterial({ color: 0xffe4b0, emissive: 0xffa040, emissiveIntensity: 1.8 });
        const lanternGlass = new THREE.Mesh(new THREE.CylinderGeometry(0.03, 0.03, 0.06, 8), lanternMat);
        lanternGlass.position.y = -0.1;
        const lanternTop = new THREE.Mesh(new THREE.ConeGeometry(0.042, 0.035, 8), iron);
        lanternTop.position.y = -0.055;
        const lanternBase = new THREE.Mesh(new THREE.CylinderGeometry(0.036, 0.036, 0.012, 8), iron);
        lanternBase.position.y = -0.136;
        lanternPivot.add(lanternGlass, lanternTop, lanternBase);
        const lanternLight = new THREE.PointLight(0xffa04a, 1.1, 3, 1.4);
        lanternLight.position.y = -0.1;
        lanternPivot.add(lanternLight);
        // Une lumière chaude qui éclaire les vagues autour du bateau
        const pool = new THREE.PointLight(0xffa860, 2.2, 5, 1.2);
        pool.position.set(-0.1, 1.6, 0.1);
        boat.add(pool);
        const haloTex = radialTexture('rgba(255,190,110,0.9)', 'rgba(255,150,60,0)');
        const halo = (size, x, y, z, parent) => {
            const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: haloTex, blending: THREE.AdditiveBlending, depthWrite: false, transparent: true }));
            sp.scale.setScalar(size);
            sp.position.set(x, y, z);
            sp.renderOrder = 10;
            parent.add(sp);
            return sp;
        };
        const lanternHalo = halo(0.6, 0, -0.1, 0, lanternPivot);
        halo(0.5, cabX + 0.2, cabY + 0.525, 0.22, boat);
        boat.traverse((m) => { if (m.isMesh) { m.castShadow = true; m.receiveShadow = true; } });
        lanternGlass.castShadow = false;
        const boatMeshes = [];
        boat.traverse((m) => { if (m.isMesh) boatMeshes.push(m); });

        // --- La vie dans le diorama (de côté comme d'en haut) et tout au fond (seulement d'en haut) ---
        const fishGeo = mergeGeos([
            new THREE.IcosahedronGeometry(0.06, 0).scale(0.55, 0.85, 1.8),
            new THREE.ConeGeometry(0.045, 0.08, 4).rotateX(-Math.PI / 2).translate(0, 0, -0.14),
            new THREE.ConeGeometry(0.02, 0.05, 3).translate(0, 0.055, -0.01),
        ]);
        const schools = [];
        const makeSchool = (n, colors, scale, deep, path) => {
            const mat = underwater(flat(0xffffff, { metalness: 0.3, roughness: 0.45 }));
            if (deep) gate(mat);
            const mesh = new THREE.InstancedMesh(fishGeo, mat, n);
            const off = [];
            for (let i = 0; i < n; i++) {
                off.push({ p: V(rr(-0.65, 0.65), rr(-0.22, 0.22), rr(-0.65, 0.65)), ph: rr(0, 6.28) });
                mesh.setColorAt(i, color(colors[i % colors.length]));
            }
            mesh.renderOrder = deep ? 2 : 0;
            mesh.frustumCulled = false;
            scene.add(mesh);
            schools.push({ mesh, off, scale, path });
        };
        makeSchool(phone ? 12 : 18, [0xbfd0db, 0x9fb6c6, 0xdfe7ec, 0x8fb0c8], 1.5, false, (t) => [Math.sin(t * 0.17) * 3.0, -1.15 + Math.sin(t * 0.35) * 0.3, Math.sin(t * 0.26 + 1) * 2.8]);
        makeSchool(phone ? 8 : 12, [0xf2c34c, 0x4fa3d8, 0xf2c34c], 1.1, false, (t) => [Math.sin(t * 0.23 + 2) * 2.6, -2.2 + Math.sin(t * 0.5) * 0.2, Math.cos(t * 0.31) * 2.4]);
        makeSchool(phone ? 14 : 26, [0x9fb6c6, 0xbfd0db], 1.7, true, (t) => [Math.sin(t * 0.12) * 2.7, -7.5 + Math.sin(t * 0.2) * 0.8, Math.cos(t * 0.15) * 2.5]);
        makeSchool(phone ? 10 : 18, [0x8fb0c8], 2.2, true, (t) => [Math.cos(t * 0.09 + 3) * 2.4, -13 + Math.sin(t * 0.17) * 1.0, Math.sin(t * 0.11) * 2.4]);

        const bigFish = [[0xe9743a, 2.3, 1.6, 1.6, 1.2, -0.9, 0.26], [0x3f7fb0, -2.2, 2.2, 1.3, 1.0, -1.9, -0.2]].map(([hex, cx, cz, rx, rz, y, sp], i) => {
            const g = new THREE.Group();
            const mat = underwater(flat(hex));
            const tail = new THREE.Mesh(new THREE.ConeGeometry(0.07, 0.13, 4).rotateX(-Math.PI / 2).translate(0, 0, -0.24), mat);
            g.add(new THREE.Mesh(new THREE.IcosahedronGeometry(0.1, 0).scale(0.75, 1, 1.9), mat), tail);
            g.scale.setScalar(1.7);
            scene.add(g);
            return { g, tail, cx, cz, rx, rz, y, sp, a: i * 2 };
        });

        // Une raie qui plane près du fond du bloc
        const ray = new THREE.Group();
        const rayMat = underwater(flat(0x34434f, { side: THREE.DoubleSide }));
        ray.add(new THREE.Mesh(new THREE.IcosahedronGeometry(0.12, 1).scale(1.1, 0.28, 1.5), rayMat));
        const rayWings = [-1, 1].map((sd) => {
            const g = new THREE.BufferGeometry();
            g.setAttribute('position', new THREE.Float32BufferAttribute([0, 0, 0.16, sd * 0.55, 0, -0.04, 0, 0, -0.14], 3));
            g.computeVertexNormals();
            const piv = new THREE.Group();
            piv.position.set(sd * 0.1, 0, 0);
            piv.add(new THREE.Mesh(g, rayMat));
            ray.add(piv);
            return { piv, sd };
        });
        ray.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([V(0, 0, -0.15), V(0, 0, -0.75)]), new THREE.LineBasicMaterial({ color: 0x34434f })));
        ray.scale.setScalar(1.8);
        scene.add(ray);

        // Méduses : quelques-unes au fond du bloc, d'autres de plus en plus bas dans le noir
        const TENT = 7;
        const SEG = 5;
        const jellies = [];
        const makeJelly = (x, y, z, hex, glow, sc, deep, i) => {
            const g = new THREE.Group();
            const mat = underwater(new THREE.MeshStandardMaterial({ color: hex, emissive: glow, emissiveIntensity: 0.75, transparent: true, opacity: 0.8, roughness: 0.35, side: THREE.DoubleSide }));
            const tmat = new THREE.LineBasicMaterial({ color: hex, transparent: true, opacity: 0.7 * Math.exp(Math.min(0, y) * 0.1) });
            if (deep) {
                gate(mat);
                gate(tmat);
            }
            const bell = new THREE.Mesh(new THREE.SphereGeometry(0.16, 16, 8, 0, Math.PI * 2, 0, Math.PI / 2), mat);
            bell.renderOrder = 3;
            g.add(bell);
            const tg = new THREE.BufferGeometry();
            tg.setAttribute('position', new THREE.Float32BufferAttribute(new Float32Array(TENT * SEG * 6), 3));
            const tent = new THREE.LineSegments(tg, tmat);
            tent.frustumCulled = false;
            tent.renderOrder = 3;
            g.add(tent);
            g.scale.setScalar(sc);
            scene.add(g);
            jellies.push({ g, bell, tg, x, y, z, ph: i * 2.1, deep });
        };
        [[-2.7, -2.35, 1.9, 0xffb3d6, 0xff6fae], [2.9, -2.5, -1.4, 0x9fefff, 0x2bb8e0], [-0.9, -2.45, -3.1, 0xffc9a8, 0xff8a5c]].slice(0, phone ? 2 : 3)
            .forEach(([x, y, z, hex, glow], i) => makeJelly(x, y, z, hex, glow, 1.3, false, i));
        for (let i = 0; i < (phone ? 5 : 8); i++) {
            const pink = i % 2;
            makeJelly(rr(-3.6, 3.6), -4.8 - i * 2.1 - rr(0, 1), rr(-3.6, 3.6), pink ? 0xffb3d6 : 0x9fefff, pink ? 0xff6fae : 0x2bb8e0, 1.4 + i * 0.12, true, i + 3);
        }

        // Une très grande ombre passe lentement, loin en dessous
        const whale = new THREE.Group();
        const whaleMat = gate(underwater(flat(0x2a3a46, { roughness: 0.9 })));
        const fluke = new THREE.Mesh(new THREE.ConeGeometry(0.5, 0.9, 4).scale(1.6, 0.25, 1).rotateX(-Math.PI / 2).translate(0, 0, -2.55), whaleMat);
        whale.add(new THREE.Mesh(new THREE.IcosahedronGeometry(1, 1).scale(0.85, 0.7, 2.3), whaleMat), fluke);
        [-1, 1].forEach((sd) => {
            const fin = new THREE.Mesh(new THREE.ConeGeometry(0.25, 1.2, 4).scale(1, 0.25, 0.6).rotateZ(sd * Math.PI / 2).translate(sd * 1.1, -0.3, 0.6), whaleMat);
            whale.add(fin);
        });
        whale.traverse((m) => { m.renderOrder = 2; });
        scene.add(whale);

        // --- Le ciel d'orage : des éclairs, toujours derrière le diorama ---
        const sky = new THREE.Group();
        scene.add(sky);
        const boltMat = new THREE.MeshBasicMaterial({ color: 0xe8efff, transparent: true, opacity: 0, depthWrite: false, blending: THREE.AdditiveBlending });
        const bolt = new THREE.Mesh(new THREE.BufferGeometry(), boltMat);
        bolt.renderOrder = 9;
        sky.add(bolt);
        const storm = { next: rr(2.5, 4.5), t0: -10, spray: rr(1, 2) };
        function lightning() {
            const pts = [];
            let px = rr(-6, 6);
            const z = rr(-9, -8);
            for (let k = 0; k <= 21; k++) {
                pts.push(V(px, 9.0 - k * 0.4, z));
                px += rr(-0.4, 0.4);
            }
            const path = new THREE.CurvePath();
            for (let k = 0; k < pts.length - 1; k++) path.add(new THREE.LineCurve3(pts[k], pts[k + 1]));
            const branch = new THREE.CurvePath();
            let bp = pts[11].clone();
            for (let k = 0; k < 4; k++) {
                const nx = bp.clone().add(V(rr(0.15, 0.4) * (px > 0 ? -1 : 1), -0.36, 0));
                branch.add(new THREE.LineCurve3(bp, nx));
                bp = nx;
            }
            bolt.geometry.dispose();
            bolt.geometry = mergeGeos([new THREE.TubeGeometry(path, 64, 0.04, 4, false), new THREE.TubeGeometry(branch, 20, 0.022, 4, false)]);
            storm.t0 = clock;
        }

        // --- La pluie, poussée par le vent ---
        const RAIN = phone ? 170 : 340;
        const rainPos = new Float32Array(RAIN * 6);
        const rainGeo = new THREE.BufferGeometry();
        rainGeo.setAttribute('position', new THREE.BufferAttribute(rainPos, 3));
        const rain = new THREE.LineSegments(rainGeo, new THREE.LineBasicMaterial({ color: 0xb4c6da, transparent: true, opacity: 0.22, depthWrite: false }));
        rain.frustumCulled = false;
        rain.renderOrder = 9;
        scene.add(rain);
        const WIND = V(1.2, -7.0, 0.5);
        const drops = Array.from({ length: RAIN }, () => ({ x: rr(-6.5, 5.5), y: rr(-0.2, 7.5), z: rr(-6, 5.5), s: rr(0.85, 1.15) }));

        // --- Le projecteur du bateau balaie la mer ---
        const spot = new THREE.SpotLight(0xffeccc, 10, 8, 0.26, 0.6, 1.2);
        scene.add(spot, spot.target);
        const beamMat = new THREE.ShaderMaterial({
            vertexShader: `varying float vAlong;
varying vec3 vN;
varying vec3 vV;
void main() {
    vAlong = uv.y;
    vec4 mv = modelViewMatrix * vec4(position, 1.0);
    vN = normalize(normalMatrix * normal);
    vV = normalize(-mv.xyz);
    gl_Position = projectionMatrix * mv;
}`,
            fragmentShader: `varying float vAlong;
varying vec3 vN;
varying vec3 vV;
void main() {
    float edge = pow(abs(dot(normalize(vN), normalize(vV))), 2.0);
    gl_FragColor = vec4(1.0, 0.9, 0.72, pow(vAlong, 1.4) * edge * 0.2);
}`,
            transparent: true,
            depthWrite: false,
            blending: THREE.AdditiveBlending,
            side: THREE.DoubleSide,
        });
        const beam = new THREE.Mesh(new THREE.ConeGeometry(Math.tan(0.2), 1, 28, 1, true).translate(0, -0.5, 0), beamMat);
        beam.renderOrder = 9;
        scene.add(beam);
        const down = V(0, -1, 0);

        // --- Particules ---
        const pointScale = { value: 1 };
        const snowIn = particles(phone ? 30 : 50, true, false, 4);
        const snowDeep = particles(phone ? 140 : 240, true, true, 4);
        const bubbles = particles(phone ? 16 : 26, false, false, 4);
        const foam = particles(22, false, false, 9);
        const splash = particles(24, false, false, 9);
        snowIn.items.forEach((p) => Object.assign(p, { x: rr(-4.7, 4.7), y: rr(BASE + 0.2, -0.2), z: rr(-4.7, 4.7), ph: rr(0, 6.28) }));
        snowDeep.items.forEach((p) => Object.assign(p, { x: rr(-4.8, 4.8), y: rr(-45, BASE - 0.3), z: rr(-4.8, 4.8), ph: rr(0, 6.28) }));
        bubbles.items.forEach((p) => resetBubble(p, true));
        foam.items.forEach((p, i) => Object.assign(p, { a: (i / 22) * Math.PI * 2, ph: rr(0, 6.28) }));
        splash.items.forEach((p) => { p.life = 1; });
        function resetBubble(p, anywhere) {
            p.x = rr(-4.3, 4.3);
            p.z = rr(-4.3, 4.3);
            p.y = anywhere ? rr(BASE + 0.2, -0.3) : BASE + 0.2;
            p.sp = rr(0.25, 0.5);
            p.ph = rr(0, 6.28);
            p.size = rr(0.04, 0.08);
        }
        function splashAt(at, n = 10) {
            let k = 0;
            splash.items.forEach((p) => {
                if (k >= n || p.life < 1) return;
                k++;
                p.life = 0;
                p.from = at.clone();
                p.s = BS * 0.9;
                p.vel = V(rr(-0.5, 0.5), rr(0.6, 1.2), rr(-0.5, 0.5)).multiplyScalar(p.s);
            });
        }

        const rings = [];
        const ringGeo = new THREE.RingGeometry(0.9, 1, 40);
        ringGeo.rotateX(-Math.PI / 2);
        for (let i = 0; i < 12; i++) {
            const m = new THREE.Mesh(ringGeo, new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0, depthWrite: false }));
            m.visible = false;
            m.renderOrder = 8;
            scene.add(m);
            rings.push({ m, t: 1, max: 0.5, dur: 1, x: 0, z: 0 });
        }
        function ripple(x, z, max = 0.45, dur = 1.4, delay = 0) {
            const r = rings.find(k => k.t >= 1) || rings[0];
            Object.assign(r, { t: -delay / dur, max, dur, x, z });
        }

        // --- Caméra : le zoom se rapproche du bateau ---
        const FAR = V(0, -1.0, 0);
        const NEAR = V(B0.x, 0.1, B0.z);
        const target = FAR.clone();
        // Vue de départ : en hauteur, en plongée sur le bateau
        const HOME_EL = 0.5;
        let az = -0.75;
        let el = HOME_EL;
        // Vue de départ : tout près du bateau
        let zoom = 0.46;
        let fit = 24;
        let lastInput = -10;
        let touched = false;
        const pointers = new Map();
        let pinch = 0;
        let downAt = null;
        const canvas = renderer.domElement;
        const spread = () => {
            const [a, b] = [...pointers.values()];
            return Math.hypot(a.x - b.x, a.y - b.y) || 1;
        };
        const onDown = (e) => {
            canvas.setPointerCapture(e.pointerId);
            pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
            if (pointers.size === 1) downAt = { x: e.clientX, y: e.clientY, t: performance.now() };
            if (pointers.size === 2) pinch = spread();
            lastInput = clock;
            touched = true;
        };
        const onMove = (e) => {
            const p = pointers.get(e.pointerId);
            if (!p) return;
            const dx = e.clientX - p.x;
            const dy = e.clientY - p.y;
            p.x = e.clientX;
            p.y = e.clientY;
            if (pointers.size === 1) {
                az -= dx * 0.0065;
                el = clamp(el + dy * 0.0045, 0.04, 1.3);
            } else if (pointers.size === 2) {
                const s = spread();
                if (pinch) zoom = clamp(zoom * pinch / s, 0.15, 1.5);
                pinch = s;
            }
            lastInput = clock;
        };
        const onUp = (e) => {
            pointers.delete(e.pointerId);
            pinch = 0;
            if (downAt && pointers.size === 0) {
                const moved = Math.hypot(e.clientX - downAt.x, e.clientY - downAt.y);
                if (moved < 7 && performance.now() - downAt.t < 400) tap(e);
            }
            downAt = null;
        };
        const onWheel = (e) => {
            e.preventDefault();
            zoom = clamp(zoom * Math.exp(e.deltaY * 0.0012), 0.15, 1.5);
            lastInput = clock;
        };
        canvas.addEventListener('pointerdown', onDown);
        canvas.addEventListener('pointermove', onMove);
        canvas.addEventListener('pointerup', onUp);
        canvas.addEventListener('pointercancel', onUp);
        canvas.addEventListener('wheel', onWheel, { passive: false });

        // Toucher le bateau : une gerbe d'écume. Toucher l'eau : des ronds. Le ciel : un éclair.
        const raycaster = new THREE.Raycaster();
        const ndc = new THREE.Vector2();
        function tap(e) {
            const r = canvas.getBoundingClientRect();
            ndc.set(((e.clientX - r.left) / r.width) * 2 - 1, -((e.clientY - r.top) / r.height) * 2 + 1);
            raycaster.setFromCamera(ndc, camera);
            if (raycaster.intersectObjects(boatMeshes, false).length) {
                boat.localToWorld(v3.set(0.95, 0.05, 0));
                splashAt(v3, 14);
                ripple(B0.x, B0.z, 1.2, 1.6);
                return;
            }
            const w = raycaster.intersectObject(mask)[0];
            if (w && w.point.y < -0.05) return;
            if (!w) {
                if (!still && clock - storm.t0 > 1.2) {
                    lightning();
                    storm.next = clock + rr(26, 44);
                }
                return;
            }
            ripple(w.point.x, w.point.z, 0.5, 1.5);
            ripple(w.point.x, w.point.z, 0.32, 1.3, 0.22);
        }

        function resize() {
            const w = stage.clientWidth || 1;
            const h = stage.clientHeight || 1;
            renderer.setSize(w, h, false);
            camera.aspect = w / h;
            const tanV = Math.tan(THREE.MathUtils.degToRad(camera.fov / 2));
            fit = Math.max(13 / tanV / 2, (camera.aspect < 0.8 ? 15.5 : 16) / (tanV * camera.aspect) / 2);
            if (!touched) zoom = camera.aspect < 0.8 ? 0.62 : 0.46;
            camera.updateProjectionMatrix();
            pointScale.value = camera.projectionMatrix.elements[5] * renderer.domElement.height / 2;
        }
        const ro = new ResizeObserver(resize);
        ro.observe(stage);
        resize();

        // --- Boucle ---
        const outDir = V(Math.sin(YAW), 0, Math.cos(YAW));
        const m4 = new THREE.Matrix4();
        const q = new THREE.Quaternion();
        const v3 = new THREE.Vector3();
        const v4 = new THREE.Vector3();
        const sc = new THREE.Vector3();
        const up = new THREE.Vector3(0, 1, 0);
        let clock = 0;
        let last = performance.now();
        let raf = 0;
        let alive = true;

        function frame(now) {
            if (!alive) return;
            const real = Math.min(0.25, (now - last) / 1000);
            const dt = Math.min(0.05, real);
            last = now;
            clock += dt;
            const t = clock;
            uTime.value = t;

            // Au repos : tour complet et lent autour du diorama, en revenant doucement à la hauteur de départ
            if (!still && !pointers.size) {
                const idle = smooth(clamp((clock - lastInput - 3) / 2, 0, 1));
                az += IDLE_SPIN * dt * idle;
                el += (HOME_EL - el) * Math.min(1, dt * 0.8) * idle;
            }
            target.lerpVectors(NEAR, FAR, smooth(clamp((zoom - 0.2) / 0.8, 0, 1)));
            const dist = fit * zoom;
            camera.position.set(target.x + dist * Math.cos(el) * Math.sin(az), target.y + dist * Math.sin(el), target.z + dist * Math.cos(el) * Math.cos(az));
            camera.lookAt(target);
            const cp = camera.position;
            const facing = [cp.z > HALF, cp.x > HALF, cp.z < -HALF, cp.x < -HALF];
            vEdges.forEach((l, i) => { l.visible = facing[(i + 3) % 4] || facing[i]; });
            bEdges.forEach((l, i) => { l.visible = facing[i]; });

            // Le bateau suit la houle
            const fx = Math.cos(YAW);
            const fz = -Math.sin(YAW);
            const hBow = wave(B0.x + fx * 0.9 * BS, B0.z + fz * 0.9 * BS, t);
            const hStern = wave(B0.x - fx * 0.9 * BS, B0.z - fz * 0.9 * BS, t);
            const hPort = wave(B0.x + outDir.x * 0.4 * BS, B0.z + outDir.z * 0.4 * BS, t);
            const hStar = wave(B0.x - outDir.x * 0.4 * BS, B0.z - outDir.z * 0.4 * BS, t);
            boat.position.set(B0.x, (hBow + hStern) / 2 - 0.03, B0.z);
            boat.rotation.order = 'YZX';
            boat.rotation.set(-(hPort - hStar) * 0.9 / BS + Math.sin(t * 0.8) * 0.05, YAW + Math.sin(t * 0.21) * 0.05, Math.atan2(hBow - hStern, 1.8 * BS) * 1.3);
            radar.rotation.y = t * 1.6;
            const fp = flagGeo.attributes.position;
            for (let i = 0; i < fp.count; i++) {
                const x = flagBase[i * 3] + 0.12;
                fp.setZ(i, Math.sin(t * 10 - x * 22) * 0.035 * (x / 0.24));
            }
            fp.needsUpdate = true;
            flagGeo.computeVertexNormals();
            lampMat.emissiveIntensity = 1.6;
            lanternPivot.rotation.set(-boat.rotation.x * 0.8 + Math.sin(t * 1.7) * 0.1, 0, -boat.rotation.z * 0.8 + Math.sin(t * 2.1 + 1) * 0.14);
            const flick = 0.85 + 0.1 * Math.sin(t * 13) + 0.05 * Math.sin(t * 29 + 2);
            lanternLight.intensity = 1.1 * flick;
            lanternMat.emissiveIntensity = 1.8 * flick;
            lanternHalo.material.opacity = flick;
            boat.updateMatrixWorld(true);

            // Les poissons
            schools.forEach((s) => {
                const [x, y, z] = s.path(t);
                const [x2, , z2] = s.path(t + 0.05);
                const heading = Math.atan2(x2 - x, z2 - z);
                s.off.forEach((o, i) => {
                    v3.set(x + (o.p.x + Math.sin(t * 1.3 + o.ph) * 0.08) * s.scale, y + o.p.y * s.scale, z + (o.p.z + Math.cos(t * 1.1 + o.ph) * 0.08) * s.scale);
                    q.setFromAxisAngle(up, heading + Math.sin(t * 6 + o.ph) * 0.12);
                    m4.compose(v3, q, sc.setScalar(s.scale));
                    s.mesh.setMatrixAt(i, m4);
                });
                s.mesh.instanceMatrix.needsUpdate = true;
            });
            bigFish.forEach((bf) => {
                bf.a += bf.sp * dt;
                bf.g.position.set(bf.cx + bf.rx * Math.cos(bf.a), bf.y + Math.sin(t * 0.8 + bf.a) * 0.08, bf.cz + bf.rz * Math.sin(bf.a));
                bf.g.rotation.y = Math.atan2(-bf.rx * Math.sin(bf.a) * Math.sign(bf.sp), bf.rz * Math.cos(bf.a) * Math.sign(bf.sp));
                bf.tail.rotation.y = Math.sin(t * 6 + bf.a) * 0.4;
            });
            const ra = t * 0.12;
            ray.position.set(Math.cos(ra) * 2.4 - 0.3, -2.75 + Math.sin(t * 0.5) * 0.06, Math.sin(ra) * 2.1);
            ray.rotation.set(0, Math.atan2(-Math.sin(ra) * 2.4, Math.cos(ra) * 2.1), -0.15);
            rayWings.forEach(({ piv, sd }) => { piv.rotation.z = sd * Math.sin(t * 1.6) * 0.35; });
            jellies.forEach((j) => {
                const pulse = Math.pow(Math.max(0, Math.sin(t * 0.9 + j.ph)), 2);
                j.bell.scale.set(1 - pulse * 0.2, 1 + pulse * 0.25, 1 - pulse * 0.2);
                const amp = j.deep ? 0.5 : 0.12;
                j.g.position.set(j.x + Math.sin(t * 0.13 + j.ph) * amp * 2, j.y + Math.sin(t * 0.22 + j.ph) * amp + pulse * 0.03, j.z + Math.cos(t * 0.11 + j.ph) * amp * 2);
                j.g.rotation.z = Math.sin(t * 0.3 + j.ph) * 0.12;
                const ta = j.tg.attributes.position.array;
                let o = 0;
                for (let k = 0; k < TENT; k++) {
                    const a = (k / TENT) * Math.PI * 2;
                    const r0 = 0.12 * (1 - pulse * 0.2);
                    for (let sgm = 0; sgm < SEG; sgm++) {
                        for (const q2 of [sgm, sgm + 1]) {
                            const sway = Math.sin(t * 2.2 - q2 * 0.9 + a) * 0.025 * q2;
                            const rad = r0 * (1 - q2 * 0.08);
                            ta[o++] = Math.cos(a) * rad + sway;
                            ta[o++] = -q2 * 0.075 * (1 - pulse * 0.15);
                            ta[o++] = Math.sin(a) * rad + sway * 0.6;
                        }
                    }
                }
                j.tg.attributes.position.needsUpdate = true;
            });
            const wa = t * 0.05;
            whale.position.set(Math.cos(wa) * 1.4, -17 + Math.sin(t * 0.2) * 0.4, Math.sin(wa) * 1.4);
            whale.rotation.y = Math.atan2(-Math.sin(wa), Math.cos(wa));
            fluke.rotation.x = Math.sin(t * 0.7) * 0.15;

            // Orage : éclairs (jamais plus de deux flashs à la suite)
            sky.rotation.y = az;
            if (!still && t > storm.next) {
                lightning();
                storm.next = t + rr(26, 44);
            }
            const since = t - storm.t0;
            // Une lueur lointaine et douce : elle monte vite, puis s'éteint lentement
            const flash = since < 0 ? 0 : since < 0.18 ? (since / 0.18) * 0.42 : 0.42 * Math.exp(-(since - 0.18) * 2.6);
            hemi.intensity = 1.05 + flash * 0.9;
            flashLight.intensity = flash * 1.2;
            uFlash.value = flash;
            boltMat.opacity = since < 0 ? 0 : 0.5 * Math.exp(-since * 5);
            renderer.setClearColor(0x9fb2d6, flash * 0.08);

            // Pluie
            for (let i = 0; i < RAIN; i++) {
                const d = drops[i];
                d.x += WIND.x * d.s * dt;
                d.y += WIND.y * d.s * dt;
                d.z += WIND.z * d.s * dt;
                const inside = Math.abs(d.x) < HALF && Math.abs(d.z) < HALF;
                if (d.y < (inside ? 0.05 : BASE) || d.x > 6.5) {
                    d.x = rr(-7, 5.5);
                    d.y = rr(6.5, 8);
                    d.z = rr(-6, 5.5);
                }
                rainPos.set([d.x, d.y, d.z, d.x - WIND.x * 0.03, d.y - WIND.y * 0.03, d.z - WIND.z * 0.03], i * 6);
            }
            rainGeo.attributes.position.needsUpdate = true;

            // Projecteur
            lamp.getWorldPosition(v3);
            const look = Math.atan2(outDir.x, outDir.z) + Math.sin(t * 0.3) * 1.0;
            v4.set(B0.x + Math.sin(look) * 2.2, 0, B0.z + Math.cos(look) * 2.2);
            v4.y = wave(v4.x, v4.z, t);
            spot.position.copy(v3);
            spot.target.position.copy(v4);
            sc.subVectors(v4, v3);
            const beamLen = sc.length();
            beam.position.copy(v3);
            beam.quaternion.setFromUnitVectors(down, sc.normalize());
            beam.scale.setScalar(beamLen);

            // Embruns à la proue de temps en temps
            if (t > storm.spray) {
                boat.localToWorld(v3.set(0.95, 0.05, rr(-0.3, 0.3)));
                splashAt(v3, 9);
                storm.spray = t + rr(1.4, 2.8);
            }

            // Ronds dans l'eau
            rings.forEach((r) => {
                if (r.t >= 1) {
                    r.m.visible = false;
                    return;
                }
                r.t += dt / r.dur;
                if (r.t < 0) return;
                const k = Math.min(1, r.t);
                r.m.visible = true;
                r.m.position.set(r.x, wave(r.x, r.z, t) + 0.015, r.z);
                r.m.scale.setScalar(0.04 + r.max * easeOut(k));
                r.m.material.opacity = (1 - k) * 0.6;
            });

            // Particules : plancton (de plus en plus gros, pâle et flou en descendant), bulles, écume
            snowIn.items.forEach((p, i) => {
                p.y -= dt * 0.03;
                if (p.y < BASE + 0.1) p.y = -0.2;
                snowIn.set(i, p.x + Math.sin(t * 0.4 + p.ph) * 0.08, p.y, p.z + Math.cos(t * 0.35 + p.ph) * 0.08, 0.035, [0.45, 0.95, 0.9], 0.3 + 0.25 * Math.sin(t * 1.3 + p.ph));
            });
            snowIn.update();
            snowDeep.items.forEach((p, i) => {
                p.y -= dt * 0.05;
                if (p.y < -45) p.y = BASE - 0.3;
                const d = -p.y;
                snowDeep.set(i, p.x + Math.sin(t * 0.3 + p.ph) * 0.1, p.y, p.z + Math.cos(t * 0.25 + p.ph) * 0.1, 0.04 + d * 0.014, [0.35, 0.85, 0.85], (0.45 + 0.2 * Math.sin(t * 1.1 + p.ph)) * Math.exp(-d * 0.07));
            });
            snowDeep.update();
            bubbles.items.forEach((p, i) => {
                p.y += p.sp * dt;
                if (p.y > -0.15) resetBubble(p, false);
                bubbles.set(i, p.x + Math.sin(t * 3 + p.ph) * 0.02, p.y, p.z + Math.cos(t * 2.6 + p.ph) * 0.02, p.size, [0.75, 0.9, 0.95], 0.45);
            });
            bubbles.update();
            foam.items.forEach((p, i) => {
                boat.localToWorld(v3.set(Math.cos(p.a) * 1.0, -0.02, Math.sin(p.a) * 0.42));
                foam.set(i, v3.x, wave(v3.x, v3.z, t) + 0.01, v3.z, 0.08, [0.85, 0.92, 0.95], 0.45 + 0.3 * Math.sin(t * 2 + p.ph));
            });
            foam.update();
            splash.items.forEach((p, i) => {
                if (p.life >= 1) {
                    splash.set(i, 0, -50, 0, 0, [0, 0, 0], 0);
                    return;
                }
                p.life += real / 0.8;
                const k = Math.min(1, p.life);
                v3.copy(p.from).addScaledVector(p.vel, k * 0.5);
                v3.y -= k * k * 0.35 * p.s;
                v3.x += k * 0.5 * p.s;
                splash.set(i, v3.x, v3.y, v3.z, 0.05 * p.s, [0.82, 0.9, 0.95], 1 - k);
            });
            splash.update();

            renderer.render(scene, camera);
            raf = requestAnimationFrame(frame);
        }
        raf = requestAnimationFrame(frame);

        return {
            dispose() {
                alive = false;
                cancelAnimationFrame(raf);
                ro.disconnect();
                canvas.removeEventListener('wheel', onWheel);
                scene.traverse((o) => {
                    if (o.geometry) o.geometry.dispose();
                    if (o.material) {
                        [].concat(o.material).forEach((m) => {
                            Object.values(m).forEach((v) => { if (v && v.isTexture) v.dispose(); });
                            m.dispose();
                        });
                    }
                });
                renderer.dispose();
                canvas.remove();
            },
        };

        // ---------------- Outils ----------------
        function limb(a, b, r1, r2, mat) {
            const dir = new THREE.Vector3().subVectors(b, a);
            const len = dir.length();
            const m = new THREE.Mesh(new THREE.CylinderGeometry(r2, r1, len, 7), mat);
            m.position.copy(a).addScaledVector(dir, 0.5);
            m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
            return m;
        }

        function mergeGeos(list) {
            const pos = [];
            list.forEach((g) => {
                const n = g.index ? g.toNonIndexed() : g;
                pos.push(...n.attributes.position.array);
            });
            const g = new THREE.BufferGeometry();
            g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
            g.computeVertexNormals();
            return g;
        }

        function particles(count, additive, deep, order) {
            const pos = new Float32Array(count * 3);
            const col = new Float32Array(count * 3);
            const size = new Float32Array(count);
            const alpha = new Float32Array(count);
            const g = new THREE.BufferGeometry();
            g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
            g.setAttribute('aColor', new THREE.BufferAttribute(col, 3));
            g.setAttribute('aSize', new THREE.BufferAttribute(size, 1));
            g.setAttribute('aAlpha', new THREE.BufferAttribute(alpha, 1));
            const m = new THREE.ShaderMaterial({
                uniforms: { uScale: pointScale },
                vertexShader: `attribute vec3 aColor;
attribute float aSize;
attribute float aAlpha;
uniform float uScale;
varying vec3 vColor;
varying float vAlpha;
void main() {
    vec4 mv = modelViewMatrix * vec4(position, 1.0);
    gl_Position = projectionMatrix * mv;
    gl_PointSize = aSize * uScale / -mv.z;
    vColor = aColor;
    vAlpha = aAlpha;
}`,
                fragmentShader: `varying vec3 vColor;
varying float vAlpha;
void main() {
    float r = length(gl_PointCoord - 0.5);
    float a = smoothstep(0.5, 0.05, r) * vAlpha;
    if (a < 0.01) discard;
    gl_FragColor = vec4(vColor, a);
}`,
                transparent: true,
                depthWrite: false,
                blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending,
            });
            if (deep) gate(m);
            const pts = new THREE.Points(g, m);
            pts.frustumCulled = false;
            pts.renderOrder = order;
            scene.add(pts);
            const items = Array.from({ length: count }, () => ({}));
            return {
                items,
                set(i, x, y, z, s, c, a) {
                    pos[i * 3] = x;
                    pos[i * 3 + 1] = y;
                    pos[i * 3 + 2] = z;
                    col[i * 3] = c[0];
                    col[i * 3 + 1] = c[1];
                    col[i * 3 + 2] = c[2];
                    size[i] = s;
                    alpha[i] = a;
                },
                update() {
                    g.attributes.position.needsUpdate = true;
                    g.attributes.aColor.needsUpdate = true;
                    g.attributes.aSize.needsUpdate = true;
                    g.attributes.aAlpha.needsUpdate = true;
                },
            };
        }

        function radialTexture(inner, outer) {
            const cv = document.createElement('canvas');
            cv.width = cv.height = 256;
            const g = cv.getContext('2d');
            const grad = g.createRadialGradient(128, 128, 10, 128, 128, 128);
            grad.addColorStop(0, inner);
            grad.addColorStop(1, outer);
            g.fillStyle = grad;
            g.fillRect(0, 0, 256, 256);
            const tex = new THREE.CanvasTexture(cv);
            tex.colorSpace = THREE.SRGBColorSpace;
            return tex;
        }
    }

    // ---------------------------------------------------------------------
    // Troisième diorama : un phare sur son rocher, une nuit de tempête. Les vagues
    // se brisent sur les rochers, le faisceau perce la brume qui traîne sur l'eau ;
    // sous l'eau, un serpent de mer tourne autour du rocher et, tout au fond,
    // une créature géante déploie ses tentacules (l'une d'elles remonte parfois).
    // ---------------------------------------------------------------------
    function buildLighthouse(THREE, stage) {
        const phone = Math.min(window.innerWidth, window.innerHeight) < 600 || touch();
        const S = 10;
        const HALF = S / 2;
        const BASE = -3.3;
        const ABYSS = -70;
        const rand = mulberry32(11);
        const rr = (a, b) => a + (b - a) * rand();
        const color = (hex) => new THREE.Color(hex);
        const V = (x, y, z) => new THREE.Vector3(x, y, z);
        const flat = (hex, extra) => new THREE.MeshStandardMaterial(Object.assign({ color: hex, flatShading: true, roughness: 0.85 }, extra || {}));
        const tmp = new THREE.Color();
        const smooth = (u) => u * u * (3 - 2 * u);
        const still = calm();
        // Le rocher du phare
        const I = V(-0.9, 0, -0.7);

        const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, stencil: true, powerPreference: 'high-performance' });
        renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, phone ? 1.75 : 2));
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        renderer.setClearColor(0x000000, 0);
        renderer.domElement.className = 'diorama-canvas';
        stage.appendChild(renderer.domElement);
        const scene = new THREE.Scene();
        // La nuit grise : le lointain se perd dans le noir (le dessous de l'eau, lui, garde sa propre teinte)
        scene.fog = new THREE.Fog(0x18202c, 20, 50);
        const camera = new THREE.PerspectiveCamera(30, 1, 0.05, 400);
        const uTime = { value: 0 };
        const uFlash = { value: 0 };

        // --- Pleine nuit : une lueur froide et faible, c'est le phare qui éclaire ---
        const HEMI = 0.78;
        const hemi = new THREE.HemisphereLight(0x7488a6, 0x101820, HEMI);
        scene.add(hemi);
        const key = new THREE.DirectionalLight(0xa6b8d6, 0.62);
        key.position.set(-7, 7, -6);
        key.castShadow = true;
        key.shadow.mapSize.set(phone ? 1024 : 2048, phone ? 1024 : 2048);
        Object.assign(key.shadow.camera, { left: -8, right: 8, top: 9, bottom: -8, near: 1, far: 40 });
        key.shadow.bias = -0.0006;
        key.shadow.normalBias = 0.02;
        scene.add(key);
        const fill = new THREE.DirectionalLight(0x8a9cae, 0.25);
        fill.position.set(6, 4, 7);
        scene.add(fill);
        const flashLight = new THREE.DirectionalLight(0xdfe6ff, 0);
        flashLight.position.set(-3, 10, -7);
        scene.add(flashLight);

        // --- La houle : plus forte que pour le bateau, aplatie juste au bord du bloc ---
        const WAVES = [
            [0.94, 0.34, 1.2, 1.25, 0.2],
            [0.25, 0.97, 1.8, 1.55, 0.12],
            [-0.6, 0.8, 2.8, 1.95, 0.07],
            [0.83, -0.56, 4.6, 2.5, 0.035],
            [-0.3, -0.95, 7.5, 3.1, 0.018],
        ];
        const EDGE = 0.6;
        const wave = (x, z, t) => {
            let h = 0;
            for (const [dx, dz, k, w, a] of WAVES) h += a * (Math.exp(Math.sin((dx * x + dz * z) * k - w * t) - 1) - 0.43);
            return h * smooth(clamp((HALF - Math.max(Math.abs(x), Math.abs(z))) / EDGE, 0, 1));
        };
        const edgeGLSL = `smoothstep(0.0, 1.0, clamp((${HALF.toFixed(2)} - max(abs(p.x), abs(p.y))) / ${EDGE.toFixed(2)}, 0.0, 1.0))`;
        const WAVE_GLSL = `uniform float uTime;
varying vec2 vXZ;
float waveH(vec2 p) {
    float h = 0.0;
${WAVES.map(([dx, dz, k, w, a]) => `    h += ${a.toFixed(4)} * (exp(sin(dot(p, vec2(${dx.toFixed(3)}, ${dz.toFixed(3)})) * ${k.toFixed(3)} - ${w.toFixed(3)} * uTime) - 1.0) - 0.43);`).join('\n')}
    return h * ${edgeGLSL};
}
vec3 waveN(vec2 p) {
    vec2 g = vec2(0.0);
    float th;
${WAVES.map(([dx, dz, k, w, a]) => `    th = dot(p, vec2(${dx.toFixed(3)}, ${dz.toFixed(3)})) * ${k.toFixed(3)} - ${w.toFixed(3)} * uTime;
    g += ${(a * k).toFixed(4)} * exp(sin(th) - 1.0) * cos(th) * vec2(${dx.toFixed(3)}, ${dz.toFixed(3)});`).join('\n')}
    g *= ${edgeGLSL};
    return normalize(vec3(-g.x, 1.0, -g.y));
}
`;

        // --- La profondeur : une eau verte qui avale les couleurs en descendant ---
        const FOG_GLSL = `uniform float uFlash;
vec3 waterFog(vec3 col, float y) {
    float d = max(0.0, -y);
    float f = 1.0 - exp(-d * 0.15);
    vec3 fogc = mix(vec3(0.07, 0.22, 0.19), vec3(0.008, 0.028, 0.035), clamp(d / 24.0, 0.0, 1.0)) * (1.0 + uFlash * 0.7);
    return mix(col, fogc, f);
}
`;
        const underwater = (mat) => {
            mat.onBeforeCompile = (sh) => {
                sh.uniforms.uFlash = uFlash;
                sh.vertexShader = 'varying vec3 vWater;\n' + sh.vertexShader.replace('#include <project_vertex>', `#include <project_vertex>
vec4 wW = vec4(transformed, 1.0);
#ifdef USE_INSTANCING
wW = instanceMatrix * wW;
#endif
vWater = (modelMatrix * wW).xyz;`);
                sh.fragmentShader = 'varying vec3 vWater;\n' + FOG_GLSL + sh.fragmentShader.replace('#include <dithering_fragment>', 'gl_FragColor.rgb = waterFog(gl_FragColor.rgb, vWater.y);\n#include <dithering_fragment>');
            };
            mat.customProgramCacheKey = () => 'underwater-lighthouse';
            // La brume de la nuit reste au-dessus de l'eau : sous la surface, on voit toujours les monstres
            mat.fog = false;
            return mat;
        };
        // Ce qui n'existe que « vu à travers le bloc » : le puits sans fond et ce qui y vit
        const gate = (mat, func) => {
            mat.stencilWrite = true;
            mat.stencilRef = 1;
            mat.stencilFunc = func === undefined ? THREE.EqualStencilFunc : func;
            mat.stencilFail = THREE.KeepStencilOp;
            mat.stencilZFail = THREE.KeepStencilOp;
            mat.stencilZPass = THREE.KeepStencilOp;
            return mat;
        };

        // --- Les parois du puits : un dégradé vert, avec des reflets qui s'éteignent en descendant ---
        const wellMat = (side, func) => {
            const m = new THREE.ShaderMaterial({
                uniforms: { uTime, uFlash },
                vertexShader: `varying vec3 vW;
varying vec3 vN;
void main() {
    vec4 w = modelMatrix * vec4(position, 1.0);
    vW = w.xyz;
    vN = normalize(mat3(modelMatrix) * normal);
    gl_Position = projectionMatrix * viewMatrix * w;
}`,
                fragmentShader: `uniform float uTime;
varying vec3 vW;
varying vec3 vN;
${FOG_GLSL}
float caustic(vec2 p, float t) {
    vec2 q = p;
    float c = 0.0;
    for (int n = 0; n < 3; n++) {
        float fn = float(n);
        q += 0.55 * vec2(sin(q.y * 1.35 + t + fn * 1.7), cos(q.x * 1.15 - t * 0.85 + fn * 2.3));
        c += abs(sin(q.x * 1.9) + sin(q.y * 1.9));
    }
    return pow(clamp(1.0 - c / 3.0, 0.0, 1.0), 3.0);
}
void main() {
    float d = max(0.0, -vW.y);
    vec2 uv = abs(vN.y) > 0.5 ? vW.xz : vec2(abs(vN.x) > 0.5 ? vW.z : vW.x, vW.y);
    float shade = 0.82 + 0.18 * dot(normalize(vN), normalize(vec3(-0.5, 0.0, 0.8)));
    vec3 col = vec3(0.09, 0.25, 0.22) * shade;
    col += vec3(0.5, 0.75, 0.62) * caustic(uv * 1.2, uTime * 0.6) * 0.3 * exp(-d * 0.45);
    col *= 1.0 - 0.1 * smoothstep(0.9, 1.0, fract(vW.y * 0.5));
    gl_FragColor = vec4(waterFog(col, vW.y), 1.0);
}`,
                side,
            });
            if (func !== undefined) gate(m, func);
            return m;
        };
        const wall = (h, yc, mat, order) => {
            [[0, HALF, 0], [HALF, 0, Math.PI / 2], [0, -HALF, Math.PI], [-HALF, 0, -Math.PI / 2]].forEach(([x, z, ry]) => {
                const m = new THREE.Mesh(new THREE.PlaneGeometry(S, h).rotateY(ry), mat);
                m.position.set(x, yc, z);
                m.renderOrder = order;
                scene.add(m);
            });
        };
        wall(-BASE, BASE / 2, wellMat(THREE.BackSide), 0);
        wall(BASE - ABYSS, (BASE + ABYSS) / 2, wellMat(THREE.BackSide, THREE.EqualStencilFunc), 2);
        const abyssCap = new THREE.Mesh(new THREE.PlaneGeometry(S, S).rotateX(-Math.PI / 2), wellMat(THREE.FrontSide, THREE.EqualStencilFunc));
        abyssCap.position.y = ABYSS;
        abyssCap.renderOrder = 2;
        scene.add(abyssCap);
        // Le masque : marque les pixels où l'on regarde dans le bloc (par le dessus ou par les côtés)
        const mask = new THREE.Mesh(new THREE.BoxGeometry(S, -BASE, S).translate(0, BASE / 2, 0), gate(new THREE.MeshBasicMaterial({ colorWrite: false, depthWrite: false }), THREE.AlwaysStencilFunc));
        mask.material.stencilZPass = THREE.ReplaceStencilOp;
        mask.renderOrder = 1;
        scene.add(mask);

        // --- Les vitres et les arêtes du bloc ---
        const glassMat = new THREE.MeshBasicMaterial({ vertexColors: true, transparent: true, depthWrite: false, fog: false });
        [[0, HALF, 0], [HALF, 0, Math.PI / 2], [0, -HALF, Math.PI], [-HALF, 0, -Math.PI / 2]].forEach(([x, z, ry]) => {
            const g = new THREE.PlaneGeometry(S, -BASE, 1, 1).rotateY(ry);
            const col = [];
            for (let i = 0; i < 4; i++) col.push(...(i < 2 ? [0.55, 0.85, 0.78, 0.12] : [0.04, 0.15, 0.14, 0.26]));
            g.setAttribute('color', new THREE.Float32BufferAttribute(col, 4));
            const m = new THREE.Mesh(g, glassMat);
            m.position.set(x, BASE / 2, z);
            m.renderOrder = 6;
            scene.add(m);
        });
        const corners = [[-HALF, HALF], [HALF, HALF], [HALF, -HALF], [-HALF, -HALF]];
        const topLine = new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints(corners.map(([x, z]) => V(x, 0.003, z))), new THREE.LineBasicMaterial({ color: 0xbfe2d8, transparent: true, opacity: 0.5 }));
        topLine.renderOrder = 8;
        scene.add(topLine);
        const edgeMat = new THREE.LineBasicMaterial({ color: 0xa9d2c8, transparent: true, opacity: 0.3 });
        const line = (p1, p2) => {
            const l = new THREE.Line(new THREE.BufferGeometry().setFromPoints([p1, p2]), edgeMat);
            l.renderOrder = 8;
            scene.add(l);
            return l;
        };
        const vEdges = corners.map(([x, z]) => line(V(x, 0, z), V(x, BASE, z)));
        const bEdges = corners.map(([x, z], i) => line(V(x, BASE, z), V(corners[(i + 1) % 4][0], BASE, corners[(i + 1) % 4][1])));
        const wellPts = [];
        const wellCol = [];
        const fade = (y) => 0.38 * Math.exp(y * 0.085);
        corners.forEach(([x, z]) => {
            for (let y = 0; y > -40; y -= 1) {
                wellPts.push(x, y, z, x, y - 1, z);
                wellCol.push(0.66, 0.86, 0.8, fade(y), 0.66, 0.86, 0.8, fade(y - 1));
            }
        });
        for (let y = -5.8; y > -40; y -= 2.5) {
            corners.forEach(([x, z], i) => {
                const [x2, z2] = corners[(i + 1) % 4];
                wellPts.push(x, y, z, x2, y, z2);
                wellCol.push(0.66, 0.86, 0.8, fade(y) * 0.45, 0.66, 0.86, 0.8, fade(y) * 0.45);
            });
        }
        const wellGeo = new THREE.BufferGeometry();
        wellGeo.setAttribute('position', new THREE.Float32BufferAttribute(wellPts, 3));
        wellGeo.setAttribute('color', new THREE.Float32BufferAttribute(wellCol, 4));
        const wellLines = new THREE.LineSegments(wellGeo, gate(new THREE.LineBasicMaterial({ vertexColors: true, transparent: true, depthWrite: false })));
        wellLines.renderOrder = 3;
        scene.add(wellLines);
        const contact = new THREE.Mesh(new THREE.PlaneGeometry(S * 1.9, S * 1.9), new THREE.MeshBasicMaterial({ map: radialTexture('rgba(0,0,0,0.45)', 'rgba(0,0,0,0)'), transparent: true, depthWrite: false }));
        contact.rotation.x = -Math.PI / 2;
        contact.position.set(1, BASE - 0.02, -0.8);
        scene.add(contact);

        // --- La surface : vert sombre, écume sur les crêtes et autour des rochers ---
        const FOAM_ROCKS = [[I.x, I.z, 1.55], [3.8, -3.7, 1.35], [2.7, -4.3, 1.1], [4.3, -2.5, 1.0]];
        const M = phone ? 100 : 140;
        const waterGeo = new THREE.PlaneGeometry(S, S, M, M);
        waterGeo.rotateX(-Math.PI / 2);
        const waterMat = new THREE.MeshStandardMaterial({ color: 0x245a50, roughness: 0.14, metalness: 0.12, transparent: true, depthWrite: false, fog: false });
        waterMat.onBeforeCompile = (sh) => {
            sh.uniforms.uTime = uTime;
            sh.uniforms.uFlash = uFlash;
            sh.vertexShader = WAVE_GLSL + sh.vertexShader
                .replace('#include <beginnormal_vertex>', 'vec3 objectNormal = waveN(position.xz);')
                .replace('#include <begin_vertex>', '#include <begin_vertex>\nvXZ = transformed.xz;\ntransformed.y += waveH(transformed.xz);');
            sh.fragmentShader = WAVE_GLSL + 'uniform float uFlash;\n' + sh.fragmentShader
                .replace('#include <normal_fragment_begin>', '#include <normal_fragment_begin>\nnormal = normalize((viewMatrix * vec4(waveN(vXZ), 0.0)).xyz);')
                .replace('#include <emissivemap_fragment>', `#include <emissivemap_fragment>
float hh = waveH(vXZ);
float foam = smoothstep(0.1, 0.22, hh);
// L'écume des vagues qui se brisent sur les rochers
float rocks = 0.0;
${FOAM_ROCKS.map(([x, z, r]) => `{ vec2 q = vXZ - vec2(${x.toFixed(2)}, ${z.toFixed(2)}); float d = length(q) - ${r.toFixed(2)};
  rocks = max(rocks, smoothstep(0.7, 0.0, d) * (0.55 + 0.45 * sin(uTime * 2.4 + atan(q.y, q.x) * 6.0 - d * 11.0)) * (0.6 + 0.4 * sin(uTime * 1.3 + q.x * 4.1 - q.y * 3.3))); }`).join('\n')}
foam = clamp(foam + rocks, 0.0, 1.0);
diffuseColor.rgb = mix(diffuseColor.rgb, vec3(0.86, 0.9, 0.86), foam * 0.8);
float fres = pow(1.0 - abs(dot(normal, normalize(vViewPosition))), 3.0);
diffuseColor.a = clamp(0.32 + fres * 0.6 + foam * 0.55, 0.0, 0.96);
totalEmissiveRadiance += vec3(0.16, 0.2, 0.18) * fres * 0.6 + vec3(0.55, 0.6, 0.7) * uFlash * fres * 0.4;`);
        };
        const water = new THREE.Mesh(waterGeo, waterMat);
        water.receiveShadow = true;
        water.renderOrder = 7;
        scene.add(water);

        // --- Rochers : des blocs taillés à facettes, coincés dans le bloc ---
        const ROCK = [0x6b6f75, 0x5d6268, 0x787c82, 0x55595f].map(color);
        const WET = color(0x383c40);
        const DEEPR = [0x3c4a46, 0x34413e].map(color);
        const MOSSR = [0x4d5c43, 0x58684b].map(color);
        const rockMat = underwater(new THREE.MeshStandardMaterial({ vertexColors: true, flatShading: true, roughness: 0.92 }));
        const deepRockMat = gate(underwater(new THREE.MeshStandardMaterial({ vertexColors: true, flatShading: true, roughness: 0.95 })));
        deepRockMat.customProgramCacheKey = () => 'underwater-lighthouse-deep';
        // Colore chaque face selon sa hauteur : mousse en haut, roche, roche mouillée, puis roche verdie sous l'eau
        function paintRock(g, mossy) {
            const p = g.attributes.position;
            const c = new Float32Array(p.count * 3);
            for (let f = 0; f < p.count; f += 3) {
                const x = (p.getX(f) + p.getX(f + 1) + p.getX(f + 2)) / 3;
                const y = (p.getY(f) + p.getY(f + 1) + p.getY(f + 2)) / 3;
                const z = (p.getZ(f) + p.getZ(f + 1) + p.getZ(f + 2)) / 3;
                const h = hash(x * 3.1 + y, z * 2.7 - y);
                if (mossy && y > 0.3 && h < 0.7) tmp.copy(MOSSR[h < 0.35 ? 0 : 1]);
                else if (y > 0.28) tmp.copy(ROCK[Math.floor(h * ROCK.length)]);
                else if (y > -0.2) tmp.copy(WET).offsetHSL(0, 0, (h - 0.5) * 0.04);
                else tmp.copy(DEEPR[h < 0.5 ? 0 : 1]);
                for (let k = 0; k < 3; k++) tmp.toArray(c, (f + k) * 3);
            }
            g.setAttribute('color', new THREE.BufferAttribute(c, 3));
            g.computeVertexNormals();
        }
        // Un bloc de roche : une sphère à facettes, cabossée, étirée, puis rognée par les vitres du bloc
        function rockGeo(r, detail, sx, sy, sz, seed) {
            const g = new THREE.IcosahedronGeometry(r, detail);
            const p = g.attributes.position;
            for (let i = 0; i < p.count; i++) {
                const x = p.getX(i);
                const y = p.getY(i);
                const z = p.getZ(i);
                const n = hash(x * 3.7 + seed, z * 2.9 + y * 4.3 - seed) - 0.5;
                const n2 = hash(y * 5.1 + seed * 2, x * 1.3 + z * 3.3) - 0.5;
                const k = 1 + n * 0.4 + n2 * 0.2;
                p.setXYZ(i, x * k * sx, y * k * sy, z * k * sz);
            }
            return g;
        }
        const rocks = [];
        function addRock(g, x, y, z, ry, tilt, mossy) {
            g.rotateX(tilt[0]);
            g.rotateZ(tilt[1]);
            g.rotateY(ry);
            g.translate(x, y, z);
            const p = g.attributes.position;
            for (let i = 0; i < p.count; i++) {
                p.setX(i, clamp(p.getX(i), -HALF + 0.02, HALF - 0.02));
                p.setZ(i, clamp(p.getZ(i), -HALF + 0.02, HALF - 0.02));
                p.setY(i, Math.max(p.getY(i), BASE + 0.01));
            }
            paintRock(g, mossy);
            const m = new THREE.Mesh(g, rockMat);
            m.castShadow = true;
            m.receiveShadow = true;
            scene.add(m);
            rocks.push(m);
            return m;
        }
        // Le rocher du phare : une grosse masse, deux épaules, et des aiguilles tout autour
        addRock(rockGeo(1.25, 1, 1.15, 1.32, 1.05, 1), I.x, -0.35, I.z, 0.3, [0, 0], true);
        addRock(rockGeo(0.85, 1, 1.05, 0.95, 1, 2), I.x + 0.95, -0.55, I.z + 0.65, 1.1, [0.1, -0.1], true);
        addRock(rockGeo(0.75, 1, 1, 1.15, 0.9, 3), I.x - 1.0, -0.45, I.z + 0.5, 2.1, [-0.1, 0.12], true);
        addRock(rockGeo(0.7, 1, 1.1, 1, 1, 4), I.x + 0.2, -0.6, I.z - 1.05, 0.7, [0.05, 0.05], true);
        for (let k = 0; k < (phone ? 6 : 8); k++) {
            const a = (k / 8) * Math.PI * 2 + rr(-0.25, 0.25);
            const d = rr(1.25, 1.6);
            addRock(rockGeo(rr(0.28, 0.4), 0, 0.7, rr(1.8, 2.6), 0.7, 10 + k), I.x + Math.cos(a) * d, rr(-0.55, -0.25), I.z + Math.sin(a) * d, rr(0, 6.28), [rr(-0.3, 0.3), rr(-0.3, 0.3)], false);
        }
        for (let k = 0; k < (phone ? 5 : 9); k++) {
            const a = rr(0, 6.28);
            const d = rr(1.7, 2.2);
            addRock(rockGeo(rr(0.18, 0.32), 0, 1, 0.8, 1, 30 + k), I.x + Math.cos(a) * d, rr(-0.25, -0.05), I.z + Math.sin(a) * d, rr(0, 6.28), [0, 0], false);
        }
        // La côte, au fond : de gros rochers dont le haut est couvert de mousse
        addRock(rockGeo(1.3, 1, 1.3, 0.75, 1.1, 50), 3.8, -0.42, -3.7, 0.4, [0, 0], true);
        addRock(rockGeo(1.1, 1, 1.2, 0.7, 1.0, 51), 2.6, -0.5, -4.3, 1.3, [0, 0.05], true);
        addRock(rockGeo(1.0, 1, 1.0, 0.8, 1.1, 52), 4.3, -0.55, -2.4, 2.2, [0.05, 0], true);
        // Sous l'eau, le rocher descend en colonne jusqu'au fond du bloc… puis dans l'abîme
        function pillarGeo(y0, y1, r0, r1, seed) {
            const h = y1 - y0;
            const g0 = new THREE.CylinderGeometry(r1, r0, h, 14, Math.max(2, Math.round(h / 0.45)), true);
            g0.translate(0, (y0 + y1) / 2, 0);
            const g = g0.toNonIndexed();
            g0.dispose();
            const p = g.attributes.position;
            for (let i = 0; i < p.count; i++) {
                const x = p.getX(i);
                const y = p.getY(i);
                const z = p.getZ(i);
                const k = 1 + (hash(x * 2.3 + seed, z * 2.3 + y * 1.7) - 0.5) * 0.45;
                p.setX(i, x * k);
                p.setZ(i, z * k);
            }
            return g;
        }
        const pillar = pillarGeo(BASE, -0.4, 1.35, 1.15, 3);
        paintRock(pillar, false);
        const pillarMesh = new THREE.Mesh(pillar, rockMat);
        pillarMesh.position.set(I.x, 0, I.z);
        pillarMesh.receiveShadow = true;
        scene.add(pillarMesh);
        const deepPillar = pillarGeo(-30, BASE, 2.3, 1.35, 3);
        paintRock(deepPillar, false);
        const deepPillarMesh = new THREE.Mesh(deepPillar, deepRockMat);
        deepPillarMesh.position.set(I.x, 0, I.z);
        deepPillarMesh.renderOrder = 2;
        scene.add(deepPillarMesh);
        scene.updateMatrixWorld(true);
        const probe = new THREE.Raycaster();
        const groundAt = (x, z, list) => {
            probe.set(V(x, 8, z), V(0, -1, 0));
            const hit = probe.intersectObjects(list, false)[0];
            return hit ? hit.point.y : -Infinity;
        };

        // --- Le phare ---
        const light = new THREE.Group();
        const TOP = groundAt(I.x, I.z, rocks);
        light.position.set(I.x, TOP - 0.18, I.z);
        scene.add(light);
        const stone = flat(0x6d6660);
        const plinth = new THREE.Mesh(new THREE.CylinderGeometry(0.64, 0.74, 0.42, 10), stone);
        plinth.position.y = 0.21;
        light.add(plinth);
        // La tour : des bandes rouges et blanches, un peu irrégulières comme peintes à la main
        const H = 3.0;
        const towerGeo0 = new THREE.CylinderGeometry(0.34, 0.5, H, 12, 12);
        towerGeo0.translate(0, 0.42 + H / 2, 0);
        const towerGeo = towerGeo0.toNonIndexed();
        towerGeo0.dispose();
        const RED = color(0x8c2733);
        const WHITE = color(0xd8cdc0);
        const tpos = towerGeo.attributes.position;
        const tcol = new Float32Array(tpos.count * 3);
        for (let f = 0; f < tpos.count; f += 3) {
            const y = (tpos.getY(f) + tpos.getY(f + 1) + tpos.getY(f + 2)) / 3 - 0.42;
            const x = (tpos.getX(f) + tpos.getX(f + 1) + tpos.getX(f + 2)) / 3;
            const z = (tpos.getZ(f) + tpos.getZ(f + 1) + tpos.getZ(f + 2)) / 3;
            tmp.copy(Math.floor(y / 0.5) % 2 ? WHITE : RED).offsetHSL(0, 0, (hash(x * 9 + y, z * 9) - 0.5) * 0.06);
            for (let k = 0; k < 3; k++) tmp.toArray(tcol, (f + k) * 3);
        }
        towerGeo.setAttribute('color', new THREE.BufferAttribute(tcol, 3));
        towerGeo.computeVertexNormals();
        const tower = new THREE.Mesh(towerGeo, new THREE.MeshStandardMaterial({ vertexColors: true, flatShading: true, roughness: 0.8 }));
        light.add(tower);
        // Porte, fenêtres (une seule allumée)
        const dark = flat(0x1b1a1c);
        const glow = new THREE.MeshStandardMaterial({ color: 0xffcf8a, emissive: 0xffb257, emissiveIntensity: 1.6, flatShading: true });
        const door = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.36, 0.06), dark);
        door.position.set(0, 0.62, 0.49);
        door.rotation.x = -0.05;
        light.add(door);
        [[1.25, 0.2, false], [2.05, 2.4, true], [2.85, 4.3, false]].forEach(([y, a, lit]) => {
            const r = 0.5 - (y - 0.42) / H * 0.16 + 0.005;
            const w = new THREE.Mesh(new THREE.BoxGeometry(0.09, 0.2, 0.04), lit ? glow : dark);
            w.position.set(Math.sin(a) * r, y, Math.cos(a) * r);
            w.rotation.y = a;
            light.add(w);
        });
        // La galerie, sa rambarde, la lanterne vitrée et le toit rouge
        const TOWER_TOP = 0.42 + H;
        const corbel = new THREE.Mesh(new THREE.CylinderGeometry(0.47, 0.36, 0.14, 12), stone);
        corbel.position.y = TOWER_TOP + 0.05;
        light.add(corbel);
        const deck = new THREE.Mesh(new THREE.CylinderGeometry(0.54, 0.54, 0.06, 16), flat(0x3a3436));
        deck.position.y = TOWER_TOP + 0.15;
        light.add(deck);
        const iron = flat(0x2a2628, { metalness: 0.4, roughness: 0.5 });
        for (let k = 0; k < 16; k++) {
            const a = (k / 16) * Math.PI * 2;
            const post = new THREE.Mesh(new THREE.CylinderGeometry(0.008, 0.008, 0.2, 4), iron);
            post.position.set(Math.cos(a) * 0.52, TOWER_TOP + 0.28, Math.sin(a) * 0.52);
            light.add(post);
        }
        const rail = new THREE.Mesh(new THREE.TorusGeometry(0.52, 0.012, 4, 32), iron);
        rail.rotation.x = Math.PI / 2;
        rail.position.y = TOWER_TOP + 0.38;
        light.add(rail);
        const LANTERN = TOWER_TOP + 0.48;
        const lanternBase = new THREE.Mesh(new THREE.CylinderGeometry(0.31, 0.31, 0.14, 12), flat(0x8c2733));
        lanternBase.position.y = TOWER_TOP + 0.25;
        light.add(lanternBase);
        const lampMat = new THREE.MeshStandardMaterial({ color: 0xfff1d0, emissive: 0xffdf9e, emissiveIntensity: 2.2, transparent: true, opacity: 0.92, roughness: 0.2 });
        const lantern = new THREE.Mesh(new THREE.CylinderGeometry(0.28, 0.28, 0.48, 8, 1, true), lampMat);
        lantern.position.y = LANTERN;
        light.add(lantern);
        for (let k = 0; k < 8; k++) {
            const a = (k / 8) * Math.PI * 2 + Math.PI / 8;
            const bar = new THREE.Mesh(new THREE.BoxGeometry(0.025, 0.5, 0.025), iron);
            bar.position.set(Math.cos(a) * 0.285, LANTERN, Math.sin(a) * 0.285);
            light.add(bar);
        }
        const roof = new THREE.Mesh(new THREE.ConeGeometry(0.38, 0.32, 8), flat(0xa33a2e, { roughness: 0.6 }));
        roof.position.y = LANTERN + 0.4;
        light.add(roof);
        const knob = new THREE.Mesh(new THREE.SphereGeometry(0.05, 8, 6), iron);
        knob.position.y = LANTERN + 0.58;
        light.add(knob);
        const spike = new THREE.Mesh(new THREE.CylinderGeometry(0.006, 0.006, 0.3, 4), iron);
        spike.position.y = LANTERN + 0.75;
        light.add(spike);
        light.traverse((m) => { if (m.isMesh) { m.castShadow = true; m.receiveShadow = true; } });
        lantern.castShadow = false;
        const lightMeshes = [];
        light.traverse((m) => { if (m.isMesh) lightMeshes.push(m); });
        // La lampe : une lueur chaude, un halo, et deux faisceaux opposés qui tournent
        const lamp = new THREE.PointLight(0xffd9a0, 4, 11, 1.2);
        lamp.position.y = LANTERN;
        light.add(lamp);
        const haloTex = radialTexture('rgba(255,225,170,0.95)', 'rgba(255,190,110,0)');
        const halo = new THREE.Sprite(new THREE.SpriteMaterial({ map: haloTex, blending: THREE.AdditiveBlending, depthWrite: false, transparent: true, fog: false }));
        halo.scale.setScalar(2.2);
        halo.position.y = LANTERN;
        halo.renderOrder = 10;
        light.add(halo);
        const uBeam = { value: 1 };
        const beamMat = new THREE.ShaderMaterial({
            uniforms: { uBeam },
            vertexShader: `varying float vAlong;
varying vec3 vN;
varying vec3 vV;
void main() {
    vAlong = uv.y;
    vec4 mv = modelViewMatrix * vec4(position, 1.0);
    vN = normalize(normalMatrix * normal);
    vV = normalize(-mv.xyz);
    gl_Position = projectionMatrix * mv;
}`,
            fragmentShader: `uniform float uBeam;
varying float vAlong;
varying vec3 vN;
varying vec3 vV;
void main() {
    float edge = pow(abs(dot(normalize(vN), normalize(vV))), 1.6);
    gl_FragColor = vec4(1.0, 0.9, 0.7, pow(vAlong, 1.8) * edge * 0.32 * uBeam);
}`,
            transparent: true,
            depthWrite: false,
            blending: THREE.AdditiveBlending,
            side: THREE.DoubleSide,
        });
        const beams = new THREE.Group();
        beams.position.y = LANTERN;
        light.add(beams);
        const BEAM_LEN = 15;
        [1, -1].forEach((sd) => {
            const g = new THREE.ConeGeometry(Math.tan(0.09), 1, 28, 1, true).translate(0, -0.5, 0).rotateZ(sd * Math.PI / 2).rotateZ(-sd * 0.05);
            const b = new THREE.Mesh(g, beamMat);
            b.scale.setScalar(BEAM_LEN);
            b.renderOrder = 9;
            beams.add(b);
        });
        // Le faisceau éclaire aussi ce qu'il touche
        const spot = new THREE.SpotLight(0xffe4b8, 7, 18, 0.12, 0.6, 1);
        scene.add(spot, spot.target);

        // --- Des pins sombres sur la côte ---
        const pineMat = flat(0x1d2b28, { roughness: 0.9 });
        const pineMat2 = flat(0x233430, { roughness: 0.9 });
        const pines = [];
        [[3.3, -3.9], [4.1, -3.2], [2.6, -4.5], [3.7, -4.5], [4.5, -2.3], [2.2, -3.8], [4.6, -4.4]].slice(0, phone ? 5 : 7).forEach(([x, z], i) => {
            const y = groundAt(x, z, rocks);
            if (y < 0.15) return;
            const g = new THREE.Group();
            const s = rr(0.85, 1.35);
            [[0.42, 0.75, 0.45], [0.33, 0.62, 0.85], [0.22, 0.5, 1.2]].forEach(([r, h, yy], k) => {
                const cone = new THREE.Mesh(new THREE.ConeGeometry(r, h, 7), k % 2 ? pineMat2 : pineMat);
                cone.position.y = yy;
                g.add(cone);
            });
            const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.04, 0.06, 0.3, 5), flat(0x2a1f1a));
            trunk.position.y = 0.12;
            g.add(trunk);
            g.position.set(x, y - 0.05, z);
            g.scale.set(s, s * rr(1.0, 1.35), s);
            g.rotation.y = rr(0, 6.28);
            g.traverse((m) => { if (m.isMesh) { m.castShadow = true; m.receiveShadow = true; } });
            scene.add(g);
            pines.push({ g, ph: rr(0, 6.28) });
        });

        // --- Des éclairs, loin derrière le diorama ---
        const sky = new THREE.Group();
        scene.add(sky);
        const boltMat = new THREE.MeshBasicMaterial({ color: 0xeef2ff, transparent: true, opacity: 0, depthWrite: false, blending: THREE.AdditiveBlending, fog: false });
        const bolt = new THREE.Mesh(new THREE.BufferGeometry(), boltMat);
        bolt.renderOrder = 9;
        sky.add(bolt);
        const storm = { next: rr(3, 5), t0: -10, wave: rr(0.3, 0.8) };
        function lightning() {
            const pts = [];
            let px = rr(-7, 7);
            const z = rr(-10, -8.5);
            for (let k = 0; k <= 21; k++) {
                pts.push(V(px, 8.6 - k * 0.4, z));
                px += rr(-0.4, 0.4);
            }
            const path = new THREE.CurvePath();
            for (let k = 0; k < pts.length - 1; k++) path.add(new THREE.LineCurve3(pts[k], pts[k + 1]));
            const branch = new THREE.CurvePath();
            let bp = pts[10].clone();
            for (let k = 0; k < 4; k++) {
                const nx = bp.clone().add(V(rr(0.15, 0.4) * (px > 0 ? -1 : 1), -0.36, 0));
                branch.add(new THREE.LineCurve3(bp, nx));
                bp = nx;
            }
            bolt.geometry.dispose();
            bolt.geometry = mergeGeos([new THREE.TubeGeometry(path, 64, 0.04, 4, false), new THREE.TubeGeometry(branch, 20, 0.022, 4, false)]);
            storm.t0 = clock;
        }

        // --- La pluie, la brume légère au ras de l'eau ---
        const RAIN = phone ? 180 : 360;
        const rainPos = new Float32Array(RAIN * 6);
        const rainGeo = new THREE.BufferGeometry();
        rainGeo.setAttribute('position', new THREE.BufferAttribute(rainPos, 3));
        const rain = new THREE.LineSegments(rainGeo, new THREE.LineBasicMaterial({ color: 0xa9b5bf, transparent: true, opacity: 0.3, depthWrite: false }));
        rain.frustumCulled = false;
        rain.renderOrder = 9;
        scene.add(rain);
        const WIND = V(2.0, -9.5, 0.8);
        const drops = Array.from({ length: RAIN }, () => ({ x: rr(-6.5, 5.5), y: rr(-0.2, 8), z: rr(-6, 5.5), s: rr(0.85, 1.15) }));
        // --- La brume : des nappes grises qui traînent sur l'eau autour du phare ---
        // Assez légère pour voir sous l'eau ; le faisceau l'éclaire quand il passe, la lanterne aussi.
        const uBeamA = { value: 0 };
        const uGlow = { value: 1 };
        const uLamp = { value: V(I.x, 0, I.z) };
        const mistMat = (alpha, seed, speed) => new THREE.ShaderMaterial({
            uniforms: { uTime, uFlash, uBeamA, uGlow, uLamp, uAlpha: { value: alpha }, uSeed: { value: seed }, uSpeed: { value: speed } },
            vertexShader: `varying vec3 vW;
void main() {
    vec4 w = modelMatrix * vec4(position, 1.0);
    vW = w.xyz;
    gl_Position = projectionMatrix * viewMatrix * w;
}`,
            fragmentShader: `uniform float uTime;
uniform float uFlash;
uniform float uBeamA;
uniform float uGlow;
uniform vec3 uLamp;
uniform float uAlpha;
uniform float uSeed;
uniform float uSpeed;
varying vec3 vW;
float h21(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
float vnoise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(mix(h21(i), h21(i + vec2(1.0, 0.0)), u.x), mix(h21(i + vec2(0.0, 1.0)), h21(i + vec2(1.0, 1.0)), u.x), u.y);
}
float fbm(vec2 p) {
    float v = 0.0;
    float a = 0.5;
    for (int k = 0; k < 4; k++) { v += a * vnoise(p); p = p * 2.03 + 7.1; a *= 0.5; }
    return v;
}
void main() {
    vec2 drift = vec2(uTime * 0.07, uTime * 0.025) * uSpeed;
    float n = fbm(vW.xz * 0.32 + drift + uSeed);
    float dens = smoothstep(0.3, 0.78, n);
    // Plus dense près du rocher, s'efface doucement au-delà du bloc
    vec2 d = vW.xz - uLamp.xz;
    float r = length(d);
    float edge = 1.0 - smoothstep(4.5, 8.0, length(vW.xz));
    float nearRock = 0.75 + 0.5 * exp(-r * 0.35);
    // Le faisceau (deux côtés opposés) et le halo de la lanterne
    float ang = atan(-d.y, d.x);
    float d1 = abs(mod(ang - uBeamA + 3.14159, 6.28318) - 3.14159);
    float d2 = abs(mod(ang - uBeamA, 6.28318) - 3.14159);
    float lit = (exp(-d1 * d1 * 60.0) + exp(-d2 * d2 * 60.0)) * exp(-r * 0.1) * smoothstep(0.4, 1.4, r);
    float glow = exp(-r * 0.75) * 0.7 * uGlow;
    float light = clamp(lit * 1.3 + glow, 0.0, 1.4);
    vec3 col = mix(vec3(0.36, 0.4, 0.44), vec3(1.0, 0.86, 0.62), clamp(light, 0.0, 1.0));
    col *= 1.0 + uFlash * 0.9;
    float a = dens * uAlpha * edge * nearRock * (1.0 + light * 1.1);
    gl_FragColor = vec4(col, clamp(a, 0.0, 0.55));
}`,
            transparent: true,
            depthWrite: false,
            side: THREE.DoubleSide,
        });
        const mistLayers = [[0.25, 0.2, 1.3, 1.0], [0.65, 0.15, 7.7, 0.8], [1.15, 0.11, 3.9, 1.2], [1.8, 0.07, 11.3, 0.7]].slice(0, phone ? 3 : 4).map(([y, alpha, seed, speed]) => {
            const m = new THREE.Mesh(new THREE.PlaneGeometry(17, 17).rotateX(-Math.PI / 2), mistMat(alpha, seed, speed));
            m.position.y = y;
            m.renderOrder = 9;
            scene.add(m);
            return m;
        });

        // --- Les monstres ---
        // Un serpent de mer qui tourne autour du rocher, sous la surface
        const SEG = phone ? 26 : 34;
        const serpentMat = underwater(flat(0xffffff, { roughness: 0.55, metalness: 0.15 }));
        const serpentBody = new THREE.InstancedMesh(new THREE.IcosahedronGeometry(1, 1).scale(1, 0.9, 1.5), serpentMat, SEG);
        serpentBody.castShadow = true;
        serpentBody.frustumCulled = false;
        const SCALE = [0x3b7a68, 0x2f6a5a, 0x3b7a68, 0x9ab878];
        for (let i = 0; i < SEG; i++) serpentBody.setColorAt(i, color(SCALE[i % 4]));
        scene.add(serpentBody);
        const finMesh = new THREE.InstancedMesh(new THREE.ConeGeometry(0.045, 0.2, 4).translate(0, 0.1, 0), underwater(flat(0xb7c98a)), SEG);
        finMesh.frustumCulled = false;
        scene.add(finMesh);
        const head = new THREE.Group();
        const headMat = underwater(flat(0x2d6a5b, { roughness: 0.5 }));
        head.add(new THREE.Mesh(new THREE.IcosahedronGeometry(0.2, 1).scale(0.85, 0.7, 1.6).translate(0, 0.02, 0.12), headMat));
        const jaw = new THREE.Group();
        jaw.position.set(0, -0.05, 0.0);
        jaw.add(new THREE.Mesh(new THREE.IcosahedronGeometry(0.15, 0).scale(0.8, 0.35, 1.8).translate(0, -0.03, 0.15), underwater(flat(0x9db27a))));
        head.add(jaw);
        const eyeGlow = new THREE.MeshBasicMaterial({ color: 0xd9ff70 });
        [-1, 1].forEach((sd) => {
            const eye = new THREE.Mesh(new THREE.SphereGeometry(0.035, 6, 5), eyeGlow);
            eye.position.set(sd * 0.11, 0.08, 0.2);
            head.add(eye);
            const horn = new THREE.Mesh(new THREE.ConeGeometry(0.04, 0.3, 5).rotateX(-Math.PI / 2 - 0.5).translate(0, 0.05, -0.12), headMat);
            horn.position.set(sd * 0.1, 0.12, 0);
            head.add(horn);
            const frill = new THREE.Mesh(new THREE.BufferGeometry().setFromPoints([V(0, 0, 0.05), V(sd * 0.32, 0.1, -0.12), V(0, 0.02, -0.2)]), underwater(flat(0x7f9c6a, { side: THREE.DoubleSide })));
            frill.geometry.computeVertexNormals();
            frill.position.set(sd * 0.12, 0, 0);
            head.add(frill);
        });
        head.traverse((m) => { if (m.isMesh) m.castShadow = true; });
        scene.add(head);
        const serpent = { s: 0, speed: 1, scare: 0 };
        const serpentAt = (s, out) => {
            const th = s * 0.33;
            const R = 2.5 + 0.4 * Math.sin(s * 0.21);
            out.set(I.x + Math.cos(th) * R, -2.0 + 0.35 * Math.sin(s * 0.55) + 0.2 * Math.sin(th * 3), I.z + Math.sin(th) * R);
            return out;
        };

        // Tout au fond : une créature géante, ses yeux, et ses tentacules qui montent vers le rocher
        const K = V(0.6, -11.5, 0.5);
        const kMat = gate(underwater(flat(0x4c2236, { roughness: 0.6 })));
        kMat.customProgramCacheKey = () => 'underwater-lighthouse-kraken';
        const mantle = new THREE.Mesh(new THREE.IcosahedronGeometry(1, 2).scale(1.8, 2.5, 1.8), kMat);
        mantle.position.copy(K);
        mantle.renderOrder = 2;
        scene.add(mantle);
        const glowTex = radialTexture('rgba(255,215,140,1)', 'rgba(255,160,60,0)');
        const glowSprite = (hex, size, deep) => {
            const m = new THREE.SpriteMaterial({ map: glowTex, color: hex, blending: THREE.AdditiveBlending, depthWrite: false, transparent: true, fog: false });
            if (deep) gate(m);
            const sp = new THREE.Sprite(m);
            sp.scale.setScalar(size);
            sp.renderOrder = 4;
            scene.add(sp);
            return sp;
        };
        const kEyes = [-1, 1].map(() => glowSprite(0xffb347, 1.4, true));
        // Des taches lumineuses sur le corps de la créature
        const kSpots = [];
        for (let i = 0; i < (phone ? 8 : 14); i++) {
            const a = rr(0, 6.28);
            const h = rr(-0.7, 0.8);
            const r = Math.sqrt(1 - h * h);
            const sp = glowSprite(i % 3 ? 0x7fe8ff : 0xd58cff, rr(0.25, 0.45), true);
            kSpots.push({ sp, x: Math.cos(a) * r * 1.85, y: h * 2.55, z: Math.sin(a) * r * 1.85, ph: rr(0, 6.28) });
        }
        const TENT = phone ? 6 : 8;
        const TSEG = 18;
        const tentGeo = new THREE.CylinderGeometry(1, 1, 1, 7, 1);
        const tentMatDeep = gate(underwater(flat(0xffffff, { roughness: 0.6 })));
        tentMatDeep.customProgramCacheKey = () => 'underwater-lighthouse-tent';
        const tentDeep = new THREE.InstancedMesh(tentGeo, tentMatDeep, TENT * TSEG);
        const tentHigh = new THREE.InstancedMesh(tentGeo, underwater(flat(0xffffff, { roughness: 0.6 })), TENT * TSEG);
        tentDeep.renderOrder = 2;
        [tentDeep, tentHigh].forEach((m) => {
            m.frustumCulled = false;
            m.instanceColor = new THREE.InstancedBufferAttribute(new Float32Array(TENT * TSEG * 3), 3);
            scene.add(m);
        });
        const TENT_BASE = color(0x4c2236);
        const TENT_TIP = color(0xa04a64);
        const tentacles = Array.from({ length: TENT }, (_, j) => ({ phi: (j / TENT) * Math.PI * 2 + 0.2, ph: rr(0, 6.28), rise: 0 }));
        const kraken = { scare: 0, next: rr(6, 10), who: -1, riseT: 0 };

        // Des poissons-lanternes dans le noir, sous le bloc
        const anglers = [0, 1].map((i) => {
            const g = new THREE.Group();
            const m = gate(underwater(flat(0x2a2f37, { roughness: 0.7 })));
            g.add(new THREE.Mesh(new THREE.IcosahedronGeometry(0.35, 1).scale(1, 0.85, 1.15), m));
            const teeth = gate(new THREE.MeshBasicMaterial({ color: 0xd9d4c6 }));
            for (let k = 0; k < 7; k++) {
                const tooth = new THREE.Mesh(new THREE.ConeGeometry(0.025, 0.1, 4), teeth);
                tooth.position.set(-0.18 + k * 0.06, -0.05, 0.36);
                tooth.rotation.x = Math.PI;
                g.add(tooth);
            }
            g.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([V(0, 0.25, 0.1), V(0, 0.6, 0.35), V(0, 0.5, 0.65)]), gate(new THREE.LineBasicMaterial({ color: 0x6a6f78 }))));
            g.traverse((o) => { o.renderOrder = 2; });
            scene.add(g);
            const lure = glowSprite(0x9fffe6, 0.55, true);
            return { g, lure, a: i * 3, y: -6.5 - i * 2.2, r: 2.6 - i * 0.6, sp: (i ? -1 : 1) * 0.12 };
        });
        // Des paires d'yeux qui s'allument et s'éteignent tout au fond
        const abyssEyes = [];
        for (let i = 0; i < (phone ? 4 : 7); i++) {
            const x = rr(-3.5, 3.5);
            const z = rr(-3.5, 3.5);
            const y = rr(-34, -18);
            const hex = i % 2 ? 0xff6a4a : 0xbfff6a;
            abyssEyes.push({ eyes: [-1, 1].map((sd) => { const e = glowSprite(hex, 0.7, true); e.position.set(x + sd * 0.35, y, z); return e; }), ph: rr(0, 6.28), sp: rr(0.15, 0.35) });
        }

        // Un petit banc de poissons qui fuit près de la surface
        const fishGeo = mergeGeos([
            new THREE.IcosahedronGeometry(0.06, 0).scale(0.55, 0.85, 1.8),
            new THREE.ConeGeometry(0.045, 0.08, 4).rotateX(-Math.PI / 2).translate(0, 0, -0.14),
        ]);
        const NF = phone ? 12 : 18;
        const school = new THREE.InstancedMesh(fishGeo, underwater(flat(0xffffff, { metalness: 0.3, roughness: 0.45 })), NF);
        const schoolOff = [];
        for (let i = 0; i < NF; i++) {
            schoolOff.push({ p: V(rr(-0.6, 0.6), rr(-0.2, 0.2), rr(-0.6, 0.6)), ph: rr(0, 6.28) });
            school.setColorAt(i, color([0xbfd0c6, 0x9fb6aa, 0xdfe7e0][i % 3]));
        }
        school.frustumCulled = false;
        scene.add(school);
        const schoolAt = (t) => [2.7 + Math.cos(t * 0.3) * 1.2, -0.95 + Math.sin(t * 0.5) * 0.15, 2.5 + Math.sin(t * 0.3) * 1.2];

        // --- Particules ---
        const pointScale = { value: 1 };
        const snowIn = particles(phone ? 30 : 50, true, false, 4);
        const snowDeep = particles(phone ? 140 : 240, true, true, 4);
        const bubbles = particles(phone ? 14 : 22, false, false, 4);
        const spray = particles(phone ? 90 : 160, false, false, 9);
        snowIn.items.forEach((p) => Object.assign(p, { x: rr(-4.7, 4.7), y: rr(BASE + 0.2, -0.2), z: rr(-4.7, 4.7), ph: rr(0, 6.28) }));
        snowDeep.items.forEach((p) => Object.assign(p, { x: rr(-4.8, 4.8), y: rr(-45, BASE - 0.3), z: rr(-4.8, 4.8), ph: rr(0, 6.28) }));
        bubbles.items.forEach((p) => resetBubble(p, true));
        spray.items.forEach((p) => { p.life = 1; });
        function resetBubble(p, anywhere) {
            const a = rr(0, 6.28);
            p.x = I.x + Math.cos(a) * rr(1.3, 1.7);
            p.z = I.z + Math.sin(a) * rr(1.3, 1.7);
            p.y = anywhere ? rr(BASE + 0.2, -0.3) : BASE + 0.2;
            p.sp = rr(0.25, 0.5);
            p.ph = rr(0, 6.28);
            p.size = rr(0.04, 0.08);
        }
        // Une vague se brise sur un rocher : une gerbe d'écume blanche
        function sprayAt(x, z, n, power = 1) {
            let k = 0;
            for (const p of spray.items) {
                if (k >= n) break;
                if (p.life < 1) continue;
                k++;
                p.life = 0;
                p.from = V(x, 0.05, z);
                const out = V(x - I.x, 0, z - I.z).normalize();
                p.vel = V(out.x * rr(0.2, 0.7) + rr(-0.3, 0.3), rr(1.0, 2.0), out.z * rr(0.2, 0.7) + rr(-0.3, 0.3)).multiplyScalar(power);
                p.size = rr(0.05, 0.11);
            }
        }

        const rings = [];
        const ringGeo = new THREE.RingGeometry(0.9, 1, 40);
        ringGeo.rotateX(-Math.PI / 2);
        for (let i = 0; i < 12; i++) {
            const m = new THREE.Mesh(ringGeo, new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0, depthWrite: false }));
            m.visible = false;
            m.renderOrder = 8;
            scene.add(m);
            rings.push({ m, t: 1, max: 0.5, dur: 1, x: 0, z: 0 });
        }
        function ripple(x, z, max = 0.45, dur = 1.4, delay = 0) {
            const r = rings.find(k => k.t >= 1) || rings[0];
            Object.assign(r, { t: -delay / dur, max, dur, x, z });
        }

        // --- Caméra : au départ, au pied du phare, la tour se découpe sur le ciel d'orage ---
        const FAR = V(0, -0.3, 0);
        const NEAR = V(I.x, 2.2, I.z);
        const target = FAR.clone();
        const HOME_EL = 0.3;
        let az = -0.55;
        let el = HOME_EL;
        let zoom = 0.5;
        let fit = 26;
        let lastInput = -10;
        let touched = false;
        const pointers = new Map();
        let pinch = 0;
        let downAt = null;
        const canvas = renderer.domElement;
        const spread = () => {
            const [a, b] = [...pointers.values()];
            return Math.hypot(a.x - b.x, a.y - b.y) || 1;
        };
        const onDown = (e) => {
            canvas.setPointerCapture(e.pointerId);
            pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
            if (pointers.size === 1) downAt = { x: e.clientX, y: e.clientY, t: performance.now() };
            if (pointers.size === 2) pinch = spread();
            lastInput = clock;
            touched = true;
        };
        const onMove = (e) => {
            const p = pointers.get(e.pointerId);
            if (!p) return;
            const dx = e.clientX - p.x;
            const dy = e.clientY - p.y;
            p.x = e.clientX;
            p.y = e.clientY;
            if (pointers.size === 1) {
                az -= dx * 0.0065;
                el = clamp(el + dy * 0.0045, 0.04, 1.3);
            } else if (pointers.size === 2) {
                const s = spread();
                if (pinch) zoom = clamp(zoom * pinch / s, 0.18, 1.5);
                pinch = s;
            }
            lastInput = clock;
        };
        const onUp = (e) => {
            pointers.delete(e.pointerId);
            pinch = 0;
            if (downAt && pointers.size === 0) {
                const moved = Math.hypot(e.clientX - downAt.x, e.clientY - downAt.y);
                if (moved < 7 && performance.now() - downAt.t < 400) tap(e);
            }
            downAt = null;
        };
        const onWheel = (e) => {
            e.preventDefault();
            zoom = clamp(zoom * Math.exp(e.deltaY * 0.0012), 0.18, 1.5);
            lastInput = clock;
        };
        canvas.addEventListener('pointerdown', onDown);
        canvas.addEventListener('pointermove', onMove);
        canvas.addEventListener('pointerup', onUp);
        canvas.addEventListener('pointercancel', onUp);
        canvas.addEventListener('wheel', onWheel, { passive: false });

        // Toucher le phare : il s'embrase. Un monstre : il prend peur. L'eau : des ronds. Le ciel : un éclair.
        const raycaster = new THREE.Raycaster();
        const ndc = new THREE.Vector2();
        const monsterTargets = [serpentBody, mantle];
        head.traverse((m) => { if (m.isMesh) monsterTargets.push(m); });
        let flare = 0;
        function tap(e) {
            const r = canvas.getBoundingClientRect();
            ndc.set(((e.clientX - r.left) / r.width) * 2 - 1, -((e.clientY - r.top) / r.height) * 2 + 1);
            raycaster.setFromCamera(ndc, camera);
            if (raycaster.intersectObjects(lightMeshes, false).length) {
                flare = 1;
                return;
            }
            if (raycaster.intersectObjects(monsterTargets.concat([tentHigh, tentDeep]), false).length) {
                serpent.scare = 3;
                kraken.scare = 4;
                return;
            }
            const w = raycaster.intersectObject(mask)[0];
            if (w && w.point.y < -0.05) return;
            if (!w) {
                if (!still && clock - storm.t0 > 1.2) {
                    lightning();
                    storm.next = clock + rr(26, 44);
                }
                return;
            }
            ripple(w.point.x, w.point.z, 0.5, 1.5);
            ripple(w.point.x, w.point.z, 0.32, 1.3, 0.22);
        }

        function resize() {
            const w = stage.clientWidth || 1;
            const h = stage.clientHeight || 1;
            renderer.setSize(w, h, false);
            camera.aspect = w / h;
            const tanV = Math.tan(THREE.MathUtils.degToRad(camera.fov / 2));
            fit = Math.max(16 / tanV / 2, (camera.aspect < 0.8 ? 15.5 : 16) / (tanV * camera.aspect) / 2);
            if (!touched) zoom = camera.aspect < 0.8 ? 0.62 : 0.5;
            camera.updateProjectionMatrix();
            pointScale.value = camera.projectionMatrix.elements[5] * renderer.domElement.height / 2;
        }
        const ro = new ResizeObserver(resize);
        ro.observe(stage);
        resize();

        // --- Boucle ---
        const m4 = new THREE.Matrix4();
        const q = new THREE.Quaternion();
        const v3 = new THREE.Vector3();
        const v4 = new THREE.Vector3();
        const v5 = new THREE.Vector3();
        const sc = new THREE.Vector3();
        const up = new THREE.Vector3(0, 1, 0);
        const beamDir = new THREE.Vector3();
        const qf = new THREE.Quaternion();
        let clock = 0;
        let last = performance.now();
        let raf = 0;
        let alive = true;

        function frame(now) {
            if (!alive) return;
            const real = Math.min(0.25, (now - last) / 1000);
            const dt = Math.min(0.05, real);
            last = now;
            clock += dt;
            const t = clock;
            uTime.value = t;

            // Au repos : tour lent autour du phare, en revenant doucement à la hauteur de départ
            if (!still && !pointers.size) {
                const idle = smooth(clamp((clock - lastInput - 3) / 2, 0, 1));
                az += IDLE_SPIN * dt * idle;
                el += (HOME_EL - el) * Math.min(1, dt * 0.8) * idle;
            }
            target.lerpVectors(NEAR, FAR, smooth(clamp((zoom - 0.3) / 0.7, 0, 1)));
            const dist = fit * zoom;
            camera.position.set(target.x + dist * Math.cos(el) * Math.sin(az), target.y + dist * Math.sin(el), target.z + dist * Math.cos(el) * Math.cos(az));
            camera.lookAt(target);
            scene.fog.near = dist - 1;
            scene.fog.far = dist + 32;
            const cp = camera.position;
            const facing = [cp.z > HALF, cp.x > HALF, cp.z < -HALF, cp.x < -HALF];
            vEdges.forEach((l, i) => { l.visible = facing[(i + 3) % 4] || facing[i]; });
            bEdges.forEach((l, i) => { l.visible = facing[i]; });

            // Le phare : les faisceaux tournent ; toucher la tour les fait briller plus fort
            flare = Math.max(0, flare - dt * 0.6);
            beams.rotation.y = t * 0.75;
            uBeamA.value = beams.rotation.y;
            uGlow.value = 1 + flare;
            uBeam.value = 1 + flare * 1.6;
            const flick = 0.92 + 0.05 * Math.sin(t * 11) + 0.03 * Math.sin(t * 23 + 1);
            lamp.intensity = (4 + flare * 4) * flick;
            lampMat.emissiveIntensity = (2.2 + flare * 2) * flick;
            halo.scale.setScalar(2.2 + flare * 1.4 + Math.sin(t * 3) * 0.05);
            light.updateMatrixWorld(true);
            beams.getWorldPosition(v3);
            beamDir.set(Math.cos(beams.rotation.y), -0.05, -Math.sin(beams.rotation.y)).normalize();
            spot.position.copy(v3);
            spot.target.position.copy(v3).addScaledVector(beamDir, 12);
            spot.intensity = 7 * (1 + flare);

            // Les pins plient sous le vent
            pines.forEach((p) => { p.g.rotation.z = Math.sin(t * 1.6 + p.ph) * 0.05 + 0.03; });

            // Le serpent de mer
            serpent.scare = Math.max(0, serpent.scare - dt);
            serpent.s += dt * (1 + serpent.scare * 0.9);
            serpentAt(serpent.s, v3);
            serpentAt(serpent.s + 0.05, v4);
            head.position.copy(v3);
            head.position.y -= serpent.scare > 0 ? Math.sin(Math.min(1, serpent.scare / 3) * Math.PI) * 0.6 : 0;
            head.lookAt(v4.x, head.position.y + (v4.y - v3.y), v4.z);
            jaw.rotation.x = 0.15 + Math.max(0, Math.sin(t * 0.9)) * 0.35 + (serpent.scare > 0 ? 0.3 : 0);
            for (let i = 0; i < SEG; i++) {
                const si = serpent.s - (i + 1) * 0.22;
                serpentAt(si, v3);
                serpentAt(si + 0.05, v4);
                v5.subVectors(v4, v3).normalize();
                const sway = Math.sin(t * 3 - i * 0.5) * 0.1;
                v3.x += -v5.z * sway;
                v3.z += v5.x * sway;
                v3.y += Math.sin(t * 2 - i * 0.45) * 0.06 - (serpent.scare > 0 ? Math.sin(Math.min(1, serpent.scare / 3) * Math.PI) * 0.6 * Math.max(0, 1 - i / 10) : 0);
                const r = 0.17 * (1 - (i / SEG) * 0.8) * (1 + 0.15 * Math.sin(i * 0.9));
                v4.copy(v3).add(v5);
                m4.lookAt(v4, v3, up);
                q.setFromRotationMatrix(m4);
                m4.compose(v3, q, sc.set(r, r, r));
                serpentBody.setMatrixAt(i, m4);
                v4.set(0, 1, 0).addScaledVector(v5, -0.7).normalize();
                qf.setFromUnitVectors(up, v4);
                m4.compose(v4.copy(v3).add(sc.set(0, r * 0.85, 0)), qf, sc.set(1, 1 - i / SEG * 0.6, 1));
                finMesh.setMatrixAt(i, m4);
            }
            serpentBody.instanceMatrix.needsUpdate = true;
            finMesh.instanceMatrix.needsUpdate = true;

            // La créature du fond : elle respire, ses yeux clignent, ses tentacules ondulent ;
            // de temps en temps l'une d'elles remonte le long du rocher, jusque dans le bloc
            kraken.scare = Math.max(0, kraken.scare - dt);
            mantle.scale.set(1, 1 + Math.sin(t * 0.5) * 0.04, 1);
            mantle.rotation.y = Math.sin(t * 0.1) * 0.3;
            const blink = Math.pow(Math.max(0, Math.sin(t * 0.37)), 40) > 0.5 ? 0.1 : 1;
            kEyes.forEach((e, k) => {
                const sd = k ? 1 : -1;
                e.position.set(K.x + sd * 0.8 + Math.sin(mantle.rotation.y) * 0.2, K.y - 0.6, K.z + 1.95);
                e.scale.set(1.1 + kraken.scare * 0.2, (1.1 + kraken.scare * 0.2) * blink, 1);
                e.material.opacity = 0.75 + 0.25 * Math.sin(t * 1.3) + kraken.scare * 0.1;
            });
            kSpots.forEach((k2) => {
                const c = Math.cos(mantle.rotation.y);
                const s2 = Math.sin(mantle.rotation.y);
                k2.sp.position.set(K.x + k2.x * c + k2.z * s2, K.y + k2.y * mantle.scale.y, K.z - k2.x * s2 + k2.z * c);
                k2.sp.material.opacity = 0.45 + 0.4 * Math.sin(t * 0.9 + k2.ph) + kraken.scare * 0.15;
            });
            if (!still && t > kraken.next && kraken.who < 0 && kraken.scare <= 0) {
                kraken.who = Math.floor(rr(0, TENT));
                kraken.riseT = 0;
            }
            if (kraken.who >= 0) {
                kraken.riseT += dt;
                if (kraken.riseT > 11 || kraken.scare > 0) {
                    kraken.who = -1;
                    kraken.next = t + rr(10, 18);
                }
            }
            let nDeep = 0;
            let nHigh = 0;
            tentacles.forEach((tc, j) => {
                const wantRise = j === kraken.who ? smooth(clamp(kraken.riseT / 3.5, 0, 1)) * smooth(clamp((11 - kraken.riseT) / 3, 0, 1)) : 0;
                tc.rise += (wantRise - tc.rise) * Math.min(1, dt * 2);
                const retract = kraken.scare > 0 ? smooth(Math.min(1, kraken.scare / 2)) : 0;
                const a = tc.phi + Math.sin(t * 0.18 + tc.ph) * 0.35;
                // Point de départ (sous la créature), but (autour du rocher), et deux points de contrôle
                const bx = K.x + Math.cos(tc.phi) * 1.3;
                const bz = K.z + Math.sin(tc.phi) * 1.3;
                const by = K.y - 1.0;
                const R = lerp(2.6 + Math.sin(t * 0.3 + j) * 0.4, 1.75, tc.rise);
                const tx = I.x + Math.cos(a) * R;
                const tz = I.z + Math.sin(a) * R;
                const ty = lerp(-5.2 + Math.sin(t * 0.33 + j * 1.3) * 1.2, -0.9, tc.rise) - retract * 5;
                let px = bx;
                let py = by;
                let pz = bz;
                for (let i = 1; i <= TSEG; i++) {
                    const u = i / TSEG;
                    const iu = 1 - u;
                    // Courbe de Bézier : part vers l'extérieur, puis remonte vers le rocher
                    const c1x = bx + Math.cos(tc.phi) * 3;
                    const c1z = bz + Math.sin(tc.phi) * 3;
                    const c1y = by + 2;
                    const c2x = tx + Math.cos(a) * 1.5;
                    const c2z = tz + Math.sin(a) * 1.5;
                    const c2y = ty - 4;
                    let x = iu * iu * iu * bx + 3 * iu * iu * u * c1x + 3 * iu * u * u * c2x + u * u * u * tx;
                    let y = iu * iu * iu * by + 3 * iu * iu * u * c1y + 3 * iu * u * u * c2y + u * u * u * ty;
                    let z = iu * iu * iu * bz + 3 * iu * iu * u * c1z + 3 * iu * u * u * c2z + u * u * u * tz;
                    // Ondulation, et une boucle au bout
                    const wv = Math.sin(u * Math.PI * 3 - t * 1.4 + tc.ph) * 0.45 * u;
                    x += -Math.sin(a) * wv;
                    z += Math.cos(a) * wv;
                    const curl = Math.max(0, (u - 0.75) / 0.25);
                    x += Math.cos(t * 1.2 + tc.ph + curl * 4) * curl * 0.35;
                    z += Math.sin(t * 1.2 + tc.ph + curl * 4) * curl * 0.35;
                    // Le bout ne sort jamais des vitres du bloc
                    if (y > BASE - 0.2) {
                        x = clamp(x, -HALF + 0.3, HALF - 0.3);
                        z = clamp(z, -HALF + 0.3, HALF - 0.3);
                    }
                    v3.set(px, py, pz);
                    v4.set(x, y, z);
                    v5.subVectors(v4, v3);
                    const len = v5.length();
                    const rad = lerp(0.36, 0.035, u);
                    q.setFromUnitVectors(up, v5.normalize());
                    m4.compose(v3.add(v4).multiplyScalar(0.5), q, sc.set(rad, len * 1.08, rad));
                    tmp.copy(TENT_BASE).lerp(TENT_TIP, u);
                    if (v3.y < BASE) {
                        tentDeep.setMatrixAt(nDeep, m4);
                        tentDeep.setColorAt(nDeep++, tmp);
                    } else {
                        tentHigh.setMatrixAt(nHigh, m4);
                        tentHigh.setColorAt(nHigh++, tmp);
                    }
                    px = x;
                    py = y;
                    pz = z;
                }
            });
            tentDeep.count = nDeep;
            tentHigh.count = nHigh;
            [tentDeep, tentHigh].forEach((m) => {
                m.instanceMatrix.needsUpdate = true;
                m.instanceColor.needsUpdate = true;
            });

            anglers.forEach((an) => {
                an.a += an.sp * dt;
                an.g.position.set(Math.cos(an.a) * an.r, an.y + Math.sin(t * 0.4 + an.a) * 0.3, Math.sin(an.a) * an.r);
                an.g.rotation.y = Math.atan2(-Math.sin(an.a) * Math.sign(an.sp), Math.cos(an.a) * Math.sign(an.sp));
                an.g.updateMatrixWorld();
                an.g.localToWorld(an.lure.position.set(0, 0.5, 0.68));
                an.lure.material.opacity = 0.7 + 0.3 * Math.sin(t * 2.3 + an.a * 3);
            });
            abyssEyes.forEach((ae) => {
                const open = Math.sin(t * ae.sp + ae.ph);
                const k = smooth(clamp((open - 0.2) / 0.3, 0, 1));
                ae.eyes.forEach((e) => {
                    e.scale.set(0.7, 0.7 * Math.max(0.05, k), 1);
                    e.material.opacity = k;
                });
            });

            const [fx, fy, fz] = schoolAt(t);
            const [fx2, , fz2] = schoolAt(t + 0.05);
            const fh = Math.atan2(fx2 - fx, fz2 - fz);
            schoolOff.forEach((o, i) => {
                v3.set(fx + (o.p.x + Math.sin(t * 1.3 + o.ph) * 0.08) * 1.4, fy + o.p.y * 1.4, fz + (o.p.z + Math.cos(t * 1.1 + o.ph) * 0.08) * 1.4);
                q.setFromAxisAngle(up, fh + Math.sin(t * 6 + o.ph) * 0.12);
                m4.compose(v3, q, sc.setScalar(1.4));
                school.setMatrixAt(i, m4);
            });
            school.instanceMatrix.needsUpdate = true;

            // Orage : éclairs (jamais plus de deux flashs à la suite)
            sky.rotation.y = az;
            if (!still && t > storm.next) {
                lightning();
                storm.next = t + rr(26, 44);
            }
            const since = t - storm.t0;
            // Une lueur lointaine et douce : elle monte vite, puis s'éteint lentement
            const flash = since < 0 ? 0 : since < 0.18 ? (since / 0.18) * 0.42 : 0.42 * Math.exp(-(since - 0.18) * 2.6);
            hemi.intensity = HEMI + flash * 0.9;
            flashLight.intensity = flash * 1.2;
            uFlash.value = flash;
            boltMat.opacity = since < 0 ? 0 : 0.5 * Math.exp(-since * 5);
            stage.style.setProperty('--flash', (flash * 0.6).toFixed(3));

            // Pluie
            for (let i = 0; i < RAIN; i++) {
                const d = drops[i];
                d.x += WIND.x * d.s * dt;
                d.y += WIND.y * d.s * dt;
                d.z += WIND.z * d.s * dt;
                const inside = Math.abs(d.x) < HALF && Math.abs(d.z) < HALF;
                if (d.y < (inside ? 0.05 : BASE) || d.x > 6.5) {
                    d.x = rr(-7, 5.5);
                    d.y = rr(6.5, 8.5);
                    d.z = rr(-6, 5.5);
                }
                rainPos.set([d.x, d.y, d.z, d.x - WIND.x * 0.03, d.y - WIND.y * 0.03, d.z - WIND.z * 0.03], i * 6);
            }
            rainGeo.attributes.position.needsUpdate = true;

            // Les vagues se brisent sur les rochers
            if (t > storm.wave) {
                const onShore = rand() < 0.3;
                const a = rr(0, 6.28);
                if (onShore) {
                    const [cx, cz, cr] = FOAM_ROCKS[1 + Math.floor(rr(0, 3))];
                    sprayAt(clamp(cx + Math.cos(a) * cr, -4.9, 4.9), clamp(cz + Math.sin(a) * cr, -4.9, 4.9), 10, 0.8);
                } else {
                    sprayAt(I.x + Math.cos(a) * 1.5, I.z + Math.sin(a) * 1.5, 14, 1);
                }
                storm.wave = t + rr(0.25, 0.7);
            }
            spray.items.forEach((p, i) => {
                if (p.life >= 1) {
                    spray.set(i, 0, -50, 0, 0, [0, 0, 0], 0);
                    return;
                }
                p.life += real / 1.1;
                const k = Math.min(1, p.life);
                v3.copy(p.from).addScaledVector(p.vel, k * 0.9);
                v3.y -= k * k * 1.4;
                v3.x += k * 0.4;
                spray.set(i, v3.x, Math.max(v3.y, -0.1), v3.z, p.size * (1 + k), [0.9, 0.93, 0.9], (1 - k) * 0.9);
            });
            spray.update();

            // Ronds dans l'eau
            rings.forEach((r) => {
                if (r.t >= 1) {
                    r.m.visible = false;
                    return;
                }
                r.t += dt / r.dur;
                if (r.t < 0) return;
                const k = Math.min(1, r.t);
                r.m.visible = true;
                r.m.position.set(r.x, wave(r.x, r.z, t) + 0.015, r.z);
                r.m.scale.setScalar(0.04 + r.max * easeOut(k));
                r.m.material.opacity = (1 - k) * 0.6;
            });

            // Particules : plancton (de plus en plus gros, pâle et flou en descendant), bulles
            snowIn.items.forEach((p, i) => {
                p.y -= dt * 0.03;
                if (p.y < BASE + 0.1) p.y = -0.2;
                snowIn.set(i, p.x + Math.sin(t * 0.4 + p.ph) * 0.08, p.y, p.z + Math.cos(t * 0.35 + p.ph) * 0.08, 0.035, [0.5, 0.95, 0.8], 0.3 + 0.25 * Math.sin(t * 1.3 + p.ph));
            });
            snowIn.update();
            snowDeep.items.forEach((p, i) => {
                p.y -= dt * 0.05;
                if (p.y < -45) p.y = BASE - 0.3;
                const d = -p.y;
                snowDeep.set(i, p.x + Math.sin(t * 0.3 + p.ph) * 0.1, p.y, p.z + Math.cos(t * 0.25 + p.ph) * 0.1, 0.04 + d * 0.014, [0.4, 0.85, 0.75], (0.45 + 0.2 * Math.sin(t * 1.1 + p.ph)) * Math.exp(-d * 0.07));
            });
            snowDeep.update();
            bubbles.items.forEach((p, i) => {
                p.y += p.sp * dt;
                if (p.y > -0.15) resetBubble(p, false);
                bubbles.set(i, p.x + Math.sin(t * 3 + p.ph) * 0.02, p.y, p.z + Math.cos(t * 2.6 + p.ph) * 0.02, p.size, [0.75, 0.92, 0.88], 0.45);
            });
            bubbles.update();

            renderer.render(scene, camera);
            raf = requestAnimationFrame(frame);
        }
        raf = requestAnimationFrame(frame);

        return {
            dispose() {
                alive = false;
                cancelAnimationFrame(raf);
                ro.disconnect();
                stage.style.removeProperty('--flash');
                canvas.removeEventListener('wheel', onWheel);
                scene.traverse((o) => {
                    if (o.geometry) o.geometry.dispose();
                    if (o.material) {
                        [].concat(o.material).forEach((m) => {
                            Object.values(m).forEach((v) => { if (v && v.isTexture) v.dispose(); });
                            m.dispose();
                        });
                    }
                });
                renderer.dispose();
                canvas.remove();
            },
        };

        // ---------------- Outils ----------------
        function mergeGeos(list) {
            const pos = [];
            list.forEach((g) => {
                const n = g.index ? g.toNonIndexed() : g;
                pos.push(...n.attributes.position.array);
            });
            const g = new THREE.BufferGeometry();
            g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
            g.computeVertexNormals();
            return g;
        }

        function particles(count, additive, deep, order) {
            const pos = new Float32Array(count * 3);
            const col = new Float32Array(count * 3);
            const size = new Float32Array(count);
            const alpha = new Float32Array(count);
            const g = new THREE.BufferGeometry();
            g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
            g.setAttribute('aColor', new THREE.BufferAttribute(col, 3));
            g.setAttribute('aSize', new THREE.BufferAttribute(size, 1));
            g.setAttribute('aAlpha', new THREE.BufferAttribute(alpha, 1));
            const m = new THREE.ShaderMaterial({
                uniforms: { uScale: pointScale },
                vertexShader: `attribute vec3 aColor;
attribute float aSize;
attribute float aAlpha;
uniform float uScale;
varying vec3 vColor;
varying float vAlpha;
void main() {
    vec4 mv = modelViewMatrix * vec4(position, 1.0);
    gl_Position = projectionMatrix * mv;
    gl_PointSize = aSize * uScale / -mv.z;
    vColor = aColor;
    vAlpha = aAlpha;
}`,
                fragmentShader: `varying vec3 vColor;
varying float vAlpha;
void main() {
    float r = length(gl_PointCoord - 0.5);
    float a = smoothstep(0.5, 0.05, r) * vAlpha;
    if (a < 0.01) discard;
    gl_FragColor = vec4(vColor, a);
}`,
                transparent: true,
                depthWrite: false,
                blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending,
            });
            if (deep) gate(m);
            const pts = new THREE.Points(g, m);
            pts.frustumCulled = false;
            pts.renderOrder = order;
            scene.add(pts);
            const items = Array.from({ length: count }, () => ({}));
            return {
                items,
                set(i, x, y, z, s, c, a) {
                    pos[i * 3] = x;
                    pos[i * 3 + 1] = y;
                    pos[i * 3 + 2] = z;
                    col[i * 3] = c[0];
                    col[i * 3 + 1] = c[1];
                    col[i * 3 + 2] = c[2];
                    size[i] = s;
                    alpha[i] = a;
                },
                update() {
                    g.attributes.position.needsUpdate = true;
                    g.attributes.aColor.needsUpdate = true;
                    g.attributes.aSize.needsUpdate = true;
                    g.attributes.aAlpha.needsUpdate = true;
                },
            };
        }

        function radialTexture(inner, outer) {
            const cv = document.createElement('canvas');
            cv.width = cv.height = 256;
            const g = cv.getContext('2d');
            const grad = g.createRadialGradient(128, 128, 10, 128, 128, 128);
            grad.addColorStop(0, inner);
            grad.addColorStop(1, outer);
            g.fillStyle = grad;
            g.fillRect(0, 0, 256, 256);
            const tex = new THREE.CanvasTexture(cv);
            tex.colorSpace = THREE.SRGBColorSpace;
            return tex;
        }
    }

    // ---------------------------------------------------------------------
    // Quatrième diorama : l'oasis dans la tempête de sable. Au milieu des dunes,
    // une petite oasis (palmiers, papyrus) où vivent des crocodiles : deux se
    // chauffent sur la berge, un autre nage tout doucement. Autour, le vent
    // soulève le sable : tout devient orange, on devine à peine le décor.
    // ---------------------------------------------------------------------
    function buildDesert(THREE, stage) {
        const phone = Math.min(window.innerWidth, window.innerHeight) < 600 || touch();
        const S = 10;
        const HALF = S / 2;
        const N = phone ? 48 : 72;
        const BASE = -3.0;
        const WATER = -0.14;
        const rand = mulberry32(7);
        const rr = (a, b) => a + (b - a) * rand();
        const color = (hex) => new THREE.Color(hex);
        const V = (x, y, z) => new THREE.Vector3(x, y, z);
        const flat = (hex, extra) => new THREE.MeshStandardMaterial(Object.assign({ color: hex, flatShading: true, roughness: 0.85 }, extra || {}));
        const tmp = new THREE.Color();
        const smooth = (u) => u * u * (3 - 2 * u);
        const still = calm();

        // --- Plan de la scène : l'oasis au centre, les dunes tout autour ---
        const PONDS = [[0.05, 0.15, 1.2], [0.95, 0.8, 0.72], [-0.9, 0.75, 0.62], [0.3, -0.75, 0.6]];
        const pondD = (x, z) => {
            let d = Infinity;
            for (const [cx, cz, r] of PONDS) d = Math.min(d, Math.hypot(x - cx, z - cz) - r);
            return d;
        };
        // Les dunes : un dos en pente douce face au vent, une face raide derrière, et deux cornes en croissant
        const DUNES = [
            [3.6, -3.2, 0.95, 0.35, 2.2, 0.85, 1.6, 0.22],
            [-3.7, 3.4, 0.85, 0.25, 2.0, 0.8, 1.5, 0.22],
            [4.2, 1.2, 0.6, 0.4, 1.5, 0.6, 1.3, 0.3],
            [-0.8, 4.4, 0.55, 0.3, 1.7, 0.7, 1.4, 0.25],
            [-4.3, -0.6, 0.7, 0.35, 1.6, 0.7, 1.4, 0.2],
            [-1.6, -4.2, 0.8, 0.35, 1.8, 0.7, 1.5, 0.2],
            [1.9, 4.3, 0.45, 0.3, 1.4, 0.6, 1.2, 0.2],
        ];
        const dune = (x, z, [cx, cz, A, th, w1, w2, wv, c]) => {
            const dx = x - cx;
            const dz = z - cz;
            const u = dx * Math.cos(th) + dz * Math.sin(th);
            const v = -dx * Math.sin(th) + dz * Math.cos(th);
            const uu = u + c * v * v;
            const p = uu < 0 ? Math.exp(-Math.pow(uu / w1, 2)) : Math.exp(-Math.pow(uu / w2, 2));
            return A * p * Math.exp(-Math.pow(v / wv, 2));
        };
        const height = (x, z) => {
            let h = 0.06 * Math.sin(x * 0.7 + z * 0.3) + 0.05 * Math.sin(z * 0.9 - x * 0.4) + 0.03 * Math.sin((x + z) * 1.7);
            for (const d of DUNES) h += dune(x, z, d);
            // L'oasis creuse une cuvette, l'eau au fond
            const d = pondD(x, z);
            h = lerp(h, 0.0, 1 - smooth(clamp(d / 1.7, 0, 1)));
            if (d < 0) {
                const k = Math.min(1, -d / 0.7);
                h = -0.02 - 0.5 * smooth(k);
            }
            return h;
        };

        // --- Rendu ---
        const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, powerPreference: 'high-performance' });
        renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, phone ? 1.75 : 2));
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        renderer.setClearColor(0x000000, 0);
        renderer.domElement.className = 'diorama-canvas';
        stage.appendChild(renderer.domElement);
        const scene = new THREE.Scene();
        // La tempête : une brume de sable épaisse et orange, qui avale le lointain
        const DUST = 0xc98a52;
        scene.fog = new THREE.Fog(DUST, 10, 30);
        const camera = new THREE.PerspectiveCamera(30, 1, 0.1, 300);
        const uTime = { value: 0 };

        // --- Un soleil voilé : la lumière passe à travers le sable, chaude et diffuse ---
        const SUN = V(-8, 7, 4);
        const hemi = new THREE.HemisphereLight(0xf0b47a, 0x8a5634, 1.35);
        scene.add(hemi);
        const sun = new THREE.DirectionalLight(0xffb878, 1.25);
        sun.position.copy(SUN);
        sun.castShadow = true;
        sun.shadow.mapSize.set(phone ? 1024 : 2048, phone ? 1024 : 2048);
        Object.assign(sun.shadow.camera, { left: -8, right: 8, top: 8, bottom: -8, near: 1, far: 40 });
        sun.shadow.bias = -0.0005;
        sun.shadow.normalBias = 0.03;
        sun.shadow.radius = 4;
        scene.add(sun);

        // Un ciel de sable en miniature, pour les reflets de l'eau
        const pmrem = new THREE.PMREMGenerator(renderer);
        const envScene = new THREE.Scene();
        const skyGeo = new THREE.SphereGeometry(10, 32, 16);
        const skyCol = [];
        const sp = skyGeo.attributes.position;
        for (let i = 0; i < sp.count; i++) {
            const y = sp.getY(i) / 10;
            tmp.copy(color(0xd9a06a)).lerp(color(y > 0 ? 0xb87a48 : 0x8a5a36), smooth(clamp(Math.abs(y) * 1.5, 0, 1)));
            skyCol.push(tmp.r, tmp.g, tmp.b);
        }
        skyGeo.setAttribute('color', new THREE.Float32BufferAttribute(skyCol, 3));
        envScene.add(new THREE.Mesh(skyGeo, new THREE.MeshBasicMaterial({ vertexColors: true, side: THREE.BackSide })));
        const envMap = pmrem.fromScene(envScene, 0.04).texture;
        envScene.traverse((o) => { if (o.geometry) o.geometry.dispose(); if (o.material) o.material.dispose(); });
        pmrem.dispose();

        // --- Le sol : sable, sable mouillé, herbe de l'oasis, fond de l'eau ---
        const grid = new THREE.PlaneGeometry(S, S, N, N);
        grid.rotateX(-Math.PI / 2);
        const gp = grid.attributes.position;
        for (let i = 0; i < gp.count; i++) gp.setY(i, height(gp.getX(i), gp.getZ(i)));
        const terrainGeo = grid.toNonIndexed();
        grid.dispose();
        const tp = terrainGeo.attributes.position;
        const tc = new Float32Array(tp.count * 3);
        const SAND = [0xe0b07a, 0xd9a670, 0xe6b886, 0xd09c66].map(color);
        const WET = color(0xa47c52);
        const GRASS = [0x7a8e3e, 0x86984a, 0x6e8238].map(color);
        const BED = color(0x7a6444);
        const DEEP = color(0x3d5a4c);
        for (let f = 0; f < tp.count; f += 3) {
            const x = (tp.getX(f) + tp.getX(f + 1) + tp.getX(f + 2)) / 3;
            const y = (tp.getY(f) + tp.getY(f + 1) + tp.getY(f + 2)) / 3;
            const z = (tp.getZ(f) + tp.getZ(f + 1) + tp.getZ(f + 2)) / 3;
            const h = hash(x, z);
            const d = pondD(x, z);
            if (y < WATER - 0.02) tmp.copy(BED).lerp(DEEP, clamp((WATER - y) / 0.4, 0, 1));
            else if (y < WATER + 0.06) tmp.copy(WET);
            else if (d < 0.7 || (d < 1.1 && h < 0.45)) tmp.copy(GRASS[Math.floor(h * GRASS.length)]);
            else tmp.copy(SAND[Math.floor(h * SAND.length)]);
            for (let k = 0; k < 3; k++) tmp.toArray(tc, (f + k) * 3);
        }
        terrainGeo.setAttribute('color', new THREE.BufferAttribute(tc, 3));
        terrainGeo.computeVertexNormals();
        const terrainMat = new THREE.MeshStandardMaterial({ vertexColors: true, flatShading: true, roughness: 0.95 });
        // Les rides que le vent dessine sur le sable, et qui avancent tout doucement
        terrainMat.onBeforeCompile = (sh) => {
            sh.uniforms.uTime = uTime;
            sh.vertexShader = 'varying vec3 vRip;\n' + sh.vertexShader.replace('#include <begin_vertex>', '#include <begin_vertex>\nvRip = (modelMatrix * vec4(transformed, 1.0)).xyz;');
            sh.fragmentShader = 'uniform float uTime;\nvarying vec3 vRip;\n' + sh.fragmentShader.replace('#include <color_fragment>', `#include <color_fragment>
float oas = 1.0 - smoothstep(1.6, 2.4, length(vRip.xz - vec2(0.05, 0.15)));
float rp = sin(dot(vRip.xz, vec2(0.94, 0.34)) * 26.0 - uTime * 0.6 + sin(vRip.x * 1.7 + vRip.z * 1.1) * 2.5);
diffuseColor.rgb *= 1.0 + 0.05 * rp * (1.0 - oas);`);
        };
        const terrain = new THREE.Mesh(terrainGeo, terrainMat);
        terrain.receiveShadow = true;
        scene.add(terrain);

        // --- Côtés du bloc : des couches de grès ---
        const sideMat = new THREE.MeshStandardMaterial({ map: strataTexture(), roughness: 1 });
        const lipMat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 1 });
        const EDGES = [
            { x0: -HALF, z0: HALF, dx: 1, dz: 0 },
            { x0: HALF, z0: HALF, dx: 0, dz: -1 },
            { x0: HALF, z0: -HALF, dx: -1, dz: 0 },
            { x0: -HALF, z0: -HALF, dx: 0, dz: 1 },
        ];
        const LIP_TOP = color(0xd9a670);
        const LIP_LOW = color(0xc08a58);
        EDGES.forEach((e, ei) => {
            const body = [];
            const bodyUv = [];
            const lip = [];
            const lipCol = [];
            for (let i = 0; i <= N; i++) {
                const x = e.x0 + e.dx * S * i / N;
                const z = e.z0 + e.dz * S * i / N;
                const top = height(x, z);
                lip.push(x, top, z, x, top - 0.1, z);
                LIP_TOP.toArray(lipCol, lipCol.length);
                LIP_LOW.toArray(lipCol, lipCol.length);
                body.push(x, top - 0.1, z, x, BASE, z);
                const u = (ei * S + S * i / N) / 6;
                bodyUv.push(u, (top - 0.1 - BASE) / (1.2 - BASE), u, 0);
            }
            const normal = [-e.dz, 0, e.dx];
            scene.add(strip(body, bodyUv, null, normal, sideMat, true));
            scene.add(strip(lip, null, lipCol, normal, lipMat, true));
        });
        const bottom = new THREE.Mesh(new THREE.PlaneGeometry(S, S).rotateX(Math.PI / 2), new THREE.MeshStandardMaterial({ color: 0x8a5c3c }));
        bottom.position.y = BASE;
        scene.add(bottom);

        // --- L'eau de l'oasis : verte et un peu trouble, le sable s'y dépose ---
        const waterGeo = new THREE.PlaneGeometry(3.8, 3.6, 38, 36);
        waterGeo.rotateX(-Math.PI / 2);
        waterGeo.translate(0.05, 0, 0.1);
        const wp = waterGeo.attributes.position;
        const waveIdx = [];
        for (let i = 0; i < wp.count; i++) if (height(wp.getX(i), wp.getZ(i)) < WATER + 0.1) waveIdx.push(i);
        const water = new THREE.Mesh(waterGeo, new THREE.MeshStandardMaterial({ color: 0x4f7a64, transparent: true, opacity: 0.82, roughness: 0.18, metalness: 0.05, flatShading: true, envMap, envMapIntensity: 0.8, depthWrite: false }));
        water.position.y = WATER;
        water.renderOrder = 2;
        scene.add(water);

        // --- L'oasis : palmiers dattiers tout autour de l'eau, papyrus, herbes, buissons ---
        const frondGeo = (() => {
            // Une palme : une longue feuille qui part vers l'extérieur et retombe, pliée en V
            const pos = [];
            const SEGS = 8;
            const pt = (s, side) => {
                const x = s * 0.95;
                const y = 0.22 * s - 0.55 * s * s;
                const w = 0.17 * Math.sin(Math.PI * Math.min(1, s * 1.15)) * (1 - s * 0.35);
                return [x, y + Math.abs(side) * w * 0.25, side * w];
            };
            for (let i = 0; i < SEGS; i++) {
                const s0 = i / SEGS;
                const s1 = (i + 1) / SEGS;
                const a0 = pt(s0, 0);
                const a1 = pt(s1, 0);
                const l0 = pt(s0, -1);
                const l1 = pt(s1, -1);
                const r0 = pt(s0, 1);
                const r1 = pt(s1, 1);
                pos.push(...a0, ...l0, ...a1, ...a1, ...l0, ...l1, ...a0, ...a1, ...r0, ...r0, ...a1, ...r1);
            }
            const g = new THREE.BufferGeometry();
            g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
            g.computeVertexNormals();
            return g;
        })();
        const frondMats = [flat(0x56763a, { side: THREE.DoubleSide }), flat(0x627f40, { side: THREE.DoubleSide }), flat(0x6c8846, { side: THREE.DoubleSide })];
        const barkMats = [flat(0x8a6a45), flat(0x75583a)];
        const dateMat = flat(0xb5652a, { roughness: 0.6 });
        const palms = [];
        const PALMS = [[-1.55, -0.4, 1.9], [-1.3, 1.55, 1.6], [1.65, -0.35, 1.8], [1.9, 1.6, 1.5], [0.4, 2.0, 1.75], [-0.4, -1.65, 1.55], [1.15, -1.55, 1.35], [-2.0, 0.6, 1.3]];
        PALMS.slice(0, phone ? 6 : 8).forEach(([x, z, h], i) => {
            const g = new THREE.Group();
            // Les palmiers penchent dans le sens du vent
            const lean = Math.PI * 0.1 + rr(-0.4, 0.4);
            const bend = rr(0.2, 0.4);
            const SEG = 7;
            let prev = V(0, 0, 0);
            for (let k = 1; k <= SEG; k++) {
                const u = k / SEG;
                const p = V(Math.cos(lean) * bend * u * u, h * u, Math.sin(lean) * bend * u * u);
                const r = lerp(0.075, 0.05, u);
                g.add(limb(prev, p, r, r * 0.92, barkMats[k % 2]));
                prev = p;
            }
            const crown = new THREE.Group();
            crown.position.copy(prev);
            g.add(crown);
            const n = 9;
            for (let k = 0; k < n; k++) {
                const f = new THREE.Mesh(frondGeo, frondMats[(k + i) % 3]);
                f.rotation.order = 'YZX';
                f.rotation.y = (k / n) * Math.PI * 2 + rr(-0.2, 0.2);
                f.rotation.z = rr(-0.15, 0.25);
                f.scale.setScalar(rr(0.85, 1.15));
                crown.add(f);
            }
            for (let k = 0; k < 3; k++) {
                const a = (k / 3) * Math.PI * 2 + rr(0, 1);
                const cl = new THREE.Mesh(new THREE.IcosahedronGeometry(0.06, 0).scale(1, 1.5, 1), dateMat);
                cl.position.set(Math.cos(a) * 0.08, -0.1, Math.sin(a) * 0.08);
                crown.add(cl);
            }
            g.position.set(x, height(x, z) - 0.03, z);
            g.traverse((m) => { if (m.isMesh) { m.castShadow = true; m.receiveShadow = true; } });
            scene.add(g);
            palms.push({ crown, ph: rr(0, 6.28) });
        });
        const papyrus = [];
        for (let tries = 0; tries < 2500 && papyrus.length < (phone ? 34 : 56); tries++) {
            const x = rr(-2.2, 2.3);
            const z = rr(-1.6, 1.8);
            const d = pondD(x, z);
            if (d > -0.05 && d < 0.18) papyrus.push({ x, z, y: height(x, z) - 0.02, h: rr(0.35, 0.65), phase: rr(0, 6.28), yaw: rr(0, 6.28) });
        }
        const stalkMesh = new THREE.InstancedMesh(new THREE.CylinderGeometry(0.008, 0.012, 1, 4).translate(0, 0.5, 0), flat(0x6f8a3e), Math.max(1, papyrus.length));
        const umbelMesh = new THREE.InstancedMesh(new THREE.ConeGeometry(0.07, 0.1, 7).rotateX(Math.PI).translate(0, 0.02, 0), flat(0x9aaa4f, { side: THREE.DoubleSide }), Math.max(1, papyrus.length));
        stalkMesh.castShadow = true;
        scene.add(stalkMesh, umbelMesh);
        const tufts = [];
        for (let tries = 0; tries < 3500 && tufts.length < (phone ? 90 : 170); tries++) {
            const x = rr(-2.8, 2.9);
            const z = rr(-2.4, 2.8);
            const d = pondD(x, z);
            if (d < 0.05 || d > 1.0) continue;
            tufts.push({ x, z, y: height(x, z) - 0.01, s: rr(0.7, 1.3), yaw: rr(0, 6.28), phase: rr(0, 6.28) });
        }
        const tuftMesh = new THREE.InstancedMesh(tuftGeometry(), flat(0xffffff, { side: THREE.DoubleSide }), Math.max(1, tufts.length));
        tufts.forEach((p, i) => tuftMesh.setColorAt(i, color([0x7a8e3e, 0x8a9a4c, 0x6e8238][Math.floor(hash(p.x * 2.3, p.z) * 3)])));
        scene.add(tuftMesh);
        const bushes = [];
        for (let tries = 0; tries < 900 && bushes.length < (phone ? 8 : 14); tries++) {
            const x = rr(-2.8, 2.8);
            const z = rr(-2.6, 2.8);
            const d = pondD(x, z);
            if (d < 0.35 || d > 1.0) continue;
            bushes.push({ x, z, y: height(x, z), s: rr(0.6, 1.1), yaw: rr(0, 6.28) });
        }
        instanced(new THREE.IcosahedronGeometry(0.17, 0).scale(1.2, 0.75, 1).translate(0, 0.08, 0), flat(0xffffff), bushes, (p) => color(hash(p.x, p.z) < 0.5 ? 0x5f7a3a : 0x6f8a44), true);
        // Quelques rochers de grès à moitié ensevelis
        const rocks = [];
        for (let tries = 0; tries < 900 && rocks.length < 14; tries++) {
            const x = rr(-4.6, 4.6);
            const z = rr(-4.6, 4.6);
            if (pondD(x, z) < 1.3) continue;
            rocks.push({ x, z, y: height(x, z) - 0.04, s: rr(0.6, 1.6), yaw: rr(0, 6.28), tilt: rr(-0.3, 0.3) });
        }
        instanced(new THREE.DodecahedronGeometry(0.14, 0).scale(1.3, 0.7, 1), flat(0xffffff, { roughness: 0.95 }), rocks, (p) => color([0xb98a5c, 0xa87c50, 0xc4966a][Math.floor(hash(p.x, p.z) * 3)]), true);

        // --- Les crocodiles : deux se chauffent sur la berge, gueule entrouverte ; un nage lentement ---
        const crocSkin = [flat(0x3c4824, { roughness: 0.8 }), flat(0x47522a, { roughness: 0.8 })];
        const bellyMat = flat(0xa69a6a);
        const eyeMat = flat(0xd9b84a, { roughness: 0.4 });
        const pupilMat = flat(0x14140f);
        const toothMat = flat(0xf2ead2);
        const mouthMat = flat(0xc47a6a);
        function makeCroc(skin) {
            const g = new THREE.Group();
            // Le corps, aplati, qui va du cou (x > 0) à la base de la queue (x < 0)
            const body = new THREE.Mesh(new THREE.CapsuleGeometry(0.12, 0.42, 4, 10).rotateZ(Math.PI / 2), skin);
            body.scale.set(1, 0.55, 1.1);
            body.position.y = 0.07;
            g.add(body);
            const belly = new THREE.Mesh(new THREE.CapsuleGeometry(0.1, 0.36, 3, 8).rotateZ(Math.PI / 2), bellyMat);
            belly.scale.set(1, 0.35, 1);
            belly.position.y = 0.035;
            g.add(belly);
            // Les écailles du dos : deux rangées de petites bosses
            for (let k = 0; k < 7; k++) {
                [-1, 1].forEach((e) => {
                    const sc = new THREE.Mesh(new THREE.ConeGeometry(0.018, 0.035, 4), skin);
                    sc.position.set(0.22 - k * 0.075, 0.135, e * 0.04);
                    g.add(sc);
                });
            }
            // La tête : une mâchoire du haut fixe, celle du bas qui s'ouvre
            const head = new THREE.Group();
            head.position.set(0.3, 0.07, 0);
            g.add(head);
            const skull = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.08, 0.15).translate(0.06, 0.01, 0), skin);
            head.add(skull);
            const upper = new THREE.Group();
            head.add(upper);
            const snout = new THREE.Mesh(new THREE.BoxGeometry(0.26, 0.045, 0.1).translate(0.26, 0.0, 0), skin);
            upper.add(snout);
            const nose = new THREE.Mesh(new THREE.SphereGeometry(0.03, 6, 4), skin);
            nose.position.set(0.38, 0.02, 0);
            nose.scale.set(1, 0.6, 1.4);
            upper.add(nose);
            const jaw = new THREE.Group();
            jaw.position.set(0.04, -0.025, 0);
            head.add(jaw);
            const lowerJaw = new THREE.Mesh(new THREE.BoxGeometry(0.34, 0.03, 0.095).translate(0.18, -0.01, 0), skin);
            jaw.add(lowerJaw);
            const tongue = new THREE.Mesh(new THREE.BoxGeometry(0.24, 0.006, 0.07).translate(0.16, 0.007, 0), mouthMat);
            jaw.add(tongue);
            for (let k = 0; k < 6; k++) {
                [-1, 1].forEach((e) => {
                    const tooth = new THREE.Mesh(new THREE.ConeGeometry(0.008, 0.025, 4).rotateX(Math.PI), toothMat);
                    tooth.position.set(0.16 + k * 0.04, -0.03, e * 0.042);
                    upper.add(tooth);
                });
            }
            // Les yeux, sur le dessus : ce qu'on voit dépasser de l'eau
            [-1, 1].forEach((e) => {
                const bump = new THREE.Mesh(new THREE.SphereGeometry(0.03, 7, 5), skin);
                bump.position.set(0.08, 0.06, e * 0.045);
                head.add(bump);
                const eye = new THREE.Mesh(new THREE.SphereGeometry(0.018, 7, 5), eyeMat);
                eye.position.set(0.1, 0.075, e * 0.05);
                head.add(eye);
                const pupil = new THREE.Mesh(new THREE.BoxGeometry(0.004, 0.022, 0.006), pupilMat);
                pupil.position.set(0.117, 0.077, e * 0.055);
                head.add(pupil);
            });
            // La queue : quatre segments qui ondulent
            const tail = [];
            let parent = g;
            let x0 = -0.3;
            for (let k = 0; k < 5; k++) {
                const piv = new THREE.Group();
                piv.position.set(k ? -0.15 : x0, k ? 0 : 0.065, 0);
                parent.add(piv);
                const r = 0.085 * (1 - k * 0.17);
                const seg = new THREE.Mesh(new THREE.CylinderGeometry(r * 0.8, r, 0.17, 7).rotateZ(Math.PI / 2).translate(-0.075, 0, 0), skin);
                seg.scale.set(1, 0.65, 1);
                piv.add(seg);
                const crest = new THREE.Mesh(new THREE.ConeGeometry(0.015, 0.035, 4), skin);
                crest.position.set(-0.07, r * 0.6, 0);
                piv.add(crest);
                tail.push(piv);
                parent = piv;
            }
            // Les pattes, écartées sur les côtés
            const legs = [];
            [[0.18, 1], [0.18, -1], [-0.2, 1], [-0.2, -1]].forEach(([lx, e]) => {
                const piv = new THREE.Group();
                piv.position.set(lx, 0.05, e * 0.1);
                g.add(piv);
                piv.add(limb(V(0, 0, 0), V(0.03, -0.035, e * 0.09), 0.028, 0.022, skin));
                const foot = new THREE.Mesh(new THREE.BoxGeometry(0.07, 0.015, 0.05), skin);
                foot.position.set(0.05, -0.045, e * 0.1);
                piv.add(foot);
                legs.push({ piv, e, front: lx > 0 });
            });
            g.traverse((m) => { if (m.isMesh) { m.castShadow = true; m.receiveShadow = true; } });
            g.scale.setScalar(1.6);
            scene.add(g);
            return { g, jaw, head, tail, legs };
        }
        const crocs = [];
        // Sur la berge, la tête vers l'eau
        [[1.75, 0.35], [-1.05, -0.95]].forEach(([x, z], i) => {
            const c = makeCroc(crocSkin[i % 2]);
            const a = Math.atan2(0.15 - z, 0.05 - x);
            c.g.position.set(x, height(x, z) + 0.01, z);
            c.g.rotation.y = -a;
            crocs.push(Object.assign(c, { kind: 'bask', gape: 0, gapeT: rr(2, 6), snap: 0, ph: rr(0, 6.28) }));
        });
        // Dans l'eau, à peine visible : le dos, les yeux, le bout du museau
        const swimmer = makeCroc(crocSkin[1]);
        crocs.push(Object.assign(swimmer, { kind: 'swim', a: rr(0, 6.28), snap: 0, dive: 0, ph: rr(0, 6.28) }));
        const crocMeshes = [];
        crocs.forEach((c, i) => c.g.traverse((m) => { if (m.isMesh) { m.userData.croc = i; crocMeshes.push(m); } }));

        // --- La tempête de sable ---
        const pointScale = { value: 1 };
        // Le vent tourne autour d'une direction moyenne et souffle par rafales lentes
        const WIND_A = 0.35;
        const wind = { x: Math.cos(WIND_A), z: Math.sin(WIND_A), k: 1 };
        // Des traînées de sable qui filent, comme une pluie couchée
        const STREAKS = phone ? 420 : 900;
        const streakPos = new Float32Array(STREAKS * 6);
        const streakCol = new Float32Array(STREAKS * 6);
        const streakGeo = new THREE.BufferGeometry();
        streakGeo.setAttribute('position', new THREE.BufferAttribute(streakPos, 3));
        streakGeo.setAttribute('color', new THREE.BufferAttribute(streakCol, 3));
        const streaks = new THREE.LineSegments(streakGeo, new THREE.LineBasicMaterial({ vertexColors: true, transparent: true, opacity: 0.42, depthWrite: false }));
        streaks.frustumCulled = false;
        streaks.renderOrder = 8;
        scene.add(streaks);
        const flying = Array.from({ length: STREAKS }, () => {
            const f = {};
            resetStreak(f, true);
            return f;
        });
        function resetStreak(f, anywhere) {
            // On repart du côté d'où vient le vent
            const along = anywhere ? rr(-8, 8) : -8 - rr(0, 2);
            const across = rr(-8, 8);
            f.x = along * wind.x - across * wind.z;
            f.z = along * wind.z + across * wind.x;
            f.y = Math.pow(rand(), 1.7) * 4.5 - 0.2;
            f.sp = rr(3.2, 6.5);
            f.len = rr(0.18, 0.55);
            f.ph = rr(0, 6.28);
            const b = rr(0.85, 1.05);
            f.c = [0.93 * b, 0.74 * b, 0.52 * b];
        }
        // De gros nuages de poussière qui roulent lentement : c'est eux qui cachent le décor
        const clouds = particles(phone ? 70 : 120);
        clouds.items.forEach((p) => resetCloud(p, true));
        function resetCloud(p, anywhere) {
            const along = anywhere ? rr(-9, 9) : -9 - rr(0, 2);
            const across = rr(-9, 9);
            p.x = along * wind.x - across * wind.z;
            p.z = along * wind.z + across * wind.x;
            p.y = rr(0.0, 3.4);
            p.s = rr(1.6, 3.6);
            p.sp = rr(0.9, 1.7);
            p.a = rr(0.08, 0.17);
            p.ph = rr(0, 6.28);
        }
        // Le sable qui court au ras du sol
        const grains = particles(phone ? 160 : 300);
        grains.items.forEach((p) => resetGrain(p, true));
        function resetGrain(p, anywhere) {
            p.x = rr(-HALF, HALF);
            p.z = rr(-HALF, HALF);
            p.age = anywhere ? rr(0, 1) : 0;
            p.life = rr(1.2, 2.6);
            p.sp = rr(1.4, 2.6);
            p.ph = rr(0, 6.28);
        }

        const rings = [];
        const ringGeo = new THREE.RingGeometry(0.9, 1, 40);
        ringGeo.rotateX(-Math.PI / 2);
        for (let i = 0; i < 10; i++) {
            const m = new THREE.Mesh(ringGeo, new THREE.MeshBasicMaterial({ color: 0xffe6c4, transparent: true, opacity: 0, depthWrite: false, fog: false }));
            m.visible = false;
            m.renderOrder = 5;
            scene.add(m);
            rings.push({ m, t: 1, max: 0.5, dur: 1 });
        }
        function ripple(x, z, max = 0.45, dur = 1.4, delay = 0) {
            const r = rings.find(k => k.t >= 1) || rings[0];
            Object.assign(r, { t: -delay / dur, max, dur });
            r.m.position.set(x, WATER + 0.03, z);
        }

        // --- Caméra : l'oasis au centre, un peu en hauteur ---
        const target = V(0.05, 0.35, 0.15);
        const HOME_EL = 0.46;
        let az = 0.6;
        let el = HOME_EL;
        let zoom = 0.5;
        let fit = 26;
        let lastInput = -10;
        let touched = false;
        const pointers = new Map();
        let pinch = 0;
        let downAt = null;
        const canvas = renderer.domElement;
        const spread = () => {
            const [a, b] = [...pointers.values()];
            return Math.hypot(a.x - b.x, a.y - b.y) || 1;
        };
        const onDown = (e) => {
            canvas.setPointerCapture(e.pointerId);
            pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
            if (pointers.size === 1) downAt = { x: e.clientX, y: e.clientY, t: performance.now() };
            if (pointers.size === 2) pinch = spread();
            lastInput = clock;
            touched = true;
        };
        const onMove = (e) => {
            const p = pointers.get(e.pointerId);
            if (!p) return;
            const dx = e.clientX - p.x;
            const dy = e.clientY - p.y;
            p.x = e.clientX;
            p.y = e.clientY;
            if (pointers.size === 1) {
                az -= dx * 0.0065;
                el = clamp(el + dy * 0.0045, 0.05, 1.2);
            } else if (pointers.size === 2) {
                const s = spread();
                if (pinch) zoom = clamp(zoom * pinch / s, 0.22, 1.5);
                pinch = s;
            }
            lastInput = clock;
        };
        const onUp = (e) => {
            pointers.delete(e.pointerId);
            pinch = 0;
            if (downAt && pointers.size === 0) {
                const moved = Math.hypot(e.clientX - downAt.x, e.clientY - downAt.y);
                if (moved < 7 && performance.now() - downAt.t < 400) tap(e);
            }
            downAt = null;
        };
        const onWheel = (e) => {
            e.preventDefault();
            zoom = clamp(zoom * Math.exp(e.deltaY * 0.0012), 0.22, 1.5);
            lastInput = clock;
        };
        canvas.addEventListener('pointerdown', onDown);
        canvas.addEventListener('pointermove', onMove);
        canvas.addEventListener('pointerup', onUp);
        canvas.addEventListener('pointercancel', onUp);
        canvas.addEventListener('wheel', onWheel, { passive: false });

        // Toucher un crocodile : il claque des mâchoires (celui qui nage plonge un instant). L'eau : des ronds.
        const raycaster = new THREE.Raycaster();
        const ndc = new THREE.Vector2();
        function tap(e) {
            const r = canvas.getBoundingClientRect();
            ndc.set(((e.clientX - r.left) / r.width) * 2 - 1, -((e.clientY - r.top) / r.height) * 2 + 1);
            raycaster.setFromCamera(ndc, camera);
            const hit = raycaster.intersectObjects(crocMeshes, false)[0];
            if (hit) {
                const c = crocs[hit.object.userData.croc];
                c.snap = 1;
                if (c.kind === 'swim') {
                    c.dive = 1;
                    ripple(c.g.position.x, c.g.position.z, 0.55, 1.4);
                }
                return;
            }
            const w = raycaster.intersectObject(water)[0];
            if (!w || height(w.point.x, w.point.z) > WATER - 0.02) return;
            ripple(w.point.x, w.point.z, 0.5, 1.5);
            ripple(w.point.x, w.point.z, 0.32, 1.3, 0.22);
        }

        function resize() {
            const w = stage.clientWidth || 1;
            const h = stage.clientHeight || 1;
            renderer.setSize(w, h, false);
            camera.aspect = w / h;
            const tanV = Math.tan(THREE.MathUtils.degToRad(camera.fov / 2));
            fit = Math.max(14 / tanV / 2, (camera.aspect < 0.8 ? 14 : 15.6) / (tanV * camera.aspect) / 2);
            if (!touched) zoom = camera.aspect < 0.8 ? 0.66 : 0.5;
            camera.updateProjectionMatrix();
            pointScale.value = camera.projectionMatrix.elements[5] * renderer.domElement.height / 2;
        }
        const ro = new ResizeObserver(resize);
        ro.observe(stage);
        resize();

        // --- Boucle ---
        const m4 = new THREE.Matrix4();
        const q = new THREE.Quaternion();
        const qYaw = new THREE.Quaternion();
        const v3 = new THREE.Vector3();
        const v4 = new THREE.Vector3();
        const sc = new THREE.Vector3();
        const up = new THREE.Vector3(0, 1, 0);
        const windAxis = new THREE.Vector3(-Math.sin(WIND_A), 0, Math.cos(WIND_A));
        const SAND_C = [0.9, 0.7, 0.48];
        const CLOUD_C = [0.86, 0.6, 0.38];
        let clock = 0;
        let last = performance.now();
        let raf = 0;
        let alive = true;

        function frame(now) {
            if (!alive) return;
            const real = Math.min(0.25, (now - last) / 1000);
            const dt = Math.min(0.05, real);
            last = now;
            clock += dt;
            const t = clock;
            uTime.value = t;

            if (!still && !pointers.size) {
                const idle = smooth(clamp((clock - lastInput - 3) / 2, 0, 1));
                az += IDLE_SPIN * dt * idle;
                el += (HOME_EL - el) * Math.min(1, dt * 0.8) * idle;
            }
            const dist = fit * zoom;
            camera.position.set(target.x + dist * Math.cos(el) * Math.sin(az), target.y + dist * Math.sin(el), target.z + dist * Math.cos(el) * Math.cos(az));
            camera.lookAt(target);
            // La tempête respire : des rafales lentes qui épaississent et éclaircissent le voile
            wind.k = 1 + 0.35 * Math.sin(t * 0.21) + 0.15 * Math.sin(t * 0.53 + 1.3);
            // (la brume suit la distance : de près, on voit l'oasis ; de loin, tout se fond dans le sable)
            scene.fog.near = dist * (0.62 - 0.1 * wind.k);
            scene.fog.far = dist * (1.95 - 0.3 * wind.k) + 2;

            // L'eau frissonne sous le vent
            for (const i of waveIdx) {
                const x = wp.getX(i);
                const z = wp.getZ(i);
                wp.setY(i, (0.014 * Math.sin(x * 3.1 + z * 1.2 + t * 2.0) * Math.cos(z * 2.6 - t * 1.3) + 0.007 * Math.sin((x + z) * 6 + t * 2.8)) * wind.k);
            }
            wp.needsUpdate = true;
            waterGeo.computeVertexNormals();

            // Palmiers et papyrus ploient dans le vent
            palms.forEach((p) => {
                p.crown.rotation.x = Math.sin(t * 1.9 + p.ph) * 0.07 * wind.k;
                p.crown.rotation.z = -0.08 * wind.k + Math.sin(t * 2.3 + p.ph * 2) * 0.08 * wind.k;
            });
            papyrus.forEach((p, i) => {
                q.setFromAxisAngle(windAxis, 0.12 * wind.k + Math.sin(t * 2.2 + p.phase) * 0.1);
                m4.compose(v3.set(p.x, p.y, p.z), q, sc.set(1, p.h, 1));
                stalkMesh.setMatrixAt(i, m4);
                v4.set(0, p.h, 0).applyQuaternion(q).add(v3);
                qYaw.setFromAxisAngle(up, p.yaw);
                m4.compose(v4, q.multiply(qYaw), sc.setScalar(1));
                umbelMesh.setMatrixAt(i, m4);
            });
            stalkMesh.instanceMatrix.needsUpdate = true;
            umbelMesh.instanceMatrix.needsUpdate = true;
            tufts.forEach((p, i) => {
                q.setFromAxisAngle(windAxis, 0.15 * wind.k + Math.sin(t * 2.4 + p.phase) * 0.14);
                qYaw.setFromAxisAngle(up, p.yaw);
                q.multiply(qYaw);
                m4.compose(v3.set(p.x, p.y, p.z), q, sc.setScalar(p.s));
                tuftMesh.setMatrixAt(i, m4);
            });
            tuftMesh.instanceMatrix.needsUpdate = true;

            // Les crocodiles
            crocs.forEach((c) => {
                c.snap = Math.max(0, c.snap - dt * 1.6);
                // Un claquement : la gueule s'ouvre grand, puis se referme d'un coup
                const snapOpen = c.snap > 0 ? (c.snap > 0.55 ? (1 - c.snap) / 0.45 : c.snap > 0.4 ? 1 : 0) : 0;
                if (c.kind === 'bask') {
                    // Au soleil (même voilé), la gueule s'entrouvre tout doucement, puis se referme
                    if (t > c.gapeT) {
                        c.gapeOn = !c.gapeOn;
                        c.gapeT = t + (c.gapeOn ? rr(6, 10) : rr(4, 8));
                    }
                    c.gape += ((c.gapeOn ? 1 : 0) - c.gape) * Math.min(1, dt * 0.6);
                    c.jaw.rotation.z = -(c.gape * 0.35 + snapOpen * 0.75);
                    c.head.rotation.z = c.gape * 0.08 + snapOpen * 0.1;
                    c.tail.forEach((s, k) => { s.rotation.y = Math.sin(t * 0.4 + c.ph + k * 0.6) * 0.06; });
                } else {
                    // Il fait le tour de l'eau en ondulant, les yeux juste au ras de l'eau
                    c.dive = Math.max(0, c.dive - dt * 0.5);
                    c.a += dt * 0.12;
                    const R = 0.62 + 0.08 * Math.sin(c.a * 2.3);
                    const x = 0.05 + Math.cos(c.a) * R;
                    const z = 0.15 + Math.sin(c.a) * R;
                    const sink = Math.sin(Math.min(1, c.dive) * Math.PI) * 0.18;
                    c.g.position.set(x, WATER - 0.13 - sink + Math.sin(t * 1.2 + c.ph) * 0.006, z);
                    c.g.rotation.y = -(c.a + Math.PI / 2);
                    c.jaw.rotation.z = -snapOpen * 0.7;
                    c.tail.forEach((s, k) => { s.rotation.y = Math.sin(t * 2.4 - k * 0.9) * (0.18 + k * 0.05); });
                    c.legs.forEach((l) => { l.piv.rotation.y = l.e * 0.9; });
                    // Un sillage discret derrière lui
                    if (Math.random() < dt * 0.9) ripple(x, z, 0.32, 2.2);
                }
            });

            // Les traînées de sable filent dans le vent
            const sw = 1 + (wind.k - 1) * 0.8;
            flying.forEach((f, i) => {
                f.x += wind.x * f.sp * sw * dt;
                f.z += wind.z * f.sp * sw * dt;
                f.y += Math.sin(t * 2 + f.ph) * 0.15 * dt;
                const along = f.x * wind.x + f.z * wind.z;
                if (along > 8) resetStreak(f, false);
                const o = i * 6;
                streakPos[o] = f.x;
                streakPos[o + 1] = f.y;
                streakPos[o + 2] = f.z;
                streakPos[o + 3] = f.x - wind.x * f.len * sw;
                streakPos[o + 4] = f.y - 0.02;
                streakPos[o + 5] = f.z - wind.z * f.len * sw;
                streakCol.set(f.c, o);
                streakCol.set(f.c, o + 3);
            });
            streakGeo.attributes.position.needsUpdate = true;
            streakGeo.attributes.color.needsUpdate = true;

            // Les nuages de poussière roulent et gonflent
            clouds.items.forEach((p, i) => {
                p.x += wind.x * p.sp * sw * dt;
                p.z += wind.z * p.sp * sw * dt;
                p.y += Math.sin(t * 0.4 + p.ph) * 0.06 * dt;
                const along = p.x * wind.x + p.z * wind.z;
                if (along > 9) resetCloud(p, false);
                const edge = clamp((9 - Math.abs(along)) / 2, 0, 1);
                clouds.set(i, p.x, p.y, p.z, p.s * (1 + 0.1 * Math.sin(t * 0.5 + p.ph)), CLOUD_C, p.a * edge * (0.75 + 0.35 * wind.k));
            });
            clouds.update();

            // Le sable court au ras du sol, par petits bonds
            grains.items.forEach((p, i) => {
                p.age += real / p.life;
                if (p.age >= 1) resetGrain(p, false);
                p.x += wind.x * p.sp * sw * dt;
                p.z += wind.z * p.sp * sw * dt;
                if (Math.abs(p.x) > HALF - 0.05 || Math.abs(p.z) > HALF - 0.05) resetGrain(p, false);
                const k = p.age;
                const y = Math.max(height(p.x, p.z), WATER) + 0.03 + Math.abs(Math.sin(k * Math.PI * 3)) * 0.08;
                grains.set(i, p.x, y, p.z, 0.035, SAND_C, Math.sin(k * Math.PI) * 0.6);
            });
            grains.update();

            rings.forEach((r) => {
                if (r.t >= 1) {
                    r.m.visible = false;
                    return;
                }
                r.t += dt / r.dur;
                if (r.t < 0) return;
                const k = Math.min(1, r.t);
                r.m.visible = true;
                r.m.scale.setScalar(0.04 + r.max * easeOut(k));
                r.m.material.opacity = (1 - k) * 0.45;
            });

            renderer.render(scene, camera);
            raf = requestAnimationFrame(frame);
        }
        raf = requestAnimationFrame(frame);

        return {
            dispose() {
                alive = false;
                cancelAnimationFrame(raf);
                ro.disconnect();
                canvas.removeEventListener('wheel', onWheel);
                scene.traverse((o) => {
                    if (o.geometry) o.geometry.dispose();
                    if (o.material) {
                        [].concat(o.material).forEach((m) => {
                            Object.values(m).forEach((v) => { if (v && v.isTexture) v.dispose(); });
                            m.dispose();
                        });
                    }
                });
                envMap.dispose();
                renderer.dispose();
                canvas.remove();
            },
        };

        // ---------------- Outils de la scène ----------------
        function instanced(geo, mat, list, tint, shadow) {
            const m = new THREE.InstancedMesh(geo, mat, Math.max(1, list.length));
            m.count = list.length;
            const rot = new THREE.Quaternion();
            const yAxis = new THREE.Vector3(0, 1, 0);
            const xAxis = new THREE.Vector3(1, 0, 0);
            list.forEach((p, i) => {
                rot.setFromAxisAngle(yAxis, p.yaw || 0);
                if (p.tilt) rot.multiply(new THREE.Quaternion().setFromAxisAngle(xAxis, p.tilt));
                m.setMatrixAt(i, new THREE.Matrix4().compose(new THREE.Vector3(p.x, p.y, p.z), rot, new THREE.Vector3(p.s, p.s, p.s)));
                if (tint) m.setColorAt(i, tint(p, i));
            });
            m.castShadow = !!shadow;
            m.receiveShadow = true;
            scene.add(m);
            return m;
        }

        function limb(a, b, r1, r2, mat) {
            const dir = new THREE.Vector3().subVectors(b, a);
            const len = dir.length();
            const m = new THREE.Mesh(new THREE.CylinderGeometry(r2, r1, len, 7), mat);
            m.position.copy(a).addScaledVector(dir, 0.5);
            m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
            return m;
        }

        function tuftGeometry() {
            const pos = [];
            for (let k = 0; k < 5; k++) {
                const a = k * 1.257 + 0.3;
                const lean = 0.035 + (k % 2) * 0.02;
                const h = 0.13 + (k % 3) * 0.035;
                const cx = Math.cos(a);
                const cz = Math.sin(a);
                const w = 0.018;
                pos.push(-cz * w, 0, cx * w, cz * w, 0, -cx * w, cx * lean, h, cz * lean);
            }
            const g = new THREE.BufferGeometry();
            g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
            g.computeVertexNormals();
            return g;
        }

        function strip(pts, uv, cols, normal, mat, shadow) {
            const g = new THREE.BufferGeometry();
            g.setAttribute('position', new THREE.Float32BufferAttribute(pts, 3));
            const count = pts.length / 3;
            const nrm = [];
            for (let i = 0; i < count; i++) nrm.push(...normal);
            g.setAttribute('normal', new THREE.Float32BufferAttribute(nrm, 3));
            if (uv) g.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
            if (cols) g.setAttribute('color', new THREE.Float32BufferAttribute(cols, 3));
            const idx = [];
            for (let i = 0; i < count / 2 - 1; i++) {
                const a = i * 2;
                idx.push(a + 1, a + 3, a + 2, a + 1, a + 2, a);
            }
            g.setIndex(idx);
            const m = new THREE.Mesh(g, mat);
            m.receiveShadow = shadow;
            return m;
        }

        // Les couches de grès sur les côtés : ocre, rose, rouille, avec des veines claires
        function strataTexture() {
            const W = 1024;
            const H = 512;
            const cv = document.createElement('canvas');
            cv.width = W;
            cv.height = H;
            const g = cv.getContext('2d');
            const yPx = (y) => (1 - (y - BASE) / (1.2 - BASE)) * H;
            const STOPS = [[1.2, [222, 190, 140]], [0.2, [214, 178, 126]], [-0.5, [201, 150, 102]], [-1.1, [214, 168, 120]], [-1.7, [178, 116, 78]], [-2.3, [196, 138, 94]], [BASE, [150, 94, 62]]];
            for (let x = 0; x < W; x += 4) {
                const u = (x / W) * Math.PI * 2;
                const grad = g.createLinearGradient(0, 0, 0, H);
                STOPS.forEach(([y, c], k) => {
                    const off = k && k < STOPS.length - 1 ? Math.sin(u * 2 + k) * 8 + Math.sin(u * 5 + k * 2) * 3 : 0;
                    grad.addColorStop(clamp((yPx(y) + off) / H, 0, 1), `rgb(${c[0]},${c[1]},${c[2]})`);
                });
                g.fillStyle = grad;
                g.fillRect(x, 0, 4, H);
            }
            const rnd = mulberry32(9);
            // Fines veines claires, un peu ondulées
            for (let k = 0; k < 9; k++) {
                const y0 = yPx(rnd() * (0.1 - BASE) + BASE);
                g.strokeStyle = `rgba(250,232,200,${0.18 + rnd() * 0.18})`;
                g.lineWidth = 1 + rnd() * 2;
                g.beginPath();
                for (let x = 0; x <= W; x += 16) {
                    const y = y0 + Math.sin((x / W) * Math.PI * 4 + k) * 4;
                    if (x) g.lineTo(x, y); else g.moveTo(x, y);
                }
                g.stroke();
            }
            for (let i = 0; i < 1400; i++) {
                const x = rnd() * W;
                const y = rnd() * H;
                g.fillStyle = `rgba(${rnd() < 0.5 ? '255,240,215' : '90,50,30'},${0.05 + rnd() * 0.08})`;
                g.fillRect(x, y, 1.5 + rnd() * 1.5, 1 + rnd());
            }
            const tex = new THREE.CanvasTexture(cv);
            tex.wrapS = THREE.RepeatWrapping;
            tex.colorSpace = THREE.SRGBColorSpace;
            tex.anisotropy = 4;
            return tex;
        }

        function particles(count) {
            const pos = new Float32Array(count * 3);
            const col = new Float32Array(count * 3);
            const size = new Float32Array(count);
            const alpha = new Float32Array(count);
            const g = new THREE.BufferGeometry();
            g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
            g.setAttribute('aColor', new THREE.BufferAttribute(col, 3));
            g.setAttribute('aSize', new THREE.BufferAttribute(size, 1));
            g.setAttribute('aAlpha', new THREE.BufferAttribute(alpha, 1));
            const m = new THREE.ShaderMaterial({
                uniforms: { uScale: pointScale },
                vertexShader: `attribute vec3 aColor;
attribute float aSize;
attribute float aAlpha;
uniform float uScale;
varying vec3 vColor;
varying float vAlpha;
void main() {
    vec4 mv = modelViewMatrix * vec4(position, 1.0);
    gl_Position = projectionMatrix * mv;
    gl_PointSize = aSize * uScale / -mv.z;
    vColor = aColor;
    vAlpha = aAlpha;
}`,
                fragmentShader: `varying vec3 vColor;
varying float vAlpha;
void main() {
    float r = length(gl_PointCoord - 0.5);
    float a = smoothstep(0.5, 0.05, r) * vAlpha;
    if (a < 0.01) discard;
    gl_FragColor = vec4(vColor, a);
}`,
                transparent: true,
                depthWrite: false,
            });
            const pts = new THREE.Points(g, m);
            pts.frustumCulled = false;
            pts.renderOrder = 9;
            scene.add(pts);
            const items = Array.from({ length: count }, () => ({}));
            return {
                items,
                set(i, x, y, z, s, c, a) {
                    pos[i * 3] = x;
                    pos[i * 3 + 1] = y;
                    pos[i * 3 + 2] = z;
                    col[i * 3] = c[0];
                    col[i * 3 + 1] = c[1];
                    col[i * 3 + 2] = c[2];
                    size[i] = s;
                    alpha[i] = a;
                },
                update() {
                    g.attributes.position.needsUpdate = true;
                    g.attributes.aColor.needsUpdate = true;
                    g.attributes.aSize.needsUpdate = true;
                    g.attributes.aAlpha.needsUpdate = true;
                },
            };
        }

        function radialTexture(inner, outer) {
            const cv = document.createElement('canvas');
            cv.width = cv.height = 256;
            const g = cv.getContext('2d');
            const grad = g.createRadialGradient(128, 128, 10, 128, 128, 128);
            grad.addColorStop(0, inner);
            grad.addColorStop(1, outer);
            g.fillStyle = grad;
            g.fillRect(0, 0, 256, 256);
            const tex = new THREE.CanvasTexture(cv);
            tex.colorSpace = THREE.SRGBColorSpace;
            return tex;
        }
    }

    // ---------------------------------------------------------------------
    // Cinquième diorama : le chalet dans la tempête de neige. Un chalet en rondins
    // perdu au fond d'une vallée de montagne, noyé dans les sapins. Dehors, le
    // blizzard efface tout ; dedans, la lumière est chaude et on devine des
    // silhouettes qui passent derrière les fenêtres.
    // ---------------------------------------------------------------------
    function buildSnow(THREE, stage) {
        const phone = Math.min(window.innerWidth, window.innerHeight) < 600 || touch();
        const S = 10;
        const HALF = S / 2;
        const N = phone ? 50 : 76;
        const BASE = -2.6;
        const rand = mulberry32(23);
        const rr = (a, b) => a + (b - a) * rand();
        const color = (hex) => new THREE.Color(hex);
        const V = (x, y, z) => new THREE.Vector3(x, y, z);
        const flat = (hex, extra) => new THREE.MeshStandardMaterial(Object.assign({ color: hex, flatShading: true, roughness: 0.85 }, extra || {}));
        const tmp = new THREE.Color();
        const smooth = (u) => u * u * (3 - 2 * u);
        const still = calm();

        // --- Plan de la scène ---
        const CH = { x: -0.7, z: -0.9, rot: 0.32, W: 2.2, D: 1.7 };
        const cr = Math.cos(CH.rot);
        const sr = Math.sin(CH.rot);
        const footprint = (x, z) => {
            const dx = x - CH.x;
            const dz = z - CH.z;
            const lx = dx * cr - dz * sr;
            const lz = dx * sr + dz * cr;
            return Math.max(Math.abs(lx) - CH.W / 2, Math.abs(lz) - CH.D / 2);
        };
        const DRIFTS = [[-3.2, 1.8, 0.28, 0.9], [3.6, -0.6, 0.32, 1.0], [-1.6, 3.4, 0.2, 0.8], [1.9, -2.6, 0.25, 0.9], [-4.0, -1.5, 0.3, 1.1]];
        const height = (x, z) => {
            let h = 0.05 * Math.sin(x * 0.9 + z * 0.4) + 0.04 * Math.sin(z * 1.3 - x * 0.6) + 0.025 * Math.sin((x - z) * 2.1);
            // Une petite combe : les montagnes montent tout autour, plus haut vers le fond
            const rad = Math.hypot(x - CH.x * 0.6, (z - CH.z * 0.4) * 1.1);
            h += 1.15 * smooth(clamp((rad - 2.0) / 3.4, 0, 1)) * (0.8 + 0.2 * Math.sin(x * 1.1 + 0.4) + 0.12 * Math.sin(z * 1.7));
            h += 0.9 * smooth(clamp((-z - 1.2) / 3.6, 0, 1)) * (0.75 + 0.25 * Math.sin(x * 0.8 + 0.5));
            // Des crêtes rocheuses sur les pentes
            h += 0.12 * Math.max(0, Math.sin(x * 2.3 + z * 1.4)) * smooth(clamp((rad - 2.6) / 2, 0, 1));
            for (const [cx, cz, a, w] of DRIFTS) h += a * Math.exp(-(Math.pow(x - cx, 2) + Math.pow(z - cz, 2)) / (w * w));
            // Le replat sous le chalet
            return lerp(h, 0.03, 1 - smooth(clamp((footprint(x, z) - 0.25) / 1.1, 0, 1)));
        };

        // --- Rendu ---
        const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, powerPreference: 'high-performance' });
        renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, phone ? 1.75 : 2));
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        renderer.setClearColor(0x000000, 0);
        renderer.domElement.className = 'diorama-canvas';
        stage.appendChild(renderer.domElement);
        const scene = new THREE.Scene();
        // Le blizzard : une brume blanche et grise, épaisse, qui avale tout au-delà de la vallée
        const WHITEOUT = 0x98a2b2;
        scene.fog = new THREE.Fog(WHITEOUT, 10, 30);
        const camera = new THREE.PerspectiveCamera(30, 1, 0.1, 300);
        const uTime = { value: 0 };

        // --- Un ciel bouché par la tempête : une lumière grise et diffuse, et la chaleur des fenêtres ---
        const MOON = V(6, 9, -5);
        const hemi = new THREE.HemisphereLight(0xaab6ca, 0x3a4354, 0.72);
        scene.add(hemi);
        const moon = new THREE.DirectionalLight(0xc6d2e8, 0.3);
        moon.position.copy(MOON);
        moon.castShadow = true;
        moon.shadow.mapSize.set(phone ? 1024 : 2048, phone ? 1024 : 2048);
        Object.assign(moon.shadow.camera, { left: -8, right: 8, top: 8, bottom: -8, near: 1, far: 40 });
        moon.shadow.bias = -0.0005;
        moon.shadow.normalBias = 0.03;
        scene.add(moon);
        const rim = new THREE.DirectionalLight(0x9fb3e6, 0.35);
        rim.position.set(-6, 3, 6);
        scene.add(rim);

        // Un ciel en miniature pour les reflets de la glace
        const pmrem = new THREE.PMREMGenerator(renderer);
        const envScene = new THREE.Scene();
        const skyGeo = new THREE.SphereGeometry(10, 32, 16);
        const skyCol = [];
        const sp = skyGeo.attributes.position;
        for (let i = 0; i < sp.count; i++) {
            const y = sp.getY(i) / 10;
            if (y > 0.02) tmp.copy(color(0xb5bfcc)).lerp(color(0x6a7486), smooth(clamp(y * 1.5, 0, 1)));
            else tmp.copy(color(0xb5bfcc)).lerp(color(0xdfe5ee), smooth(clamp(-y * 3, 0, 1)));
            skyCol.push(tmp.r, tmp.g, tmp.b);
        }
        skyGeo.setAttribute('color', new THREE.Float32BufferAttribute(skyCol, 3));
        envScene.add(new THREE.Mesh(skyGeo, new THREE.MeshBasicMaterial({ vertexColors: true, side: THREE.BackSide })));
        const envMap = pmrem.fromScene(envScene, 0.03).texture;
        envScene.traverse((o) => { if (o.geometry) o.geometry.dispose(); if (o.material) o.material.dispose(); });
        pmrem.dispose();

        // --- Le sol : neige poudreuse, sentier tassé, bord de l'étang ---
        const grid = new THREE.PlaneGeometry(S, S, N, N);
        grid.rotateX(-Math.PI / 2);
        const gp = grid.attributes.position;
        for (let i = 0; i < gp.count; i++) gp.setY(i, height(gp.getX(i), gp.getZ(i)));
        const terrainGeo = grid.toNonIndexed();
        grid.dispose();
        const tp = terrainGeo.attributes.position;
        const tc = new Float32Array(tp.count * 3);
        const SNOW = [0xf3f6fb, 0xeaf0f8, 0xf7f9fc, 0xe4ebf5].map(color);
        const HOLLOW = color(0xc7d4ea);
        const ROCK = [0x5d6470, 0x6b7380].map(color);
        const v3a = new THREE.Vector3();
        const v3b = new THREE.Vector3();
        for (let f = 0; f < tp.count; f += 3) {
            const x = (tp.getX(f) + tp.getX(f + 1) + tp.getX(f + 2)) / 3;
            const y = (tp.getY(f) + tp.getY(f + 1) + tp.getY(f + 2)) / 3;
            const z = (tp.getZ(f) + tp.getZ(f + 1) + tp.getZ(f + 2)) / 3;
            const h = hash(x, z);
            tmp.copy(SNOW[Math.floor(h * SNOW.length)]);
            // Les creux restent dans l'ombre bleue
            tmp.lerp(HOLLOW, clamp(0.35 - y * 0.6, 0, 0.45));
            // Sur les pentes les plus raides, la roche sombre perce la neige
            v3a.set(tp.getX(f + 1) - tp.getX(f), tp.getY(f + 1) - tp.getY(f), tp.getZ(f + 1) - tp.getZ(f));
            v3b.set(tp.getX(f + 2) - tp.getX(f), tp.getY(f + 2) - tp.getY(f), tp.getZ(f + 2) - tp.getZ(f));
            const ny = Math.abs(v3a.cross(v3b).normalize().y);
            if (ny < 0.8 && h < 0.7) tmp.copy(ROCK[Math.floor(h * 2.9) % 2]);
            for (let k = 0; k < 3; k++) tmp.toArray(tc, (f + k) * 3);
        }
        terrainGeo.setAttribute('color', new THREE.BufferAttribute(tc, 3));
        terrainGeo.computeVertexNormals();
        const terrainMat = new THREE.MeshStandardMaterial({ vertexColors: true, flatShading: true, roughness: 0.9 });
        // La neige scintille : de minuscules cristaux qui s'allument et s'éteignent
        terrainMat.onBeforeCompile = (sh) => {
            sh.uniforms.uTime = uTime;
            sh.vertexShader = 'varying vec3 vSn;\n' + sh.vertexShader.replace('#include <begin_vertex>', '#include <begin_vertex>\nvSn = (modelMatrix * vec4(transformed, 1.0)).xyz;');
            sh.fragmentShader = 'uniform float uTime;\nvarying vec3 vSn;\n' + sh.fragmentShader.replace('#include <color_fragment>', `#include <color_fragment>
vec2 cell = floor(vSn.xz * 70.0);
float n = fract(sin(dot(cell, vec2(12.9898, 78.233))) * 43758.5453);
float tw = 0.5 + 0.5 * sin(uTime * (1.5 + n * 4.0) + n * 60.0);
diffuseColor.rgb += step(0.9965, n) * tw * 0.55;`);
        };
        const terrain = new THREE.Mesh(terrainGeo, terrainMat);
        terrain.receiveShadow = true;
        scene.add(terrain);

        // --- Côtés du bloc : la neige, puis la terre gelée et la roche ---
        const sideMat = new THREE.MeshStandardMaterial({ map: earthTexture(), roughness: 1 });
        const lipMat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.9 });
        const EDGES = [
            { x0: -HALF, z0: HALF, dx: 1, dz: 0 },
            { x0: HALF, z0: HALF, dx: 0, dz: -1 },
            { x0: HALF, z0: -HALF, dx: -1, dz: 0 },
            { x0: -HALF, z0: -HALF, dx: 0, dz: 1 },
        ];
        const LIP_TOP = color(0xf2f6fb);
        const LIP_LOW = color(0xc3d0e6);
        EDGES.forEach((e, ei) => {
            const body = [];
            const bodyUv = [];
            const lip = [];
            const lipCol = [];
            for (let i = 0; i <= N; i++) {
                const x = e.x0 + e.dx * S * i / N;
                const z = e.z0 + e.dz * S * i / N;
                const top = height(x, z);
                // Une couche de neige d'épaisseur un peu irrégulière
                const thick = 0.2 + 0.05 * Math.sin(i * 0.7 + ei) + 0.03 * Math.sin(i * 1.9);
                lip.push(x, top, z, x, top - thick, z);
                LIP_TOP.toArray(lipCol, lipCol.length);
                LIP_LOW.toArray(lipCol, lipCol.length);
                body.push(x, top - thick, z, x, BASE, z);
                const u = (ei * S + S * i / N) / 6;
                bodyUv.push(u, (top - thick - BASE) / (1.4 - BASE), u, 0);
            }
            const normal = [-e.dz, 0, e.dx];
            scene.add(strip(body, bodyUv, null, normal, sideMat, true));
            scene.add(strip(lip, null, lipCol, normal, lipMat, true));
        });
        const bottom = new THREE.Mesh(new THREE.PlaneGeometry(S, S).rotateX(Math.PI / 2), new THREE.MeshStandardMaterial({ color: 0x3a3430 }));
        bottom.position.y = BASE;
        scene.add(bottom);
        const contact = new THREE.Mesh(new THREE.PlaneGeometry(S * 1.9, S * 1.9), new THREE.MeshBasicMaterial({ map: radialTexture('rgba(10,16,34,0.45)', 'rgba(10,16,34,0)'), transparent: true, depthWrite: false, fog: false }));
        contact.rotation.x = -Math.PI / 2;
        contact.position.set(0.6, BASE - 0.02, 0.6);
        scene.add(contact);

        // --- Le chalet ---
        const chalet = new THREE.Group();
        chalet.position.set(CH.x, 0.02, CH.z);
        chalet.rotation.y = CH.rot;
        scene.add(chalet);
        const chaletMeshes = [];
        const add = (m, parent = chalet) => {
            m.castShadow = true;
            m.receiveShadow = true;
            parent.add(m);
            chaletMeshes.push(m);
            return m;
        };
        const W = CH.W;
        const D = CH.D;
        const STONE_H = 0.26;
        const R = 0.062;
        const LEVELS = 9;
        const TOP = STONE_H + LEVELS * 2 * R;
        const snowMat = flat(0xf4f7fc, { roughness: 0.8 });
        const darkWood = flat(0x3f2716);
        // Le soubassement en pierres
        const stoneMat = flat(0x7a7570, { roughness: 1 });
        add(new THREE.Mesh(new THREE.BoxGeometry(W + 0.14, STONE_H, D + 0.14), stoneMat)).position.y = STONE_H / 2;
        for (let i = 0; i < 26; i++) {
            const side = i % 4;
            const k = rand() - 0.5;
            const st = add(new THREE.Mesh(new THREE.DodecahedronGeometry(rr(0.05, 0.08), 0), flat([0x8a847e, 0x6c6762, 0x958f88][i % 3], { roughness: 1 })));
            const along = side < 2 ? W + 0.1 : D + 0.1;
            const px = side < 2 ? k * along : (side === 2 ? 1 : -1) * (W / 2 + 0.07);
            const pz = side < 2 ? (side === 0 ? 1 : -1) * (D / 2 + 0.07) : k * along;
            st.position.set(side < 2 ? px : px * 0.985, rr(0.06, 0.2), side < 2 ? pz * 0.985 : pz);
            st.scale.set(1, 0.6, 1);
            st.rotation.set(rand() * 3, rand() * 3, rand() * 3);
        }
        // Les rondins, croisés aux angles comme dans un vrai chalet
        const LOGS = [0x7b4e2c, 0x6e4426, 0x845533, 0x74492a].map((c) => flat(c, { roughness: 0.95 }));
        const endMat = flat(0xb38658, { roughness: 1 });
        const logX = new THREE.CylinderGeometry(R, R, W + 0.32, 8).rotateZ(Math.PI / 2);
        const logZ = new THREE.CylinderGeometry(R, R, D + 0.32, 8).rotateX(Math.PI / 2);
        const endGeo = new THREE.CircleGeometry(R * 0.86, 8);
        for (let i = 0; i < LEVELS; i++) {
            const yx = STONE_H + R + i * 2 * R;
            const yz = yx + R * 0.9;
            [-1, 1].forEach((s) => {
                const a = add(new THREE.Mesh(logX, LOGS[(i * 2 + s + 4) % 4]));
                a.position.set(0, yx, s * D / 2);
                if (i < LEVELS - 1) {
                    const b = add(new THREE.Mesh(logZ, LOGS[(i + s + 5) % 4]));
                    b.position.set(s * W / 2, yz, 0);
                }
                // Les bouts des rondins, plus clairs, qui dépassent aux angles
                [-1, 1].forEach((e) => {
                    const c = add(new THREE.Mesh(endGeo, endMat));
                    c.position.set(e * (W / 2 + 0.16), yx, s * D / 2);
                    c.rotation.y = e * Math.PI / 2;
                });
            });
        }
        // Le pignon en planches, côté porte et derrière
        const RIDGE = 0.98;
        const OVER = 0.36;
        const pitch = Math.atan2(RIDGE, W / 2);
        const gable = new THREE.Shape();
        gable.moveTo(-W / 2 - 0.05, 0);
        gable.lineTo(W / 2 + 0.05, 0);
        gable.lineTo(0, RIDGE + 0.04);
        gable.closePath();
        const gableGeo = new THREE.ShapeGeometry(gable);
        const boardsTex = boardTexture();
        const gableMat = new THREE.MeshStandardMaterial({ map: boardsTex, roughness: 0.95, side: THREE.DoubleSide });
        // Les coordonnées de texture suivent les planches verticales
        const guv = gableGeo.attributes.uv;
        const gpos = gableGeo.attributes.position;
        for (let i = 0; i < guv.count; i++) guv.setXY(i, gpos.getX(i) * 1.6, gpos.getY(i) * 1.6);
        [-1, 1].forEach((s) => {
            const g = add(new THREE.Mesh(gableGeo, gableMat));
            g.position.set(0, TOP - R * 0.4, s * (D / 2 + R * 0.2));
            if (s < 0) g.rotation.y = Math.PI;
        });

        // Le toit : deux pans très pentus, débordants, et un gros édredon de neige dessus
        const ridgeY = TOP + RIDGE;
        const span = W / 2 + OVER;
        const L = span / Math.cos(pitch);
        const ROOF_D = D + 0.7;
        const roofMat = flat(0x4a2d1a, { roughness: 0.9 });
        const roofSnow = [];
        [-1, 1].forEach((s) => {
            const dir = V(s * Math.cos(pitch), -Math.sin(pitch), 0);
            const nrm = V(s * Math.sin(pitch), Math.cos(pitch), 0);
            const top = V(0, ridgeY + 0.02, 0);
            const slab = add(new THREE.Mesh(new THREE.BoxGeometry(L, 0.08, ROOF_D), roofMat));
            slab.position.copy(top).addScaledVector(dir, L / 2).addScaledVector(nrm, 0.04);
            slab.rotation.z = -s * pitch;
            // La neige, un peu bombée : on gonfle le milieu du pan
            const sg = new THREE.BoxGeometry(L + 0.04, 0.18, ROOF_D + 0.06, 8, 2, 8);
            const sgp = sg.attributes.position;
            for (let i = 0; i < sgp.count; i++) {
                if (sgp.getY(i) > 0) {
                    const u = sgp.getX(i) / (L + 0.04) + 0.5;
                    const w = sgp.getZ(i) / (ROOF_D + 0.06) + 0.5;
                    sgp.setY(i, sgp.getY(i) + 0.05 * Math.sin(u * Math.PI) * Math.sin(w * Math.PI) + 0.012 * Math.sin(i * 1.7));
                }
            }
            sg.computeVertexNormals();
            const sn = add(new THREE.Mesh(sg, snowMat));
            sn.position.copy(top).addScaledVector(dir, L / 2).addScaledVector(nrm, 0.16);
            sn.rotation.z = -s * pitch;
            roofSnow.push(sn);
            // Le bourrelet de neige qui déborde au bout du toit
            const eave = V(0, ridgeY, 0).addScaledVector(dir, L).addScaledVector(nrm, 0.12);
            const lip = add(new THREE.Mesh(new THREE.CapsuleGeometry(0.1, ROOF_D - 0.1, 4, 10).rotateX(Math.PI / 2), snowMat));
            lip.position.copy(eave).addScaledVector(dir, -0.03);
            lip.scale.set(1, 0.85, 1);
            // Les stalactites de glace sous le rebord
            const iceMat = new THREE.MeshStandardMaterial({ color: 0xd6e8f8, roughness: 0.15, metalness: 0.1, transparent: true, opacity: 0.85, envMap, emissive: 0x31435e, emissiveIntensity: 0.4 });
            const count = phone ? 10 : 16;
            for (let i = 0; i < count; i++) {
                const len = rr(0.07, 0.26) * (i % 3 === 0 ? 1.4 : 1);
                const ic = new THREE.Mesh(new THREE.ConeGeometry(rr(0.014, 0.026), len, 5).rotateX(Math.PI), iceMat);
                ic.position.set(eave.x - s * 0.05, eave.y - 0.06 - len / 2, -ROOF_D / 2 + 0.12 + (ROOF_D - 0.24) * (i + rr(-0.3, 0.3)) / (count - 1));
                chalet.add(ic);
                chaletMeshes.push(ic);
            }
        });
        // La neige sur le faîte
        const ridgeSnow = add(new THREE.Mesh(new THREE.CapsuleGeometry(0.13, ROOF_D - 0.2, 4, 10).rotateX(Math.PI / 2), snowMat));
        ridgeSnow.position.set(0, ridgeY + 0.2, 0);
        ridgeSnow.scale.set(1.3, 0.75, 1);
        // Les poutres sous le débord, côté pignon
        [-1, 1].forEach((s) => {
            [-1, 1].forEach((e) => {
                const beam = add(new THREE.Mesh(new THREE.BoxGeometry(0.07, 0.07, 0.5), darkWood));
                beam.position.set(e * (W / 2 - 0.25), TOP + (RIDGE * 0.25) - 0.05, s * (D / 2 + 0.2));
            });
        });

        // La cheminée en pierre, avec son chapeau de neige
        const chimX = 0.55;
        const chimZ = -0.35;
        const roofAt = ridgeY - chimX * Math.tan(pitch);
        const chimTop = ridgeY + 0.38;
        const chim = add(new THREE.Mesh(new THREE.BoxGeometry(0.3, chimTop - roofAt + 0.2, 0.3), flat(0x6e6863, { roughness: 1 })));
        chim.position.set(chimX, (chimTop + roofAt - 0.2) / 2, chimZ);
        const chimCap = add(new THREE.Mesh(new THREE.BoxGeometry(0.38, 0.05, 0.38), flat(0x55504c)));
        chimCap.position.set(chimX, chimTop, chimZ);
        const chimSnow = add(new THREE.Mesh(new THREE.SphereGeometry(0.21, 10, 6, 0, Math.PI * 2, 0, Math.PI / 2), snowMat));
        chimSnow.position.set(chimX, chimTop + 0.02, chimZ);
        chimSnow.scale.set(1, 0.45, 1);
        chalet.updateMatrixWorld(true);
        const smokeFrom = V(chimX, chimTop + 0.12, chimZ).applyMatrix4(chalet.matrixWorld);

        // Les fenêtres : lumière chaude, croisillons, volets rouges et rebord enneigé
        // La lumière des fenêtres perce la tempête (le brouillard ne l'éteint pas)
        const glassMat = new THREE.MeshStandardMaterial({ color: 0x2a1a0c, emissive: 0xffa84f, emissiveIntensity: 1.6, roughness: 0.4, fog: false });
        const shutterMat = flat(0x8c3424, { roughness: 0.9 });
        // Une silhouette : la tête et les épaules (une plus petite pour un enfant)
        const bust = (k) => {
            const sh = new THREE.Shape();
            sh.moveTo(-0.13 * k, 0);
            sh.quadraticCurveTo(-0.13 * k, 0.12 * k, -0.05 * k, 0.13 * k);
            sh.lineTo(0.05 * k, 0.13 * k);
            sh.quadraticCurveTo(0.13 * k, 0.12 * k, 0.13 * k, 0);
            sh.closePath();
            const head = new THREE.CircleGeometry(0.055 * k, 14).translate(0, 0.2 * k, 0);
            const neck = new THREE.PlaneGeometry(0.04 * k, 0.05 * k).translate(0, 0.14 * k, 0);
            const body = new THREE.ShapeGeometry(sh, 6);
            const parts = [body, head, neck].map((g) => g.toNonIndexed());
            const pos = [];
            parts.forEach((g) => { pos.push(...g.attributes.position.array); g.dispose(); });
            const g = new THREE.BufferGeometry();
            g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
            return g;
        };
        const silGeo = bust(1);
        const silSmall = bust(0.78);
        const people = [];
        const WINDOWS = [
            { x: -0.66, y: STONE_H + 0.52, z: D / 2, ry: 0, who: 'read' },
            { x: 0.66, y: STONE_H + 0.52, z: D / 2, ry: 0, who: 'walk' },
            { x: W / 2, y: STONE_H + 0.52, z: -0.35, ry: Math.PI / 2, who: 'small' },
            { x: W / 2, y: STONE_H + 0.52, z: 0.42, ry: Math.PI / 2 },
            { x: -W / 2, y: STONE_H + 0.52, z: 0.25, ry: -Math.PI / 2, who: 'walk' },
            { x: 0, y: STONE_H + 0.52, z: -D / 2, ry: Math.PI },
        ];
        WINDOWS.forEach((w) => {
            const g = new THREE.Group();
            g.position.set(w.x, w.y, w.z);
            g.rotation.y = w.ry;
            chalet.add(g);
            const out = R + 0.012;
            add(new THREE.Mesh(new THREE.BoxGeometry(0.4, 0.42, 0.05), darkWood), g).position.z = out;
            add(new THREE.Mesh(new THREE.PlaneGeometry(0.32, 0.34), glassMat), g).position.z = out + 0.027;
            if (w.who) {
                // Quelqu'un à l'intérieur, à contre-jour : on ne voit que sa silhouette
                const sil = new THREE.Mesh(w.who === 'small' ? silSmall : silGeo, new THREE.MeshBasicMaterial({ color: 0x2e1a0c, transparent: true, opacity: 0, depthWrite: false }));
                sil.position.set(0, -0.17, out + 0.029);
                g.add(sil);
                people.push({ sil, base: rr(-0.04, 0.04), on: rand() < 0.7, until: rr(3, 9), a: 0, ph: rr(0, 6.28), read: w.who === 'read' });
            }
            const bar1 = add(new THREE.Mesh(new THREE.BoxGeometry(0.025, 0.34, 0.02), darkWood), g);
            bar1.position.z = out + 0.035;
            const bar2 = add(new THREE.Mesh(new THREE.BoxGeometry(0.32, 0.025, 0.02), darkWood), g);
            bar2.position.z = out + 0.035;
            [-1, 1].forEach((e) => {
                const sh = add(new THREE.Mesh(new THREE.BoxGeometry(0.19, 0.44, 0.03), shutterMat), g);
                sh.position.set(e * 0.31, 0, out + 0.01);
            });
            const sill = add(new THREE.Mesh(new THREE.BoxGeometry(0.46, 0.04, 0.12), darkWood), g);
            sill.position.set(0, -0.23, out + 0.04);
            const sillSnow = add(new THREE.Mesh(new THREE.CapsuleGeometry(0.035, 0.38, 3, 8).rotateZ(Math.PI / 2), snowMat), g);
            sillSnow.position.set(0, -0.19, out + 0.05);
            sillSnow.scale.set(1, 0.8, 1.3);
        });
        // La petite fenêtre ronde du pignon
        const oculus = add(new THREE.Mesh(new THREE.CircleGeometry(0.13, 16), glassMat));
        oculus.position.set(0, TOP + 0.42, D / 2 + R * 0.2 + 0.02);
        const oculusRim = add(new THREE.Mesh(new THREE.TorusGeometry(0.14, 0.025, 6, 18), darkWood));
        oculusRim.position.copy(oculus.position);

        // La porte, son auvent et le paillasson de neige tassée
        const doorMesh = add(new THREE.Mesh(new THREE.BoxGeometry(0.46, 0.8, 0.06), flat(0x4f301b)));
        doorMesh.position.set(0, STONE_H + 0.4, D / 2 + R + 0.02);
        const doorWin = add(new THREE.Mesh(new THREE.PlaneGeometry(0.18, 0.16), glassMat));
        doorWin.position.set(0, STONE_H + 0.6, D / 2 + R + 0.052);
        const knob = add(new THREE.Mesh(new THREE.SphereGeometry(0.022, 8, 6), flat(0xc9a04f, { metalness: 0.6, roughness: 0.4 })));
        knob.position.set(0.15, STONE_H + 0.38, D / 2 + R + 0.06);
        const step = add(new THREE.Mesh(new THREE.BoxGeometry(0.62, 0.1, 0.3), stoneMat));
        step.position.set(0, 0.05, D / 2 + 0.2);

        // Le tas de bois contre le mur, sous la neige
        const pile = new THREE.Group();
        pile.position.set(-W / 2 - 0.3, 0, -0.35);
        chalet.add(pile);
        const pileLog = new THREE.CylinderGeometry(0.065, 0.065, 0.42, 7).rotateZ(Math.PI / 2);
        const pileEnd = new THREE.CircleGeometry(0.056, 7);
        [4, 3, 2].forEach((n, row) => {
            for (let i = 0; i < n; i++) {
                const z = (i - (n - 1) / 2) * 0.135;
                const y = 0.07 + row * 0.115;
                add(new THREE.Mesh(pileLog, LOGS[(i + row) % 4]), pile).position.set(0, y, z);
                const e = add(new THREE.Mesh(pileEnd, endMat), pile);
                e.position.set(-0.212, y, z);
                e.rotation.y = -Math.PI / 2;
            }
        });
        const pileSnow = add(new THREE.Mesh(new THREE.SphereGeometry(0.3, 12, 6, 0, Math.PI * 2, 0, Math.PI / 2), snowMat), pile);
        pileSnow.position.set(0, 0.36, 0);
        pileSnow.scale.set(0.9, 0.35, 1.05);

        // La lanterne près de la porte
        const lanternPos = V(0.62, 0, D / 2 + 0.55);
        const post = add(new THREE.Mesh(new THREE.CylinderGeometry(0.03, 0.035, 0.95, 6), darkWood));
        post.position.set(lanternPos.x, 0.47, lanternPos.z);
        const lanternMat = new THREE.MeshStandardMaterial({ color: 0x2a1a0c, emissive: 0xffb562, emissiveIntensity: 2.2, fog: false });
        const lantern = add(new THREE.Mesh(new THREE.BoxGeometry(0.11, 0.14, 0.11), lanternMat));
        lantern.position.set(lanternPos.x, 1.0, lanternPos.z);
        const lanternHat = add(new THREE.Mesh(new THREE.ConeGeometry(0.1, 0.07, 4).rotateY(Math.PI / 4), darkWood));
        lanternHat.position.set(lanternPos.x, 1.1, lanternPos.z);
        const lanternSnow = add(new THREE.Mesh(new THREE.SphereGeometry(0.06, 8, 5, 0, Math.PI * 2, 0, Math.PI / 2), snowMat));
        lanternSnow.position.set(lanternPos.x, 1.125, lanternPos.z);
        lanternSnow.scale.set(1, 0.6, 1);

        // La lumière des fenêtres qui coule sur la neige
        const glowFront = new THREE.PointLight(0xffa456, 3.2, 4.2, 1.3);
        glowFront.position.set(0, 0.75, D / 2 + 0.75);
        chalet.add(glowFront);
        const glowRight = new THREE.PointLight(0xffa456, 2.2, 3.4, 1.3);
        glowRight.position.set(W / 2 + 0.7, 0.75, 0);
        chalet.add(glowRight);
        const glowLeft = new THREE.PointLight(0xffa456, 1.6, 3, 1.3);
        glowLeft.position.set(-W / 2 - 0.7, 0.75, 0.3);
        chalet.add(glowLeft);
        const lanternLight = new THREE.PointLight(0xffb468, 1.6, 2.6, 1.3);
        lanternLight.position.set(lanternPos.x, 1.0, lanternPos.z + 0.05);
        chalet.add(lanternLight);
        const glows = [[glowFront, 3.2], [glowRight, 2.2], [glowLeft, 1.6]];

        // --- La forêt de sapins, tous poudrés de neige ---
        const firGeo = firGeometry();
        const firMat = new THREE.MeshStandardMaterial({ vertexColors: true, flatShading: true, roughness: 0.9 });
        const firs = [];
        const tries = phone ? 1600 : 3000;
        const want = phone ? 95 : 160;
        for (let i = 0; i < tries && firs.length < want; i++) {
            const x = rr(-HALF + 0.3, HALF - 0.3);
            const z = rr(-HALF + 0.3, HALF - 0.3);
            const back = smooth(clamp((-z + 1) / 5, 0, 1));
            const sideEdge = smooth(clamp((Math.abs(x) - 2) / 2.5, 0, 1));
            // Les sapins couvrent toute la vallée ; il ne reste qu'une petite clairière autour du chalet
            if (rand() > 0.55 + 0.45 * Math.max(back, sideEdge)) continue;
            if (footprint(x, z) < 1.0) continue;
            const fd = footprint(x, z);
            if (fd < 1.6 && rand() < 0.5) continue;
            // On garde une trouée devant la façade, pour voir les fenêtres éclairées
            const lx = (x - CH.x) * cr - (z - CH.z) * sr;
            const lz = (x - CH.x) * sr + (z - CH.z) * cr;
            if (lz > 0 && lz < 3.4 && Math.abs(lx) < 0.55 + lz * 0.35) continue;
            const s = rr(0.65, 1.15) * (0.8 + 0.4 * back);
            const r = 0.45 * s;
            if (firs.some((f) => Math.hypot(f.x - x, f.z - z) < (r + f.r) * 0.55)) continue;
            firs.push({ x, y: height(x, z) - 0.02, z, s, r, yaw: rr(0, 6.28), tilt: rr(-0.05, 0.05), shake: 0, ph: rr(0, 6.28) });
        }
        const firMesh = instanced(firGeo, firMat, firs, (p) => tmp.setScalar(rr(0.82, 1.05)).clone(), true);

        // --- La neige qui tombe ---
        const pointScale = { value: 1 };
        const flakes = particles(phone ? 900 : 1700);
        const SKY_TOP = 7;
        let gust = 0;
        let storm = 1;
        flakes.items.forEach((p) => resetFlake(p, true));
        function resetFlake(p, anywhere) {
            p.x = rr(-HALF - 1, HALF + 1);
            p.z = rr(-HALF - 1, HALF + 1);
            p.y = anywhere ? rr(-0.5, SKY_TOP) : SKY_TOP + rr(0, 1);
            p.sp = rr(0.5, 0.95);
            p.s = rr(0.025, 0.065);
            p.ph = rr(0, 6.28);
            p.sw = rr(0.15, 0.35);
        }
        // Des traînées blanches : la neige que le vent fait filer à l'horizontale
        const STREAKS = phone ? 300 : 650;
        const streakPos = new Float32Array(STREAKS * 6);
        const streakGeo = new THREE.BufferGeometry();
        streakGeo.setAttribute('position', new THREE.BufferAttribute(streakPos, 3));
        const streakLines = new THREE.LineSegments(streakGeo, new THREE.LineBasicMaterial({ color: 0xf2f6fb, transparent: true, opacity: 0.38, depthWrite: false }));
        streakLines.frustumCulled = false;
        streakLines.renderOrder = 8;
        scene.add(streakLines);
        const streaks = Array.from({ length: STREAKS }, () => {
            const f = {};
            resetStreak(f, true);
            return f;
        });
        function resetStreak(f, anywhere) {
            f.x = anywhere ? rr(-8, 8) : -8 - rr(0, 2);
            f.z = rr(-8, 8);
            f.y = Math.pow(rand(), 1.4) * 5 - 0.2;
            f.sp = rr(3.5, 6.5);
            f.len = rr(0.15, 0.4);
            f.ph = rr(0, 6.28);
        }
        // La fumée de la cheminée
        const smoke = particles(phone ? 26 : 40);
        smoke.items.forEach((p) => resetPuff(p, true));
        function resetPuff(p, anywhere) {
            p.age = anywhere ? rand() : 0;
            p.life = rr(4.5, 6.5);
            p.dx = rr(-0.05, 0.05);
            p.dz = rr(-0.05, 0.05);
            p.ph = rr(0, 6.28);
        }
        // Les paquets de neige qui tombent des branches quand on secoue un sapin
        const puffs = particles(phone ? 80 : 140);
        puffs.items.forEach((p) => { p.age = 1; });
        let puffNext = 0;
        function snowPuff(x, y, z, n, spread) {
            for (let k = 0; k < n; k++) {
                const p = puffs.items[puffNext];
                puffNext = (puffNext + 1) % puffs.items.length;
                Object.assign(p, { x: x + rr(-spread, spread), y: y + rr(0, spread * 2.2), z: z + rr(-spread, spread), vx: rr(-0.25, 0.25), vy: rr(-0.2, 0.4), vz: rr(-0.25, 0.25), age: 0, life: rr(0.9, 1.6), s: rr(0.05, 0.11) });
            }
        }

        // --- Caméra : au départ, de face, le chalet entre les sapins ---
        const target = V(0.0, 0.7, 0.0);
        const HOME_EL = 0.38;
        let az = 0.35;
        let el = HOME_EL;
        let zoom = 0.48;
        let fit = 26;
        let lastInput = -10;
        let touched = false;
        const pointers = new Map();
        let pinch = 0;
        let downAt = null;
        const canvas = renderer.domElement;
        const spread = () => {
            const [a, b] = [...pointers.values()];
            return Math.hypot(a.x - b.x, a.y - b.y) || 1;
        };
        const onDown = (e) => {
            canvas.setPointerCapture(e.pointerId);
            pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
            if (pointers.size === 1) downAt = { x: e.clientX, y: e.clientY, t: performance.now() };
            if (pointers.size === 2) pinch = spread();
            lastInput = clock;
            touched = true;
        };
        const onMove = (e) => {
            const p = pointers.get(e.pointerId);
            if (!p) return;
            const dx = e.clientX - p.x;
            const dy = e.clientY - p.y;
            p.x = e.clientX;
            p.y = e.clientY;
            if (pointers.size === 1) {
                az -= dx * 0.0065;
                el = clamp(el + dy * 0.0045, 0.05, 1.2);
            } else if (pointers.size === 2) {
                const s = spread();
                if (pinch) zoom = clamp(zoom * pinch / s, 0.25, 1.5);
                pinch = s;
            }
            lastInput = clock;
        };
        const onUp = (e) => {
            pointers.delete(e.pointerId);
            pinch = 0;
            if (downAt && pointers.size === 0) {
                const moved = Math.hypot(e.clientX - downAt.x, e.clientY - downAt.y);
                if (moved < 7 && performance.now() - downAt.t < 400) tap(e);
            }
            downAt = null;
        };
        const onWheel = (e) => {
            e.preventDefault();
            zoom = clamp(zoom * Math.exp(e.deltaY * 0.0012), 0.25, 1.5);
            lastInput = clock;
        };
        canvas.addEventListener('pointerdown', onDown);
        canvas.addEventListener('pointermove', onMove);
        canvas.addEventListener('pointerup', onUp);
        canvas.addEventListener('pointercancel', onUp);
        canvas.addEventListener('wheel', onWheel, { passive: false });

        // Toucher le chalet : on éteint ou rallume. Un sapin : il se secoue et perd sa neige.
        // Ailleurs : une rafale encore plus forte.
        const raycaster = new THREE.Raycaster();
        const ndc = new THREE.Vector2();
        let lightsOn = true;
        let light = 1;
        function tap(e) {
            const r = canvas.getBoundingClientRect();
            ndc.set(((e.clientX - r.left) / r.width) * 2 - 1, -((e.clientY - r.top) / r.height) * 2 + 1);
            raycaster.setFromCamera(ndc, camera);
            const hits = raycaster.intersectObjects([...chaletMeshes, firMesh], false);
            const hit = hits[0];
            if (hit && chaletMeshes.includes(hit.object)) {
                lightsOn = !lightsOn;
                if (!lightsOn) roofSnow.forEach((m) => snowPuff(...m.getWorldPosition(v3).toArray(), 10, 0.5));
                return;
            }
            if (hit && hit.object === firMesh && hit.instanceId != null) {
                const f = firs[hit.instanceId];
                f.shake = 1;
                snowPuff(f.x, f.y + f.s * 0.5, f.z, phone ? 18 : 28, f.r * 0.8);
                return;
            }
            gust = 1;
        }

        function resize() {
            const w = stage.clientWidth || 1;
            const h = stage.clientHeight || 1;
            renderer.setSize(w, h, false);
            camera.aspect = w / h;
            const tanV = Math.tan(THREE.MathUtils.degToRad(camera.fov / 2));
            fit = Math.max(14 / tanV / 2, (camera.aspect < 0.8 ? 14 : 15.6) / (tanV * camera.aspect) / 2);
            if (!touched) zoom = camera.aspect < 0.8 ? 0.64 : 0.48;
            camera.updateProjectionMatrix();
            pointScale.value = camera.projectionMatrix.elements[5] * renderer.domElement.height / 2;
        }
        const ro = new ResizeObserver(resize);
        ro.observe(stage);
        resize();

        // --- Boucle ---
        const m4 = new THREE.Matrix4();
        const q = new THREE.Quaternion();
        const qT = new THREE.Quaternion();
        const v3 = new THREE.Vector3();
        const sc = new THREE.Vector3();
        const up = new THREE.Vector3(0, 1, 0);
        const xAxis = new THREE.Vector3(1, 0, 0);
        const zAxis = new THREE.Vector3(0, 0, 1);
        const FLAKE = [0.95, 0.97, 1.0];
        let clock = 0;
        let last = performance.now();
        let raf = 0;
        let alive = true;

        function frame(now) {
            if (!alive) return;
            const real = Math.min(0.25, (now - last) / 1000);
            const dt = Math.min(0.05, real);
            last = now;
            clock += dt;
            const t = clock;
            uTime.value = t;

            if (!still && !pointers.size) {
                const idle = smooth(clamp((clock - lastInput - 3) / 2, 0, 1));
                az += IDLE_SPIN * dt * idle;
                el += (HOME_EL - el) * Math.min(1, dt * 0.8) * idle;
            }
            const dist = fit * zoom;
            camera.position.set(target.x + dist * Math.cos(el) * Math.sin(az), target.y + dist * Math.sin(el), target.z + dist * Math.cos(el) * Math.cos(az));
            camera.lookAt(target);
            // Les rafales épaississent et éclaircissent le voile blanc, lentement
            storm = 1 + 0.3 * Math.sin(t * 0.19) + 0.15 * Math.sin(t * 0.47 + 2.1) + gust * 0.6;
            scene.fog.near = dist * (0.46 - 0.1 * storm);
            scene.fog.far = dist * (1.55 - 0.28 * storm) + 1.5;

            // Le feu de cheminée fait vaciller la lumière des fenêtres
            light += ((lightsOn ? 1 : 0) - light) * Math.min(1, dt * 3);
            const flick = 0.9 + 0.06 * Math.sin(t * 7.3) + 0.04 * Math.sin(t * 13.1 + 1.3);
            glassMat.emissiveIntensity = 0.05 + 2.1 * light * flick;
            glows.forEach(([g, base]) => { g.intensity = base * light * flick; });
            lanternMat.emissiveIntensity = 0.1 + 2.1 * light;
            lanternLight.intensity = 1.6 * light;

            // Les silhouettes : elles vont et viennent, l'une lit en hochant un peu la tête
            people.forEach((p) => {
                if (t > p.until) {
                    p.on = !p.on;
                    p.until = t + (p.on ? rr(8, 16) : rr(4, 9));
                }
                p.a += ((p.on && light > 0.3 ? 1 : 0) - p.a) * Math.min(1, dt * 1.2);
                p.sil.material.opacity = 0.82 * p.a;
                p.sil.position.x = p.base + (p.read ? Math.sin(t * 0.3 + p.ph) * 0.01 : (1 - p.a) * 0.12 + Math.sin(t * 0.5 + p.ph) * 0.025);
                p.sil.rotation.z = p.read ? Math.sin(t * 0.7 + p.ph) * 0.04 : 0;
                p.sil.position.y = -0.17 + Math.sin(t * 1.1 + p.ph) * 0.004;
            });

            // Les sapins secoués
            let dirty = false;
            firs.forEach((f, i) => {
                if (f.shake <= 0) return;
                f.shake = Math.max(0, f.shake - dt * 0.9);
                const w = Math.sin(t * 22 + f.ph) * 0.09 * f.shake;
                q.setFromAxisAngle(up, f.yaw);
                qT.setFromAxisAngle(xAxis, f.tilt + w);
                q.multiply(qT);
                qT.setFromAxisAngle(zAxis, w * 0.6);
                q.multiply(qT);
                m4.compose(v3.set(f.x, f.y, f.z), q, sc.setScalar(f.s));
                firMesh.setMatrixAt(i, m4);
                dirty = true;
            });
            if (dirty) firMesh.instanceMatrix.needsUpdate = true;


            // La neige tombe, en se balançant ; la rafale l'emporte
            gust = Math.max(0, gust - dt * 0.35);
            const wind = 1.6 * storm + gust * 1.6;
            flakes.items.forEach((p, i) => {
                p.y -= p.sp * dt * (1 + gust * 0.4) * (0.8 + 0.2 * storm);
                p.x += (wind * (0.7 + p.sw) + Math.sin(t * 1.6 + p.ph) * p.sw) * dt;
                p.z += (wind * 0.25 + Math.cos(t * 1.3 + p.ph) * p.sw * 0.9 + gust * Math.sin(p.ph) * 0.8) * dt;
                if (p.x > HALF + 1) p.x -= S + 2;
                if (p.z > HALF + 1) p.z -= S + 2;
                const inside = Math.abs(p.x) < HALF && Math.abs(p.z) < HALF;
                const floor = inside ? height(p.x, p.z) : BASE;
                if (p.y < floor) resetFlake(p, false);
                const fade = clamp((SKY_TOP + 0.5 - p.y) / 1.2, 0, 1) * clamp((p.y - floor) / 0.15, 0, 1);
                flakes.set(i, p.x, p.y, p.z, p.s, FLAKE, 0.9 * fade);
            });
            flakes.update();
            streaks.forEach((f, i) => {
                f.x += f.sp * (0.55 + 0.45 * storm + gust * 0.8) * dt;
                f.z += f.sp * 0.25 * dt;
                f.y -= 0.35 * dt + Math.sin(t * 2 + f.ph) * 0.1 * dt;
                if (f.x > 8 || f.y < -0.5) resetStreak(f, false);
                if (f.z > 8) f.z -= 16;
                const o = i * 6;
                streakPos[o] = f.x;
                streakPos[o + 1] = f.y;
                streakPos[o + 2] = f.z;
                streakPos[o + 3] = f.x - f.len * storm;
                streakPos[o + 4] = f.y + 0.03;
                streakPos[o + 5] = f.z - f.len * 0.25;
            });
            streakGeo.attributes.position.needsUpdate = true;

            // La fumée monte, gonfle et se disperse
            smoke.items.forEach((p, i) => {
                p.age += real / p.life;
                if (p.age >= 1) resetPuff(p, false);
                const k = p.age;
                const x = smokeFrom.x + p.dx + k * (1.4 * storm + gust * 1.5) + Math.sin(t * 0.8 + p.ph) * 0.06 * k;
                const y = smokeFrom.y + k * 0.9;
                const z = smokeFrom.z + p.dz + Math.sin(t * 0.6 + p.ph) * 0.08 * k;
                const g = 0.52 + 0.18 * k;
                smoke.set(i, x, y, z, 0.12 + k * 0.5, [g, g + 0.02, g + 0.06], Math.sin(Math.min(1, k * 4) * Math.PI / 2) * (1 - k) * 0.42 * (0.4 + 0.6 * light));
            });
            smoke.update();

            puffs.items.forEach((p, i) => {
                if (p.age >= 1) {
                    puffs.set(i, 0, -50, 0, 0, FLAKE, 0);
                    return;
                }
                p.age += real / p.life;
                p.vy -= dt * 1.4;
                p.x += p.vx * dt;
                p.y += p.vy * dt;
                p.z += p.vz * dt;
                puffs.set(i, p.x, p.y, p.z, p.s * (1 + p.age), FLAKE, (1 - p.age) * 0.75);
            });
            puffs.update();

            renderer.render(scene, camera);
            raf = requestAnimationFrame(frame);
        }
        raf = requestAnimationFrame(frame);

        return {
            dispose() {
                alive = false;
                cancelAnimationFrame(raf);
                ro.disconnect();
                canvas.removeEventListener('wheel', onWheel);
                scene.traverse((o) => {
                    if (o.geometry) o.geometry.dispose();
                    if (o.material) {
                        [].concat(o.material).forEach((m) => {
                            Object.values(m).forEach((v) => { if (v && v.isTexture) v.dispose(); });
                            m.dispose();
                        });
                    }
                });
                envMap.dispose();
                renderer.dispose();
                canvas.remove();
            },
        };

        // ---------------- Outils de la scène ----------------
        function instanced(geo, mat, list, tint, shadow) {
            const m = new THREE.InstancedMesh(geo, mat, Math.max(1, list.length));
            m.count = list.length;
            const rot = new THREE.Quaternion();
            const yAx = new THREE.Vector3(0, 1, 0);
            const xAx = new THREE.Vector3(1, 0, 0);
            list.forEach((p, i) => {
                rot.setFromAxisAngle(yAx, p.yaw || 0);
                if (p.tilt) rot.multiply(new THREE.Quaternion().setFromAxisAngle(xAx, p.tilt));
                m.setMatrixAt(i, new THREE.Matrix4().compose(new THREE.Vector3(p.x, p.y, p.z), rot, new THREE.Vector3(p.s, p.s, p.s)));
                if (tint) m.setColorAt(i, tint(p, i));
            });
            m.castShadow = !!shadow;
            m.receiveShadow = true;
            scene.add(m);
            return m;
        }

        function limb(a, b, r1, r2, mat) {
            const dir = new THREE.Vector3().subVectors(b, a);
            const len = dir.length();
            const m = new THREE.Mesh(new THREE.CylinderGeometry(r2, r1, len, 6), mat);
            m.position.copy(a).addScaledVector(dir, 0.5);
            m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
            return m;
        }

        function strip(pts, uv, cols, normal, mat, shadow) {
            const g = new THREE.BufferGeometry();
            g.setAttribute('position', new THREE.Float32BufferAttribute(pts, 3));
            const count = pts.length / 3;
            const nrm = [];
            for (let i = 0; i < count; i++) nrm.push(...normal);
            g.setAttribute('normal', new THREE.Float32BufferAttribute(nrm, 3));
            if (uv) g.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
            if (cols) g.setAttribute('color', new THREE.Float32BufferAttribute(cols, 3));
            const idx = [];
            for (let i = 0; i < count / 2 - 1; i++) {
                const a = i * 2;
                idx.push(a + 1, a + 3, a + 2, a + 1, a + 2, a);
            }
            g.setIndex(idx);
            const m = new THREE.Mesh(g, mat);
            m.receiveShadow = shadow;
            return m;
        }

        // Un sapin : un tronc, quatre étages de branches aux bords irréguliers,
        // et sur chaque étage une couche de neige qui retombe sur les côtés
        function firGeometry() {
            const r0 = mulberry32(5);
            const parts = [];
            const paint = (g, hex, jitter) => {
                const n = g.attributes.position.count;
                const c = new Float32Array(n * 3);
                const base = color(hex);
                for (let i = 0; i < n; i++) {
                    tmp.copy(base).multiplyScalar(1 - jitter + r0() * jitter * 2);
                    tmp.toArray(c, i * 3);
                }
                g.setAttribute('color', new THREE.BufferAttribute(c, 3));
                return g;
            };
            parts.push(paint(new THREE.CylinderGeometry(0.035, 0.055, 0.32, 6).translate(0, 0.16, 0).toNonIndexed(), 0x4a3020, 0.08));
            const TIERS = [[0.2, 0.46, 0.62], [0.52, 0.38, 0.55], [0.82, 0.29, 0.48], [1.08, 0.19, 0.42]];
            TIERS.forEach(([y, r, h], k) => {
                const cone = new THREE.ConeGeometry(r, h, 9, 1, true).toNonIndexed();
                const p = cone.attributes.position;
                // Les pointes des branches : le bas du cône en dents irrégulières
                for (let i = 0; i < p.count; i++) {
                    if (p.getY(i) < 0) {
                        const a = Math.atan2(p.getZ(i), p.getX(i));
                        const f = 1 + 0.12 * Math.sin(a * 9 + k * 2);
                        p.setX(i, p.getX(i) * f);
                        p.setZ(i, p.getZ(i) * f);
                        p.setY(i, p.getY(i) - 0.03 * (0.5 + 0.5 * Math.sin(a * 9 + k)));
                    }
                }
                cone.rotateY(k * 0.9);
                cone.translate(0, y + h / 2, 0);
                parts.push(paint(cone, [0x1f4a35, 0x23523a, 0x1b4330, 0x275a40][k], 0.12));
                // La neige : un cône plus plat qui couvre le haut de l'étage
                const sh = h * 0.6;
                const snow = new THREE.ConeGeometry(r * 0.82, sh, 9, 1, true).toNonIndexed();
                const s = snow.attributes.position;
                for (let i = 0; i < s.count; i++) {
                    if (s.getY(i) < 0) {
                        const a = Math.atan2(s.getZ(i), s.getX(i));
                        const f = 1 + 0.18 * Math.sin(a * 5 + k * 3);
                        s.setX(i, s.getX(i) * f);
                        s.setZ(i, s.getZ(i) * f);
                        s.setY(i, s.getY(i) - 0.05 * Math.max(0, Math.sin(a * 5 + k * 3)));
                    }
                }
                snow.rotateY(k * 0.9 + 0.2);
                snow.translate(0, y + h - sh / 2 + 0.012, 0);
                parts.push(paint(snow, 0xf2f6fc, 0.04));
            });
            // Un petit tas de neige au pied
            parts.push(paint(new THREE.SphereGeometry(0.3, 9, 4, 0, Math.PI * 2, 0, Math.PI / 2).scale(1, 0.22, 1).toNonIndexed(), 0xeef3fa, 0.03));
            let count = 0;
            parts.forEach((g) => { count += g.attributes.position.count; });
            const pos = new Float32Array(count * 3);
            const col = new Float32Array(count * 3);
            let o = 0;
            parts.forEach((g) => {
                pos.set(g.attributes.position.array, o * 3);
                col.set(g.attributes.color.array, o * 3);
                o += g.attributes.position.count;
                g.dispose();
            });
            const g = new THREE.BufferGeometry();
            g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
            g.setAttribute('color', new THREE.BufferAttribute(col, 3));
            g.computeVertexNormals();
            return g;
        }

        // Les planches verticales du pignon
        function boardTexture() {
            const cv = document.createElement('canvas');
            cv.width = cv.height = 256;
            const g = cv.getContext('2d');
            const rnd = mulberry32(17);
            for (let x = 0; x < 256; x += 32) {
                const b = 0.85 + rnd() * 0.25;
                g.fillStyle = `rgb(${Math.round(110 * b)},${Math.round(70 * b)},${Math.round(40 * b)})`;
                g.fillRect(x, 0, 32, 256);
                g.fillStyle = 'rgba(30,16,8,0.7)';
                g.fillRect(x, 0, 3, 256);
                for (let k = 0; k < 6; k++) {
                    g.strokeStyle = `rgba(60,34,18,${0.15 + rnd() * 0.2})`;
                    g.lineWidth = 1;
                    g.beginPath();
                    const xx = x + 6 + rnd() * 22;
                    g.moveTo(xx, 0);
                    g.bezierCurveTo(xx + rnd() * 6 - 3, 90, xx + rnd() * 6 - 3, 170, xx, 256);
                    g.stroke();
                }
            }
            const tex = new THREE.CanvasTexture(cv);
            tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
            tex.colorSpace = THREE.SRGBColorSpace;
            return tex;
        }

        // Les côtés du bloc : terre gelée, puis roche grise avec quelques cailloux
        function earthTexture() {
            const Wt = 1024;
            const Ht = 512;
            const cv = document.createElement('canvas');
            cv.width = Wt;
            cv.height = Ht;
            const g = cv.getContext('2d');
            const yPx = (y) => (1 - (y - BASE) / (1.4 - BASE)) * Ht;
            const STOPS = [[1.4, [88, 70, 58]], [0.4, [76, 60, 50]], [-0.3, [92, 88, 86]], [-1.0, [74, 72, 74]], [-1.7, [96, 92, 90]], [BASE, [58, 56, 58]]];
            for (let x = 0; x < Wt; x += 4) {
                const u = (x / Wt) * Math.PI * 2;
                const grad = g.createLinearGradient(0, 0, 0, Ht);
                STOPS.forEach(([y, c], k) => {
                    const off = k && k < STOPS.length - 1 ? Math.sin(u * 2 + k) * 8 + Math.sin(u * 5 + k * 2) * 3 : 0;
                    grad.addColorStop(clamp((yPx(y) + off) / Ht, 0, 1), `rgb(${c[0]},${c[1]},${c[2]})`);
                });
                g.fillStyle = grad;
                g.fillRect(x, 0, 4, Ht);
            }
            const rnd = mulberry32(13);
            // Des cailloux pris dans la roche
            for (let i = 0; i < 160; i++) {
                const x = rnd() * Wt;
                const y = yPx(rnd() * (0.2 - BASE) + BASE);
                const r = 3 + rnd() * 9;
                const c = 90 + rnd() * 50;
                g.fillStyle = `rgba(${c},${c - 4},${c - 6},0.8)`;
                g.beginPath();
                g.ellipse(x, y, r * 1.3, r, rnd() * 3, 0, Math.PI * 2);
                g.fill();
                g.fillStyle = 'rgba(255,255,255,0.12)';
                g.beginPath();
                g.ellipse(x - r * 0.3, y - r * 0.3, r * 0.5, r * 0.35, 0, 0, Math.PI * 2);
                g.fill();
            }
            // Des racines et du givre près du haut
            for (let k = 0; k < 18; k++) {
                let x = rnd() * Wt;
                let y = yPx(1.2);
                g.strokeStyle = `rgba(48,34,24,${0.4 + rnd() * 0.3})`;
                g.lineWidth = 1 + rnd() * 2;
                g.beginPath();
                g.moveTo(x, y);
                for (let s = 0; s < 6; s++) {
                    x += (rnd() - 0.5) * 20;
                    y += 8 + rnd() * 10;
                    g.lineTo(x, y);
                }
                g.stroke();
            }
            for (let i = 0; i < 1600; i++) {
                const x = rnd() * Wt;
                const y = rnd() * Ht;
                g.fillStyle = `rgba(${rnd() < 0.5 ? '220,230,245' : '30,26,24'},${0.05 + rnd() * 0.08})`;
                g.fillRect(x, y, 1.5 + rnd() * 1.5, 1 + rnd());
            }
            const tex = new THREE.CanvasTexture(cv);
            tex.wrapS = THREE.RepeatWrapping;
            tex.colorSpace = THREE.SRGBColorSpace;
            tex.anisotropy = 4;
            return tex;
        }

        function particles(count) {
            const pos = new Float32Array(count * 3);
            const col = new Float32Array(count * 3);
            const size = new Float32Array(count);
            const alpha = new Float32Array(count);
            const g = new THREE.BufferGeometry();
            g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
            g.setAttribute('aColor', new THREE.BufferAttribute(col, 3));
            g.setAttribute('aSize', new THREE.BufferAttribute(size, 1));
            g.setAttribute('aAlpha', new THREE.BufferAttribute(alpha, 1));
            const m = new THREE.ShaderMaterial({
                uniforms: { uScale: pointScale },
                vertexShader: `attribute vec3 aColor;
attribute float aSize;
attribute float aAlpha;
uniform float uScale;
varying vec3 vColor;
varying float vAlpha;
void main() {
    vec4 mv = modelViewMatrix * vec4(position, 1.0);
    gl_Position = projectionMatrix * mv;
    gl_PointSize = aSize * uScale / -mv.z;
    vColor = aColor;
    vAlpha = aAlpha;
}`,
                fragmentShader: `varying vec3 vColor;
varying float vAlpha;
void main() {
    float r = length(gl_PointCoord - 0.5);
    float a = smoothstep(0.5, 0.05, r) * vAlpha;
    if (a < 0.01) discard;
    gl_FragColor = vec4(vColor, a);
}`,
                transparent: true,
                depthWrite: false,
            });
            const pts = new THREE.Points(g, m);
            pts.frustumCulled = false;
            pts.renderOrder = 9;
            scene.add(pts);
            const items = Array.from({ length: count }, () => ({}));
            return {
                items,
                set(i, x, y, z, s, c, a) {
                    pos[i * 3] = x;
                    pos[i * 3 + 1] = y;
                    pos[i * 3 + 2] = z;
                    col[i * 3] = c[0];
                    col[i * 3 + 1] = c[1];
                    col[i * 3 + 2] = c[2];
                    size[i] = s;
                    alpha[i] = a;
                },
                update() {
                    g.attributes.position.needsUpdate = true;
                    g.attributes.aColor.needsUpdate = true;
                    g.attributes.aSize.needsUpdate = true;
                    g.attributes.aAlpha.needsUpdate = true;
                },
            };
        }

        function radialTexture(inner, outer) {
            const cv = document.createElement('canvas');
            cv.width = cv.height = 256;
            const g = cv.getContext('2d');
            const grad = g.createRadialGradient(128, 128, 10, 128, 128, 128);
            grad.addColorStop(0, inner);
            grad.addColorStop(1, outer);
            g.fillStyle = grad;
            g.fillRect(0, 0, 256, 256);
            const tex = new THREE.CanvasTexture(cv);
            tex.colorSpace = THREE.SRGBColorSpace;
            return tex;
        }
    }

    // ---------------------------------------------------------------------
    // Sixième diorama : la petite salle de classe, un soir de pluie. Dehors il
    // pleut doucement contre les vitres ; dedans, quatre élèves révisent sous
    // leur lampe de bureau, et la prof, ravie, se promène devant le tableau.
    // Les murs côté caméra s'effacent, comme dans une maison de poupée.
    // ---------------------------------------------------------------------
    function buildClassroom(THREE, stage) {
        const phone = Math.min(window.innerWidth, window.innerHeight) < 600 || touch();
        const S = 6;
        const HALF = S / 2;
        const BASE = -0.45;
        const WALL_H = 2.75;
        const WALL_T = 0.14;
        const rand = mulberry32(61);
        const rr = (a, b) => a + (b - a) * rand();
        const pick = (list) => list[Math.floor(rand() * list.length)];
        const color = (hex) => new THREE.Color(hex);
        const V = (x, y, z) => new THREE.Vector3(x, y, z);
        const flat = (hex, extra) => new THREE.MeshStandardMaterial(Object.assign({ color: hex, flatShading: true, roughness: 0.8 }, extra || {}));
        const smooth = (u) => u * u * (3 - 2 * u);
        const still = calm();
        const english = en();

        // --- Rendu ---
        const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, powerPreference: 'high-performance' });
        renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, phone ? 1.75 : 2));
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        renderer.setClearColor(0x000000, 0);
        renderer.domElement.className = 'diorama-canvas';
        stage.appendChild(renderer.domElement);
        const scene = new THREE.Scene();
        const camera = new THREE.PerspectiveCamera(30, 1, 0.1, 300);

        // --- Un soir de pluie : un jour gris et bleuté par les fenêtres, et les lampes qui réchauffent tout ---
        const hemi = new THREE.HemisphereLight(0xe8d2bc, 0x54443a, 0.62);
        scene.add(hemi);
        const sun = new THREE.DirectionalLight(0x9fb4d6, 0.7);
        sun.position.set(-11, 7.5, 3.2);
        sun.target.position.set(0, 0, 0);
        sun.castShadow = true;
        sun.shadow.mapSize.set(phone ? 1536 : 2048, phone ? 1536 : 2048);
        Object.assign(sun.shadow.camera, { left: -8, right: 8, top: 8, bottom: -8, near: 1, far: 30 });
        sun.shadow.bias = -0.0006;
        sun.shadow.normalBias = 0.02;
        scene.add(sun, sun.target);
        const fill = new THREE.DirectionalLight(0xffcf9a, 0.35);
        fill.position.set(6, 6, 7);
        scene.add(fill);

        // --- Le plancher ---
        const floorTex = plankTexture();
        floorTex.repeat.set(1.5, 1.5);
        const floor = new THREE.Mesh(new THREE.BoxGeometry(S, 0.1, S), [
            flat(0x8a5d3b), flat(0x8a5d3b),
            new THREE.MeshStandardMaterial({ map: floorTex, roughness: 0.7 }),
            flat(0x6e4a30), flat(0x8a5d3b), flat(0x8a5d3b),
        ]);
        floor.position.y = -0.05;
        floor.receiveShadow = true;
        scene.add(floor);
        // Le socle sous la pièce
        const slab = new THREE.Mesh(new THREE.BoxGeometry(S, -BASE - 0.1, S), flat(0xd8c3a5, { roughness: 1 }));
        slab.position.y = (BASE - 0.1) / 2;
        scene.add(slab);
        const trim = new THREE.Mesh(new THREE.BoxGeometry(S + 0.02, 0.06, S + 0.02), flat(0x6b4a33));
        trim.position.y = -0.11;
        scene.add(trim);
        const contact = new THREE.Mesh(new THREE.PlaneGeometry(S * 1.9, S * 1.9), new THREE.MeshBasicMaterial({ map: radialTexture('rgba(80,50,30,0.35)', 'rgba(80,50,30,0)'), transparent: true, depthWrite: false }));
        contact.rotation.x = -Math.PI / 2;
        contact.position.y = BASE - 0.02;
        scene.add(contact);
        // Un grand tapis au fond, pour le coin lecture
        const rug = new THREE.Mesh(new THREE.PlaneGeometry(2.1, 1.0), new THREE.MeshStandardMaterial({ map: rugTexture(), roughness: 1 }));
        rug.rotation.x = -Math.PI / 2;
        rug.position.set(-1.25, 0.006, 2.35);
        rug.receiveShadow = true;
        scene.add(rug);

        // --- Les murs : chacun s'efface quand la caméra passe de son côté ---
        const wallPaint = flat(0xf2e3c8, { roughness: 0.95 });
        const wainscot = flat(0x9fbf9c, { roughness: 0.9 });
        const woodTrim = flat(0x7a5236);
        const walls = [];
        // Un mur : le long de l'axe x (side 'z', à z = c) ou de l'axe z (side 'x', à x = c), avec des trous (fenêtres, porte)
        function makeWall(side, c, inward, holes) {
            const g = new THREE.Group();
            scene.add(g);
            const solid = [];
            const deco = [];
            const box = (u0, u1, y0, y1, mat, depth = WALL_T, off = 0) => {
                if (u1 - u0 < 0.001 || y1 - y0 < 0.001) return null;
                const geo = side === 'z' ? new THREE.BoxGeometry(u1 - u0, y1 - y0, depth) : new THREE.BoxGeometry(depth, y1 - y0, u1 - u0);
                const m = new THREE.Mesh(geo, mat);
                const u = (u0 + u1) / 2;
                const cc = c + inward * off;
                if (side === 'z') m.position.set(u, (y0 + y1) / 2, cc); else m.position.set(cc, (y0 + y1) / 2, u);
                m.castShadow = true;
                m.receiveShadow = true;
                g.add(m);
                return m;
            };
            // Le mur découpé autour des trous
            const sorted = holes.slice().sort((a, b) => a.u0 - b.u0);
            const yLow = sorted.length ? Math.min(...sorted.map((h) => h.y0)) : WALL_H;
            const yHigh = sorted.length ? Math.max(...sorted.map((h) => h.y1)) : WALL_H;
            solid.push(box(-HALF, HALF, 0, yLow, wallPaint), box(-HALF, HALF, yHigh, WALL_H, wallPaint));
            let u = -HALF;
            sorted.forEach((h) => {
                solid.push(box(u, h.u0, yLow, yHigh, wallPaint));
                solid.push(box(h.u0, h.u1, yLow, h.y0, wallPaint), box(h.u0, h.u1, h.y1, yHigh, wallPaint));
                u = h.u1;
            });
            solid.push(box(u, HALF, yLow, yHigh, wallPaint));
            // Le soubassement vert et sa moulure, côté intérieur
            let w = -HALF;
            const wainTop = 0.9;
            sorted.filter((h) => h.y0 < wainTop).forEach((h) => {
                deco.push(box(w, h.u0, 0, wainTop, wainscot, 0.02, WALL_T / 2 + 0.01));
                deco.push(box(w, h.u0, wainTop - 0.02, wainTop + 0.04, woodTrim, 0.04, WALL_T / 2 + 0.02));
                w = h.u1;
            });
            deco.push(box(w, HALF, 0, wainTop, wainscot, 0.02, WALL_T / 2 + 0.01));
            deco.push(box(w, HALF, wainTop - 0.02, wainTop + 0.04, woodTrim, 0.04, WALL_T / 2 + 0.02));
            // Le bandeau en haut du mur
            solid.push(box(-HALF, HALF, WALL_H - 0.03, WALL_H + 0.03, woodTrim, WALL_T + 0.04));
            const wall = { g, solid: solid.filter(Boolean), deco: deco.filter(Boolean), side, c, inward, shown: true };
            walls.push(wall);
            return wall;
        }
        // Place un objet contre l'intérieur d'un mur (u le long du mur, y en hauteur, d vers l'intérieur)
        const onWall = (wall, obj, u, y, d = 0) => {
            const off = WALL_T / 2 + d;
            if (wall.side === 'z') {
                obj.position.set(u, y, wall.c + wall.inward * off);
                obj.rotation.y = wall.inward > 0 ? 0 : Math.PI;
            } else {
                obj.position.set(wall.c + wall.inward * off, y, u);
                obj.rotation.y = wall.inward > 0 ? Math.PI / 2 : -Math.PI / 2;
            }
            wall.g.add(obj);
            wall.deco.push(obj);
            obj.traverse((m) => { if (m.isMesh) { m.castShadow = true; m.receiveShadow = true; } });
            return obj;
        };

        const WIN = [-1.3, 1.3].map((u) => ({ u0: u - 0.75, u1: u + 0.75, y0: 0.95, y1: 2.25 }));
        const front = makeWall('z', -HALF + WALL_T / 2, 1, []);
        const left = makeWall('x', -HALF + WALL_T / 2, 1, WIN);
        const back = makeWall('z', HALF - WALL_T / 2, -1, []);
        const DOOR = { u0: 1.75, u1: 2.75, y0: 0, y1: 2.05 };
        const right = makeWall('x', HALF - WALL_T / 2, -1, [DOOR]);

        // --- Le tableau noir, et ce qui est écrit dessus ---
        const BOARD_W = 3.0;
        const BOARD_H = 3.0 * 435 / 1380;
        const boardCanvas = document.createElement('canvas');
        boardCanvas.width = 1380;
        boardCanvas.height = 435;
        const boardTex = new THREE.CanvasTexture(boardCanvas);
        boardTex.colorSpace = THREE.SRGBColorSpace;
        boardTex.anisotropy = 8;
        const MESSAGES = english ? [
            { title: 'Revision day!', lines: ['Take your time, you\'ve got this', 'Chapter 5: summary + exercises'], doodle: 'sun' },
            { title: 'Exam on Friday', lines: ['SELECT * FROM students', 'WHERE motivated = TRUE;'], doodle: 'heart' },
            { title: 'Today\'s formulas', lines: ['E = mc²     a² + b² = c²', 'σ = √( Σ(x − μ)² / n )'], doodle: 'star' },
            { title: 'Proud of you all!', lines: ['Small steps every day', 'Questions? Raise your hand :)'], doodle: 'heart' },
        ] : [
            { title: 'Jour de révisions !', lines: ['Prenez votre temps, vous allez y arriver', 'Chapitre 5 : fiche + exercices'], doodle: 'sun' },
            { title: 'Contrôle vendredi', lines: ['SELECT * FROM eleves', 'WHERE motive = TRUE;'], doodle: 'heart' },
            { title: 'Les formules du jour', lines: ['E = mc²     a² + b² = c²', 'σ = √( Σ(x − μ)² / n )'], doodle: 'star' },
            { title: 'Fière de vous !', lines: ['Un petit pas chaque jour', 'Une question ? Levez la main :)'], doodle: 'heart' },
        ];
        let boardMsg = 0;
        // Le texte s'écrit petit à petit, comme à la craie
        let boardWrite = 1;
        function drawBoard(k = 1) {
            const g = boardCanvas.getContext('2d');
            const Wc = boardCanvas.width;
            const Hc = boardCanvas.height;
            const grad = g.createLinearGradient(0, 0, Wc, Hc);
            grad.addColorStop(0, '#2c4a3b');
            grad.addColorStop(1, '#25402f');
            g.fillStyle = grad;
            g.fillRect(0, 0, Wc, Hc);
            // Les traces d'anciennes craies effacées
            const rnd = mulberry32(3 + boardMsg);
            for (let i = 0; i < 26; i++) {
                g.fillStyle = `rgba(230,240,230,${0.025 + rnd() * 0.03})`;
                g.beginPath();
                g.ellipse(rnd() * Wc, rnd() * Hc, 60 + rnd() * 160, 14 + rnd() * 30, rnd() * 0.4 - 0.2, 0, Math.PI * 2);
                g.fill();
            }
            const m = MESSAGES[boardMsg];
            const all = [m.title, ...m.lines];
            const total = all.reduce((a, s) => a + s.length, 0);
            let budget = Math.floor(total * k);
            g.textBaseline = 'middle';
            g.shadowColor = 'rgba(255,255,255,0.35)';
            g.shadowBlur = 3;
            all.forEach((s, i) => {
                const shown = s.slice(0, Math.max(0, budget));
                budget -= s.length;
                if (!shown) return;
                g.fillStyle = i === 0 ? 'rgba(255,240,170,0.95)' : 'rgba(244,246,240,0.9)';
                g.font = i === 0 ? '700 84px "Segoe Print", "Comic Sans MS", "Chalkboard SE", cursive' : '500 54px "Segoe Print", "Comic Sans MS", "Chalkboard SE", cursive';
                g.textAlign = 'left';
                g.fillText(shown, 70, i === 0 ? 92 : 210 + (i - 1) * 92);
                if (i === 0 && shown.length === s.length) {
                    // On souligne le titre
                    const tw = g.measureText(s).width;
                    g.strokeStyle = 'rgba(255,240,170,0.7)';
                    g.lineWidth = 5;
                    g.beginPath();
                    g.moveTo(70, 142);
                    g.quadraticCurveTo(70 + tw / 2, 152, 70 + tw, 138);
                    g.stroke();
                }
            });
            g.shadowBlur = 0;
            if (k >= 1) {
                const cx = Wc - 170;
                const cy = Hc / 2 - 10;
                g.strokeStyle = 'rgba(255,190,200,0.85)';
                g.fillStyle = 'rgba(255,190,200,0.18)';
                g.lineWidth = 6;
                g.beginPath();
                if (m.doodle === 'heart') {
                    g.moveTo(cx, cy + 70);
                    g.bezierCurveTo(cx - 120, cy - 10, cx - 60, cy - 100, cx, cy - 40);
                    g.bezierCurveTo(cx + 60, cy - 100, cx + 120, cy - 10, cx, cy + 70);
                } else if (m.doodle === 'sun') {
                    g.strokeStyle = 'rgba(255,225,140,0.9)';
                    g.fillStyle = 'rgba(255,225,140,0.15)';
                    g.arc(cx, cy, 52, 0, Math.PI * 2);
                    for (let r = 0; r < 10; r++) {
                        const a = (r / 10) * Math.PI * 2;
                        g.moveTo(cx + Math.cos(a) * 70, cy + Math.sin(a) * 70);
                        g.lineTo(cx + Math.cos(a) * 100, cy + Math.sin(a) * 100);
                    }
                    g.moveTo(cx - 22, cy - 12);
                    g.arc(cx - 22, cy - 12, 3, 0, Math.PI * 2);
                    g.moveTo(cx + 25, cy - 12);
                    g.arc(cx + 22, cy - 12, 3, 0, Math.PI * 2);
                    g.moveTo(cx - 26, cy + 14);
                    g.quadraticCurveTo(cx, cy + 38, cx + 26, cy + 14);
                } else {
                    g.strokeStyle = 'rgba(200,225,255,0.9)';
                    g.fillStyle = 'rgba(200,225,255,0.15)';
                    for (let p = 0; p < 10; p++) {
                        const a = -Math.PI / 2 + (p / 10) * Math.PI * 2;
                        const r = p % 2 ? 40 : 95;
                        if (p) g.lineTo(cx + Math.cos(a) * r, cy + Math.sin(a) * r); else g.moveTo(cx + Math.cos(a) * r, cy + Math.sin(a) * r);
                    }
                    g.closePath();
                }
                g.fill();
                g.stroke();
            }
            // Un peu de poussière de craie en bas
            g.fillStyle = 'rgba(240,240,235,0.08)';
            g.fillRect(0, Hc - 26, Wc, 26);
            boardTex.needsUpdate = true;
        }
        drawBoard(1);
        const boardGroup = new THREE.Group();
        const boardFrame = new THREE.Mesh(new THREE.BoxGeometry(BOARD_W + 0.16, BOARD_H + 0.16, 0.06), flat(0x6b4529));
        boardGroup.add(boardFrame);
        const boardFace = new THREE.Mesh(new THREE.PlaneGeometry(BOARD_W, BOARD_H), new THREE.MeshStandardMaterial({ map: boardTex, roughness: 0.92 }));
        boardFace.position.z = 0.032;
        boardGroup.add(boardFace);
        // La rigole à craies, avec des craies et la brosse
        const ledge = new THREE.Mesh(new THREE.BoxGeometry(BOARD_W, 0.04, 0.12), flat(0x6b4529));
        ledge.position.set(0, -BOARD_H / 2 - 0.06, 0.06);
        boardGroup.add(ledge);
        [[0xffffff, -1.0], [0xffe9a0, -0.86], [0xffb8c8, -0.72], [0xb8e0ff, 1.15]].forEach(([c, x]) => {
            const ch = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.012, 0.09, 6).rotateZ(Math.PI / 2), flat(c));
            ch.position.set(x, -BOARD_H / 2 - 0.028, 0.07);
            boardGroup.add(ch);
        });
        const eraser = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.05, 0.08), flat(0x3d3d48));
        eraser.position.set(0.6, -BOARD_H / 2 - 0.015, 0.07);
        boardGroup.add(eraser);
        const eraserTop = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.02, 0.08), flat(0xc89058));
        eraserTop.position.set(0.6, -BOARD_H / 2 + 0.02, 0.07);
        boardGroup.add(eraserTop);
        onWall(front, boardGroup, -0.35, 1.6, 0.03);
        const boardMeshes = [boardFrame, boardFace];

        // L'horloge au-dessus de la porte du couloir... non : à droite du tableau, à l'heure du vrai monde
        const wallClock = new THREE.Group();
        const face = new THREE.Mesh(new THREE.CylinderGeometry(0.26, 0.26, 0.03, 32).rotateX(Math.PI / 2), new THREE.MeshStandardMaterial({ map: clockTexture(), roughness: 0.5 }));
        face.rotation.z = Math.PI;
        wallClock.add(face);
        const rimC = new THREE.Mesh(new THREE.TorusGeometry(0.27, 0.03, 8, 32), flat(0xc0392b));
        wallClock.add(rimC);
        const handH = new THREE.Group();
        handH.add(new THREE.Mesh(new THREE.BoxGeometry(0.025, 0.14, 0.01).translate(0, 0.06, 0), flat(0x222228)));
        handH.position.z = 0.025;
        const handM = new THREE.Group();
        handM.add(new THREE.Mesh(new THREE.BoxGeometry(0.016, 0.21, 0.01).translate(0, 0.09, 0), flat(0x222228)));
        handM.position.z = 0.032;
        const handS = new THREE.Group();
        handS.add(new THREE.Mesh(new THREE.BoxGeometry(0.006, 0.22, 0.006).translate(0, 0.08, 0), flat(0xc0392b)));
        handS.position.z = 0.038;
        wallClock.add(handH, handM, handS);
        onWall(front, wallClock, 2.05, 2.1, 0.02);

        // Les fenêtres : cadres, croisillons, vitres, rebords avec des plantes
        const glassMat = new THREE.MeshStandardMaterial({ color: 0x8ea4c4, emissive: 0x3c4c66, emissiveIntensity: 0.6, transparent: true, opacity: 0.32, roughness: 0.05, metalness: 0.1, depthWrite: false });
        const frameMat = flat(0xf7f3ea, { roughness: 0.6 });
        WIN.forEach((h, wi) => {
            const wg = new THREE.Group();
            const ww = h.u1 - h.u0;
            const wh = h.y1 - h.y0;
            [[ww + 0.1, 0.07, 0, wh / 2], [ww + 0.1, 0.07, 0, -wh / 2], [0.07, wh, -ww / 2, 0], [0.07, wh, ww / 2, 0], [0.05, wh, 0, 0], [ww, 0.05, 0, wh * 0.12]].forEach(([a, b, x, y]) => {
                const f = new THREE.Mesh(new THREE.BoxGeometry(a, b, WALL_T + 0.04), frameMat);
                f.position.set(x, y, -WALL_T / 2);
                wg.add(f);
            });
            const glass = new THREE.Mesh(new THREE.PlaneGeometry(ww, wh), glassMat);
            glass.position.z = -WALL_T / 2;
            glass.castShadow = false;
            wg.add(glass);
            const sill = new THREE.Mesh(new THREE.BoxGeometry(ww + 0.2, 0.05, 0.24), frameMat);
            sill.position.set(0, -wh / 2 - 0.02, 0.06);
            wg.add(sill);
            // Des pots de plantes sur le rebord
            const potCol = [0xc4673f, 0x6f8fb0][wi];
            [-0.45, 0.35].forEach((px, k) => {
                if (wi === 1 && k === 1) return;
                const pot = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.06, 0.13, 8), flat(potCol));
                pot.position.set(px, -wh / 2 + 0.07, 0.08);
                wg.add(pot);
                const leaves = new THREE.Mesh(new THREE.IcosahedronGeometry(0.11 + k * 0.03, 0), flat(k ? 0x5f9a4c : 0x4b8a45));
                leaves.position.set(px, -wh / 2 + 0.2 + k * 0.03, 0.08);
                leaves.scale.set(1, 1.2, 1);
                wg.add(leaves);
                if (!k) {
                    // Une petite fleur
                    const fl = new THREE.Mesh(new THREE.SphereGeometry(0.03, 6, 4), flat([0xff7aa2, 0xffd54f][wi]));
                    fl.position.set(px + 0.03, -wh / 2 + 0.33, 0.1);
                    wg.add(fl);
                }
            });
            onWall(left, wg, (h.u0 + h.u1) / 2, (h.y0 + h.y1) / 2, 0);
            glass.castShadow = false;
        });

        // La porte du couloir, entrouverte
        const doorG = new THREE.Group();
        const dW = DOOR.u1 - DOOR.u0;
        const doorFrame = [[dW + 0.14, 0.08, 0, DOOR.y1 + 0.04], [0.08, DOOR.y1, -dW / 2 - 0.03, DOOR.y1 / 2], [0.08, DOOR.y1, dW / 2 + 0.03, DOOR.y1 / 2]];
        doorFrame.forEach(([a, b, x, y]) => {
            const f = new THREE.Mesh(new THREE.BoxGeometry(a, b, WALL_T + 0.06), woodTrim);
            f.position.set(x, y, -WALL_T / 2);
            doorG.add(f);
        });
        const leaf = new THREE.Group();
        leaf.position.set(-dW / 2, 0, 0);
        leaf.rotation.y = 0.55;
        const panel = new THREE.Mesh(new THREE.BoxGeometry(dW - 0.04, DOOR.y1 - 0.03, 0.05), flat(0xd28b4f));
        panel.position.set(dW / 2, (DOOR.y1 - 0.03) / 2, 0);
        leaf.add(panel);
        const doorPane = new THREE.Mesh(new THREE.PlaneGeometry(0.4, 0.55), new THREE.MeshStandardMaterial({ color: 0xdff0ff, emissive: 0x9ab8cc, emissiveIntensity: 0.4 }));
        doorPane.position.set(dW / 2, 1.45, 0.027);
        leaf.add(doorPane);
        const handle = new THREE.Mesh(new THREE.SphereGeometry(0.035, 8, 6), flat(0xd8b35a, { metalness: 0.6, roughness: 0.35 }));
        handle.position.set(dW - 0.12, 1.0, 0.05);
        leaf.add(handle);
        doorG.add(leaf);
        // Le couloir, un peu plus lumineux derrière la porte
        const hall = new THREE.Mesh(new THREE.PlaneGeometry(dW, DOOR.y1), new THREE.MeshBasicMaterial({ color: 0xf4ead8 }));
        hall.position.set(0, DOOR.y1 / 2, -WALL_T - 0.02);
        doorG.add(hall);
        onWall(right, doorG, (DOOR.u0 + DOOR.u1) / 2, 0, 0);

        // Les affiches et les dessins des élèves
        const POSTERS = english ? [
            { wall: right, u: 0.3, y: 2.15, w: 1.1, h: 0.55, kind: 'sign', text: ['Quiet please,', 'we are revising'] },
            { wall: back, u: -1.5, y: 1.75, w: 1.5, h: 0.85, kind: 'map' },
            { wall: back, u: 0.2, y: 1.9, w: 1.05, h: 0.58, kind: 'drawings' },
        ] : [
            { wall: right, u: 0.3, y: 2.15, w: 1.1, h: 0.55, kind: 'sign', text: ['Chut,', 'on révise'] },
            { wall: back, u: -1.5, y: 1.75, w: 1.5, h: 0.85, kind: 'map' },
            { wall: back, u: 0.2, y: 1.9, w: 1.05, h: 0.58, kind: 'drawings' },
        ];
        POSTERS.forEach((p) => {
            const tex = posterTexture(p);
            const m = new THREE.Mesh(new THREE.PlaneGeometry(p.w, p.h), new THREE.MeshStandardMaterial({ map: tex, roughness: 0.9 }));
            onWall(p.wall, m, p.u, p.y, 0.012);
        });

        // Les portemanteaux avec les sacs à dos, près de la porte
        const hooks = new THREE.Group();
        const rail = new THREE.Mesh(new THREE.BoxGeometry(2.0, 0.1, 0.04), woodTrim);
        hooks.add(rail);
        [0xe74c3c, 0x3498db, 0xf1c40f, 0x2ecc71, 0x9b59b6].forEach((c, i) => {
            const x = -0.8 + i * 0.4;
            const hook = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.012, 0.1, 5).rotateX(Math.PI / 2), flat(0xbfbfc6, { metalness: 0.5 }));
            hook.position.set(x, 0, 0.05);
            hooks.add(hook);
            if (i === 3) return;
            const bag = new THREE.Mesh(new THREE.BoxGeometry(0.28, 0.36, 0.14), flat(c));
            bag.position.set(x, -0.2, 0.1);
            bag.rotation.z = rr(-0.08, 0.08);
            hooks.add(bag);
            const pocket = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.14, 0.05), flat(new THREE.Color(c).multiplyScalar(0.8).getHex()));
            pocket.position.set(x, -0.28, 0.18);
            hooks.add(pocket);
        });
        onWall(right, hooks, 0.3, 1.45, 0.02);

        // La bibliothèque du fond, pleine de livres de toutes les couleurs
        const shelf = new THREE.Group();
        const shelfWood = flat(0xa8734a);
        const SH_W = 1.7;
        [[SH_W, 0.05, 0, 0], [SH_W, 0.05, 0, 0.45], [SH_W, 0.05, 0, 0.9], [SH_W, 0.05, 0, 1.3], [0.05, 1.3, -SH_W / 2, 0.65], [0.05, 1.3, SH_W / 2, 0.65], [0.05, 1.3, 0, 0.65]].forEach(([a, b, x, y]) => {
            const p = new THREE.Mesh(new THREE.BoxGeometry(a, b, 0.36), shelfWood);
            p.position.set(x, y, 0.18);
            shelf.add(p);
        });
        const BOOKS = [0xc0392b, 0x2980b9, 0x27ae60, 0xf39c12, 0x8e44ad, 0x16a085, 0xd35400, 0x2c3e50, 0xe84393, 0xfdcb6e];
        [0.03, 0.48, 0.93].forEach((y) => {
            [-1, 1].forEach((half) => {
                let x = half < 0 ? -SH_W / 2 + 0.06 : 0.06;
                const end = half < 0 ? -0.06 : SH_W / 2 - 0.06;
                while (x < end - 0.05) {
                    const bw = rr(0.05, 0.09);
                    const bh = rr(0.26, 0.38);
                    if (rand() < 0.08) {
                        x += 0.12;
                        continue;
                    }
                    const b = new THREE.Mesh(new THREE.BoxGeometry(bw, bh, rr(0.22, 0.28)), flat(pick(BOOKS)));
                    b.position.set(x + bw / 2, y + bh / 2, 0.17);
                    if (rand() < 0.1) b.rotation.z = 0.25;
                    shelf.add(b);
                    x += bw + 0.008;
                }
            });
        });
        // Un globe et une petite plante sur le dessus
        const plant = new THREE.Mesh(new THREE.IcosahedronGeometry(0.16, 0), flat(0x4f8f4a));
        plant.position.set(-0.6, 1.52, 0.18);
        shelf.add(plant);
        const plantPot = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.08, 0.16, 8), flat(0xe8d6b8));
        plantPot.position.set(-0.6, 1.4, 0.18);
        shelf.add(plantPot);
        onWall(back, shelf, 1.95, 0, 0);

        // Des coussins sur le tapis du coin lecture
        [[-1.85, 0xf6b26b], [-1.25, 0x8fc1e3], [-0.65, 0xe39fc1]].forEach(([x, c]) => {
            const cu = new THREE.Mesh(new THREE.CylinderGeometry(0.22, 0.24, 0.1, 10), flat(c, { roughness: 1 }));
            cu.position.set(x, 0.05, 2.38);
            cu.castShadow = true;
            cu.receiveShadow = true;
            scene.add(cu);
        });
        // La poubelle et la corbeille à papier près du bureau
        const bin = new THREE.Mesh(new THREE.CylinderGeometry(0.15, 0.12, 0.34, 10, 1, true), flat(0x4a90a4, { side: THREE.DoubleSide }));
        bin.position.set(2.7, 0.17, -1.6);
        bin.castShadow = true;
        scene.add(bin);

        // --- Les personnages ---
        const SKIN = [0xf3cfb1, 0xe7b48f, 0xc98c62, 0x8d5a3b, 0xf6dcc6, 0xd9a07a];
        const HAIR = [0x231a14, 0x4b2f1c, 0x6e4526, 0xd6b062, 0xa1452a, 0x2e2018];
        const SHIRT = [0xe57373, 0x64b5f6, 0x81c784, 0xffd54f, 0xba68c8, 0x4db6ac, 0xff8a65, 0x7986cb, 0xf06292, 0xaed581, 0x90a4ae, 0xffb74d];
        const PANTS = [0x34495e, 0x3d5a80, 0x5d4037, 0x2c3e50, 0x546e7a];
        const pickable = [];
        const coal = flat(0x24201e);
        const cheekMat = new THREE.MeshBasicMaterial({ color: 0xff8a8a, transparent: true, opacity: 0.45, depthWrite: false });
        // Un membre (cylindre d'un point à l'autre)
        function limb(a, b, r1, r2, mat) {
            const dir = new THREE.Vector3().subVectors(b, a);
            const len = dir.length();
            const m = new THREE.Mesh(new THREE.CylinderGeometry(r2, r1, len, 7), mat);
            m.position.copy(a).addScaledVector(dir, 0.5);
            m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
            return m;
        }
        // Une tête souriante : yeux ronds (ou fermés de bonheur), sourire, joues roses, cheveux
        function makeHead(r, skin, hair, opts) {
            const head = new THREE.Group();
            const skinMat = flat(skin, { roughness: 0.7 });
            head.add(new THREE.Mesh(new THREE.IcosahedronGeometry(r, 2), skinMat));
            const hairMat = flat(hair, { roughness: 0.9 });
            const cap = new THREE.Mesh(new THREE.SphereGeometry(r * 1.07, 14, 10, 0, Math.PI * 2, 0, Math.PI * 0.52), hairMat);
            cap.rotation.x = -0.42;
            cap.position.set(0, r * 0.06, -r * 0.05);
            head.add(cap);
            if (opts.long) {
                const back = new THREE.Mesh(new THREE.CapsuleGeometry(r * 0.78, r * 1.0, 3, 10), hairMat);
                back.position.set(0, -r * 0.55, -r * 0.48);
                back.scale.set(1.1, 1, 0.55);
                head.add(back);
            }
            if (opts.pony) {
                const pony = new THREE.Mesh(new THREE.CapsuleGeometry(r * 0.25, r * 0.9, 3, 8), hairMat);
                pony.position.set(0, -r * 0.1, -r * 1.1);
                pony.rotation.x = 0.5;
                head.add(pony);
                const tie = new THREE.Mesh(new THREE.TorusGeometry(r * 0.22, r * 0.06, 5, 10), flat(0xff6f91));
                tie.position.set(0, r * 0.3, -r * 0.95);
                tie.rotation.x = 1.2;
                head.add(tie);
            }
            if (opts.bun) {
                const bun = new THREE.Mesh(new THREE.IcosahedronGeometry(r * 0.45, 1), hairMat);
                bun.position.set(0, r * 0.75, -r * 0.65);
                head.add(bun);
            }
            const fz = r * 0.93;
            if (opts.happy) {
                // Les yeux plissés de bonheur : ^ ^
                [-1, 1].forEach((e) => {
                    const eye = new THREE.Mesh(new THREE.TorusGeometry(r * 0.13, r * 0.03, 4, 10, Math.PI), coal);
                    eye.position.set(e * r * 0.36, r * 0.12, fz + r * 0.02);
                    head.add(eye);
                });
            } else {
                [-1, 1].forEach((e) => {
                    const eye = new THREE.Mesh(new THREE.SphereGeometry(r * 0.1, 6, 5), coal);
                    eye.position.set(e * r * 0.34, r * 0.1, fz);
                    eye.scale.set(1, 1.25, 0.6);
                    head.add(eye);
                });
            }
            const smile = new THREE.Mesh(new THREE.TorusGeometry(r * (opts.happy ? 0.28 : 0.2), r * 0.035, 4, 12, Math.PI), flat(opts.happy ? 0x9b2c2c : 0x5a2a20));
            smile.rotation.z = Math.PI;
            smile.position.set(0, -r * 0.2, fz);
            head.add(smile);
            [-1, 1].forEach((e) => {
                const ch = new THREE.Mesh(new THREE.CircleGeometry(r * 0.16, 10), cheekMat);
                ch.position.set(e * r * 0.55, -r * 0.12, r * 0.84);
                ch.rotation.y = e * 0.55;
                head.add(ch);
            });
            const nose = new THREE.Mesh(new THREE.SphereGeometry(r * 0.1, 6, 4), skinMat);
            nose.position.set(0, -r * 0.03, fz + r * 0.04);
            head.add(nose);
            if (opts.glasses) {
                const gm = flat(0x6b3f26, { metalness: 0.3 });
                [-1, 1].forEach((e) => {
                    const ring = new THREE.Mesh(new THREE.TorusGeometry(r * 0.2, r * 0.03, 5, 14), gm);
                    ring.position.set(e * r * 0.36, r * 0.1, fz + r * 0.06);
                    head.add(ring);
                });
                const bridge = new THREE.Mesh(new THREE.BoxGeometry(r * 0.3, r * 0.03, r * 0.03), gm);
                bridge.position.set(0, r * 0.12, fz + r * 0.07);
                head.add(bridge);
            }
            head.traverse((m) => { if (m.isMesh && m.material !== cheekMat) m.castShadow = true; });
            return head;
        }

        const lamps = [];
        const bulbMat = new THREE.MeshStandardMaterial({ color: 0x3a2a14, emissive: 0xffc070, emissiveIntensity: 2.2 });
        function deskLamp(parent, x, y, z, yaw) {
            const lg = new THREE.Group();
            lg.position.set(x, y, z);
            lg.rotation.y = yaw;
            parent.add(lg);
            const shadeCol = [0x2e7d6b, 0xc0392b, 0x2c5f8a, 0xd4a017, 0x6b4a8a][lamps.length % 5];
            const base = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.06, 0.02, 10), flat(0x2b2b30));
            lg.add(base);
            const arm = new THREE.Mesh(new THREE.CylinderGeometry(0.007, 0.007, 0.26, 5), flat(0x3a3a40, { metalness: 0.4 }));
            arm.position.set(0, 0.13, 0);
            arm.rotation.z = 0.15;
            lg.add(arm);
            const shade = new THREE.Mesh(new THREE.ConeGeometry(0.065, 0.08, 10, 1, true), flat(shadeCol, { side: THREE.DoubleSide }));
            shade.position.set(-0.04, 0.25, 0.03);
            shade.rotation.set(0.35, 0, 0.25);
            lg.add(shade);
            const bulb = new THREE.Mesh(new THREE.SphereGeometry(0.025, 8, 6), bulbMat);
            bulb.position.set(-0.04, 0.225, 0.04);
            lg.add(bulb);
            const pl = new THREE.PointLight(0xffb866, 1.7, 2.4, 1.4);
            pl.position.set(-0.04, 0.18, 0.06);
            lg.add(pl);
            lamps.push({ pl, ph: rr(0, 6.28) });
            return lg;
        }

        // Un élève assis à son pupitre, tourné vers +z (on tourne le tout vers le tableau ensuite)
        function makeStudent(i, x, z) {
            const st = new THREE.Group();
            st.position.set(x, 0, z);
            st.rotation.y = Math.PI;
            scene.add(st);
            const skin = pick(SKIN);
            const hairC = pick(HAIR);
            const shirtC = SHIRT[i % SHIRT.length];
            const shirt = flat(shirtC, { roughness: 0.85 });
            const pants = flat(pick(PANTS));
            const skinMat = flat(skin, { roughness: 0.7 });
            const style = i % 4;
            // La chaise
            const chairMat = flat([0xe67e22, 0x3498db, 0x2ecc71, 0xe74c3c][i % 4], { roughness: 0.6 });
            const metal = flat(0x8a8f99, { metalness: 0.4, roughness: 0.5 });
            const seat = new THREE.Mesh(new THREE.BoxGeometry(0.38, 0.04, 0.36), chairMat);
            seat.position.set(0, 0.4, -0.03);
            st.add(seat);
            const backrest = new THREE.Mesh(new THREE.BoxGeometry(0.38, 0.22, 0.03), chairMat);
            backrest.position.set(0, 0.68, -0.22);
            backrest.rotation.x = -0.08;
            st.add(backrest);
            [[-0.16, -0.18], [0.16, -0.18], [-0.16, 0.12], [0.16, 0.12]].forEach(([lx, lz]) => {
                const leg = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.012, 0.4, 5), metal);
                leg.position.set(lx, 0.2, lz);
                st.add(leg);
            });
            [-0.16, 0.16].forEach((lx) => {
                const post = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.012, 0.3, 5), metal);
                post.position.set(lx, 0.55, -0.2);
                st.add(post);
            });
            // Le pupitre
            const deskWood = flat(0xd9b07a, { roughness: 0.7 });
            const top = new THREE.Mesh(new THREE.BoxGeometry(0.74, 0.035, 0.46), deskWood);
            top.position.set(0, 0.62, 0.44);
            st.add(top);
            const cubby = new THREE.Mesh(new THREE.BoxGeometry(0.66, 0.12, 0.38), metal);
            cubby.position.set(0, 0.54, 0.46);
            st.add(cubby);
            [[-0.33, 0.25], [0.33, 0.25], [-0.33, 0.64], [0.33, 0.64]].forEach(([lx, lz]) => {
                const leg = new THREE.Mesh(new THREE.CylinderGeometry(0.014, 0.014, 0.6, 5), metal);
                leg.position.set(lx, 0.3, lz);
                st.add(leg);
            });
            // La lampe de bureau : un pied, un bras, un abat-jour, et une lumière chaude
            deskLamp(st, 0.27, 0.64, 0.6, -0.5);
            // Le livre ouvert, avec une page qui peut se tourner
            const bookCol = pick(BOOKS);
            const cover = new THREE.Mesh(new THREE.BoxGeometry(0.36, 0.012, 0.25), flat(bookCol));
            cover.position.set(-0.06, 0.643, 0.42);
            st.add(cover);
            const pageMat = flat(0xfbf6ea, { roughness: 0.9 });
            const linesTex = pageTexture();
            const pageFace = new THREE.MeshStandardMaterial({ map: linesTex, roughness: 0.9 });
            [-1, 1].forEach((e) => {
                const pg = new THREE.Mesh(new THREE.BoxGeometry(0.165, 0.016, 0.23), [pageMat, pageMat, pageFace, pageMat, pageMat, pageMat]);
                pg.position.set(-0.06 + e * 0.085, 0.655, 0.42);
                pg.rotation.z = -e * 0.07;
                st.add(pg);
            });
            const pagePivot = new THREE.Group();
            pagePivot.position.set(-0.06, 0.664, 0.42);
            st.add(pagePivot);
            const turning = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.004, 0.22).translate(-0.08, 0, 0), [pageMat, pageMat, pageFace, pageFace, pageMat, pageMat]);
            pagePivot.add(turning);
            pagePivot.visible = false;
            // Le cahier et la trousse
            const note = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.01, 0.24), new THREE.MeshStandardMaterial({ map: linesTex, roughness: 0.9 }));
            note.position.set(0.22, 0.643, 0.44);
            note.rotation.y = -0.15;
            st.add(note);
            if (i % 3 === 0) {
                const pencilCase = new THREE.Mesh(new THREE.CapsuleGeometry(0.035, 0.14, 3, 8).rotateZ(Math.PI / 2), flat(pick(SHIRT)));
                pencilCase.position.set(0.18, 0.66, 0.62);
                st.add(pencilCase);
            }
            // Le corps
            const body = new THREE.Group();
            st.add(body);
            const torso = new THREE.Mesh(new THREE.CapsuleGeometry(0.12, 0.2, 4, 10), shirt);
            torso.position.set(0, 0.68, 0.0);
            torso.scale.set(1.1, 1, 0.75);
            body.add(torso);
            [-1, 1].forEach((e) => {
                body.add(limb(V(e * 0.065, 0.45, -0.02), V(e * 0.065, 0.46, 0.3), 0.055, 0.05, pants));
                body.add(limb(V(e * 0.065, 0.46, 0.3), V(e * 0.065, 0.06, 0.34), 0.045, 0.04, pants));
                const shoe = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.06, 0.15), flat(0x2d2d33));
                shoe.position.set(e * 0.065, 0.03, 0.38);
                body.add(shoe);
            });
            const headPivot = new THREE.Group();
            headPivot.position.set(0, 0.86, 0.01);
            body.add(headPivot);
            const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.04, 0.06, 6), skinMat);
            neck.position.y = 0.01;
            headPivot.add(neck);
            const head = makeHead(0.11, skin, hairC, { long: style === 1, pony: style === 2, glasses: i % 5 === 3 });
            head.position.y = 0.12;
            headPivot.add(head);
            // Les bras : l'épaule pivote, la main gauche tient le livre, la droite écrit
            const arms = [-1, 1].map((e) => {
                const piv = new THREE.Group();
                piv.position.set(e * 0.15, 0.8, 0);
                body.add(piv);
                const elbow = V(e * 0.04, -0.19, 0.12);
                const hand = V(e * -0.03, -0.14, 0.33);
                piv.add(limb(V(0, 0, 0), elbow, 0.04, 0.036, shirt));
                piv.add(limb(elbow, hand, 0.034, 0.03, skinMat));
                const h = new THREE.Mesh(new THREE.SphereGeometry(0.035, 7, 5), skinMat);
                h.position.copy(hand);
                piv.add(h);
                if (e > 0) {
                    const pencil = new THREE.Mesh(new THREE.CylinderGeometry(0.006, 0.006, 0.14, 5), flat(0xf2c94c));
                    pencil.position.copy(hand).add(V(0.01, 0.04, -0.01));
                    pencil.rotation.set(-0.5, 0, 0.3);
                    piv.add(pencil);
                }
                return piv;
            });
            st.traverse((m) => {
                if (!m.isMesh) return;
                if (m.material !== cheekMat) m.castShadow = true;
                m.receiveShadow = true;
                m.userData.student = i;
                pickable.push(m);
            });
            return {
                st, body, torso, headPivot, arms, pagePivot,
                ph: rr(0, 6.28),
                state: pick(['write', 'read', 'write']),
                until: rr(2, 7),
                page: 0,
                raise: 0,
                pose: { hx: 0.42, hy: 0, rx: 0, ry: 0, lx: 0 },
            };
        }

        const students = [];
        const COLS = [-0.85, 0.85];
        const ROWS = [-0.45, 1.25];
        ROWS.forEach((z) => COLS.forEach((x) => students.push(makeStudent(students.length, x + rr(-0.06, 0.06), z + rr(-0.05, 0.05)))));

        // --- Le bureau de la prof : pile de copies, pomme, globe, mug ---
        const desk = new THREE.Group();
        desk.position.set(1.95, 0, -2.05);
        desk.rotation.y = -0.15;
        scene.add(desk);
        const dWood = flat(0xb07a4a, { roughness: 0.7 });
        const dTop = new THREE.Mesh(new THREE.BoxGeometry(1.5, 0.05, 0.7), dWood);
        dTop.position.y = 0.76;
        desk.add(dTop);
        [-0.7, 0.7].forEach((x) => {
            const side = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.74, 0.66), dWood);
            side.position.set(x, 0.37, 0);
            desk.add(side);
        });
        const modesty = new THREE.Mesh(new THREE.BoxGeometry(1.36, 0.5, 0.04), dWood);
        modesty.position.set(0, 0.5, 0.3);
        desk.add(modesty);
        const papers = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.08, 0.22), flat(0xfbf8f0));
        papers.position.set(-0.4, 0.82, -0.05);
        papers.rotation.y = 0.2;
        desk.add(papers);
        const apple = new THREE.Mesh(new THREE.IcosahedronGeometry(0.06, 1), flat(0xd8342c, { roughness: 0.4 }));
        apple.position.set(0.05, 0.84, 0.1);
        desk.add(apple);
        const stem = new THREE.Mesh(new THREE.CylinderGeometry(0.005, 0.005, 0.04, 4), flat(0x5a3a20));
        stem.position.set(0.05, 0.91, 0.1);
        desk.add(stem);
        const leafA = new THREE.Mesh(new THREE.SphereGeometry(0.02, 5, 3), flat(0x4caf50));
        leafA.scale.set(1.4, 0.4, 0.8);
        leafA.position.set(0.075, 0.915, 0.1);
        desk.add(leafA);
        const mug = new THREE.Mesh(new THREE.CylinderGeometry(0.045, 0.04, 0.1, 10), flat(0xffffff));
        mug.position.set(0.3, 0.83, 0.12);
        desk.add(mug);
        const mugHandle = new THREE.Mesh(new THREE.TorusGeometry(0.03, 0.008, 5, 10), flat(0xffffff));
        mugHandle.position.set(0.35, 0.83, 0.12);
        desk.add(mugHandle);
        const heartMug = new THREE.Mesh(new THREE.CircleGeometry(0.018, 8), new THREE.MeshBasicMaterial({ color: 0xff5c8a }));
        heartMug.position.set(0.3, 0.83, 0.167);
        desk.add(heartMug);
        const globeStand = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.07, 0.04, 8), flat(0x8a6a3a));
        globeStand.position.set(0.55, 0.8, -0.12);
        desk.add(globeStand);
        const globe = new THREE.Mesh(new THREE.SphereGeometry(0.12, 16, 12), new THREE.MeshStandardMaterial({ map: globeTexture(), roughness: 0.5 }));
        globe.position.set(0.55, 0.96, -0.12);
        globe.rotation.z = 0.4;
        desk.add(globe);
        const globeArc = new THREE.Mesh(new THREE.TorusGeometry(0.14, 0.008, 5, 18, Math.PI), flat(0xc9a04f, { metalness: 0.6 }));
        globeArc.position.copy(globe.position);
        globeArc.rotation.set(0, Math.PI / 2, 0.4 - Math.PI / 2);
        desk.add(globeArc);
        const tChair = new THREE.Mesh(new THREE.BoxGeometry(0.45, 0.06, 0.42), flat(0xc0392b));
        tChair.position.set(0.1, 0.46, -0.6);
        desk.add(tChair);
        const tBack = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.26, 0.05), flat(0xc0392b));
        tBack.position.set(0.1, 0.68, -0.8);
        desk.add(tBack);
        const tLeg = new THREE.Mesh(new THREE.CylinderGeometry(0.025, 0.025, 0.44, 6), flat(0x777c86));
        tLeg.position.set(0.1, 0.22, -0.6);
        desk.add(tLeg);
        deskLamp(desk, -0.6, 0.785, -0.15, 0.6);
        desk.traverse((m) => { if (m.isMesh) { m.castShadow = true; m.receiveShadow = true; } });

        // --- La prof : debout, ravie, avec son livre sous le bras ---
        const teacher = new THREE.Group();
        scene.add(teacher);
        const tBody = new THREE.Group();
        teacher.add(tBody);
        const tSkin = flat(0xf1c7a6, { roughness: 0.7 });
        const blouse = flat(0xf7a7b8, { roughness: 0.8 });
        const skirt = flat(0x4a6fa5, { roughness: 0.85 });
        const tLegs = [-1, 1].map((e) => {
            const piv = new THREE.Group();
            piv.position.set(e * 0.08, 0.84, 0);
            tBody.add(piv);
            piv.add(limb(V(0, 0, 0), V(0, -0.78, 0), 0.05, 0.04, tSkin));
            const shoe = new THREE.Mesh(new THREE.BoxGeometry(0.09, 0.06, 0.17), flat(0x7b2d3b));
            shoe.position.set(0, -0.8, 0.04);
            piv.add(shoe);
            return piv;
        });
        const skirtM = new THREE.Mesh(new THREE.CylinderGeometry(0.15, 0.25, 0.42, 12), skirt);
        skirtM.position.y = 0.72;
        tBody.add(skirtM);
        const tTorso = new THREE.Mesh(new THREE.CapsuleGeometry(0.14, 0.26, 4, 12), blouse);
        tTorso.position.y = 1.1;
        tTorso.scale.set(1.05, 1, 0.75);
        tBody.add(tTorso);
        const collar = new THREE.Mesh(new THREE.TorusGeometry(0.075, 0.02, 5, 12).rotateX(Math.PI / 2), flat(0xffffff));
        collar.position.y = 1.33;
        tBody.add(collar);
        // Un petit badge fleur
        const brooch = new THREE.Mesh(new THREE.SphereGeometry(0.022, 6, 4), flat(0xffe066));
        brooch.position.set(0.07, 1.22, 0.1);
        tBody.add(brooch);
        const tHeadPivot = new THREE.Group();
        tHeadPivot.position.set(0, 1.36, 0);
        tBody.add(tHeadPivot);
        const tNeck = new THREE.Mesh(new THREE.CylinderGeometry(0.04, 0.045, 0.08, 6), tSkin);
        tHeadPivot.add(tNeck);
        const tHead = makeHead(0.13, 0xf1c7a6, 0x7a4a2a, { bun: true, happy: true, glasses: true });
        tHead.position.y = 0.14;
        tHeadPivot.add(tHead);
        const tArms = [-1, 1].map((e) => {
            const piv = new THREE.Group();
            piv.position.set(e * 0.18, 1.3, 0);
            tBody.add(piv);
            const elbow = V(e * 0.04, -0.24, 0.0);
            const hand = V(e * 0.02, -0.46, 0.06);
            piv.add(limb(V(0, 0, 0), elbow, 0.045, 0.04, blouse));
            piv.add(limb(elbow, hand, 0.038, 0.033, tSkin));
            const h = new THREE.Mesh(new THREE.SphereGeometry(0.04, 7, 5), tSkin);
            h.position.copy(hand);
            piv.add(h);
            return { piv, hand };
        });
        // Le livre qu'elle tient contre elle
        const tBook = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.3, 0.22), flat(0x2e86de));
        tBook.position.copy(tArms[0].hand).add(V(0.0, 0.08, 0.05));
        tArms[0].piv.add(tBook);
        teacher.traverse((m) => {
            if (!m.isMesh) return;
            if (m.material !== cheekMat) m.castShadow = true;
            m.receiveShadow = true;
        });
        const teacherMeshes = [];
        teacher.traverse((m) => { if (m.isMesh) teacherMeshes.push(m); });
        const T = { x: -0.4, z: -1.85, heading: 0, state: 'pause', until: 3, goal: -0.6, gait: 0, move: 0, hop: 0, look: null, lookUntil: 0, heartAt: 2 };

        // --- Les petits cœurs de la prof heureuse ---
        const heartShape = new THREE.Shape();
        heartShape.moveTo(0, -0.05);
        heartShape.bezierCurveTo(-0.09, 0.02, -0.05, 0.09, 0, 0.04);
        heartShape.bezierCurveTo(0.05, 0.09, 0.09, 0.02, 0, -0.05);
        const heartGeo = new THREE.ShapeGeometry(heartShape, 6);
        const hearts = Array.from({ length: 10 }, () => {
            const m = new THREE.Mesh(heartGeo, new THREE.MeshBasicMaterial({ color: 0xff5c8a, transparent: true, opacity: 0, depthWrite: false, side: THREE.DoubleSide }));
            m.visible = false;
            m.renderOrder = 8;
            scene.add(m);
            return { m, t: 1, vx: 0, vz: 0 };
        });
        function heart(x, y, z, n = 1) {
            for (let k = 0; k < n; k++) {
                const h = hearts.find((q2) => q2.t >= 1) || hearts[0];
                h.t = -k * 0.12;
                h.m.position.set(x + rr(-0.12, 0.12), y, z + rr(-0.12, 0.12));
                h.vx = rr(-0.12, 0.12);
                h.vz = rr(-0.12, 0.12);
                h.m.material.color.setHex(pick([0xff5c8a, 0xff7aa2, 0xffa3c0, 0xff4d6d]));
            }
        }

        // --- La poussière qui danse dans les rayons du soleil ---
        const pointScale = { value: 1 };
        // La pluie dehors, derrière les fenêtres et le long du mur
        const RAIN = phone ? 160 : 300;
        const rainPos = new Float32Array(RAIN * 6);
        const rainGeo = new THREE.BufferGeometry();
        rainGeo.setAttribute('position', new THREE.BufferAttribute(rainPos, 3));
        const rainLines = new THREE.LineSegments(rainGeo, new THREE.LineBasicMaterial({ color: 0xc4d2e6, transparent: true, opacity: 0.4, depthWrite: false }));
        rainLines.frustumCulled = false;
        rainLines.renderOrder = 7;
        scene.add(rainLines);
        const drops = Array.from({ length: RAIN }, () => ({ x: rr(-HALF - 1.6, -HALF - 0.15), y: rr(0, 3.6), z: rr(-HALF, HALF), sp: rr(3.2, 4.4) }));
        // Les gouttes qui glissent sur les vitres
        const beads = particles(phone ? 30 : 60);
        beads.items.forEach((p) => resetBead(p, true));
        function resetBead(p, anywhere) {
            const w = WIN[Math.floor(rand() * WIN.length)];
            p.z = rr(w.u0 + 0.05, w.u1 - 0.05);
            p.y = anywhere ? rr(w.y0, w.y1) : w.y1 - 0.02;
            p.y0 = w.y0;
            p.sp = 0;
            p.wait = rr(0, 4);
            p.s = rr(0.02, 0.035);
        }

        // --- Caméra : de biais, depuis le fond de la classe, le tableau et les fenêtres en face ---
        const target = V(0.05, 0.75, -0.1);
        const HOME_EL = 0.56;
        let az = 0.95;
        let el = HOME_EL;
        let zoom = 0.42;
        let fit = 26;
        let lastInput = -10;
        let touched = false;
        const pointers = new Map();
        let pinch = 0;
        let downAt = null;
        const canvas = renderer.domElement;
        const spread = () => {
            const [a, b] = [...pointers.values()];
            return Math.hypot(a.x - b.x, a.y - b.y) || 1;
        };
        const onDown = (e) => {
            canvas.setPointerCapture(e.pointerId);
            pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
            if (pointers.size === 1) downAt = { x: e.clientX, y: e.clientY, t: performance.now() };
            if (pointers.size === 2) pinch = spread();
            lastInput = clock;
            touched = true;
        };
        const onMove = (e) => {
            const p = pointers.get(e.pointerId);
            if (!p) return;
            const dx = e.clientX - p.x;
            const dy = e.clientY - p.y;
            p.x = e.clientX;
            p.y = e.clientY;
            if (pointers.size === 1) {
                az -= dx * 0.0065;
                el = clamp(el + dy * 0.0045, 0.12, 1.25);
            } else if (pointers.size === 2) {
                const s = spread();
                if (pinch) zoom = clamp(zoom * pinch / s, 0.22, 1.5);
                pinch = s;
            }
            lastInput = clock;
        };
        const onUp = (e) => {
            pointers.delete(e.pointerId);
            pinch = 0;
            if (downAt && pointers.size === 0) {
                const moved = Math.hypot(e.clientX - downAt.x, e.clientY - downAt.y);
                if (moved < 7 && performance.now() - downAt.t < 400) tap(e);
            }
            downAt = null;
        };
        const onWheel = (e) => {
            e.preventDefault();
            zoom = clamp(zoom * Math.exp(e.deltaY * 0.0012), 0.22, 1.5);
            lastInput = clock;
        };
        canvas.addEventListener('pointerdown', onDown);
        canvas.addEventListener('pointermove', onMove);
        canvas.addEventListener('pointerup', onUp);
        canvas.addEventListener('pointercancel', onUp);
        canvas.addEventListener('wheel', onWheel, { passive: false });

        // Toucher un élève : il lève la main, la prof se tourne vers lui toute contente.
        // La prof : elle sautille et des cœurs s'envolent. Le tableau : un nouveau message s'écrit.
        const raycaster = new THREE.Raycaster();
        const ndc = new THREE.Vector2();
        function tap(e) {
            const r = canvas.getBoundingClientRect();
            ndc.set(((e.clientX - r.left) / r.width) * 2 - 1, -((e.clientY - r.top) / r.height) * 2 + 1);
            raycaster.setFromCamera(ndc, camera);
            const visibleBoard = front.shown ? boardMeshes : [];
            const hit = raycaster.intersectObjects([...pickable, ...teacherMeshes, ...visibleBoard], false)[0];
            if (!hit) return;
            if (hit.object.userData.student != null) {
                const s = students[hit.object.userData.student];
                s.raise = 3.5;
                T.look = s;
                T.lookUntil = clock + 3.5;
                T.state = 'pause';
                T.until = clock + 3.5;
                heart(T.x, 1.85, T.z, 1);
                return;
            }
            if (teacherMeshes.includes(hit.object)) {
                T.hop = 1;
                heart(T.x, 1.8, T.z, 5);
                return;
            }
            if (boardMeshes.includes(hit.object)) {
                boardMsg = (boardMsg + 1) % MESSAGES.length;
                boardWrite = 0;
            }
        }

        function resize() {
            const w = stage.clientWidth || 1;
            const h = stage.clientHeight || 1;
            renderer.setSize(w, h, false);
            camera.aspect = w / h;
            const tanV = Math.tan(THREE.MathUtils.degToRad(camera.fov / 2));
            fit = Math.max(14 / tanV / 2, (camera.aspect < 0.8 ? 14 : 15.6) / (tanV * camera.aspect) / 2);
            if (!touched) zoom = camera.aspect < 0.8 ? 0.58 : 0.42;
            camera.updateProjectionMatrix();
            pointScale.value = camera.projectionMatrix.elements[5] * renderer.domElement.height / 2;
        }
        const ro = new ResizeObserver(resize);
        ro.observe(stage);
        resize();

        // Les murs côté caméra : on ne les dessine plus, mais ils gardent leur ombre (le soleil passe toujours par les fenêtres)
        function setWall(wall, shown) {
            if (wall.shown === shown) return;
            wall.shown = shown;
            wall.solid.forEach((m) => {
                m.material = shown ? m.userData.mat || m.material : hiddenMat;
                if (!shown) return;
            });
            wall.deco.forEach((o) => { o.visible = shown; });
        }
        const hiddenMat = new THREE.MeshBasicMaterial({ colorWrite: false, depthWrite: false });
        walls.forEach((w) => w.solid.forEach((m) => { m.userData.mat = m.material; }));

        // --- Boucle ---
        let clock = 0;
        let last = performance.now();
        let raf = 0;
        let alive = true;
        const ease = (cur, want, k) => cur + (want - cur) * k;

        function frame(now) {
            if (!alive) return;
            const real = Math.min(0.25, (now - last) / 1000);
            const dt = Math.min(0.05, real);
            last = now;
            clock += dt;
            const t = clock;

            if (!still && !pointers.size) {
                const idle = smooth(clamp((clock - lastInput - 3) / 2, 0, 1));
                az += IDLE_SPIN * dt * idle;
                el += (HOME_EL - el) * Math.min(1, dt * 0.8) * idle;
            }
            const dist = fit * zoom;
            camera.position.set(target.x + dist * Math.cos(el) * Math.sin(az), target.y + dist * Math.sin(el), target.z + dist * Math.cos(el) * Math.cos(az));
            camera.lookAt(target);
            // Les deux murs entre la caméra et la classe disparaissent
            setWall(front, camera.position.z > 0.5);
            setWall(back, camera.position.z < -0.5);
            setWall(left, camera.position.x > 0.5);
            setWall(right, camera.position.x < -0.5);

            // L'horloge donne l'heure du vrai monde
            const d = new Date();
            const sec = d.getSeconds() + d.getMilliseconds() / 1000;
            const min = d.getMinutes() + sec / 60;
            const hr = (d.getHours() % 12) + min / 60;
            handS.rotation.z = -(sec / 60) * Math.PI * 2;
            handM.rotation.z = -(min / 60) * Math.PI * 2;
            handH.rotation.z = -(hr / 12) * Math.PI * 2;

            // Le tableau : la craie écrit le nouveau message
            if (boardWrite < 1) {
                boardWrite = Math.min(1, boardWrite + dt * 0.45);
                drawBoard(boardWrite);
            }

            // Les élèves révisent : ils écrivent, lisent, tournent les pages, lèvent le nez de temps en temps
            const k = Math.min(1, dt * 4);
            students.forEach((s) => {
                if (t > s.until) {
                    const r2 = rand();
                    s.state = r2 < 0.45 ? 'write' : r2 < 0.75 ? 'read' : r2 < 0.9 ? 'flip' : 'look';
                    s.until = t + (s.state === 'flip' ? 1.2 : s.state === 'look' ? rr(1.5, 2.5) : rr(3, 8));
                    if (s.state === 'flip') s.page = 0;
                }
                s.raise = Math.max(0, s.raise - dt);
                const p = s.pose;
                const raising = s.raise > 0;
                let hx = 0.45;
                let hy = Math.sin(t * 0.3 + s.ph) * 0.05;
                let rx = 0;
                let ry = 0;
                if (s.state === 'write') {
                    ry = Math.sin(t * 9 + s.ph) * 0.07;
                    rx = Math.sin(t * 14 + s.ph) * 0.025;
                    hy += Math.sin(t * 1.2 + s.ph) * 0.06;
                } else if (s.state === 'read') {
                    hx = 0.38;
                    hy += Math.sin(t * 0.9 + s.ph) * 0.15;
                } else if (s.state === 'flip') {
                    rx = -0.15;
                    s.page = Math.min(1, s.page + dt / 0.9);
                } else if (s.state === 'look') {
                    hx = 0.02;
                    hy = Math.sin(s.ph) * 0.25;
                }
                if (raising) {
                    hx = -0.05;
                    hy = 0;
                    rx = -2.25 + Math.sin(t * 6) * 0.08;
                    ry = 0;
                }
                p.hx = ease(p.hx, hx, k);
                p.hy = ease(p.hy, hy, k);
                p.rx = ease(p.rx, rx, raising ? Math.min(1, dt * 6) : k);
                p.ry = ease(p.ry, ry, k);
                s.headPivot.rotation.x = p.hx;
                s.headPivot.rotation.y = p.hy;
                s.arms[1].rotation.x = p.rx;
                s.arms[1].rotation.y = p.ry;
                s.arms[1].rotation.z = raising ? 0.12 : 0;
                s.torso.scale.y = 1 + Math.sin(t * 1.6 + s.ph) * 0.02;
                s.body.rotation.x = 0.05 + Math.sin(t * 0.4 + s.ph) * 0.015;
                // La page se tourne de droite à gauche
                s.pagePivot.visible = s.state === 'flip' && s.page < 1;
                s.pagePivot.rotation.z = Math.PI * (1 - smooth(s.page));
            });

            // La prof se promène devant le tableau, s'arrête pour regarder sa classe, toute contente
            if (T.look && t > T.lookUntil) T.look = null;
            if (t > T.until && !T.look) {
                if (T.state === 'pause') {
                    T.state = 'walk';
                    T.goal = rr(-1.4, 0.9);
                    if (Math.abs(T.goal - T.x) < 0.6) T.goal = T.x > -0.25 ? -1.2 : 0.7;
                    T.until = t + 20;
                } else {
                    T.state = 'pause';
                    T.until = t + rr(3, 6);
                }
            }
            let wantHeading = 0;
            let moving = 0;
            if (T.state === 'walk' && !T.look) {
                const dx = T.goal - T.x;
                if (Math.abs(dx) < 0.05) {
                    T.state = 'pause';
                    T.until = t + rr(3, 6);
                } else {
                    T.x += Math.sign(dx) * Math.min(Math.abs(dx), dt * 0.55);
                    wantHeading = Math.sign(dx) * Math.PI / 2;
                    moving = 1;
                }
            }
            if (T.look) {
                const sp2 = T.look.st.position;
                wantHeading = Math.atan2(sp2.x - T.x, sp2.z - T.z);
            }
            T.heading += Math.atan2(Math.sin(wantHeading - T.heading), Math.cos(wantHeading - T.heading)) * Math.min(1, dt * 4);
            T.move = ease(T.move, moving, Math.min(1, dt * 5));
            T.gait += dt * 6 * T.move;
            T.hop = Math.max(0, T.hop - dt * 1.2);
            const hopY = T.hop > 0 ? Math.abs(Math.sin((1 - T.hop) * Math.PI * 3)) * 0.18 * T.hop : 0;
            teacher.position.set(T.x, hopY + Math.abs(Math.sin(T.gait)) * 0.02 * T.move, T.z);
            teacher.rotation.y = T.heading;
            tLegs.forEach((l, i) => { l.rotation.x = Math.sin(T.gait + i * Math.PI) * 0.45 * T.move; });
            // En marchant, le bras libre se balance ; à l'arrêt, un petit signe de la main de temps en temps
            const wave = T.look || T.hop > 0 ? 1 : 0;
            tArms[1].piv.rotation.x = ease(tArms[1].piv.rotation.x, wave ? -2.5 : Math.sin(T.gait + Math.PI) * 0.4 * T.move, Math.min(1, dt * 6));
            tArms[1].piv.rotation.z = wave ? 0.25 + Math.sin(t * 9) * 0.25 : 0.05;
            tArms[0].piv.rotation.x = -0.6;
            tArms[0].piv.rotation.z = 0.15;
            tHeadPivot.rotation.z = Math.sin(t * 1.3) * 0.08;
            tHeadPivot.rotation.x = -0.05 + Math.sin(t * 0.7) * 0.04;
            tBody.rotation.z = Math.sin(t * 1.3 + 0.5) * 0.02 * (1 - T.move);
            // De temps en temps, un petit cœur : elle est fière de ses élèves
            if (t > T.heartAt) {
                if (T.state === 'pause') heart(T.x, 1.85, T.z, 1);
                T.heartAt = t + rr(3.5, 6);
            }
            hearts.forEach((h) => {
                if (h.t >= 1) {
                    h.m.visible = false;
                    return;
                }
                h.t += dt / 2.2;
                if (h.t < 0) return;
                h.m.visible = true;
                h.m.position.y += dt * 0.35;
                h.m.position.x += h.vx * dt + Math.sin(t * 3 + h.vz * 50) * 0.003;
                h.m.position.z += h.vz * dt;
                h.m.quaternion.copy(camera.quaternion);
                h.m.scale.setScalar(0.6 + easeOut(Math.min(1, h.t * 4)) * 0.7);
                h.m.material.opacity = Math.min(1, h.t * 6) * (1 - smooth(h.t));
            });

            // La pluie tombe doucement dehors
            drops.forEach((d2, i) => {
                d2.y -= d2.sp * dt;
                d2.z += 0.3 * dt;
                if (d2.y < 0) {
                    d2.y += 3.6;
                    d2.z = rr(-HALF, HALF);
                }
                if (d2.z > HALF) d2.z -= S;
                const o = i * 6;
                rainPos[o] = d2.x;
                rainPos[o + 1] = d2.y;
                rainPos[o + 2] = d2.z;
                rainPos[o + 3] = d2.x;
                rainPos[o + 4] = d2.y + 0.22;
                rainPos[o + 5] = d2.z - 0.02;
            });
            rainGeo.attributes.position.needsUpdate = true;
            // Les gouttes sur les vitres : elles attendent, puis glissent d'un coup
            beads.items.forEach((p, i) => {
                if (p.wait > 0) p.wait -= dt;
                else p.sp = Math.min(0.6, p.sp + dt * 0.8);
                p.y -= p.sp * dt;
                if (p.y < p.y0 + 0.03) resetBead(p, false);
                beads.set(i, -HALF + WALL_T / 2 + 0.005, p.y, p.z, p.s, [0.86, 0.9, 1.0], 0.55);
            });
            beads.update();
            // Les lampes : une lumière chaude qui respire à peine
            lamps.forEach((l) => { l.pl.intensity = 1.7 + Math.sin(t * 0.8 + l.ph) * 0.05; });

            renderer.render(scene, camera);
            raf = requestAnimationFrame(frame);
        }
        raf = requestAnimationFrame(frame);

        return {
            dispose() {
                alive = false;
                cancelAnimationFrame(raf);
                ro.disconnect();
                canvas.removeEventListener('wheel', onWheel);
                walls.forEach((w) => w.solid.forEach((m) => { m.material = m.userData.mat; }));
                scene.traverse((o) => {
                    if (o.geometry) o.geometry.dispose();
                    if (o.material) {
                        [].concat(o.material).forEach((m) => {
                            Object.values(m).forEach((v) => { if (v && v.isTexture) v.dispose(); });
                            m.dispose();
                        });
                    }
                });
                hiddenMat.dispose();
                renderer.dispose();
                canvas.remove();
            },
        };

        // ---------------- Outils de la scène ----------------
        function canvasTex(w, h, draw, repeat) {
            const cv = document.createElement('canvas');
            cv.width = w;
            cv.height = h;
            draw(cv.getContext('2d'), w, h);
            const tex = new THREE.CanvasTexture(cv);
            tex.colorSpace = THREE.SRGBColorSpace;
            tex.anisotropy = 8;
            if (repeat) tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
            return tex;
        }

        // Le parquet : des lattes de chêne miel, décalées
        function plankTexture() {
            return canvasTex(1024, 1024, (g, w, h) => {
                const rnd = mulberry32(11);
                const rowH = h / 10;
                for (let r = 0; r < 10; r++) {
                    let x = -rnd() * 300;
                    while (x < w) {
                        const len = 220 + rnd() * 260;
                        const b = 0.86 + rnd() * 0.22;
                        g.fillStyle = `rgb(${Math.round(196 * b)},${Math.round(146 * b)},${Math.round(96 * b)})`;
                        g.fillRect(x, r * rowH, len, rowH);
                        // Les veines du bois
                        for (let v = 0; v < 5; v++) {
                            g.strokeStyle = `rgba(110,70,40,${0.08 + rnd() * 0.1})`;
                            g.lineWidth = 1 + rnd();
                            g.beginPath();
                            const y = r * rowH + 8 + rnd() * (rowH - 16);
                            g.moveTo(x, y);
                            g.bezierCurveTo(x + len * 0.3, y + rnd() * 8 - 4, x + len * 0.7, y + rnd() * 8 - 4, x + len, y);
                            g.stroke();
                        }
                        g.fillStyle = 'rgba(70,40,20,0.55)';
                        g.fillRect(x, r * rowH, 2, rowH);
                        x += len;
                    }
                    g.fillStyle = 'rgba(70,40,20,0.5)';
                    g.fillRect(0, r * rowH, w, 2);
                }
            }, true);
        }

        function rugTexture() {
            return canvasTex(512, 256, (g, w, h) => {
                g.fillStyle = '#e8c07a';
                g.fillRect(0, 0, w, h);
                const cols = ['#e57373', '#64b5f6', '#81c784', '#ffd54f', '#ba68c8'];
                g.fillStyle = '#c75b5b';
                g.fillRect(12, 12, w - 24, h - 24);
                g.fillStyle = '#f6e2b3';
                g.fillRect(24, 24, w - 48, h - 48);
                for (let i = 0; i < 5; i++) {
                    g.fillStyle = cols[i];
                    g.beginPath();
                    g.arc(80 + i * 88, h / 2, 30, 0, Math.PI * 2);
                    g.fill();
                }
            });
        }

        function pageTexture() {
            return canvasTex(128, 160, (g, w, h) => {
                g.fillStyle = '#fbf6ea';
                g.fillRect(0, 0, w, h);
                g.strokeStyle = 'rgba(90,120,180,0.45)';
                g.lineWidth = 2;
                for (let y = 22; y < h; y += 14) {
                    g.beginPath();
                    g.moveTo(10, y);
                    g.lineTo(w - 10, y);
                    g.stroke();
                }
                g.strokeStyle = 'rgba(40,40,60,0.55)';
                g.lineWidth = 2;
                const rnd = mulberry32(5);
                for (let y = 18; y < h - 10; y += 14) {
                    let x = 14;
                    const end = 30 + rnd() * (w - 44);
                    g.beginPath();
                    g.moveTo(x, y);
                    while (x < end) {
                        x += 4;
                        g.lineTo(x, y + Math.sin(x * 0.9) * 2);
                    }
                    g.stroke();
                }
            });
        }

        function clockTexture() {
            return canvasTex(256, 256, (g, w) => {
                g.fillStyle = '#fffdf6';
                g.fillRect(0, 0, w, w);
                g.fillStyle = '#2b2b30';
                for (let i = 0; i < 12; i++) {
                    const a = (i / 12) * Math.PI * 2;
                    g.save();
                    g.translate(w / 2 + Math.sin(a) * 100, w / 2 - Math.cos(a) * 100);
                    g.rotate(a);
                    g.fillRect(-3, -10, 6, i % 3 ? 14 : 22);
                    g.restore();
                }
            });
        }

        function globeTexture() {
            return canvasTex(256, 128, (g, w, h) => {
                g.fillStyle = '#4a90c8';
                g.fillRect(0, 0, w, h);
                g.fillStyle = '#7cb35b';
                const rnd = mulberry32(8);
                for (let i = 0; i < 14; i++) {
                    g.beginPath();
                    g.ellipse(rnd() * w, 20 + rnd() * (h - 40), 12 + rnd() * 26, 8 + rnd() * 18, rnd() * 3, 0, Math.PI * 2);
                    g.fill();
                }
            });
        }

        function posterTexture(p) {
            const W2 = 512;
            const H2 = Math.round(512 * p.h / p.w);
            return canvasTex(W2, H2, (g, w, h) => {
                if (p.kind === 'sign') {
                    g.fillStyle = '#fff6d6';
                    g.fillRect(0, 0, w, h);
                    g.strokeStyle = '#f2a65a';
                    g.lineWidth = 14;
                    g.strokeRect(10, 10, w - 20, h - 20);
                    g.fillStyle = '#3a4a6b';
                    g.textAlign = 'center';
                    g.textBaseline = 'middle';
                    g.font = '700 64px "Comic Sans MS", "Chalkboard SE", cursive';
                    g.fillText(p.text[0], w / 2, h * 0.36);
                    g.font = '600 52px "Comic Sans MS", "Chalkboard SE", cursive';
                    g.fillText(p.text[1], w / 2, h * 0.64);
                    g.fillStyle = '#ff7aa2';
                    g.beginPath();
                    g.arc(w - 60, h - 56, 14, 0, Math.PI * 2);
                    g.fill();
                } else if (p.kind === 'alphabet') {
                    g.fillStyle = '#ffffff';
                    g.fillRect(0, 0, w, h);
                    const cols = ['#e57373', '#64b5f6', '#81c784', '#ffb74d', '#ba68c8', '#4db6ac'];
                    g.textAlign = 'center';
                    g.textBaseline = 'middle';
                    g.font = '700 62px "Comic Sans MS", "Chalkboard SE", cursive';
                    'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('').forEach((c, i) => {
                        g.fillStyle = cols[i % cols.length];
                        g.fillText(c, 50 + (i % 6) * 82, 60 + Math.floor(i / 6) * 94);
                    });
                } else if (p.kind === 'map') {
                    g.fillStyle = '#9fd0ea';
                    g.fillRect(0, 0, w, h);
                    g.fillStyle = '#9cc97a';
                    const blobs = [[0.2, 0.35, 0.12, 0.18], [0.27, 0.7, 0.07, 0.16], [0.5, 0.3, 0.07, 0.1], [0.52, 0.6, 0.08, 0.17], [0.72, 0.35, 0.16, 0.16], [0.82, 0.72, 0.07, 0.07]];
                    blobs.forEach(([x, y, rx, ry]) => {
                        g.beginPath();
                        g.ellipse(x * w, y * h, rx * w, ry * h, 0.3, 0, Math.PI * 2);
                        g.fill();
                    });
                    g.strokeStyle = 'rgba(255,255,255,0.5)';
                    g.lineWidth = 2;
                    for (let i = 1; i < 6; i++) {
                        g.beginPath();
                        g.moveTo((i / 6) * w, 0);
                        g.lineTo((i / 6) * w, h);
                        g.moveTo(0, (i / 6) * h);
                        g.lineTo(w, (i / 6) * h);
                        g.stroke();
                    }
                    g.strokeStyle = '#6b4a33';
                    g.lineWidth = 16;
                    g.strokeRect(0, 0, w, h);
                } else {
                    // Les dessins des élèves, punaisés
                    g.fillStyle = 'rgba(0,0,0,0)';
                    g.clearRect(0, 0, w, h);
                    g.fillStyle = '#c9a77c';
                    g.fillRect(0, 0, w, h);
                    const rnd = mulberry32(19);
                    for (let i = 0; i < 4; i++) {
                        const x = 18 + i * 124;
                        const y = 24 + (i % 2) * 18;
                        g.save();
                        g.translate(x + 50, y + 70);
                        g.rotate((rnd() - 0.5) * 0.15);
                        g.fillStyle = '#ffffff';
                        g.fillRect(-52, -70, 104, 140);
                        if (i === 0) {
                            g.fillStyle = '#ffd54f';
                            g.beginPath();
                            g.arc(-20, -30, 20, 0, Math.PI * 2);
                            g.fill();
                            g.fillStyle = '#81c784';
                            g.fillRect(-48, 30, 96, 36);
                        } else if (i === 1) {
                            g.fillStyle = '#e57373';
                            g.fillRect(-30, -10, 60, 50);
                            g.beginPath();
                            g.moveTo(-38, -10);
                            g.lineTo(0, -48);
                            g.lineTo(38, -10);
                            g.fill();
                        } else if (i === 2) {
                            g.fillStyle = '#64b5f6';
                            g.beginPath();
                            g.arc(0, 0, 32, 0, Math.PI * 2);
                            g.fill();
                            g.fillStyle = '#2b2b30';
                            g.beginPath();
                            g.arc(-10, -6, 4, 0, Math.PI * 2);
                            g.arc(10, -6, 4, 0, Math.PI * 2);
                            g.fill();
                        } else {
                            g.fillStyle = '#ff7aa2';
                            g.beginPath();
                            g.moveTo(0, 30);
                            g.bezierCurveTo(-50, -5, -25, -45, 0, -15);
                            g.bezierCurveTo(25, -45, 50, -5, 0, 30);
                            g.fill();
                        }
                        g.fillStyle = '#d94040';
                        g.beginPath();
                        g.arc(0, -62, 6, 0, Math.PI * 2);
                        g.fill();
                        g.restore();
                    }
                }
            });
        }

        function particles(count) {
            const pos = new Float32Array(count * 3);
            const col = new Float32Array(count * 3);
            const size = new Float32Array(count);
            const alpha = new Float32Array(count);
            const g = new THREE.BufferGeometry();
            g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
            g.setAttribute('aColor', new THREE.BufferAttribute(col, 3));
            g.setAttribute('aSize', new THREE.BufferAttribute(size, 1));
            g.setAttribute('aAlpha', new THREE.BufferAttribute(alpha, 1));
            const m = new THREE.ShaderMaterial({
                uniforms: { uScale: pointScale },
                vertexShader: `attribute vec3 aColor;
attribute float aSize;
attribute float aAlpha;
uniform float uScale;
varying vec3 vColor;
varying float vAlpha;
void main() {
    vec4 mv = modelViewMatrix * vec4(position, 1.0);
    gl_Position = projectionMatrix * mv;
    gl_PointSize = aSize * uScale / -mv.z;
    vColor = aColor;
    vAlpha = aAlpha;
}`,
                fragmentShader: `varying vec3 vColor;
varying float vAlpha;
void main() {
    float r = length(gl_PointCoord - 0.5);
    float a = smoothstep(0.5, 0.05, r) * vAlpha;
    if (a < 0.01) discard;
    gl_FragColor = vec4(vColor, a);
}`,
                transparent: true,
                depthWrite: false,
            });
            const pts = new THREE.Points(g, m);
            pts.frustumCulled = false;
            pts.renderOrder = 9;
            scene.add(pts);
            const items = Array.from({ length: count }, () => ({}));
            return {
                items,
                set(i, x, y, z, s, c, a) {
                    pos[i * 3] = x;
                    pos[i * 3 + 1] = y;
                    pos[i * 3 + 2] = z;
                    col[i * 3] = c[0];
                    col[i * 3 + 1] = c[1];
                    col[i * 3 + 2] = c[2];
                    size[i] = s;
                    alpha[i] = a;
                },
                update() {
                    g.attributes.position.needsUpdate = true;
                    g.attributes.aColor.needsUpdate = true;
                    g.attributes.aSize.needsUpdate = true;
                    g.attributes.aAlpha.needsUpdate = true;
                },
            };
        }

        function radialTexture(inner, outer) {
            const cv = document.createElement('canvas');
            cv.width = cv.height = 256;
            const g = cv.getContext('2d');
            const grad = g.createRadialGradient(128, 128, 10, 128, 128, 128);
            grad.addColorStop(0, inner);
            grad.addColorStop(1, outer);
            g.fillStyle = grad;
            g.fillRect(0, 0, 256, 256);
            const tex = new THREE.CanvasTexture(cv);
            tex.colorSpace = THREE.SRGBColorSpace;
            return tex;
        }
    }

    // Les fissures : un réseau de cellules (comme du verre ou de la terre qui casse)
    // qui ne s'ouvre qu'à l'intérieur d'un rayon qui grandit (uSpread). Au centre,
    // un vrai trou ; sur les bords, de fines fêlures avec un liseré lumineux.
    function clamp(v, a, b) {
        return Math.max(a, Math.min(b, v));
    }

    function lerp(a, b, k) {
        return a + (b - a) * k;
    }

    function easeOut(k) {
        return 1 - Math.pow(1 - k, 3);
    }

    function hash(x, z) {
        const s = Math.sin(x * 12.9898 + z * 78.233) * 43758.5453;
        return s - Math.floor(s);
    }

    function mulberry32(a) {
        return () => {
            a = (a + 0x6D2B79F5) | 0;
            let t = Math.imul(a ^ (a >>> 15), 1 | a);
            t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
            return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
        };
    }
})();
